window.CK_CATS=[{"code": "GNL", "tr": "Günlük Yaşam ve Deneyim"}, {"code": "TOP", "tr": "Toplum ve İlginç Haberler"}, {"code": "DUN", "tr": "Dünya Gündemi"}, {"code": "DOG", "tr": "Hayvanlar, Doğa ve Çevre"}, {"code": "BLT", "tr": "Bilim ve Teknoloji"}, {"code": "SAG", "tr": "Sağlık ve Yaşam"}, {"code": "TAR", "tr": "Tarih, Kültür ve Sanat"}, {"code": "POR", "tr": "Ünlüler ve Portreler"}, {"code": "SPO", "tr": "Spor"}];
window.CK_TEXTS=[{"id":"CK-001","no":1,"title":"Üniversite yıllarım","level":1,"code":"GNL","s":[{"tr":"Hayatındaki hangi önemli günleri hatırlıyorsun?","en":"What important days in your life do you remember?"},{"tr":"Üniversitedeki ilk günümü çok net hatırlıyorum.","en":"I remember my first day very clearly at university."},{"tr":"Heyecanlı ve mutlu hissettim.","en":"I felt excited and happy."},{"tr":"Aynı zamanda çok gergindim çünkü kimseyi tanımıyordum.","en":"I was also very nervous because I didn’t know anyone."},{"tr":"Ancak üniversitedeki ilk günüm unutulmazdı.","en":"However, my first day at university was unforgettable."},{"tr":"İlk başta kafam karıştı ve kayboldum.","en":"At first I was confused and lost."},{"tr":"Nereye gideceğimi bilmiyordum.","en":"I didn’t know where to go."},{"tr":"Bir yabancıya birinci sınıf öğrencilerinin nerede buluşacağını sormak zorunda kaldım.","en":"I had to ask a foreigner where the freshmen would meet."},{"tr":"Bu kişi çok kibardı ve bana yolu gösterdi.","en":"This person was very kind and showed me the way."},{"tr":"Bazı büyük binalardan geçtim ve geldiğimde birçok öğrenci gördüm ve korktum.","en":"I went through some big buildings, and when I arrived, I saw many students and got scared."},{"tr":"Daha sonra derslerimize başladık.","en":"Then we started our lessons."},{"tr":"Ancak, tüm sınıf arkadaşlarımız sessizdi.","en":"However, all our classmates were silent."},{"tr":"Öğretmen bir süre konuştu ve sonra kendimizi tanıttık.","en":"The teacher talked for a while, and then we introduced ourselves."},{"tr":"İki kızla tanıştım.","en":"I met two girls."},{"tr":"İsimleri June ve Apple idi.","en":"Their names were June and Apple."},{"tr":"Hemen iyi arkadaş olduk ve sohbet etmeye başladık ve birbirimiz hakkında daha çok şey öğrendik.","en":"We soon became good friends, and started to chat, and we learned more about each other."},{"tr":"Farklı illerden gelmemize rağmen birçok ortak yönümüz vardı.","en":"Although we came from different cities, we had many common aspects."},{"tr":"Eve gitmek zorunda kalana kadar günün geri kalanını birlikte geçirdik.","en":"We spent the rest of the day together until we had to go home."},{"tr":"O günü hep hatırlayacağım çünkü birçok insanla tanışma fırsatım oldu.","en":"I will always remember that day because I had the opportunity to meet many people."},{"tr":"En önemlisi, sahip olduğum en iyi arkadaşlarımla tanıştım.","en":"Most importantly, I met my best friends I have ever had."},{"tr":"Son olarak, üniversitedeki ilk günümüzde gergin hissetmemizin doğal olduğunu düşünüyorum, ancak çoğu zaman zor deneyimlerin mutlu sonları oluyor.","en":"Finally, I think that it is natural to feel nervous on my first day at college, but often difficult experiences have happy endings."},{"tr":"Bu yüzden üniversitedeki ilk günümün unutulmaz olduğunu söylüyorum.","en":"That’s why I say that my first day at college was memorable."}]},{"id":"CK-002","no":2,"title":"Lise ve Üniversite öğrencileri arasındaki farklar nelerdir?","level":1,"code":"GNL","s":[{"tr":"Eğitim toplum için çok önemlidir.","en":"Education is very important to society."},{"tr":"Bireyin gelişiminde de çok önemlidir.","en":"It is also very important in the development of the individual."},{"tr":"Öncelikle lise öğrencilerinin sadece kurallara ve öğretmenlerine uymaları gerekir.","en":"First of all, high school students just have to obey the rules and their teachers."},{"tr":"Bunun aksine, üniversite öğrencilerinin lise öğrencilerinden daha fazla sorumluluğu vardır.","en":"In contrast, college students have more responsibility than high school students."},{"tr":"Daha bağımsız olmaları ve kararları kendi kendilerine vermeleri gerekir.","en":"They need to be more independent and make the decisions themselves."},{"tr":"İkincisi, lise öğrencileri genellikle üniversite öğrencilerinden daha çok eğlenirler.","en":"Second, high school students usually enjoy more than college students."},{"tr":"Hayatları o kadar ciddi değil.","en":"Their lives aren’t so serious."},{"tr":"Daha kaygısızlar ve daha eğlenceli aktiviteler yaparlar.","en":"They are more carefree and do more fun activities."},{"tr":"Ancak, üniversite öğrencilerinin çoğu zaman fazla boş zamanı yoktur, ve sınavları daha ciddi olduğu için daha streslilerdir.","en":"However, college students don’t generally have much free time, and because their exams are more serious, they are more stressful."},{"tr":"Son olarak, lise öğrencileri genellikle küçük, dar bir dünyada yaşarlar.","en":"Finally, high school students often live in a small and narrow world."},{"tr":"Genellikle kendilerine benzer insanlarla okula giderler.","en":"They frequently go to school with people similar to them."},{"tr":"Benzer hayatlar yaşarlar ve benzer düşünürler.","en":"They live similar lives, and think similarly."},{"tr":"Kimse fikirlerine meydan okumaz.","en":"Nobody challenges their ideas."},{"tr":"Diğer taraftan, üniversite öğrencileri ise daha geniş bir insan yelpazesiyle kaynaşır.","en":"On the other hand, college students socialize with a wider range of people."},{"tr":"Farklı insanlarla tanışırlar.","en":"They meet different people."},{"tr":"Gerçek dünyada yaşamayı öğrenmeye başlamalılar.","en":"They must start learning to live in the real world."},{"tr":"Sonuç olarak, çoğu üniversite öğrencisi daha açık fikirli hale geliyor.","en":"As a result, most college students are becoming more open-minded."}]},{"id":"CK-003","no":3,"title":"Teknolojinin Gelişimi ve Bilgi Teknolojilerinin Önemi","level":3,"code":"BLT","s":[{"tr":"Teknoloji, ekonomik ve ticari sistemlerde ve operasyonlarda büyük değişikliklere yol açtı.","en":"Technology has led to major changes in economic and commercial systems and operations."},{"tr":"İşletmeler artık bulut hizmetlerini veya makine öğrenimini kullanıyorlar.","en":"Businesses are using cloud services or machine learning now."},{"tr":"Başarısızlığı göze alıyorlar.","en":"They are risking failure."},{"tr":"Sonuç olarak, her büyük şirket, hangi sektörde olursa olsun faaliyetlerini bilgi işlem üzerine kurar.","en":"As a result, every big company bases its activities on computing, regardless of the sector."},{"tr":"Örneğin, Coca Cola, BBC ve Levi's pazarları farklı ürünler ve hizmetler satarlar, ancak hepsi tek bir temel özelliği paylaşır.","en":"For example, Coca Cola, BBC and Levi’s markets sell different products and services, but they all share one main feature."},{"tr":"Gelişmiş bilgi işlem hizmetleri olmadan operasyonlar çöker.","en":"Operations collapse without advanced computing services."},{"tr":"Yeni teknolojiler ekonomik dinamizmin bir üretecisidir.","en":"New technologies are a generator of economic dynamism."},{"tr":"Çin, Hindistan ve diğer birçok gelişmekte olan ülke, ekonomilerini yönlendiren büyük BT sektörlerine sahiptir.","en":"China, India, and many other developing countries have large IT sectors driving their economies."},{"tr":"Teknolojik değişimin diğer önemli etkisi, iletişimde devrim yapmasıdır.","en":"The other important effect of technological change is the revolutionizing in communication."},{"tr":"Örneğin, geçmişte insanlar sabit hatlarda mektup yazıyor veya telefonlarda konuşuyorlardı, bu da iletişim sürecini yavaşlatıyordu.","en":"For example, in the past, people wrote letters or talked on phones on fixed landlines, this slowed down the communication process too."},{"tr":"Artık mobil cihazları kullanarak e-posta, metin veya sohbet gönderiyorlar.","en":"Now, they send e-mail, text, and chat by using mobile devices."},{"tr":"Bir mektup için haftalarca beklemek veya bir sabit hat bulmak için zaman harcamak yerine, bir mesaj veya e-posta gönderildikten sonra anında tam zamanlı veya saniyeler içinde iletişim kurabiliriz.","en":"Instead of waiting weeks for a letter or spending time to find a landline, we can communicate in real time or seconds after a message or an email is sent."},{"tr":"Yeni iletişim biçimleri daha ucuz veya ücretsizdir.","en":"New forms of communication are cheaper or free."},{"tr":"Sonuç olarak artık birbirinden binlerce kilometre uzakta yaşayan insanlar istedikleri kadar ve istedikleri zaman iletişim kurabiliyor.","en":"As a result, now people who live thousands of kilometres away from each other can communicate as much as they want and whenever they want."},{"tr":"Dahası, Almanya, Amerika Birleşik Devletleri, Japonya ve Kore gibi daha gelişmiş ekonomiler, endüstri temelli bir ekonomiden bilgi işlem ve BT tabanlı bir ekonomiye geçiyorlar.","en":"Moreover, more advanced economies such as Germany, The United States, Japan, and Korea are moving from an industry-based economy to a computing and IT-based economy."}]},{"id":"CK-004","no":4,"title":"Nasıl eğlenilir?","level":2,"code":"GNL","s":[{"tr":"İnsanlar her zaman bana en iyi partilere sahip olduğumu söyler ve bunu nasıl yaptığımı sorarlar.","en":"People always tell me that I have the best parties, and ask me how I do it."},{"tr":"Yıllar içinde eğlenceyi başarılı kılmak için şu üç adımı keşfettiğimi söylüyorum: Rahatlatıcı bir atmosfer yaratmak, bol bol iyi yemek temin etmek ve yapacak birçok eğlenceli şeye sahip olmak.","en":"I say that over the years, I have discovered these three steps to make entertaining successful: creating a relaxing atmosphere, providing a lot of good food, and having many fun things to do."},{"tr":"Eğlenirken düşünmeniz gereken ilk şey, rahatlatıcı bir atmosferin nasıl yaratılacağıdır.","en":"The first thing we have to think about when entertaining is how to be created a relaxing atmosphere."},{"tr":"Elbette uygun dekorasyonlar planlamanız gerekir.","en":"Sure, you have to plan appropriate decorations."},{"tr":"Aydınlatma, hava durumu ve mobilyaları da düşünmeniz lazım.","en":"You also need to think about lighting, the weather, and the furniture."},{"tr":"Sonra yemeği planlayın.","en":"Next, plan the food."},{"tr":"Çok iyi yemek hazırlamanız gerekiyor.","en":"You need to prepare very good food."},{"tr":"Ardından, yemeği nasıl organize edeceğinizi düşünün.","en":"Then consider how you will organize the food."},{"tr":"Masanın etrafında kaynaşmanın ve dolaşmanın kolay olduğu bir yerde olması gerekiyor.","en":"It needs to be in a good location where it is easy to mingle and walk around the table."},{"tr":"Çeşitli içecekler de hazırlayın.","en":"Prepare a variety of drinks too."},{"tr":"İlginç yiyecek ve içecekler harika sohbet başlatanlardır.","en":"Interesting food and beverages are great conversation starters."},{"tr":"Son olarak, biraz eğlenin.","en":"Finally, have some fun."},{"tr":"Sadece sahip olduğunuz eğlence türlerini düşünün.","en":"Just think about the kinds of entertainment you have."},{"tr":"Belki bir havuz veya masa tenisi veya bilardo masaları gibi oyun masaları vardır.","en":"Maybe there is a pool or games tables such as ping pong or billiards."},{"tr":"Belki de video oyunlarını uygun bir yere koyabilirsiniz.","en":"Perhaps you can put video games in a suitable place."},{"tr":"Buz kırıcı olarak servis edebilen şeyler partinize katkıda bulunacaktır.","en":"Things that can serve as an icebreaker will add to your party."},{"tr":"Özetle, akşam ilerledikçe konuklarınızın keyif aldığını görürseniz, partinin başarılı olduğunu görürsünüz.","en":"To sum up, if you see your guests enjoying themselves as the evening progresses, you see that the party is successful."},{"tr":"O zaman siz kendiniz de eğleneceksiniz.","en":"Then you will enjoy yourself too."}]},{"id":"CK-005","no":5,"title":"Christiane Amanpour","level":2,"code":"POR","s":[{"tr":"Dünyanın herhangi bir yerinde TV izliyorsanız, muhtemelen Christiane Amanpour'un yüzüne aşinasınızdır.","en":"If you watch TV anywhere in the world, you are probably familiar with the face of Christiane Amanpour."},{"tr":"Dünyanın en başarılı uluslararası haber muhabirlerinden biridir.","en":"She is one of the world’s most successful international news reporters."},{"tr":"O kadar çok ülkeden ve o kadar çok konuda haber yaptı ki, birçok film veya müzik ünlülerinden daha ünlü.","en":"She has reported from so many countries and on so many issues, which she is more famous than many movie or music celebrities."},{"tr":"Christiane Amanpour, 1958'de Londra'da doğdu.","en":"Christiane Amanpour was born in London in 1958."},{"tr":"Babası İranlı ve annesi İngiliz.","en":"Her father is Iranian and her mother is British."},{"tr":"Karma kültürel mirası nedeniyle İngilizce, Farsça ve Fransızca konuşmayı öğrendi.","en":"Owing to her mixed cultural heritage, she learned to speak English, Persian, and French."},{"tr":"İlk küresel haber ajansı CNN'de çalışmaya başladıktan sonra ünlü oldu.","en":"She became famous after she started working for CNN, the first global news agency."},{"tr":"Amanpour, CNN için çalışırken, yüksek kaliteli gazetecilikle kısa sürede ün kazandı.","en":"Amanpour quickly gained a reputation for high quality journalism while working for CNN."},{"tr":"Ayrıca cesaretiyle de tanınıyordu.","en":"She was also known for her bravery."},{"tr":"Her zaman doğru zamanda dünyanın haber yapma noktalarında yer aldı.","en":"She was always in the newsmaking hotspots in the world at the right time."},{"tr":"Örneğin, Berlin Duvarı'nın yıkılışını ve Körfez Savaşı'nı bildirdi.","en":"For example, she reported on the Fall of the Berlin Wall and Gulf War."},{"tr":"Amanpour, 20 yıldan fazla bir süredir dünyadaki yüksek kaliteli gazeteciliğin belki de en ünlü sembolü haline geldi.","en":"Over more than 20 years, perhaps Amanpour has become the most famous symbol of high quality journalism in the world."},{"tr":"Pek çok ödül kazandı ve birçok başkan, başbakan, kral, kraliçe ve diğer önemli kişilerle röportaj yaptı.","en":"She has won many awards, and she has interviewed many presidents, prime ministers, kings, queens, and other important people."},{"tr":"Ancak şöhret ve güçle yüzleştiğinde asla utangaç değildir.","en":"However, she is never shy when she confronts fame and power."},{"tr":"Özetlemek gerekirse, Christiane Amanpour gazeteci olmak isteyen herkes için bir rol model.","en":"To sum up, Christiane Amanpour is a role model for everybody wanting to be a journalist."},{"tr":"Cesur, dürüst ve bağımsız olmasının yanı sıra şefkatli ve yardımseverdir.","en":"She is compassionate and helpful as well as being brave, honest, and independent."},{"tr":"Dünya onun gibi daha çok insanla çok daha iyi olabilirdi.","en":"The world could be so much better with more people like her."}]},{"id":"CK-007","no":7,"title":"Kaplanlar hakkındaki bilinmeyenler","level":2,"code":"DOG","s":[{"tr":"Bir kavgada kim kazanır, aslan mı yoksa kaplan mı?","en":"Who wins in a fight, lion or tiger?"},{"tr":"Boyutu ön plana koyarsak, kaplan kazanır, çünkü kaplanlar tüm kedi türlerinin en büyüğüdür.","en":"If we put size first, the tiger wins, because tigers are the largest of all cat species."},{"tr":"Kaplanlar, dört metre uzunluğa kadar büyürler ve 500 kg ağırlığa ulaşabilirler.","en":"They grow up to four meters long and can reach 500 kg weight."},{"tr":"Bu, kaplanları üçüncü en büyük kara etoburu yapar.","en":"This makes tigers the third largest land carnivore."},{"tr":"En büyük ilk iki kara etoburu kutup ayıları ve kahverengi ayılardır.","en":"The first two largest land carnivores are polar bears and brown bears."},{"tr":"Kaplanlar sadece büyük değil, aynı zamanda hızlılar.","en":"Tigers are not only large but also fast."},{"tr":"Kısa mesafelerde saatte 40 km'ye kadar koşabilir ve yatay olarak 3 metreye kadar sıçrayabilirler.","en":"They can run up to 40 km per hour in short distances, and jump up to 3 meters horizontally."},{"tr":"Bu, son derece tehlikeli bir saldırıya neden olur.","en":"This extremely causes to a dangerous attack."},{"tr":"Bu kadar büyük, hızlı ve vahşi yaratıkların hayatta kalmak için yardıma ihtiyacı olduğunu düşünmeyebilirsiniz, ama onların yardıma ihtiyacı var.","en":"You may not think such large, fast, and wild creatures need help to survive, but they need help."},{"tr":"Kaplan, nesli tükenmekte olan bir türdür.","en":"The tiger is an endangered species."},{"tr":"İnsanlar, avlanma yoluyla dünyanın kaplan nüfusuna önemli ölçüde zarar vermişlerdir, ancak yaşam alanlarının yok edilmesi belki de daha fazla hasara neden olmuştur.","en":"Humans have significantly damaged the World’s tiger population through hunting, but destruction of their habitats has perhaps caused more damage."},{"tr":"on 100 yılda kaplanlar, Asya'nın her yerine yayılmak yerine, artık güney ve güneydoğu Asya'da küçük bölgelerde izole olmuşlardır.","en":"In the last 100 years, instead of spreading all over Asia, tigers have become isolated in small areas of South and southeast Asia."},{"tr":"Çünkü, insanlar çevrelerini büyük ölçüde değiştirdiler.","en":"Because, people have drastically changed their environment."},{"tr":"İnsanlar kasaba ve şehirler inşa ettiler.","en":"People have built towns and cities."},{"tr":"Bu kasaba ve şehirleri birbirine bağlamak için yol yaptılar.","en":"They have made roads to connect these towns and cities."},{"tr":"Bu alanlarda yaşayan insanları beslemek için ormanlar ve tarlaları tarım arazilerine dönüştürdüler.","en":"They have turned forests and fields into farmlands to feed people living in these areas."},{"tr":"Kaplan nüfusu, birçok tehdit ve engelle karşı karşıya olsa da, onları koruma çabalarında bazı önemli başarılar elde edildi.","en":"Although the tiger population faced many threats and obstacles, some significant success has been made in efforts to protect them."},{"tr":"Örneğin, vahşi kaplan popülasyonunu eski haline getirmek için çalışan bir kuruluş olan \"Save China’s Tigers\", az sayıda Güney Çin kaplanını başarıyla yabanileştirildi.","en":"For instance, \"Save China’s Tigers\", an organization working to restore the wild tiger population, successfully wilded a small number of South China tigers."},{"tr":"Bu kaplanlar, aynı zamanda tutsak olan ve vahşi doğada yaşayamayan ebeveynlerden doğdu.","en":"These tigers were born from parents that were also captive and couldn’t live in the wild."}]},{"id":"CK-008","no":8,"title":"Johannes Gutenberg - Modern Matbaacılığın Babası","level":3,"code":"POR","s":[{"tr":"Şu anda bunu okuyorsanız, okuryazarlık harikasının içinde yer alıyorsunuz.","en":"If you are reading this right now, you are taking part in wonder of literacy."},{"tr":"Basılı kelimeler sayesinde, fikirler yazılı olarak kodlanır ve binlerce kilometre ve yıl boyunca okuyuculara iletilir.","en":"Thanks to printed words, ideas are encoded in writing, and transmitted to readers across thousands of km and years."},{"tr":"Bu olgunun gelişmesi için verilen itibarın çoğu tek bir adama atfedilebilir.","en":"Much of credit for the development of this phenomenon can be attribute to one man."},{"tr":"Johannes Gutenberg, Almanya'nın Mainz şehrinde doğdu.","en":"Johannes Gutenberg was born in the city of Mainz in Germany."},{"tr":"Gutenberg’in çocukluk yaşamının çoğu bir sır olsa da, tarihçiler onun 1418'de Erfurt Üniversitesi'nde okuduğuna ve genç yetişkin hayatının çoğunu babasının mesleğini icra ederek geçirdiğine inanıyor: kuyumculuk.","en":"Though most of Gutenberg’s childhood life is a mystery, historians believe that he studied at the University of Erfurt in 1418 and much of his young adult life experienced by making his father’s profession: goldsmithing."},{"tr":"Gutenberg'in fikri, tüm insanlığın en büyük fikirlerinden biriydi.","en":"Gutenberg’s idea was one of the greatest ideas of all mankind."},{"tr":"Bu fikir, sayısız diğerlerinin yayılmasına yol açacaktı.","en":"This idea would lead to the spread of countless others."},{"tr":"Rönesans, Reform, Aydınlanma Çağı ve Bilimsel Devrim'in gelişiminde kilit bir rol oynayacaktı.","en":"It would play a key role in the development of Renaissance, Reformation, the Age of Enlightening, and Scientific Revolution."},{"tr":"Gutenberg’in fikrinin yayılmasından önce, edebiyat öncelikle el yazısıyla yazılmıştı.","en":"Before the spread of Gutenberg’s idea, literature was primarily handwritten."},{"tr":"Dolayısıyla sıkıntılı ve enderdi.","en":"Thus, it was troublesome and rare."},{"tr":"Gutenberg’in icadı onu değiştirecekti.","en":"Gutenberg’s invention would change it."},{"tr":"Matbaası, literatürün kitlesel ölçekte üretilmesine izin verdi.","en":"His printing press allowed literature to be produced on the mass scale."},{"tr":"Hareketli metal türü bir kerede bir sayfa oluşturarak düzenlenebilir ve baskısı sayfayı tekrar tekrar basabilirdi.","en":"His moveable metal type could be once arranged by forming a page and his press could print the page again and again."},{"tr":"Gutenberg'in ürettiği ilk büyük metin İncil'in 42 satırlık bir kopyasıydı.","en":"The first major text that Gutenberg produced was 42 lines copy of the bible."},{"tr":"Latince yazılmış ve 1272 sayfa içeren Gutenberg İncilinin, basılı sözün tarihi üzerinde ölçülemez bir etkisi olmuştur.","en":"Gutenberg Bible, written in Latin and containing 1272 pages, had an immeasurable effect on the history of the printed word."}]},{"id":"CK-010","no":10,"title":"Özgürlük Anıtı","level":3,"code":"TAR","s":[{"tr":"Her yıl bir milyondan fazla insan Amerika Birleşik Devletleri'ne göç ediyor ve New York’a gideceklerse görecekleri ilk yerlerden biri Özgürlük Heykelidir.","en":"More than a million people immigrate to the United States every year, and if they arrive in New York, one of the first sights that they will see is Statue of Liberty."},{"tr":"Özgürlük Heykeli, New York'ta Manhattan yakınlarındaki Özgürlük Adası'nda yer almaktadır.","en":"The Statue of Liberty stands on Liberty Island near Manhattan in New York."},{"tr":"Özgürlük Heykeli çok büyük.","en":"The Statue of Liberty is huge."},{"tr":"Meşalenin ucundan üzerinde durduğu kaideye kadar 46 metreden biraz daha uzundur.","en":"From the tip of the torch to the pedestal on which she stands, she is just over 46 meters tall."},{"tr":"Kaideyi ölçümünüze dahil ederseniz, yerden 93 metreden daha yüksekte durur.","en":"If you include the pedestal in your measurement, she stands more than 93 meters off of the ground."},{"tr":"Bu 30'dan fazla basketbol sahası veya bir futbol sahası demektir.","en":"This means more than 30 basketball saloons or a football field."},{"tr":"Amerika, Özgürlük Heykeli’nin üzerinde durduğu kaideyi finanse edip inşa etmesine rağmen, heykelin kendisi Fransa'dan bir armağandı.","en":"Even if America financed and built the pedestal on which the Statue of Liberty stands, the statue itself was a gift from France."},{"tr":"28 Ekim 1886'da, Amerika'nın Büyük Britanya'dan bağımsızlığını ilan etmesinden yüz yıldan biraz daha uzun bir süre sonra, Özgürlük Heykeli Frédéric Auguste Bartholdi tarafından tamamlandı.","en":"On October 28th 1886, a little more than a hundred years after America declared its independence from Great Britain, the Statue of Liberty was completed by Frédéric Auguste Bartholdi."},{"tr":"Fransız bağış toplama çabalarına liderlik etti ve heykelin görünümünü tasarladı.","en":"He led the French fundraising efforts, and designed the appearance of the statue."},{"tr":"Özgürlük Heykeli’nin görünümü Roma özgürlük tanrıçası Libertas'tan türetilmiştir.","en":"The appearance of the statue was derived from Libertas, the Roman goddess of freedom."},{"tr":"Meşale, özgürlüğün dünyayı nasıl aydınlattığını temsil eder.","en":"The torch represents how liberty enlightens the World."},{"tr":"Tacın tepesinden gelen yedi nokta veya ışın, güneşi, yedi denizi, yedi kıtayı ve (meşalede olduğu gibi) özgürlüğün dünyayı nasıl aydınlattığını temsil eder.","en":"The seven points or rays coming from the top of the crown represent the sun, the seven seas, the seven continents, and (as with the torch) how liberty enlightens the World."},{"tr":"Bartholdi, heykelin dış görünüşünden sorumlu olsa da, iç tasarım büyük ölçüde yenilikçi tasarımcı Gustave Eiffel’e atfedilebilir.","en":"Although Bartholdi was responsible for the appearance of statue, the internal design can be attributed to innovative designer Gustave Eiffel greatly."}]},{"id":"CK-011","no":11,"title":"Çelik Yelek: Kevlar","level":2,"code":"BLT","s":[{"tr":"Naylon kadar esnek ve hafif, çelikten beş kat daha güçlü olan bir lifin var olduğunu biliyor muydunuz?","en":"Did you know that there is a fiber that is as flexible and lightweight as nylon, five times stronger than steel?"},{"tr":"Bu kumaşın 500 Fahrenheit dereceden yüksek sıcaklıklara karşı dayanıklı olduğunu biliyor muydunuz?","en":"Did you know that this fabric is resistant to temperatures higher than 500 degrees Fahrenheit?"},{"tr":"Bu lifi bir kadının icat ettiğini biliyor muydunuz?","en":"Did you know that a woman invented this fiber?"},{"tr":"Bu mucizevi kumaşa Kevlar deniyor ve vücut zırhından müzik aletlerine kadar her şeyin yapımında kullanılıyor.","en":"This miraculous fabric is called Kevlar, and it is used to make everything from body armor to musical instruments."},{"tr":"Yıl 1964'tü.","en":"The year was 1964."},{"tr":"Stephanie Louise Kwolek, bir Amerikan kimya şirketi olan DuPont için çalışıyordu.","en":"Stephanie Louise Kwolek was working for DuPont, an American chemical company."},{"tr":"O ve grubu, lastiklerde kullanılmak üzere hafif ama dayanıklı bir lif yapmaya çalışıyorlardı.","en":"She and her group were trying to make a lightweight, yet durable fiber to be used in tires."},{"tr":"Süreçteki adımlardan birinde Kwolek, işlemde sıklıkla kullanılan iki kimyasalı karıştırarak süt beyazı bir çözelti yarattı.","en":"During one of the steps in the process, Kwolek created a milky white solution by mixing two chemicals that were often used in the process."},{"tr":"Kwolek'in yarattığı kumaşın sadece naylondan değil aynı zamanda çelikten daha dayanıklı olduğunu keşfettiklerinde şaşırdılar.","en":"They were amazed when discovering the fabric that Kwolek had created was more durable than not only nylon but also steel."},{"tr":"Kwolek, Kevlar'ı icat etmişti.","en":"Kwolek had invented Kevlar."},{"tr":"Kevlar, gücü ve dayanıklılığı ile tanınan olağanüstü bir kumaştır.","en":"Kevlar is a remarkable fabric known for its strength and durability."},{"tr":"Buluşundan bu yana çok çeşitli ürünlerde kullanılmıştır.","en":"Since its invention, it has been used into a wide variety of products."},{"tr":"Kevlar, bisiklet lastikleri ve tenis raketleri gibi spor ekipmanlarında kullanılır.","en":"Kevlar is used in sporting equipments such as bike tires and tennis rackets."},{"tr":"Richard Armellino, 1975'te ilk Kevlar kurşun geçirmez yeleğini yaptı.","en":"Richard Armellino created the first Kevlar bulletproof vest in 1975."},{"tr":"Tabanca ve av tüfeği mermilerini durdurabilecek 15 katlı Kevlar içeriyordu.","en":"It contained 15 layers of Kevlar, which could stop handgun and shotgun bullets."},{"tr":"Yeleğin ayrıca tüfek mermilerini durduracak kadar güçlü olmasını sağlayan, kalbin üzerinde çelik bir plakası vardı.","en":"The vest also had a steel plate over the heart, which made the vest strong enough to stop shotgun bullets."},{"tr":"Armellino’nunki gibi yelekler polis güçleri tarafından hemen alındı ve günümüzde Amerika'daki polis memurlarının yarısının kurşun geçirmez yelek giydiği tahmin ediliyor.","en":"Vests like Armellino’s were quickly taken by police forces, and today, it is estimated that half of the police officers in America wear bulletproof vests."}]},{"id":"CK-012","no":12,"title":"Asya Sazanları Savaş Çıkartmış","level":1,"code":"DOG","s":[{"tr":"Amerika Birleşik Devletleri'nin uzun bir savaşma geçmişi var.","en":"The United States has a lengthy history of going to war."},{"tr":"Savaştan doğan bir millettir.","en":"It is a nation born from war."},{"tr":"1776'dan beri herhangi bir yılı seçin ve Amerika'nın en az bir savaşa dahil olma ihtimali %90'ın üzerindedir.","en":"Pick any year since 1776, and odds of America being involved in at least one war is over 90%."},{"tr":"Her ABD Başkanı savaşla karşılaştı.","en":"Every US President has faced war."},{"tr":"Yine de ABD hükümetinin bir balıkla savaşta olduğunu duymak sizi şaşırtabilir.","en":"Still, it may surprise you to hear that the US government is at war with a fish."},{"tr":"Asya sazanı, 1970'lerde Amerikan sularına getirildi.","en":"Asian carp were introduced to American waters in 1970s."},{"tr":"Güneyli balık çiftçileri, göletlerini temizlemeye yardımcı olmak için onları ithal etmeye başladı.","en":"Southern fish farmers began importing them to help clean their ponds."},{"tr":"Asya sazanı olağanüstü temizleyicilerdir.","en":"Asian carp are phenomenal cleaners."},{"tr":"Ne yazık ki, bu göletlerden, belki de selden kaçmaları ve Mississippi Nehri'ne girmeleri çok uzun sürmedi.","en":"Unfortunately, it didn’t take too long to escape from these ponds perhaps flooding, and get into the Mississippi River."},{"tr":"Oradan da, akıntıya karşı doğal eğilimlerini izlediler. Bu eğilim, onları balıkçılar için bir kabus senaryosu olan Büyük Göller ve Kanada'ya götürebilir.","en":"From there, they have followed their natural tendency upstream, this tendency may lead them into the Great Lakes and Canada, a nightmare scenario for fishermen."},{"tr":"Asya sazanı büyük balıktır.","en":"Asian carp are large fish."},{"tr":"Bir türü olan gümüş sazan, 45 kilograma kadar büyüyebilir.","en":"One species of it, silver carp can grow to be 45 kilograms."},{"tr":"Ancak büyüklüklerine rağmen besin zincirinin altından beslenirler.","en":"However, despite their size, they feed from the bottom of the food chain."},{"tr":"Bu, plankton ve yosun yedikleri anlamına gelir.","en":"That means that they eat plankton and algae."},{"tr":"\"Uçan sazan\" olarak da bilinmelerinin bir nedeni var.","en":"There is a reason why they are known as \"flying carp\"."},{"tr":"Bu özel Asya sazan türü, korktuklarında zıplama eğilimindedir.","en":"This particular species of Asian carp has a tendency to jump when they frighten."},{"tr":"Havada üç metreye kadar zıplayabilirler ve tekne motorlarının sesi onları korkutur.","en":"They can jump up to three meters in the air, and the sound of boat motors frightens them."},{"tr":"2003 yılında bir jetski üzerindeki kadın onlardan biriyle çarpıştı ve burnunu ve bir omurunu kırdı.","en":"In 2003, a woman on a jet ski collided with one of them, and broke her nose and a vertebra."},{"tr":"Neredeyse boğuluyordu.","en":"She almost drowned."},{"tr":"2008'de bir genç su kayağı yaparken çenesini birisi yüzünden kırdı.","en":"In 2008, a teenager broke his jaw because of one while water skiing."},{"tr":"Bazıları Büyük Göllerin Mississippi Nehri ile olan bağlantısının kesilmesi gerektiğini düşünüyor.","en":"Some think that Great Lakes must be cut off the connection of Mississippi River."},{"tr":"Michigan Başsavcısı, kanalın kapatılması için dava açtı.","en":"The Michigan Attorney General sued in order to have the canal closed."},{"tr":"Bu arada engeller devam ediyor ama ne kadar devam edebilirler?","en":"In the meantime, the barriers are continuing, but how long can they?"},{"tr":"Sazan, Büyük Gölleri kuşattı.","en":"The carp have surrounded the Great Lakes."},{"tr":"Bu kaybetmeye mahkum olduğumuz bir savaş mı?","en":"Is this a war that we are destined to lose?"}]},{"id":"CK-014","no":14,"title":"Etçil Bitkiler","level":1,"code":"DOG","s":[{"tr":"Bir sinek olduğunuzu hayal edin.","en":"Imagine that you are a fly."},{"tr":"Güzel pembe bir yaprak gördüğünüzde, sadece gökyüzünü dolaşarak dinlenecek bir yer arıyorsunuz.","en":"You are just zipping around the sky, looking for a place to rest."},{"tr":"İnmek için güzel bir yere benziyor.","en":"That looks like a nice place to land."},{"tr":"Ayaklarınızı yaprağın üzerinde dinlendirirken tuhaf bir şey fark edersiniz.","en":"As you rest your feet on the leaf, you notice something strange."},{"tr":"Bu yaprak tüylü.","en":"This leaf is hairy."},{"tr":"Harekete geçmeye başlıyorsunuz ama bitkinin refleksini tetikliyorsunuz.","en":"You begin to make your move, but you trigger the plant’s reflex."},{"tr":"Şak!","en":"Snap!"},{"tr":"Saniyenin onda birinde, Venüs sinekkapanına yakalanırsınız.","en":"In one-tenth of a second, you are caught in the Venus flytrap."},{"tr":"Beş ila on iki gün içinde sindirileceksiniz.","en":"You will be digested in five to twelve days."},{"tr":"Etçil bitkiler dünyasına hoş geldiniz!","en":"Welcome to the World’ of carnivorous plants!"},{"tr":"Çeyrek milyondan fazla bitki türü vardır.","en":"There are over a quarter of a million plant species."},{"tr":"Sadece 600 civarı etobur.","en":"Only 600 or so are carnivorous."},{"tr":"Biz onlara bunu diyoruz çünkü böcekleri çekiyor, tuzağa düşürüyor ve yiyorlar.","en":"We call them this because they attract, trap, and eat bugs."},{"tr":"Diğer bitkiler gibi, güneşten enerji alırlar.","en":"Like other plants, they get energy from the sun."},{"tr":"Ancak diğer bitkilerden farklı olarak, besinlerini avlarından alırlar.","en":"However, unlike other plants, they get nutrients from their prey."},{"tr":"Etçil bitkiler bataklıklarda ve toprağın besin maddelerinin bulunmadığı yerlerde yaşarlar.","en":"Carnivorous plants live in bogs and places where the soil lacks nutrients."},{"tr":"Çoğu bitki besin maddelerini topraktan alır.","en":"Most plants get nutrients from the soil."},{"tr":"Etçil bitkiler başka kaynaklara yöneldi.","en":"Carnivorous plants have turned to other sources."},{"tr":"Sinekkapan bitkisinin kapması bitkilerin böcek yemesinin tek yolu değildir.","en":"The snap of the Venus flytrap isn’t the only way that plants eat bugs."},{"tr":"Sürahi bitkileri avlarını kandırarak üzerlerine inerler.","en":"Pitcher plants land on them tricking their prey."},{"tr":"Onları alacak aptal böceklere nektar rüşveti veriyorlar.","en":"They offer nectar bribes to foolish insects that would take them."},{"tr":"İsmine sadık kalarak, sürahi bitkilerinin derin bölmeleri vardır.","en":"True to their name, pitcher plants have deep chambers."},{"tr":"İniş yüzeyleri kaygandır.","en":"Their landing surface is slippery."},{"tr":"İçine dönük tüyleri vardır ve bu da kaçmayı zorlaştırır.","en":"They have inward hairs, and this makes it hard to escape."},{"tr":"Sinek, yemek için sürahi bitkisinin üzerine konar, ancak sindirim sıvılarıyla dolu bir çukura kayar ve yenir.","en":"The fly lands on the pitcher plant to eat, but slips into a pit filled with digestive fluids and is eaten."},{"tr":"Etçil bitkiler kulağa hoş gelebilir, ancak evde tutmaları zordur.","en":"Carnivorous plants might sound nice, but they are difficult to keep at home."},{"tr":"Diğer bitkilerin yapamayacağı yerlerde hayatta kalmak için yaratılmışlardır.","en":"They are created to survive in places where other plants cannot."},{"tr":"Bu uzmanlığın bir bedeli vardır.","en":"This specialization comes at a cost."},{"tr":"Diğer ortamlara uyum sağlamakta zorlanırlar.","en":"They have a hard time adapting to other environments."},{"tr":"Zengin topraklarda güçleri zayıf yönlere dönüşür.","en":"Their strengths become weaknesses in rich soil."}]},{"id":"CK-016","no":16,"title":"Kolezyum: Roma","level":1,"code":"TAR","s":[{"tr":"Kolezyum, Roma'nın merkezinde bulunan eski bir stadyumdur.","en":"The Coliseum is an ancient stadium in the center of Rome."},{"tr":"Türünün en büyüğüdür ve çok eskidir.","en":"It is the largest of its kind, and very old."},{"tr":"70 yılında inşa etmeye başladılar.","en":"They started building it in the year 70."},{"tr":"İnşası on yıl sürdü.","en":"It took ten years to build."},{"tr":"Bugün hala ayaktadır.","en":"It is still standing today."},{"tr":"Kolezyum pek çok şekilde kullanılmıştır.","en":"The Coliseum was used in many ways."},{"tr":"Antik Roma'da insanlar içinde savaştılar.","en":"In ancient Rome, people fought each other in it."},{"tr":"Aslanlara, kaplanlara ve ayılara karşı savaştılar.","en":"They fought against lions, tigers, and bears."},{"tr":"Aman!","en":"Oh my!"},{"tr":"Korkunçtu.","en":"It was dreadful."},{"tr":"Ama insanların çoğu onu sevdi.","en":"However, most of the people loved it."},{"tr":"80.000 kadar Romalı izlemek için içeri toplanırdı.","en":"As many as 80.000 Romans would pack inside to watch."},{"tr":"Bu korkunç olaylar 523 yılına kadar devam etti.","en":"These gruesome events went on until 523."},{"tr":"Kolezyum, yıllar boyunca birçok kez hasar gördü.","en":"The Coliseum has been damaged many times over the years."},{"tr":"217 yılında yıldırım çarptı.","en":"It was struck by lightning in 217."},{"tr":"Bu yangın çıkardı.","en":"This started a fire."},{"tr":"Kolezyum'un çoğu taştan yapılmıştır.","en":"Much of the Coliseum is made of stone."},{"tr":"Ancak yangın üst katlara zarar verdi çünkü tahtadan yapılmışlardı.","en":"However, the fire damaged the upstairs because they were made of wood."},{"tr":"Bu hasarın onarılması uzun yıllar aldı.","en":"Being repaired of this damage took many years."},{"tr":"240 yılına kadar bitmemişti.","en":"It hadn’t finished until the year 240."},{"tr":"O günlerin Romalıları Kolezyum'a bağlı değildi.","en":"The Romans of those days weren’t connected to the Coliseum."},{"tr":"En son kale olarak kullanılmıştı.","en":"It had last been used as a castle."},{"tr":"Ondan önce bir mezarlıktı.","en":"Before that, it was a graveyard."},{"tr":"Oyunlardan bu yana yüzlerce yıl geçti.","en":"It has been hundreds of years since the games."},{"tr":"Kolezyum'daki hasar hiç onarılmadı.","en":"The damage in the Coliseum was never repaired."},{"tr":"Dış duvarının hala sağlam durması iyi bir şey.","en":"It is a good thing that outer wall of it still stands strong."},{"tr":"Bugün Kolezyum, Roma'nın en popüler turistik yerlerinden biridir.","en":"Today, the Coliseum is one of Rome’s most popular attractions."},{"tr":"Dünyanın her yerinden insanlar onu görmek için İtalya'ya geliyor.","en":"People from all over the world come to Italy so as to see it."},{"tr":"Papa, her Kutsal Cuma günü çevresinde büyük bir yürüyüşe çıkar.","en":"The Pope walks a big march around it every Good Friday."},{"tr":"Birçok kişinin bildiği bir semboldür.","en":"It is a symbol that many people know."},{"tr":"Bir madalyonun arkasında bile göründü.","en":"It has even appeared on the back of a coin."},{"tr":"Sanırım bu onu birçok insanın da istediği bir sembol yapıyor.","en":"I guess that makes it a symbol that many people want too."}]},{"id":"CK-017","no":17,"title":"Çöpler","level":1,"code":"DOG","s":[{"tr":"Çöp kutuları sihirli portallar değildir.","en":"Garbage cans aren’t magical portals."},{"tr":"Çöp, bir teneke kutuya attığınızda kaybolmaz.","en":"Trash doesn’t disappear when you toss it in a can."},{"tr":"Sihirli çöp perileri yoksa, tüm bu pislikler nereye gidiyor?","en":"If there aren’t magical garbage fairies, where does all that trash go?"},{"tr":"Atıkları yönetmenin dört yöntemi vardır: geri dönüşüm, düzenli depolama, gübreleme ve yakma.","en":"There are four methods to manage waste: recycling, landfilling, composting, and incinerating."},{"tr":"Her yöntemin güçlü ve zayıf yönleri vardır.","en":"Each method has its strengths and weaknesses."},{"tr":"Her birine hızlıca bir göz atalım.","en":"Let’s take a quick look at each."},{"tr":"Geri dönüşüm, atıkları yeni malzemelere dönüştürme sürecidir.","en":"Recycling is the process of turning waste into new materials."},{"tr":"Örneğin kullanılmış kağıt, kitap kapakları yapmak için kullanılabilecek karton haline getirilebilir.","en":"For example, used paper can be turned into paperboard, which can be used to make book covers."},{"tr":"Bazıları atıkların toplanması, işlenmesi ve dönüştürülmesinin tasarruf ettiğinden daha fazla enerji kullandığına inanıyor.","en":"Some believe that being collected, processed, converted of waste use more energy than it saves."},{"tr":"Yine de çoğu insan geri dönüşümün gezegen için düzenli depolamadan daha iyi olduğu konusunda hemfikir.","en":"Even so, most people agree that recycling is better for the planet than landfilling."},{"tr":"Düzenli depolama, atıkları yönetmenin en eski yöntemidir.","en":"Landfilling is the oldest method of managing waste."},{"tr":"En basit şekliyle, çöplük, insanların çöpleri bir deliğe gömmesidir.","en":"In its simplest form, landfilling is when people bury garbage in a hole."},{"tr":"Çöp, deliğe atılmadan önce sıkıştırılır.","en":"Garbage is compacted before it is thrown into the hole."},{"tr":"Gübreleme, gıda atıkları gibi organik maddeleri biriktirmek ve onları ayrıştırmaktır.","en":"Composting is to pile up organic matter such as food waste and to decompose them."},{"tr":"Organik gübre mahsul yetiştirmek için toprağı daha zengin ve daha iyi hale getirmek için toprağa eklenir.","en":"Compost can be added to the soil to make the soil richer and better for growing crops."},{"tr":"Bazen çöpler karıştıktan sonra bunu yapmak zordur.","en":"Sometimes it’s hard to do after the garbage is mixed up."},{"tr":"Çünkü, plastik ve diğer inorganik malzemelerin gübre yığınından çıkarılması gerekir, aksi takdirde toprağı kirleteceklerdir.","en":"Because plastic and other inorganic materials must be removed from the compost pile, otherwise they will pollute the soil."},{"tr":"Çöpte çok fazla plastik var, bu da büyük ölçekte gübre yapmayı zorlaştırıyor.","en":"There is a lot of plastic in garbage, this makes it hard to compost on a large scale."},{"tr":"Yapması daha kolay olan bir şey çöp yakmaktır.","en":"One thing that is easier to do is burning garbage."},{"tr":"Atıkları yakmanın iki ana yolu vardır.","en":"There are two main ways to incinerate waste."},{"tr":"Birincisi, atıklardan metan gazı gibi bir yakıt oluşturmak veya toplamak ve yakıtı yakmaktır.","en":"The first is to create or harvest a fuel from the waste such as methane gas, and to burn the fuel."},{"tr":"İkincisi, atıkları doğrudan yakmaktır.","en":"The second is to burn the waste directly."},{"tr":"Yakma işleminden gelen ısı, buhar jeneratörlerine güç sağlayan suyu kaynatabilir.","en":"The heat from the incineration process can boil water, which power steam generators."},{"tr":"Maalesef yanan çöp havayı kirletiyor.","en":"Unfortunately, burning garbage pollutes the air."},{"tr":"Ayrıca, bazı eleştirmenler çöp yakma tesislerinin geri dönüştürülebilecek değerli kaynakları yok etmesinden endişe ediyor.","en":"Also, Some critics worry that incinerators destroy valuable resources that could be recycled."}]},{"id":"CK-018","no":18,"title":"Google","level":1,"code":"BLT","s":[{"tr":"Google, bağlantıları dikkate almaya başlayan ilk arama motoruydu.","en":"Google was the first search engine that began considering links."},{"tr":"Bağlantılar, üzerlerine tıkladığınızda sizi diğer sayfalara götüren mavi altı çizili kelimelerdir.","en":"Links are blue underlined words taking you to other pages when you click on them."},{"tr":"Google'ın kurucu ortağı Larry Page, bu bağlantıların nasıl bağlandığından anlamlı verilerin elde edilebileceğine inanıyordu.","en":"Larry Page, cofounder of Google, believed that meaningful data could be obtained from how those links connected."},{"tr":"Page, birçok bağlantılı web sitelerinin, az sayıdaki web sitelerine göre daha önemli olduğunu anladı.","en":"Page figured that websites with many links were more important than websites with few links."},{"tr":"Haklıydı.","en":"He was right."},{"tr":"Google'ın arama sonuçları rakiplerinden çok daha iyiydi.","en":"Google’s search results were much better than their rivals."},{"tr":"Yakında dünyanın en çok kullanılan arama motoru olacaklardı.","en":"They would soon become the World’s most used search engine."},{"tr":"Google'ın bu kadar beğenilmesine neden olan sadece harika arama sonuçları değildi.","en":"It wasn’t just the great search results caused Google to be so liked."},{"tr":"Ürünlerini sunma biçimleriyle de ilgiliydi.","en":"It was also about the way that they presented their products."},{"tr":"Diğer arama motorlarının çoğu dağınıktı.","en":"Most of the other search engines were very cluttered."},{"tr":"Ana sayfaları haber hikayelerinden hisse senedi fiyatlarına kadar her şeyle doluydu.","en":"Their homepages were filled with everything from news stories to stock prices."},{"tr":"Ancak Google'ın ana sayfası temizdi ve hala temiz.","en":"However, Google’s homepage was clean and is still clean."},{"tr":"Üzerinde logo, arama kutusu ve birkaç bağlantıdan başka bir şey yok.","en":"There is nothing on it but the logo, the search box, and a few links."},{"tr":"Neredeyse boş görünüyor.","en":"It almost appears empty."}]},{"id":"CK-019","no":19,"title":"Bal porsuğu","level":1,"code":"DOG","s":[{"tr":"Bir aslandan daha vahşi ama bir tazıdan daha küçük olan şey nedir?","en":"What’s wilder than a lion but smaller than a beagle?"},{"tr":"Bal porsuğu, Afrika ve Batı Asya'daki en sert memelilerden biridir.","en":"Honey badger is one of the hardest mammals in Africa and western Asia."},{"tr":"Bal porsukları sadece birkaç santimetre uzunluğundadır.","en":"Honey badgers are only a couple centimeters long."},{"tr":"Yine de, boyutlarından çok dayanıklıkları ile bilinirler.","en":"However, they have a reputation for durability than their size."},{"tr":"Bazı bal porsukları aslanları kovalar ve avlarını alır.","en":"Some honey badgers chase away lions and take their kills."},{"tr":"Sanırım bu size dövüşte önemli olan tek şeyin boyut olmadığını gösteriyor.","en":"I guess that shows you that size isn’t the only thing that matters in combat."},{"tr":"Bal porsuklarının uzun, keskin pençeleri vardır.","en":"Honey badgers have long, sharp claws."},{"tr":"Bu pençeler saldırı için iyidir ve kazmak için daha da iyidir.","en":"These claws are good for attacking and even better for digging."},{"tr":"Bal porsukları, doğanın en yetenekli kazıcılarından bazılarıdır.","en":"Honey badgers are some of most skilled diggers of nature."},{"tr":"Sert zemine yaklaşık 10 dakika içinde 9 metrelik bir tünel kazabilirler.","en":"They can dig a nine-meters tunnel into hard ground in about 10 minutes."},{"tr":"Kurbağa, kemirgen ve kobraların yuvalarını kazarak yemek yemeyi severler.","en":"They love eating a meal by digging the burrows of frogs, rodents, and cobras."},{"tr":"Ayrıca evlerini oluşturmak için kazma becerilerini kullanırlar.","en":"They also use their digging skills in order to create their houses."},{"tr":"Zemindeki küçük bölmelerde yaşarlar ve onları canı pahasına savunurlar.","en":"They live in small chambers in the ground and defend them fiercely."},{"tr":"Bir bal porsuğunun inini dürtecek kadar aptallarsa atlara, ineklere ve hatta su bufalolarına saldırırlar.","en":"They will attack horses, cows, and even water buffalo if they are foolish enough to poke around a honey badger’s den."}]},{"id":"CK-021","no":21,"title":"Sinekkuşu","level":1,"code":"DOG","s":[{"tr":"Hiç sinek kuşunun sesini duydun mu?","en":"Have you ever heard the sound of a hummingbird?"},{"tr":"Uçarken uğultulu bir ses çıkarırlar.","en":"They make a buzzing noise when they fly."},{"tr":"Bu sesi çok hızlı kanat çırptıkları için yapıyorlar.","en":"They make this noise because they beat their wings so fast."},{"tr":"Saniyede 80 defaya kadar kanat çırparlar.","en":"They beat their wings up to 80 times a second."},{"tr":"Tüm bu kanat çırpmaları çok fazla gürültü çıkarır.","en":"All that flapping makes a lot of noise."},{"tr":"Bu yüzden onlara sinek kuşları diyoruz.","en":"That’s why we call them hummingbirds."},{"tr":"Sinek kuşları benzersiz bir şekilde uçarlar.","en":"Hummingbirds fly in a unique way."},{"tr":"Kanatlarını o kadar hızlı hareket ettirirler ki havada asılı kalabilirler.","en":"They move their wings so fast that, they can hover."},{"tr":"Bu, helikopter gibi havanın ortasında bir noktada kalabilecekleri anlamına gelir.","en":"This means that they can stay in one spot in the middle of the air, like a helicopter."},{"tr":"Bazen uçarlar veya ters dönerler.","en":"Sometimes they fly or hover upside down."},{"tr":"Geriye doğru uçan tek kuş onlardır.","en":"They are the only bird that flies backward."},{"tr":"Sinek kuşları küçüktür.","en":"Hummingbirds are small."},{"tr":"Arı sinekkuşu adı verilen bir tür, dünyadaki en küçük kuştur.","en":"One type called the bee hummingbird is the smallest bird in the World."},{"tr":"Sinek kuşları hızlı hareket eder.","en":"Hummingbirds move fast."},{"tr":"Onlar kadar hızlı hareket etmek çok fazla enerji gerektirir.","en":"This takes a lot of energy to move as fast as they do."},{"tr":"Bu, çok fazla yemek yemeleri gerektiği anlamına gelir.","en":"This means that they need to eat a lot of food."},{"tr":"En sevdikleri yiyecek, bazı çiçeklerin içinde tatlı bir sıvı olan nektardır.","en":"Their favorite food is nectar, a sweet liquid inside of some flowers."},{"tr":"Günlük nektardan kendi ağırlıklarından fazlasını içerler.","en":"They drink more nectar than their own weight daily."},{"tr":"Sinek kuşları da çiçeklere yardım eder.","en":"Hummingbirds help flowers too."},{"tr":"Beslendiklerinde kafalarına ve gagalarına polen dökülür.","en":"Pollen is poured on their heads and bills."},{"tr":"Çiçekler tohum yapmak için polen kullanır.","en":"Flowers use pollen to make seeds."},{"tr":"Sinek kuşları, polenlerin bir çiçekten diğerine geçmesine yardımcı olur.","en":"Hummingbirds help pollen to get from one flower to the next."}]},{"id":"CK-022","no":22,"title":"Metal dedektörü","level":1,"code":"BLT","s":[{"tr":"Hiç sahile gittiniz mi?","en":"Have you ever been to the beach?"},{"tr":"Yere uzun bir direği doğrultan kulaklıklı bir adam gördünüz mü?","en":"Did you see a man with a headset pointing a long pole at the ground?"},{"tr":"Öyleyse, metal detektörü kullanan bir kişi görmüş olabilirsiniz.","en":"If so, you might have seen a person using a metal detector."},{"tr":"İnsanlar metal bulmak için bu cihazları kullanır.","en":"People use these devices to find metal."},{"tr":"İlk metal detektörlerinin madencilere yardım etmesi amaçlandı.","en":"The first metal detectors were purposed to help miners."},{"tr":"Onlar büyüktü.","en":"They were big."},{"tr":"Çok paraya mal oluyorlardı.","en":"They cost much money."},{"tr":"Çok fazla güç kullandılar.","en":"They used a lot of power."},{"tr":"Ve en kötüsü, iyi çalışmadılar.","en":"And worst of all, they didn’t work well."},{"tr":"İnsanlar onları daha iyi hale getirmeye çalıştı.","en":"People tried to make them better."},{"tr":"Metal dedektörleri küçüldü.","en":"Metal detectors got smaller."},{"tr":"Şimdi hafif ve ucuzlar.","en":"Now they are light and cheap."},{"tr":"Ayrıca daha iyi çalışıyorlar.","en":"They also work better."},{"tr":"Bu yüzden insanlar onları sahile getiriyor.","en":"Hence people bring them to the beach."},{"tr":"Suda yüzük arayabilirler.","en":"They can look for a ring in the water."},{"tr":"Kumda telefon arayabilirler.","en":"They can look for phone in the sand."},{"tr":"Metal dedektörleri bunları bulmalarına yardımcı olur.","en":"Metal detectors help them find these things."},{"tr":"Genelde çöp bulurlar.","en":"They usually find junk."},{"tr":"Metal dedektörleri de insanları korur.","en":"Metal detectors also protect people."},{"tr":"Silahları bazı yerlerden uzak tutmaya yardımcı olurlar.","en":"They help to keep guns out of some places."}]},{"id":"CK-023","no":23,"title":"İlk gökdelenler","level":3,"code":"TAR","s":[{"tr":"İlk gökdelenler, 1884 ile 1945 yılları arasında, ağırlıklı olarak New York ve Chicago'daki Amerikan şehirlerinde inşa edilmiş bir dizi yüksek ticari binalardı.","en":"The early skyscrapers were a range of tall commercial buildings built predominantly in the American cities of New York and Chicago between 1884 and 1945.. They help to keep guns out of some places."},{"tr":"Amerika Birleşik Devletleri'ndeki şehirler geleneksel olarak alçak binalardan oluşuyordu, ancak İç Savaş'tan sonra önemli ekonomik büyüme ve artan kentsel alan kullanımı, 1870'lerden başlayarak daha yüksek binaların gelişimini teşvik etti.","en":"Cities in the United States were traditionally made up of low-rise buildings, but significant economic growth and increasing use of urban land after the Civil War encouraged development of taller buildings beginning in the 1870s."},{"tr":"Teknolojik gelişmeler, asansör ve elektrikli aydınlatma gibi yeni buluşlarla donatılmış, derin temellere sahip yanmaz demir çerçeveli yapıların inşasına olanak sağladı.","en":"Technological improvements enabled the construction of fireproofed iron-framed structures with deep foundations equipped with new inventions such as the elevator and electric lighting."},{"tr":"Bunlar, hem teknik hem de ticari olarak yeni sınıf yüksek binalar inşa etmeyi uygun hale getirdi; bunlardan ilki olan Chicago'nun 42 m yüksekliğindeki Ev Sigorta Binası 1885'te açıldı.","en":"These made it both technically and commercially suitable to build a new class of taller buildings; the first of which, Chicago’s 42 m tall Home Insurance Building, opened in 1885."},{"tr":"Sayıları hızla arttı ve 1888'de gökdelenler olarak adlandırılıyorlardı.","en":"Their numbers grew rapidly, and they were being labelled skyscrapers in 1888."}]},{"id":"CK-024","no":24,"title":"Hillary Clinton","level":3,"code":"POR","s":[{"tr":"Hillary Clinton kesinlikle kendi kuşağındaki birçok Amerikalı kadının hayallerinin vücut bulmuş halidir.","en":"Hillary Clinton is certainly the incarnation of the dreams of many American women of her generation."},{"tr":"\"Her şeye\" sahip: bir aile, iyi bir kariyer ve sadece onu destekleyen ve yaptığı şeyi onaylayan değil, aynı zamanda yeteneklerini sonuna kadar kullanmasına imkân veren bir koca.","en":"She has got everything: a family, a good career, and a husband who not only supports her and approves of what she does but also allows to use her talents to the full."},{"tr":"Hillary ile ilk kez Yale Hukuk Fakültesi'nde tanışan yakışıklı genç Bill Clinton, çapkın namına rağmen, aslında döneminin en parlak öğrencilerinden biriydi.","en":"Bill Clinton, a good looking young man, who first met Hillary at Yale Law School was actually one of the brightest students in his year in spite of his womanizer reputation."},{"tr":"Efsane, Bill’in en sonunda Hillary'yi çok iyi konuştuğu için \"fark ettiğini\" söylüyor.","en":"Legend says that Bill finally noticed Hillary Because she spoke very well."},{"tr":"Hillary, ünlü Watergate duruşmalarına katıldığı Washington'da parlak bir avukat oldu.","en":"Hillary became a brilliant lawyer in Washington, where she took part in the famous Watergate hearings."},{"tr":"Birkaç büyük avukat firması onlara katılmasını istese de, 1973'te Washington'dan ayrılmaya ve Arkansas'ta Bill'e katılmaya karar verdi.","en":"Though several major firms of lawyers asked her to join them, she decided to leave Washington in 1973 and join Bill in Arkansas."},{"tr":"1975'te evlendiler ve Hillary, Little Rock'ta bir avukat firmasına katıldı.","en":"They got married in 1975, and Hillary joined a firm of lawyers in Little Rock."},{"tr":"Görünüşünü de değiştirdi, çok daha şık giyinmeye başladı, yeni bir saç modeli aldı ve gözlüklerini lenslerle değiştirdi.","en":"She also changed her look, started to dress much more smartly, got a new hairstyle and replaced her glasses with lenses."},{"tr":"Washington'a hazırdı.","en":"She was ready for Washington."}]},{"id":"CK-025","no":25,"title":"Şükran Günü","level":3,"code":"TAR","s":[{"tr":"Şükran Günü, belki de Amerika'nın en değerli festivalidir.","en":"Thanksgiving is perhaps America’s most precious festival."},{"tr":"Pek çok ülkede herkesin çok yemek yediği günler varken, sadece Amerikalıların yeterince yemek yemeyi kutladıkları bir gün vardır.","en":"While many countries have days when everyone eats a lot, only the Americans have a day on which they celebrate eating enough."},{"tr":"Belki de bugün sakinleri dünyanın en iyi beslenenleri arasında olan bir ülkede bu oldukça gereksiz görünebilir; ancak Şükran Günü Amerikalılara durumun her zaman böyle olmadığını hatırlatır.","en":"Perhaps this may seem rather superfluous in a country whose inhabitants are among the best-fed in the world today; but Thanksgiving reminds Americans that this isn’t always the case."},{"tr":"Şükran Günü, Amerika Birleşik Devletleri'ndeki Kızılderili olmayan en eski gelenektir ve ilk olarak 1621 yılında kutlanmıştır.","en":"Thanksgiving is the oldest non-Indian tradition in the United States, was first celebrated in the year 1621."},{"tr":"İlk New England kolonilerinden biri olan Plymouth'taki erkekler ve kadınlar o yıl içinde, çiftçilik yılının sonunu kutlamak için bir bayram günü kurmaya karar verdiler.","en":"It was in that year that the men and women in Plymouth, one of the first New England colonies, decided to establish a feast day to celebrate the end of the farming year."},{"tr":"Dindar Protestanlar olarak bayram günlerine, insanların yetiştirmeyi ve hasat etmeyi başardıkları mahsulleri kutlayıp Tanrı'ya şükredebilecekleri bir gün olan \"Şükran Günü\" adını verdiler.","en":"As devout Protestants, they called their feast day “Thanksgiving”, a day on which people could celebrate the crops they managed to grow and harvest and give thanks to God."},{"tr":"Bu aslında orijinal bir fikir değildi, ancak mahsuller içeri girdiğinde insanların Tanrı'ya şükrettikleri eski bir gelenek olan İngiliz \"Hasat Festivali\" ne dayanıyordu.","en":"This wasn’t in fact an original idea, but was based on the English “Harvest Festival”, an old custom that people gave thanks to God when the crops were all in."}]},{"id":"CK-026","no":26,"title":"İnsan Beyni ve Tatil","level":3,"code":"SAG","s":[{"tr":"İnsanların niçin tatil yaptığına dair birçok yanıltıcı neden var.","en":"There are many misleading reasons as to why people take holidays."},{"tr":"Ancak bunun nedeninin, silindir şapkaların gelişmesinin derin bir sosyolojik analiziyle ve aynı zamanda insanların iş ve boş zamanlarını kontrol eden ve yönlendiren çürüyen sistemlerle ilgisi yoktur.","en":"However, the reason of this has nothing to do with a deep sociological analysis of tile developing and at the same time, decaying systems that control and direct people’s work and leisure."},{"tr":"Planlayıcıların farklı \"boş zaman arama\" tarzlarını kataloglamaya olan düşkünlükleri veya potansiyel talebi ölçmek ve karşılamak için yaptıkları çaresiz girişimler ile hiçbir şekilde ilişkili değildir.","en":"It is in no way related to the planners’ fondness for cataloguing different styles of \"leisure-seeking\" or their desperate attempts to measure and satisfy potential demand."},{"tr":"Sebep bundan çok daha kolaydır ve Bireyin ruhunda gizlidir.","en":"The reason is much easier than this and is hidden in the Individual’s psyche."},{"tr":"İnsan beyni monotonluğu reddetmeye programlanmıştır.","en":"The human brain is programmed to reject monotony."}]},{"id":"CK-027","no":27,"title":"Mars’taki yeni renkli ışıklar","level":3,"code":"BLT","s":[{"tr":"Mars'ın bir teleskopla dikkatlice incelenmesi, düzensiz şekillenmiş bir dizi koyu mavi-yeşil işaret ortaya çıkarıyor.","en":"A careful study of Mars through a telescope reveals a number of irregularly shaped dark blue-green marks."},{"tr":"Bunlar, çok az kalıcı Mars haritalarına eklenmiş ve özellikleri adlandırılmıştır, ancak şekil veya görünüm olarak tam sabit değildirler.","en":"These were added to very few permanent Martian maps and their features were named, but they aren’t exactly constant in shape or appearance."},{"tr":"Özellikle, kutup zirvelerinin erimesi ile zamanla Mars'ta değişen mevsimlerle bir renk değişimi gösterirler.","en":"In particular, they show a variation of colour with the changing seasons on Mars in time with the melting of the polar caps."},{"tr":"Bu işaretleri açıklamak için öne sürülen birçok hipotez vardır, kutup zirvelerinden gelen nem onlara ulaştıkça renk değiştiren minerallerden oluşmaları buna bir örnektir.","en":"There are many hypotheses put forward to explain these marks, as the moisture from the polar caps reaches them, an example of which is that they are composed of minerals that change colour."},{"tr":"Ama bilim insanlarına göre en makul açıklama, onların kısa Mars yazında gelişen bitki örtüsü olmalarıdır.","en":"However, according to scientists, the most reasonable explanation is to be vegetation that flourishes in the short Martian summer."}]},{"id":"CK-028","no":28,"title":"Tezgahtarlık deneyimim","level":3,"code":"GNL","s":[{"tr":"Yaz boyunca büyük bir mağazanın giyim bölümünde geçici şekilde tezgâhtar olarak çalışmanın unutulmaz bir deneyimini yaşadım.","en":"During the summer, I had the unforgettable experience of working temporarily as a shop assistant in the dress department of a large store."},{"tr":"Sabahları gelen önemli bayan müşteriler bütün günü alışveriş yaparak geçirenlerdi.","en":"The important female customers who arrive in the mornings spent the whole day by shopping."},{"tr":"Bir elbiseyi ne kadar çok sevseler de, geldikleri ilk mağazadan satın alma fikrinden hiç hoşlanmıyorlardı ve onlar için bir kenara koyulup koyulamayacağını soruyorlardı.","en":"However much they liked a dress, they never liked the idea of buying at the first shop they had come into and asked me if it could be put aside for them."},{"tr":"Bitmek bilmeyen başka dükkanların etrafında dolaştıktan sonra, \"bizimkinde yeniden göründüklerinde, bu arada elbiseyi başka bir müşteriye satsaydım, aşırı derecede rahatsız olurlardı.","en":"After they went round endless other shops, when they reappeared at ours, if I sold the dress to another customer, they would be extremely irritated in the meantime."}]},{"id":"CK-029","no":29,"title":"Ne tip sabah insanısınız?","level":1,"code":"GNL","s":[{"tr":"Ne tip sabah insanısınız?","en":"What kind of morning person are you?"},{"tr":"Sabah neye benziyorsun?","en":"What are you like in the morning?"},{"tr":"Nasıl davranıyorsun?","en":"How do you behave?"},{"tr":"Muhtemelen şu üç türden birine dahilsiniz: sabahlardan nefret edenler, onlarla uyuyanlar veya onlardan hoşlananlar.","en":"You probably belong to one of the following three types: those who hate mornings, those who sleep through them or those who like them."},{"tr":"Sabahlardan nefret edenler genellikle \"somurtkan tip\" olarak adlandırılır.","en":"Those who hate mornings are often called “grumps”."},{"tr":"Somurtkan kimse sabah uyanmaktan nefret eder ve onları uyandırmaya çalışırsanız şikayet eder ve sizi kıvrandırırlar.","en":"Grumps hate waking up in the morning and if you try to wake them up, they complain and make you suffer."},{"tr":"İkinci tip sabah insanı, her zaman \"bana bir dakika daha ver\" diyen ve ardından \"bir dakika daha\" uyku alarmıyla 30 veya 40 dakikaya uzatan türdür.","en":"The second type of morning person is the kind who always says “give me just another minute” and then stretches “another minute” into 30 or 40 minutes with a snooze alarm."},{"tr":"Son tip sabah insanı en sinir bozucudur çünkü aslında sabahları sever.","en":"The last kind of morning person is the most annoying because she actually likes mornings."},{"tr":"Onun için çalar saate gerek yok.","en":"For her, there is no need for an alarm clock."},{"tr":"Her zaman erken kalkar, parlak gözlüdür ve yeni bir günle yüzleşmekten mutluluk duyar.","en":"She always gets up early, she is bright-eyed and happy to face a new day."}]},{"id":"CK-030","no":30,"title":"Benim sabahım","level":2,"code":"GNL","s":[{"tr":"Yataktan çıkacak gibi görünmüyorum.","en":"I can’t seem to get out of bed."},{"tr":"Çalar saatin çaldığını duyduğumda, hastalık yüzünden işyerine gelmeyeceğimi belirtmek veya en azından geç kalacağımı söylemek gibi her türlü olasılığı düşlüyorum.","en":"When I hear the alarm clock ring, I imagine all kind of possibilities, such as calling in ill or at least saying I’ll be late."},{"tr":"Ancak pratik bir insan olarak bir şekilde yataktan kalkıp işe gidiyorum.","en":"However, as a practical person, I somehow get out of bed and go to work."},{"tr":"Bunu nasıl yapıyorum?","en":"How do I do it?"},{"tr":"Sabah sorunuma birkaç çözüm buldum.","en":"I have found a few solutions to my morning problem."},{"tr":"Öncelikle hafta içi her gece erken yatıyorum, böylece bolca uyku alabiliyorum.","en":"First of all, I go to sleep early every weekday night, so that I can get plenty of sleep."},{"tr":"Çoğu insan sadece altı ila sekiz saat uykuya ihtiyaç duysa da, sekiz ila dokuz saatin benim için daha iyi olduğunu buldum.","en":"Though most people only need six to eight hours of sleep, I have found that eight to nine hours is better for me."},{"tr":"Yeterince uyuduğumda dinlenmiş hissediyorum ve hatta daha iyi bir modda olurum.","en":"When I get enough sleep, I feel rested, and I’m even in a better mood."},{"tr":"İkinci olarak, öğle yemeği sandviçlerimi yapmak ve ertesi sabah giyeceğim kıyafetleri çıkarmak gibi her şeyi bir gece önce hazırlıyorum.","en":"Secondly, I prepare everything before a night, such as making my lunch sandwiches and putting out the clothes that I’m going to wear next morning."},{"tr":"Ancak, her zaman sabaha bıraktığım bir şey vardır - duş almak; sabah duşum daha hızlı uyanmama yardımcı oluyor.","en":"However, there is always one thing that I leave for the morning – taking a shower; my morning shower helps me wake up faster."},{"tr":"Aslında, sabah kalktığımda dört gözle beklediğim tek şey duştur.","en":"Actually, when I get up in the morning, the shower is the only thing that I look forward to."},{"tr":"Son olarak, çalar saati 30 dakika ileri ayarlarım, böylece kestirmek için 30 dakikam olacaktır.","en":"Finally, I set the alarm clock 30 minutes ahead, so I’ll have 30 minutes to snooze."},{"tr":"Bu fazladan kestirme süresi bana geç uyuyormuşum gibi hissettiriyor.","en":"That extra snoozing time makes me feel as though I’m sleeping late."},{"tr":"Bu üç basit adım bana çok yardımcı oldu.","en":"These three simple steps have helped me a lot."},{"tr":"İster inanın ister inanmayın, son iki haftadır tam zamanında işe bile geldim.","en":"Believe it or not, I have even come to work on time for the last two weeks."}]},{"id":"CK-031","no":31,"title":"San Francisco Gezisi","level":2,"code":"GNL","s":[{"tr":"Ayşe, Temmuz ayında California, San Francisco'da yaşayan arkadaşlarını ziyaret etti.","en":"In July, Ayşe visited her friends who live in San Francisco, California."},{"tr":"Bu, Ayşe'nin şehre ilk gelişiydi ve etrafta dolaşma ve keşfetme fırsatlarının tadını çıkardı.","en":"This was Ayşe’s first time in the city, and she enjoyed her opportunities to walk around and explore."},{"tr":"Ayşe gezisinin ilk gününde Golden Gate Köprüsü'nü ziyaret etti.","en":"On the first day of her trip, Ayşe visited the Golden Gate Bridge."},{"tr":"Bu kırmızı asma köprü 2,7 km uzunluğundadır.","en":"This red suspension bridge measures 2.7 km in length."},{"tr":"Ayşe ve arkadaşları köprüden geçmediler.","en":"Ayşe and her friends didn’t walk across the bridge."},{"tr":"Ancak, onu yürüyüş parkurları, piknik alanları ve köprü ile şehrin muhteşem manzaralarını sunan Golden Gate Ulusal Eğlence Alanından seyrettiler.","en":"However, they viewed it from the Golden Gate National Recreation Area, which offers hiking trails, picnic areas, and spectacular views of the bridge and city."},{"tr":"Ayşe ve arkadaşları arka plandaki köprünün fotoğrafını burada çektiler, ertesi gün Ayşe ve arkadaşları Alcatraz Adası'nı ziyaret ettiler.","en":"Ayşe and her friends took the photo of the bridge in the background here, the next day, Ayşe and her friends visited Alcatraz Island."},{"tr":"Ayşe’nin tüm seyahatinin en sevdiği kısmı, onu San Francisco'nun tepelik sokaklarında yukarı ve aşağı taşımak için bir el arabası kullanmaktı.","en":"Ayşe’s favorite part of her entire trip was taking a trolley to transport her up and down the hilly streets of San Francisco."},{"tr":"Ayşe, son gününde şehir merkezinde çok alışveriş yaptı.","en":"Ayşe did a lot of shopping downtown on her last day."}]},{"id":"CK-032","no":32,"title":"Bitkiler","level":2,"code":"DOG","s":[{"tr":"Bitkiler olağanüstü canlılardır.","en":"Plants are extraordinary living things."},{"tr":"Basit görünseler de aslında bizden daha karmaşıklardır.","en":"Although they seem simple, they are actually more complicated than us."},{"tr":"Örneğin, tek bir yapraktan yepyeni bir bitki yetiştirilebilir.","en":"For instance, a brand new plant can be grown from just a single leaf."},{"tr":"Bunu hiçbir hayvan başaramaz!","en":"No animal can accomplish that!"},{"tr":"Bitkilerin tohumlarını dağıtma biçimleri de inanılmazdır.","en":"The way of the plants’ distributing their seeds is amazing too."},{"tr":"Bitkiler kabuklarından tohum atabilir, onları rüzgarla uçurabilir veya hayvanların kürküne tohum iliştiren dikenler yetiştirerek her yere yeni nesilleri yayabilirler.","en":"Plants can shoot seeds from their pods, send them flying on the wind, or spread new generations everywhere by growing spines that attach seeds to animals’ fur."},{"tr":"Bitkiler ayrıca inanılmaz derecede uyumludur ve hem sıcak hem de soğuk imkansız ortamlarda bile büyümenin yollarını bulurlar.","en":"Plants are also amazingly adaptable, and find ways to grow even in impossible environments, both hot and cold."},{"tr":"Bitkiler kendi besinlerini güneş ışığından üretir, topraktan besinleri emer ve böcekleri kandırarak polenlerini yayarlar.","en":"Plants manufacture their own food from sunlight, Absorb nutrients from the grounds, and spread their pollen by fooling insects."},{"tr":"Gerçekten, bunlar doğanın en iyi yaratılışlardan bazılarıdır.","en":"Truly, They are some of nature’s finest creations."}]},{"id":"CK-033","no":33,"title":"Hayat Ağacı","level":3,"code":"DOG","s":[{"tr":"Ağaçların çevreye faydaları bilinen gerçeklerdir.","en":"He benefits of trees to the environment are well-known facts."},{"tr":"Ağaçların yaprakları, fotosentez olarak bilinen bir işlem sırasında karbondioksit alarak ve ardından oksijeni serbest bırakarak havanın temizlenmesine yardımcı olur.","en":"Leaves of trees help clean the air by taking in carbon dioxide and then releasing oxygen during a process known as photosynthesis."},{"tr":"Ağaçların kök sistemleri, toprak erozyonunu ve su baskınını caydırmanın yanı sıra suyu korumada önemli bir rol oynar.","en":"The root systems of trees play an important role in conserving water, as well as deterring soil erosion and flooding."},{"tr":"Çevreye olan faydalarının yanı sıra, bilim insanları artık ağaçların sağlığımız üzerinde doğrudan bir etkisini gözler önüne seriyorlar.","en":"In addition to benefits to the environment, scientists are now revealing that trees have a direct effect on our health."},{"tr":"Ağaçlar, astım gibi sağlık sorunlarına katkıda bulunan kirliliği filtreler.","en":"Trees filter pollution that contributes to health problems such as asthma."},{"tr":"Çalışmalar, araba kullanılan yol boyu ağaçlarla kaplandığında sürüşle ilgili stresin azaldığını göstermiştir.","en":"Studies have shown that stress associated with driving is reduced when the road driven along is lined with trees."},{"tr":"Ağaçlar hayatımıza getirdikleri güzelliklerden dolayı popülerdir, ancak bir ağacın altında oturmaktan aldığımız huzur duygusu genel sağlığımız üzerinde daha doğrudan ve olumlu bir etkiye sahip olabilir.","en":"Trees are popular owing to the beauty they bring into our lives, but the sense of tranquillity that we get from sitting under a tree may have a more direct and positive effect on our general health."}]},{"id":"CK-034","no":34,"title":"USK Vadisi Yürüyüşü","level":2,"code":"GNL","s":[{"tr":"Yürüyüşümüze Usk Köprüsü'nde başladık.","en":"We started our hike at the Usk Bridge."},{"tr":"Oradan, Park Farm'ı dolaştık ve ardından eski madencilerin yoluna ulaşana kadar Monmouthshire ve Brecon Kanalı boyunca kısa bir mesafe yürüdük.","en":"From there, we walked around Park Farm and then we walked a short distance along the Monmouthshire and Brecon Canal until we reached the old miners’ path."},{"tr":"Bu patikayı takip ettik ve dik yamaçtan çıkmaya başladık.","en":"We took this path and began to ascend the steep hillside."},{"tr":"Yol, yerel olarak 'Yalnız Çoban' olarak bilinen zirveye ve bir kaya sütununa çıktı.","en":"The path led to the summit known as “Lonely Shepherd” and a pillar of rock."},{"tr":"Bu noktadan Usk vadisinin harika bir manzarasını gördük.","en":"From this stop, we saw a wonderful view of the Usk valley."},{"tr":"Doyurucu bir öğle yemeği yedikten sonra orman patikasının yanındaki vadiye geri döndük.","en":"After eating a filling lunch, we came back into the valley by the forest trail."},{"tr":"Birdenbire, bütün gün yağmurla bizi korkutan kara bulutlar gök gürültüsüyle çıngırdadı ve gökler açıldı.","en":"Suddenly, the black clouds intimidating us with rain all day rattled with thunder and heavens opened."},{"tr":"Yağmur şiddetli olduğu için eski bir çoban kulübesine sığındık.","en":"As the rain was torrential, we took shelter in an old shepherd’s hut."},{"tr":"Yağmura doymuş bir şekilde oturup sohbet ettik ve yağmurun hafiflemesini bekledik ama şiddetli yağmur yağmaya devam etti.","en":"Saturated with rain, we sat and chatted, and we waited for the rain to ease, but the heavy rain continued to fall."},{"tr":"Başka seçeneğimiz kalmadan bitişte sıcakcık bir ateş ve içeceği dört gözle bekleyerek yürüyüşümüze devam ettik.","en":"Without having any other option, we continued our hike, looking forward to a warm fire and a drink at the finish."}]},{"id":"CK-035","no":35,"title":"Mavi Kızılgerdan’ın Hikayesi","level":3,"code":"DOG","s":[{"tr":"Ekim ayında binlerce kuş gözlemcisi, orada görülen nadir bir kuşu görmek umuduyla bir sahil beldesine akın etti.","en":"A thousand bird watchers flocked to a coastal resort with a view to see a rare bird seen there in October."},{"tr":"Son zamanlarda olağanüstü hava koşulları sonucu Minsmere doğa koruma bölgesinde ortaya çıkan, Doğu'dan gelen birkaç kuştan biri olan Sibirya mavi Kızılgerdan’ı, 25 yıldır ilk kez İngiltere'de görüldü.","en":"A Siberian blue robin, one of a number of birds from the East, which appeared at the Minsmere nature reserve as a result of extraordinary weather recently, has been seen in Britain for the first time in 25 years."},{"tr":"Bir İngiliz kızılgerdanını andıran mavi ve beyaz kuşun, garip hava koşulları nedeniyle Çin'deki olağan kışı geçirme alanından 12.000 km uzak seyirde uçtuğu düşünülüyor.","en":"The blue and White bird, which resembles a a British robin, is thought that it has flown 12,000 km off course from its usual wintering ground in China Because of freak weather"},{"tr":"Kuşun son İngiliz gözlemi 1975'te Sark Kanal Adaları’ndaydı.","en":"The last British sighting of the bird was in the Channel Islands of Sark in 1975."},{"tr":"Daha olağan olan yaşam alanı, Çin ve Japonya ile birlikte eski Sovyetler Birliği'nin kapladığı alandır.","en":"Its more usual habitat is the area covering by the former Soviet Union together with China and Japon."},{"tr":"Son gözlemler böyle bir yansımaya neden oldu çünkü kuş gözlemcileri artık nadir kuşların görülmesi ile ilgili bilgileri iletmek için kapsamlı bilgi teknolojisi kullanıyor.","en":"The recent sighting has caused such a response because bird watchers now use extensive information technology to transmit information on sighting of rare birds."}]},{"id":"CK-036","no":36,"title":"Yükseklik Tehlikesi","level":3,"code":"SAG","s":[{"tr":"Emma Christoffersen, Avustralya'dan uzun bir uçuş yaptıktan birkaç dakika sonra bayıldığında yirmi sekiz yaşındaydı.","en":"Emma Christoffersen was twenty-eight years old when she collapsed a few minutes after taking a long flight from Australia."},{"tr":"Onun ölümü, uzun uçuşlar sırasında sağlıkla ilgili sorunlarla ilgili istatistikleri öne çıkardı.","en":"Her death highlighted the statistics concerning health-related problems during long flights."},{"tr":"Aslında, hava kazalarından çok uçuşlar sırasında sağlıkla ilgili olaylardan daha fazla insan ölüyor.","en":"In fact, more people die from health-related incidents during flights than from air crashes."},{"tr":"Araştırmalar, kötü hava kalitesinin, düşük oksijen seviyelerinin ve sıkışık oturma yerlerinin kalp krizlerini tetiklediğini ve giderek artan sayıda yolcu arasında bulaşıcı hastalıklara neden olduğunu gösteriyor.","en":"Studies Show that poor air quality, low oxygen levels and cramped seating trigger heart attacks and cause contagious diseases among gradually large number of passengers."},{"tr":"Sıkışık alanlarda uzun süre oturma, Emma'nın öldüğü derin damar trombozuna yol açabililen, özellikle bacaklarda ve alt karın bölgesinde kan pıhtılarına neden olabilir.","en":"Long periods of sitting in cramped quarters can cause blood clots, especially in the legs and lower abdomen, which can cause deep vein thrombosis, from which Emma died."},{"tr":"Havacılık Sağlık Enstitüsü, kabinlerin her üç dakikada bir havalandırılmasını tavsiye ediyor, ancak şu anda ortalama onda bir.","en":"The Aviation Health Institute advises that cabins must be ventilated every three minutes, but at present, the average is every ten."},{"tr":"Sağlıklarına yönelik riski en aza indirmek için, yolcuların uçuş sırasında bol bol su içmeleri ve egzersiz yapmaları tavsiye edilir.","en":"To minimize the risk to their health, passengers are advised to drink plenty of water and exercise during a flight."}]},{"id":"CK-037","no":37,"title":"Muhteşem AVMler","level":3,"code":"BLT","s":[{"tr":"Guinness Dünya Rekorlar Kitabı'na göre, 46 hektarlık bir alanda 4,5 milyon metrekareyi çevreleyen Kanada, West Edmonton AVM, dünyanın açık ara en büyüğüdür.","en":"According to Guinness Book of World Records, the West Edmonton Mall, Canada, encloses 4.5 million square meters on a 46-hectare site, is by far the largest in the world."},{"tr":"1990'ların başında açılan ve Amerika Birleşik Devletleri'nin bu türden en büyük merkezi olan Mall of America, selefi Torrance, California'daki Del Amo Moda Merkezi'nden iki kat daha büyüktür.","en":"The Mall of America, which opened in the early 1990s, the largest such center in the United States, is twice the size of predecessor, Del Amo Fashion Center in Torrance, California."},{"tr":"Bölgesel bir eğlence merkezi olarak tasarlanan, Knott's Berry Camp Snoopy adlı bir tema parkı etrafında tasarlanan bu alışveriş merkezi, hala West Edmonton Mall'dan bir milyon metrekare daha küçük.","en":"This mall designed as a regional entertainment center and designed around a theme park, Knott's Berry Camp Snoopy is still a million square meters than the West Edmonton Mall."},{"tr":"West Edmonton Mall'da 11 bölge mağazası dahil 800'den fazla mağaza ve 100'den fazla restoran ve atıştırmalık büfesi vardır.","en":"The West Edmonton Mall has more than 800 stores including 11 department stores, and more than 100 restaurants and snack bars."},{"tr":"Diğer cazibeleri şunları kapsar: 18 delikli minyatür golf sahası; plajları ve sörf yapmak için bir dalga makinesi bulunan kapalı bir su parkı; yunus su gösterisi; dünyanın en uzun su kaydıraklarından biri; su altı gezintileri için denizaltılar; boyut ayarlamalı bir hokey pisti; New Orleans'taki Bourbon Caddesi'nden sonra tasarlanan bir gece kulübü alanı; sinemalar; Kanada Fantasyland, yaklaşık 50 gezinti yolu olan bir eğlence parkı; bir hayvanat bahçesi; sanat sergileri; ve 360 odalı bir otel.","en":"Its other attractions include: an 18-hole miniature gold course; an indoor water park with beaches and a wave-making machine to surf; a dolphin water show; one of the world’s longest water slides; submarines for underwater trips; a regulation-sized hockey rink; a nightclub area designed after Bourbon Street in New Orleans; cinemas; Canada Fantasyland, an amusement park with nearly 50 rides; a zoo; art exhibits; and a 360-room hotel."}]},{"id":"CK-038","no":38,"title":"Su ürünleri yetiştiriciliği","level":3,"code":"DOG","s":[{"tr":"Gıda ve diğer ürünler için karada bitki ve hayvan yetiştiriciliği tarımdır.","en":"The growing of plants and animals on land for food and other products is agriculture."},{"tr":"Suda hayvan ve bitki yetiştirmek su ürünleri yetiştiriciliğidir.","en":"Raising animals and plants in the water is aquaculture."},{"tr":"Dünyanın birçok yerinde eski zamanlardan beri uygulanan su ürünleri yetiştiriciliği, Çin'in göletlerde sazan yetiştirme geleneği, İzlanda'da deniz yosununun hasat edilmesi ve işlenmesi ve bir Japon icadı - yapay inci kültürü gibi çok çeşitli etkinlikleri kapsamaktadır.","en":"Aquaculture practised since ancient times in many parts of the World includes such diverse activities as the Chinese tradition of growing carp in ponds, the harvesting and processing of seaweed in Iceland and the artificial culture pearls – a Japanese invention."},{"tr":"Su ürünleri yetiştiriciliği durgun suda veya akan suda, tatlı suda veya tuzlu suda gerçekleştirilebilir.","en":"Aquaculture can be taken place in still water or running water, fresh water or salt water."},{"tr":"Su ürünleri yetiştiriciliği uygulamaları hızla artmaktadır.","en":"The practice of aquaculture has been increasing rapidly."},{"tr":"Uzmanlar, 20. yüzyılın son çeyreğinde hasatlarda beş kat artış öngörüyorlar.","en":"Experts estimate a five-fold increase in harvests during the final quarter of the 20th century."},{"tr":"1970'lerde, Asya bu alandaki dünya üretiminin yaklaşık %85'ini oluşturuyordu.","en":"In the 1970s, Asia accounted for approximately 85% of World production in this field."},{"tr":"Sürülebilir arazi miktarı sınırlıdır ve her yerde azalmaktadır.","en":"The quantity of tillable land is limited and shrinking everywhere."},{"tr":"Su ürünleri yetiştiriciliği, dünyanın gıda tedarik sorunlarına olası bir çözüm olarak görülüyor.","en":"Aquaculture is regarded as one possible solution to the World’s food supply problems."}]},{"id":"CK-039","no":39,"title":"Çevresel savaş maliyetleri","level":3,"code":"DOG","s":[{"tr":"Çeyrek asırlık çatışma ve savaş, Afganistan'ı Dünya üzerinde çevreye en çok zarar veren ülkelerden biri haline getirdi ve şimdi Afganistan'ın çevresel bozulması, gelişmesine engel olarak görülüyor.","en":"A quarter century of conflict and war has rendered Afghanistan one of the most environmentally damaging nations on the Earth, and now Afghanistan’s environmental degradation is considered a stumbling block to its development."},{"tr":"Beş yıllık kuraklık ve asırlık bir kanal ağının tahrip edilmesi, birçok Afgan'ı temiz içme suyundan veya sulama suyundan mahrum bıraktı.","en":"Five years of drought and the destruction of a century-old canal network have left many Afghans without clean drinking water or water for irrigation."},{"tr":"BM raporu, geçen yıl bir milyondan fazla mültecinin Afganistan'a geri dönmesi gibi iyi haberlerin bile çevreye zarar verdiğini, büyük şehirleri egzoz gazlarıyla boğduğunu ve kanalizasyon sistemlerini zorladığını söylüyor.","en":"The UN report says that even the good news, such as the return of more than a million refugees to Afghanistan last year is damaging the environment, drowning big cities with exhaust gases and straining sewage systems."},{"tr":"Yetkililer, \"Şu anda bir karmaşa içindeyiz. Kuraklık, savaş, ihmal ve çevre konusunda halkın düşük anlayış seviyesi tüm bu sorunlara neden oldu. Bu yüzden şu anda ne şekilde olursak olalım müdahale etmeliyiz. \"dedi.","en":"The officials said that ‘right now, we are in a mess. The drought, the war, neglect and the low understanding level of people caused all these problems. So right now, we have to intervene in whatever way we can.’"}]},{"id":"CK-040","no":40,"title":"Zimbabwe’de Festival","level":3,"code":"TAR","s":[{"tr":"Zimbabwe'nin başkentinde, her yıl düzenlenen Harare Uluslararası Sanat Fetsivali, biraz tartışmalı şekilde sadece bir hafta süren koşunun ardından Pazar günü sona erdi.","en":"The annual Harare International Arts Festival, which is held in the capital of Zimbabwe, controversially ended on Sunday after the run that lasted only a week."},{"tr":"Festival, London Community Gospel korosunun son performansı vermesinin ardından bir umut mesajı vererek bir havai fişek gösterisi ile sona erdi.","en":"The festival ended with a fireworks display after London Community Gospel choir gave the final performance, delivering a message of hope."},{"tr":"Ekonomik ve politik kriz nedeniyle festivalin bu yıl yapılmaması gerektiğini düşünen bazı Zimbabveliler var.","en":"There are some Zimbabweans who think that the festival shouldn’t be held this year because of the economic and political crisis."},{"tr":"Bazıları festivali düzenlemenin Zimbabve'de her şeyin normal olduğuna dair bir mesaj gönderdiğini söylüyor.","en":"Some say that holding the festival sends a message that everything is normal in Zimbabwe."},{"tr":"Tartışmaya rağmen festivale mütevazı fiyatlı biletleri alabilen ve şehir merkezine gidecek yakıtı olan binlerce kişi katıldı.","en":"Despite the controversy, thousands of people who could afford the modestly priced tickets and had the fuel to go to the city centre attended the festival."},{"tr":"Zimbabwe'nin zor sorunları arasında %80 işsizlik oranı, temel malların kıtlığı ve ulusu bölen siyasi bir kriz yer alıyor.","en":"Zimbabwe’s difficult problems include an 80% unemployment rate, shortages of basic commodities, and a political crisis that is splitting the nation."},{"tr":"Ancak geçen hafta, Harare Uluslararası Sanat Festivali, en azından biraz dikkat dağıttı.","en":"However, last week, the Harare International Arts Festival provided, at least, some distraction."}]},{"id":"CK-041","no":41,"title":"Büyük Kanyon","level":2,"code":"DOG","s":[{"tr":"Doğanın en büyük oyma örneği olan Kuzey Arizona'daki Büyük Kanyon, dünyanın en görkemli kanyonudur.","en":"In Nothtern Arizona The Grand Canyon, nature’s greatest example of sculpture, is the most spectacular canyon in the world."},{"tr":"Colorado Nehri'nin yüksek platolarından geçen 446 kilometrelik bir geçittir.","en":"It is a 446-kilometer gorge that passes through high plateaus by the Colorado River."},{"tr":"Fantastik şekilleri ve renkleri ile dikkat çekiyor.","en":"It is noted for its fantastic shapes and colours."},{"tr":"Kanyonun duvarları içinde heybetli tepeler, kanyonlar ve vadiler duruyor.","en":"Within the the walls of the canyon, imposing hills, canyons and ravines stand."},{"tr":"Kanyonda birçok çeşit yaban hayatı vardır.","en":"The canyon has many varieties of wildlife."},{"tr":"Bol su bulunan kanyonun dibinde söğüt ağaçları ve pamuk ağaçları yetişir.","en":"Willow trees and cottonwoods grow at the bottom of the canyon where there is plenty of water."},{"tr":"Toprağın nemli ve derin olduğu kanyonun kuzey kenarında muhteşem ormanlar var.","en":"There are magnificent forests on the North rim of the canyon where the soil is moist and deep."},{"tr":"Çok sayıda kaktüs türü dahil olmak üzere kuraklığa dayanıklı bitkiler de vardır.","en":"There are also drought-resistant plants, including numerous species of cactus."},{"tr":"Avrupalılar tarafından Büyük Kanyon'un ilk görülmesi, 1540'daki Coronado keşif gezisine borçludur.","en":"The first sighting of the Grand Canyon by Europeans is credited to the Coronado expedition in 1540."},{"tr":"1869'da John Wesley Powell kanyondan geçen ilk partiyi organize etti.","en":"In 1869, John Wesley Powell organized the first party that went through the canyon."},{"tr":"Onun hesabı bir klasik Amerikan seyahati olmaya devam ediyor.","en":"His account continues to be a classic of American travel."},{"tr":"1870'lerde, bölge hakkında kapsamlı raporlar yayınlanıyordu.","en":"In the 1870s, extensive reports about the area were being published."}]},{"id":"CK-042","no":42,"title":"Pele, Futbol Efsanesi","level":3,"code":"SPO","s":[{"tr":"\"En saf haliyle futbol\", 1975'te bir Kuzey Amerika takımına katıldığında dünyanın en ünlü ve en yüksek maaşlı sporcusu olan Güney Amerika süperstarı Pele tarafından oynandı.","en":"Soccer ‘in its purest form’ was played by Pele a South American superstar who was the World’s most famous and highest-paid sportsman when he joined a North American team in 1975."},{"tr":"Brezilya milli futbol takımını 1958, 1962 ve 1970’de üç Dünya Kupası zaferine götürdü.","en":"He led the Brazilian national soccer team to three World Cup victories in 1958, 1962, and 1970."},{"tr":"Edson Arantes do Nascimento, 23 Ekim 1940'ta Brezilya'nın Tres Coracoes kentinde fakir bir ailede dünyaya geldi.","en":"Edson Arantes do Nascimento was born to a poor family in Tres Coracoes city of Brazil on October 23, 1940."},{"tr":"Gençken yerel bir küçük lig kulübü için oynamaya başladı.","en":"He began playing for a local minor-league club when he was a teenager."},{"tr":"Sahneye ilk çıkışını 1956'da Santos Futbol Kulübü ile yaptı.","en":"He made his debut with the Santos Soccer Club in 1956."},{"tr":"Pele, 1969'da 1.000'inci golünü attı.","en":"Pele scored his 1000th goal in 1969."},{"tr":"Efsanevi atlet 1974'te emekli oldu, ancak Kuzey Amerika Futbol Ligi'nin New York Cosmos'uyla üç yıllık 7 milyon dolarlık bir sözleşmeyi kabul ettikten sonra 1975'te bir geri dönüş yaptı.","en":"The legendary athlete retired in 1974, but he made a comeback in 1975 after he accepted a $7 million contract for three years with the New York Cosmos of the North American Soccer League."},{"tr":"Ortalama büyüklükte bir adam, hızı, mükemmel dengesi, muazzam görüşü, topu mükemmel bir şekilde kontrol etme yeteneği ve her iki ayağıyla ve başıyla güçlü ve doğru atış yapabilme yeteneği ile kutsanmıştı.","en":"An average-sized man, he was blessed with his speed, great balance, tremendous vision, the ability to control the ball superbly and the ability to be able to shoot powerfully and accurately either foot as well as with his head."},{"tr":"Kariyerinde 1.363 maçta oynadı ve 1.281 gol attı.","en":"In his career, he played in 1363 matches and scored 1281 goals."},{"tr":"En iyi sezonu, 139 gol attığı 1958'di.","en":"His best season was 1958 when he scored 139 goals."},{"tr":"1978'de Uluslararası Barış Ödülü'nün sahibi oldu ve 1980'de yüzyılın sporcusu seçildi.","en":"He had the International Peace Award in 1978, and he was selected athlete of the century in 1980."}]},{"id":"CK-043","no":43,"title":"Savaşçı kadınlar","level":3,"code":"TAR","s":[{"tr":"Arkeologlar, kadınların kılıç, hançer, yay ve oklarla gömüldüğünü tespit etti.","en":"Archeologists have detected that the women had been buried along with swords, daggers, bows, and arrows."},{"tr":"Arkeologların çoğu Sarmation göçebe kabilesinin mezarlarının izini sürerek en azından bazı kadın üyelerinin savaşçı olarak hizmet ettikleri sonucuna vardı.","en":"Most archaeologists came to the conclusion that at least some female members had served as warriors tracing the tombs of Sarmation nomadic tribe."},{"tr":"En etkileyici mezarlardan biri, bir hançerle ve içinde 40 bronz uçlu ok bulunan bir oklukla gömülen çarpık bacaklı bir genç kadındı.","en":"One of the most affective graves was that of a bowlegged young woman who had been buried with a dagger and a quiver containing 40 bronze-tipped arrows."},{"tr":"Kadının eğilmiş bacakları, yan tarafındaki silahlarla birleştiğinde, hem ata binme hem de okçuluk eğitimi aldığını ve belki de atlı savaşta yetenekli olduğunu gösteriyor gibiydi.","en":"The woman’s bent legs, when they combine with the weapons on her side, seemed to indicate that she was trained in both horse riding and archery, and perhaps skilled in equestrian warfare."},{"tr":"Bazı gözlemciler, kadın savaşçıların, Yunan tarihçi Herodot'un yazdığı güçlü kadın savaşçılar olan efsanevi Amazonlarla bir miktar ilişki içinde olduklarını öne sürdüler.","en":"Some observers have suggested that the female warriors had some relationship with the legendary Amazons who was powerful female warriors that the Greek historian Herodotus had written."}]},{"id":"CK-044","no":44,"title":"Samurai ordusunun sahibi","level":3,"code":"POR","s":[{"tr":"Kendi samuray ordusuna sahip bir romancıydı ve vücut geliştirmede çalışan bir entelektüeldi.","en":"He was a novelist who had his own samurai army, and he was an intellectual who worked at body-building."},{"tr":"Parlak Japon yazar Yukio Mishima, Japon geleneği ile kültürünün batılılaşması arasında hırpalanmış bir adamdı.","en":"The brilliant Japanese writer Yukio Mishima was a man torn between Japanese tradition and the westernization of his culture."},{"tr":"14 Ocak 1925'te Tokyo'da Hiraoka Kimitake olarak doğdu, ancak bir yetişkin olarak kitaplarını Yukio Mishima adıyla çıkardı.","en":"He was born as Hiraoka Kimitake in Tokyo on January 14, 1925, but as an adult, he published his books under the name Yukio Mishima."},{"tr":"Mishima'nın yazarlık kariyeri, ilk romanı ‘Bir Maskenin İtirafları’nın 1949'da yayımlanmasıyla başladı.","en":"Mishima’s writing career started with the publication of his first novel, ‘Confessions of a Mask’ in 1949."},{"tr":"Disiplinli ve büyük enerjili adam, genellikle gece yarısından sabaha kadar yazardı ve yaşamı boyunca romanlar, kısa hikayeler, senaryolar ve geleneksel Japon No ve Kabuki oyunları dahil olmak üzere 100'den fazla eser üretti.","en":"The disciplined and energetic man usually wrote from midnight to morning and in his lifetime, he produced more than 100 works, including novels, short stories, screenplays, and traditional Japanese No and Kabuki plays."},{"tr":"Son çalışması ‘Bereket Denizi’ modern Japonya'yı ayın çorak manzarasıyla karşılaştırıyor.","en":"His last work,‘Sea of Fertility’, compares modern Japan to the barren landscape of the moon."},{"tr":"Samuray geleneğini yeniden ele geçirmek için Mishima, Shield Society adlı özel bir ordu düzenledi.","en":"He organized a private army called Shield Society to recapture the samurai tradition."},{"tr":"25 Kasım 1970'te Mishima ve dört cemiyet üyesi, Tokyo'daki askeri karargahtaki bir ofisinin kontrolünü ele geçirdi.","en":"On November 25, 1970, Mishima and four society members took control of an office at military headquarters in Tokyo."},{"tr":"Japonya'nın 2. Dünya Savaşı sonrası anayasasına saldıran bir konuşma yaptı ve ardından intihar etti.","en":"He gave a speech attacking Japan’s post-World War II constitution and then committed suicide."}]},{"id":"CK-045","no":45,"title":"Evrenin gizemleri","level":3,"code":"BLT","s":[{"tr":"Evrenbilim, evrenin neye benzediğine dair bilimsel araştırmadır.","en":"Cosmology is the scientific study of what the universe is like."},{"tr":"Bilim insanları, gözlemlenebilir evrenin davranışıyla çelişmeyen varsayımlar yaparak, evreni kökeni ve geleceği de dahil olmak üzere bir bütün olarak tanımlamaya çalışan modeller veya teoriler oluştururlar.","en":"By making assumptions that aren’t contradicted by the behavior of the observable universe, scientists build models or theories that try to describe the universe as a whole, including its origin and future."},{"tr":"Kendisiyle çelişen bir şey bulunana kadar her modeli kullanırlar.","en":"They use each model until something that contradicts itself is found."},{"tr":"Daha sonra model değiştirilmeli veya atılmalıdır.","en":"Then the model must be modified or discarded."},{"tr":"Kozmologlar genellikle, küçük düzensizlikler dışında, evrenin, gözlemcilerin evrenin neresinde bulunduklarına bakılmaksızın tüm gözlemcilerle aynı görünüme sahip olduğunu varsayarlar.","en":"Cosmologists usually assume that the universe has the same appearance to all observers irrespective of where in the universe the observers are located, except for small irregularities."},{"tr":"Uzay sonsuz olmalı ve maddeyle eşit şekilde doldurulmalı ya da alternatif olarak uzayın geometrisi, tüm gözlemcilerin kendilerini merkezde görmelerini sağlayacak şekilde olmalıdır.","en":"Space must be infinite and evenly filled with matter, or alternatively, th geometry of space must be such that all observers see themselves at the centre."}]},{"id":"CK-046","no":46,"title":"Nasıl Kral Olunur?","level":3,"code":"POR","s":[{"tr":"Büyük bir askeri lider ve Prusya kralı olacak olan çocuk, kariyerine bir askerin hayatından nefret ederek başladı.","en":"The boy who was to become a great military leader and king of Prussia began his career hating the life of a soldier."},{"tr":"II Frederick, 24 Ocak 1712'de Berlin'de doğdu.","en":"Frederick II was worn in Berlin on January 24, 1712."},{"tr":"Babası Kral I. Frederick William'dı. Annesi, İngiltere Kralı II. George'un kız kardeşi, Hanover'li Prenses Sophia Dorothea idi.","en":"His father was King Frederick William I. His mother was Princess Sophia Dorothea of Hanover, sister of King George II of England."},{"tr":"Frederick'in babası, oğlu için pratik, askeri bir eğitimde ısrar etti.","en":"Frederick’s father insisted on a practical and military education for his son."},{"tr":"Çocuk, müzik, sanat ve edebiyatı tercih etti.","en":"The boy preferred music, art, and literature."},{"tr":"Babasının kraliyet ailesinin doğal zevkleri olduğuna inandığı tütüne, içkiye ve avlanmaya isyan etti.","en":"He rebelled against tobacco, drinking, and hunting which his father believed that they were pleasures of royalty."},{"tr":"Kral, prensin öğretmenlerinin kendisine Latince öğretmesini yasakladı, ancak onu ve klasikleri gizlice inceledi.","en":"The king forbid the prince’s teachers to teach him Latin, but he studied it and the classics in secret."},{"tr":"Frederick 18 yaşındayken, babasının tiranlığından firar ederek kaçmaya çalıştı.","en":"When Frederick was 18, he tried to escape from the tyranny of his father by running away."},{"tr":"Sınırı geçemeden yakalandı, bir süre hücre hapsinde kaldı.","en":"He was caught before he crossed the border, he was locked in solitary confinement for a time."},{"tr":"Hücresinin bir penceresinden, kaçışında kendisine eşlik eden en yakın arkadaşının infazını izlemek zorunda kaldı.","en":"From a window of his cell, he was forced to watch the execution of his closest friend, who had accompanied him in his flight."},{"tr":"Bu olaydan sonra genç Frederick değişti ve acımasız, kurnaz ve alaycı oldu.","en":"After this incident, young Frederick was changed, and became ruthless, crafty, and cynical."},{"tr":"Yavaş yavaş yaşlı kral oğluna daha büyük sorumluluklar verdi.","en":"Gradually the old king gave his son greater responsibilities."}]},{"id":"CK-047","no":47,"title":"İnternet","level":3,"code":"BLT","s":[{"tr":"İnternet, ABD ordusu tarafından araştırma yapmak için kullanılan bir sistem olarak ortaya çıktı.","en":"The Internet originated as a system used to research by the military of the USA."},{"tr":"Sisteme bağlanan sonraki grup üniversitelerdi.","en":"Universities were the next group that connected to the system."},{"tr":"İnternet, 1980'lerin sonunda ticari bir sistem olarak gelişmeye başladı ve 1990'ların ortalarında, ev kullanıcıları önemli sayıda internete bağlanmaya başladı.","en":"The Internet started to develop as a commercial system in the late 1980s, and in the mid-1990s, home users started to connect to the Internet in significant numbers."},{"tr":"İnternet kullanımı hala hızla artıyor ve çevrimiçi olarak geçirdiğimiz saat sayısı keskin bir şekilde artıyor.","en":"Internet usage is still growing quickly, and the number od hours we spend online is growing sharply."},{"tr":"Amerika Birleşik Devletleri internet kullanımında hala başı çekiyor, ancak Avrupa yetişiyor.","en":"The United States still leads the way in Internet usage, but Europe is catching up."},{"tr":"E-posta, İnternet'in en basit uygulamasıdır, ancak aynı zamanda hem işletmeler hem de kişisel kullanıcılar arasında en popüler olanıdır.","en":"E-mail is the simplest application of the Internet, but it is also the most popular with both businesses and personal users."},{"tr":"E-posta, formalite ve hız açısından telefonla faks arasında bir yere düşen, İnternet kullanarak iletişim kurmanın basit ve uygun maliyetli bir yoludur.","en":"E-mail is a simple and cost-effective way of communicating using Internet, falling somewhere between the phone and the fax in terms of formality and speed."},{"tr":"E-posta ucuzdur ve bir iletinin İnternete ulaşması yalnızca birkaç saniye sürer.","en":"E-mail is cheap and it only takes a few seconds for a message to reach the Internet."},{"tr":"Şu anda, bilgisayar, insanların İnternet'e bağlanmasının en yaygın yoludur, ardından cep telefonları ve TV setleri geliyor.","en":"At the moment, the computer is the most common way people connect to the Internet, followed by mobile phones and TV sets."}]},{"id":"CK-048","no":48,"title":"100’e kadar nasıl yaşanır","level":3,"code":"SAG","s":[{"tr":"Yaşlanma ve yaşam süresi büyük ölçüde bir türün genetik planı tarafından belirlendiğinden, çevreyi değiştirerek modifikasyon olasılıklarına dikkat çekilmiştir.","en":"Since aging and lifespan are broadly determined by the genetic plan of a species, attention has been directed the possibilities of their modification by altering the environment."},{"tr":"Biyolog Jacques Loeb, 20. yüzyılın başlarında meyve sineğinin yaşam süresinin sıcaklıktaki her 10 derecelik artışla yarı yarıya azaldığını gösterdi.","en":"The biologist Jacques Loeb showed that the life span of the fruit fly was halved by every 10-degree rise in temperature early in the 20th century."},{"tr":"Laboratuvar faresinde kalori alımının oldukça ciddi şekilde kısıtlanması, esas olarak olgunlaşmamışlık dönemini uzatarak, ömrünü iki katından fazla artırabilir.","en":"Fairly severe restriction of caloric intake in the laboratory rat can increase more than double its life span, chiefly by prolonging the period of immaturity."},{"tr":"Kalori kısıtlaması, şu ana kadar yaşlanma ve yaşam süresi üzerinde önemli bir etkiye sahip olduğu gösterilen tek faktördür.","en":"Caloric restriction is so far the only factor shown to have a major effect on aging and lifespan."},{"tr":"Ne yazık ki, gıda kısıtlamasının kemirgenler dışındaki türler üzerinde daha az etkisi vardır.","en":"Unfortunately, food restriction has less effect on species other than rodents."},{"tr":"Yetersiz beslenen insan popülasyonlarının daha uzun yaşadığı gösterilmemiştir, ancak bu tür gruplarda bulunan vitamin eksikliği, hastalık ve yetersiz tıbbi bakım analizi karmaşıklaştırmaktadır.","en":"It hasn’t been shown that undernourished human populations live longer, but vitamin deficiency, disease, and poor medical care found in such groups complicate the analysis."},{"tr":"Umut, insanın yaşamını engelleyen hastalık süreçlerini doğal yaşam süresinin sonuna kadar ortadan kaldırmaktır.","en":"The hope eliminates the disease processes that prevent human’s living to the end of their natural lifespan."}]},{"id":"CK-049","no":49,"title":"Hatalı uygulama","level":3,"code":"SAG","s":[{"tr":"Hukukta, hatalı uygulama, bir doktor, avukat veya muhasebeci gibi profesyonel bir kişi tarafından suistimal veya ihmal anlamına gelir.","en":"In law, malpractice refers to misconduct or negligence by a Professional person such as a doctor, lawyer, or accountant."},{"tr":"Bu tür bir suistimal, lisanslı bir profesyonelden beklenen beceri ve öğrenme düzeyini kullanamamayı içerir.","en":": Such misconduct includes not to use the level of skill and learning expected of a licensed professional."},{"tr":"Müşteriye veya hastaya yönelik hatalı uygulamanın sonucu, mesleki yetersizlik nedeniyle yaralanma, hasar veya bazı kayıplardır.","en":"The result of malpractice to the client or patient is injury, damage or some loss due to professional incompetence."},{"tr":"Geçerli bir tıbbi hatalı uygulama iddiası için resmi kriterler görev, ihlal, zararlar ve nedenselliktir.","en":"The official criteria for a valid medical malpractice claim are duty, breach, damages, and causation."},{"tr":"Hatalı uygulama kanıtı varsa, bir müşteri bir hukuk davasında dava açabilir ve para şeklinde tazminat talep edebilir.","en":"If there is evidence of malpractice, a client may sue in a civil action, and demand compensation in the form of money."},{"tr":"En çok dava açılacak olanlar cerrahlardır, çünkü hatalı uygulama, cerrahi bir operasyon yapıldığında ispatlanması çok daha kolaydır.","en":"Surgeons are the ones to be sued the most, because malpractice is much easier to prove when a surgical operation has been done."},{"tr":"Tıbbi hatalı uygulama eylemleri üç şey yapar: tıp mesleği için kalite kontrol sağlamak; yapılan zarar için bir miktar tazminat sağlamak; ve davacıya, şikayette bulunma ve tatmin edici bir yanıt alma yeteneğinin bir ölçüsü olan duygusal doğrulama vermek.","en":"Medical malpractice actions do three things: to provide quality control for the medical profession; provide some compensation for the harm done; and give emotional vindication which is a measure of her ability to make a complaint and receive a satisfactory response."}]},{"id":"CK-050","no":50,"title":"ABD'de kış sporları","level":3,"code":"SPO","s":[{"tr":"Her yerde soğuk olur, genellikle çok soğuk.","en":"Everywhere it gets cold, often very cold."},{"tr":"Kasım ayının sonunda, birçok Amerikan eyaleti genellikle karla kaplıdır; ve son kışlar daha az soğuk olmasına rağmen, kışın spor genellikle kar sporları veya kapalı mekan sporları anlamına gelir.","en":"By the end of November, many American states are often covered in snow; and although recent winters have been less cold, sport in winter usually means snow sports, or indoor sports."},{"tr":"Ocak ayına kadar, Kuzey Amerika'daki birçok insan -30 ° C sıcaklığa sahip olacak; elbette her gün değil, ama bu kadar düşük sıcaklıklar nadir değildir.","en":"By January, many people in North America will have temperature of -30 ° C; not every day of course, but such low temperatures aren’t rare."},{"tr":"Chicago ve Minneapolis'te sıcaklık -40 ° C'nin altına düşebilir.","en":"In Chicago and Minneapolis, the temperature can fall below -40 ° C."},{"tr":"Kuzey Amerika'nın ortasındaki geniş düz bölgelerde en popüler kış sporları kar motosikleti, kar ayakkabısıyla yürüyüş ve kros kayağıdır.","en":"In the large flat regions in the middle of North America, the most popular winter sports are snowmobiling, snow-shoeing and cross-skiing."},{"tr":"Buz pateni de popülerdir; göller ve nehirler donuyor ve birçok kasaba ve şehirde ücretsiz açık hava paten pistleri var.","en":"Ice-skating is popular too; lakes and rivers freeze, and many towns and cities have free open-air skating rinks."},{"tr":"Birçok yerde, hava karardıktan sonra bunlar ışıklandırılmıştır, böylece insanlar akşamları paten yapmanın keyfini çıkarabilir.","en":"In many places, these are floodlit after dark, so that people can enjoy skating in the evening."},{"tr":"Amerika'daki kayak merkezleri ile Avrupa'daki çoğu Alp tatil beldesi arasında büyük bir fark vardır: trafik!","en":"There is one big difference between American ski resorts and most Alpine resorts in Europe: traffic!"},{"tr":"Çoğu Amerikalı için kayak tatili, çoğu Amerikan şehri Rockies'ten çok uzakta olduğu için uçakla seyahat anlamına gelir.","en":"For most Americans, a skiing holiday means a trip by plane, as most American cities are a long way from the Rockies."},{"tr":"Amerikalılar uzun tatiller yapmazlar, bu yüzden birkaç günlerini Rocky Dağları'na sürerek geçiremezler.","en":"Americans don’t take long holidays, so they cannot spend several days driving to the Rockies."}]},{"id":"CK-051","no":51,"title":"İranlı Şair Firdevsî","level":3,"code":"POR","s":[{"tr":"Persia’nın en büyük şairi - şimdinin İran’ı - Firdawsi adıyla yazan Ebu El-Kasım Mansur'du.","en":"The greatest poet of Persia – now Iran – was Ebu El-Qasem Mansur, who wrote under the name Firdawsi."},{"tr":"Ülkenin ulusal destanı olan Krallar Kitabı'nı son haliyle yazdı.","en":"He wrote the country’s national epic, Book of Kings, in its final form."},{"tr":"Adamın kendisi hakkında çok az şey biliniyor.","en":"About the man himself, little is known."},{"tr":"En güvenilir bilgi kaynağı, Firdawsi'nin memleketi Tus'u ziyaret eden ve onun hakkında hikayeler toplayan 12. yüzyıl şairi Nezami-ye 'Aruzi'nin anlatımıdır.","en":"The most reliable source of information is an account by 12th-century poet, Nezami-ye 'Aruzi, who visited Firdawsi’s native village of Tus and collected stories about him."},{"tr":"Firdawsi, zengin bir toprak sahibinin oğlu olarak 935'te doğdu.","en":"Firdawsi was born in 935, as the son of a wealthy landowner."},{"tr":"Yaklaşık 60.000 beyit uzunluğundaki eser, aynı adı taşıyan bir düzyazı çalışmasına dayanıyordu, kendisi de en eski zamanlardan II. Hüsrev dönemine kadar 7. yüzyılda Pers krallarının tarihinin bir çevirisine dayanıyordu.","en":"The work, nearly 60.000 couplets long, was based on a prose work of the same name, itself a translation of a history of the king of Persia from the most ancient times to the reign of Khosrow II in the 7th century."},{"tr":"Krallar Kitabı, Pers dilindeki en popüler eserlerden biri olmaya devam etti.","en":"The Book of Kings has remained one of the most popular works in the Persian language."},{"tr":"Modern İranlılar bunu kolayca anlıyor çünkü yazıldığı dil modern Farsça ile bir ilişki taşıyor - Shakespeare İngilizcesi ile çağdaş İngilizce arasındaki ilişkiye benzer bir ilişkidir.","en":"Modern Iranians understand it easily because the language in which it was written bears a relationship to modern Persian – a relationship similar to that between Shakespearean English and contemporary English."}]},{"id":"CK-052","no":52,"title":"Atina’nın Efsanevi Kralı Theseus","level":2,"code":"TAR","s":[{"tr":"Yunan efsanesine göre Atina kralı Aegeus'un oğlu kahraman Theseus uzak bir diyarda doğmuş ve büyümüştür.","en":"According to Greek legend, the hero Theseus, the son of Aegeus, king of Athens, was born and brought up in a distant land."},{"tr":"Theseus birçok maceradan sonra Atina'ya vardığında, şehri derin bir yas içinde buldu.","en":"After many adventures, when Theseus arrived in Athens, he found the city in deep mourning."},{"tr":"Girit kralı Minos'a, yedi genç ve yedi bakirenin Minotaur tarafından yutulması için yıllık haraç göndermenin zamanı gelmişti.","en":"I was again time to send to Minos, king of Crete, the yearly tribute of seven youths and seven maidens to be devoured by the Minotaur."},{"tr":"Bu korkunç bir canavardı, yarı insan yarı boğaydı.","en":"This was a terrible monster, half-human and half-bull."},{"tr":"Theseus, canavarı öldürebileceğini umarak kendisini kurbanlardan biri olarak sundu.","en":"Theseus offered himself as one of the victims hoping that he would be able to slay the monster."},{"tr":"Girit'e vardığında kralın güzel kızı Ariadne ona aşık oldu.","en":"When he reached Crete, Ariadne, the beautiful daughter of the king, fell in love with him."},{"tr":"Minotaur'u öldürdüğü bir kılıç ve canavarın tutulduğu dolambaçlı labirentten çıkış yolunu bulabileceği bir iplik yumağı vererek ona yardım etti.","en":"She aided him by giving a sword, with which he killed the Minatour, and a ball of thread, with which he was able to find his way out of winding labyrinth where the monster was kept."},{"tr":"Theseus, babasına, görevini başarırsa, geri döndüğünde gemisine beyaz yelkenler çekeceğine söz vermişti; Ayrıldığında siyah yelkenleri vardı.","en":"Theseus had promised his father that if he succeeded in his quest, he would hoist white sails on his ship when he returned; it had black sails when he left."},{"tr":"Sözünü unuttu.","en":"He forgot his promise."},{"tr":"Kara yelkenleri gören Kral Aegeus, oğlunun öldüğünü düşünerek denize atladı.","en":"King, Aegeus, seeing the dark sails, thought his son was dead and jumped into the sea."},{"tr":"Deniz o zamandan beri onun onuruna Ege olarak anılıyor.","en":"The sea has been called the Aegean in his honour since."},{"tr":"Theseus, Atinalıların isyanı sırasında ihanetle öldürüldü.","en":"Theseus was killed by treachery during a revolt of the Athenians."},{"tr":"Daha sonra hafızasına büyük saygı duyuldu.","en":"Later his memory was held in great reverence."},{"tr":"M.Ö. 490'daki Maraton savaşında Atinalıların çoğu, ruhunun Perslere karşı onları yönlendirdiğini gördüklerine inanıyordu","en":"At the battle of Marathon in 490 BC, many of the Athenians believed that they saw his spirit leading them against the Persians."},{"tr":"Pers Savaşlarından sonra Delphi'deki kahin Atinalılara Theseus'un mezarını, öldürüldüğü Skyros adasında bulmalarını ve kemiklerini Atina'ya geri getirmelerini emretti.","en":"After the Persian Wars, the oracle at Delphi ordered the Athenians to find the grave of Theseus on the island of Skyros, where he had been killed, and to bring his bones back to Athens."},{"tr":"Kahinin talimatlarına uyuldu.","en":"The oracle’s instructions were obeyed."},{"tr":"MÖ 469'da Theseus'un kalıntıları Atina'ya geri taşındı.","en":"In 469 BC, the remains of Theseus were carried back in Athens."},{"tr":"Büyük kahramanın mezarı şehrin fakir ve mazlum halkı için bir sığınak haline geldi.","en":"The tomb of the great hero became a place of refuge for poor and oppressed people of the city."}]},{"id":"CK-053","no":53,"title":"Haymarket Olayı","level":3,"code":"TAR","s":[{"tr":"1 Mayıs 1886'da işçi sendikaları Amerika Birleşik Devletleri'nin Chicago, Illinois kentinde sekiz saatlik bir iş günü için grev düzenlediler.","en":"On 1 May 1886, labor unions organized a strike for an eight-hour work day Chicago, Illinois, in the United States."},{"tr":"3 Mayıs'ta polisin isyancılar ile çatışması sonucu bir vurulma olduğu McCormick Biçerdöver Fabrikasında bir kişinin öldüğü küçük bir isyan çıktı.","en":"On 3 May, a small riot occurred at McCormick Harvester Plant where there was a shooting and one death when police clashed with the rioters."},{"tr":"4 Mayıs'ta Haymarket Meydanı'nda protesto mitingi başladığında şiddet yoğunlaştı.","en":"Violence intensified on 4 May when the protest meeting began in Haymarket Square."},{"tr":"Önceki günlerde yaşanan olayları kınamak için yapılan bu toplantıda, polisin bomba atması, on iki kişiyi öldürmesi ve altmıştan fazla kişiyi yaralamasıyla kalabalığı daha yeni boşaltmaya başlamıştı.","en":"During this meeting held to denounce the events of the previous days, the police had just begun to clear out the crowd with the police’s throwing a bomb, killing twelve people, and wounding more than sixty people."},{"tr":"Polis memuru Mathias J. Degan neredeyse anında öldürüldü ve daha sonra yedi polis memuru yaraları nedeniyle öldü.","en":"Policeman Mathias J. Degan was killed almost instantly and then seven policemen died as a result of their injuries."},{"tr":"Bomba patladığında protestoculardan dördü de öldürüldü ve ardından gelen panik sonucu polis kalabalığa ateş ederek bir kişiyi daha öldürdü.","en":"Four of the protestors were also killed when the bomb went off and in the panic that followed, the police killed one more person firing into the crowd."},{"tr":"Adamlardan yedisi ölüm cezasına çarptırıldı ve sekizincisi, bombalama olayında herhangi birinin rolü olduğuna dair şaşırtıcı bir delil olmamasına rağmen Yargıç Joseph Gary tarafından on beş yıl hapse mahkum edildi.","en":"Seven of the men were sentenced to death and eighth was sentenced to fifteen years in prison by Judge Joseph Gary, in spite of a surprising lack of evidence about that any of them had had any role in the bombing event."},{"tr":"Ceza, uluslararası işçi çevrelerinde öfkeye yol açtı, tüm dünyada protestolara ve nihayetinde uluslararası bir işçi günü olarak 1 Mayıs dünya çapındaki kutlamaların başlangıcına neden oldu.","en":"The sentencing sparked outrage in international labor circles, resulted in protests all around the world and, eventually, the beginning of the worldwide celebrations of 1 May as an international worker’s day."}]},{"id":"CK-054","no":54,"title":"Noel kartları","level":3,"code":"TAR","s":[{"tr":"Noel kartları, İngilizce konuşulan dünyada büyük bir gelenektir.","en":"Christmas cards are a big tradition in the English speaking World."},{"tr":"2017'de İngiltere'deki insanlar yaklaşık 900 milyon kart gönderip aldı.","en":"In 2017, people in Britain sent and received about 900 million cards."},{"tr":"Bu, küçük bebeklerden en büyük büyükanne ve büyükbabaya kadar her kişi için ortalama on iki karttır.","en":"This is an average of twelve cards for every person, from tiny babies to the oldest grandparents."},{"tr":"İngiltere'nin her yerine gönderilen kartların sayısı, posta hizmetlerinde yıllık bir baş ağrısına neden oluyor.","en":"The number of cards sent around Britain causes an annual headache for the postal service."},{"tr":"Her yıl, posta hizmetleri, fazladan postaya yardımcı olmak için mevsimlik personel almak zorundadır ve posta tasnif büroları, maksimum kapasitelerine ve bazen de ötesine genişletilir.","en":"Each year, the postal service has to hire seasonal staff to help with the extra mail, and postal sorting offices are stretched to their maximum capacity and sometimes beyond it."},{"tr":"İlk kartlar genellikle salondaki şöminenin üzerindeki şömine rafının üzerine konur; daha fazlası geldikçe, mevcut herhangi bir düz yüzey kullanılır:","en":"The first cards are usually put up on the mantelpiece above the fire in the lounge; as more come in, any available flat surface is used:"},{"tr":"kitap rafları, televizyonun tepesi, pencere pervazları, herhangi bir dolabın tepesi.","en":"bookshelves, the top of the TV, window-sills, the top of any cupboard."},{"tr":"Bazı evlerde kartlar duvardaki şeritlere dikey olarak veya duvardaki uzun yaylar halinde asılır.","en":"In some houses, cards are hung on ribbons on the wall either vertically or in long arcs across the wall."},{"tr":"Noel kartları geleneği 1843'te Britanya'da, ilk ulusal posta hizmetinin, 1840'ta başlayan \"kuruşlu posta\" nın başlamasından hemen sonra başladı.","en":"The tradition of Christmas cards began in Britain in 1843, just after the first national postal service ‘penny post which began’ started in 1840."},{"tr":"Bugün, neredeyse 200 yıl sonra, Noel kartları - bazen Yeni Yıl kartları olarak da bilinir - sadece Hıristiyan ülkelerde değil, tüm dünyada bir gelenektir.","en":"Today almost 200 years later, Christmas cards- sometimes known as New Year cards – are a tradition all over the World, and not only in Christian countries."}]},{"id":"CK-055","no":55,"title":"Alkol, yasak ve Al Capone","level":1,"code":"TAR","s":[{"tr":"Bugün, bir barda oturabilir ve bir bira içebilirsiniz - yaş sınırının altında olmadığınız sürece; yüz yıl önce yapamazdın.","en":"Today, you can sit in a bar and drink a beer – as long as you aren’t below the the age limit; a hundred years ago, you couldn’t."},{"tr":"Amerika içki karşıtıydı.","en":"America was dry."},{"tr":"Alkol yasadışıydı.","en":"Alcohol was illegal."},{"tr":"Onu ne içebilir, ne yapabilir, ne satın alabilir, ne ithal, ne de satabilirdiniz.","en":"You could neither drink it nor make it, not buy it, nor import it, nor sell it."},{"tr":"Alkol, 1919 yılında yasadışı hale geldi; on dört yıl boyunca yasadışı kaldı.","en":"Alcohol became illegal in the year 1919; it remained illegal for fourteen years."},{"tr":"Birden, 1919'da endüstri durmak zorunda kaldı!","en":"Suddenly, in 1919, the industry had to stop!"},{"tr":"Tabii ki duramadı.","en":"Of course, it couldn’t stop."},{"tr":"Resmi olarak durdu, ancak gayri resmi olarak gelişmeye devam etti.","en":"It stopped officially, but it continued to prosper unofficially."},{"tr":"Büyük işlerin yerine büyük suç işlendi.","en":"In place of big business, there was big crime."},{"tr":"Mafya dağıtımın kontrolünü ele aldı ve Mafya'nın patronları bira fabrikalarının ve içki fabrikalarının patronlarının yerini aldı.","en":"The Mafia took control of the distribution, and the bosses of the Mafia replaced the bosses of the breweries and distilleries."},{"tr":"İçlerinde en büyük gangster New York'tan gelen ve Chicago’da çalışan Al Capone'du.","en":"The biggest gangster of them was Al Capone, who came from New York and operated in Chicago."},{"tr":"Capone, geniş bir suç imparatorluğunu kontrol ediyordu.","en":"Capone controlled a vast empire of crime."},{"tr":"O kadar güçlüydü ki istediği herkesi kontrol edebiliyordu.","en":"He was so powerful that he could control anyone he wanted to."},{"tr":"Polisi \"satın alabilirdi\", politikacıları \"satın alabilirdi\".","en":"He could ‘buy’ policemen, he could ‘buy’ politicians."},{"tr":"Dokunulmazdı.","en":"He was untouchable."},{"tr":"Chicago'daki kalesinde oldukça güvendeydi, çünkü Belediye Başkanı \"Büyük\" Bill Thompson'ın bir arkadaşıydı.","en":"He was quite safe in his fortress in Chicago because he was a friend of the Mayor ‘Big’ Bill Thompson."},{"tr":"Çoğu polis, mecbur kalmadıkça Al Capone'un yoluna çıkmamaya çok dikkat etti.","en":"Most policemen were very careful not to get in the way of Al Capone, unless they had to."},{"tr":"Çoğu polis, ama hepsi değil.","en":"Most policemen, but not all."},{"tr":"\"Dokunulmazlar\" olarak bilinen küçük bir polis grubu, Al Capone'un sonsuza dek adaletten kaçamayacağına karar verdi.","en":"A small group of policemen, known as ‘the Untouchables’ determined that Al Capone wouldn’t escape from justice for ever."},{"tr":"İşlerini yapmak birkaç yıl sürdü, ama sonunda başardılar.","en":"They took several years to do their work, but in the end they succeeded."},{"tr":"Al Capone sonunda hapse gönderildi.","en":"Al Capone was finally sent to prison."},{"tr":"Ancak, asla öldürmek veya alkol satmakla suçlanmadı.","en":"However, he was never accused of killing or selling alcohol."},{"tr":"Bunun için fazla akıllıydı.","en":"He was too clever for that."},{"tr":"Bunun için hiçbir delil onu suçlayamazdı.","en":"No evidence could incriminate him for that."},{"tr":"Vergi ödemediği için cezaevine gönderildi.","en":"He was sent to prison for not paying taxes."}]},{"id":"CK-056","no":56,"title":"Meslek: Kovboy","level":1,"code":"TAR","s":[{"tr":"Amerika'nın batısında hâlâ kovboy var mı?","en":"Are there still cowboys in the American West?"},{"tr":"Cevap kesinlikle evet!","en":"The answer is certainly yes!"},{"tr":"Amerika'nın batısında hala binlerce kovboy var.","en":"There are still thousands of cowboys in the American West."},{"tr":"Hala ata biniyorlar ve hala silah taşıyorlar; ama zamanlarını Kızılderililerle savaşarak harcamıyorlar.","en":"They still ride horses and they still carry guns; but they don’t spend their time fighting Indians."},{"tr":"Kovboylar çalışan adamlardır; Teksas'tan Kanada'ya kadar dağlardaki çayırlarda yaşayan sığır sürülerine bakıyorlar.","en":"Cowboys are working men; they look after herds of cattle that live on the prairies in the mountains from Texas to Canada."},{"tr":"Yapacakları çok iş var;","en":"They have lot of jobs to do."},{"tr":"Tanımlanabilmeleri için sığırları işaretlemeleri gerekir; sığırları bir yerden bir yere taşımak zorundalar; onları aşılamalı ve sağlıklı olup olmadığını kontrol etmelidirler.","en":"They have to mark cattle so that they can be identified; they have to move cattle from place to place; they have to vaccinate them, and check if they are healthy."},{"tr":"Ayrıca kilometrelerce uzunluğundaki çitleri ve dikenli tel bariyerleri de incelemek zorundalar.","en":"They also have to inspect miles and miles of fences and barbed-wire barriers."},{"tr":"Elbette kovboylar çoğu zaman atlarından düşmezler!","en":"Cowboys don’t often fall off their horses, of course!"},{"tr":"Mükemmel biniciler olmalılar; ama iki nedenden dolayı silah taşırlar.","en":"They have to be excellent riders; but they carry guns for two reasons."},{"tr":"İlk olarak, yaralı bir hayvanı - bir ineği ya da bir atı - öldürmeleri gerekebilir;","en":"Firstly, they may have to kill an injured animal - a cow or a horse;"},{"tr":"İkinci olarak, çıngıraklı yılanlar gibi tehlikeli vahşi hayvanlarla karşılaşabilirler.","en":"Secondly, they encounter dangerous wild animals, such as rattle snakes."},{"tr":"Ayılar ve kurtlar da vardır, ancak genellikle insanlara saldırmazlar.","en":"There are bears and wolves too, but they don’t usually attack humans."}]},{"id":"CK-057","no":57,"title":"George Washington","level":3,"code":"POR","s":[{"tr":"George Washington'un hayatını tek kelimeyle özetlemek zorunda olsaydınız, bu kelime unutulmaz olmalıydı.","en":"If you had to sum up George Washington’s life in one word, that word would have to be unforgettable."},{"tr":"George'un hikayesi, seyahat ve macera, risklerle dolu ve en önemlisi de ihtişamla dolu.","en":"George’s story is full of travel and adventure, risks, and most of all, full of glory."},{"tr":"Ne de olsa 1789'da, dünyanın en güçlü ülkesi olacak olan Amerika Birleşik Devletleri'nin ilk başkanı seçildi.","en":"After all, in 1789, he was elected the first president of the United States, a country that was to become the most powerful in the world."},{"tr":"George, 1799'da hayatının sonunda uluslararası bir kahramandı.","en":"At the end of his life, in 1799, George was an international hero."},{"tr":"George, çok genç bir adam olarak orduya gönderildi.","en":"George was sent into the Army as a very young man."},{"tr":"Kendi kuşağından bir sömürgeci için bu, yapılması gereken saygın bir şeydi.","en":"For a colonist of his generation, it was a respectable thing to do."},{"tr":"Ona geçimini sağlama ve aynı zamanda o zamanlar vahşi hayvanlar ve Kızılderililerle dolu olan ülkeyi görme fırsatı verdi.","en":"It gave him an opportunity to make a living, and at the same time see the country, which at the time was full of wild animals and Indians."},{"tr":"Fransız ve Kızılderili Savaşı, George için daha sonra Amerikan Bağımsızlık Savaşı'nda yararlanacağı bir öğrenme deneyimiydi.","en":"The French and Indian Wars were a learning experience for George, one that he would later exploit in the War for American Independence."},{"tr":"Nitekim, yirmi yıl sonra, George bir Amerikan üniforması giymişti ve Fransızlara değil, İngilizlere karşı savaşıyordu.","en":"Indeed, twenty years later, George dressed an American uniform, and he was fighting not against the French, but against the British."},{"tr":"Bu savaşta, George'un ateşli liderliğinin Amerikan birliklerine açlık ve soğukluk içinde ilham verdiği ve savaştan en büyük general olarak çıktığı söylenir.","en":"In this war, it is said that George’s fiery leadership inspired his American troops in starving and cold, and he emerged from the war as the greatest general."},{"tr":"Muzaffer Amerikalıların onu ilk başkanları olarak seçmeleri şaşırtıcı değildi.","en":"It wasn’t surprise that victorious Americans chose him as their first president."},{"tr":"Dolarlık banknotun resmini çekmeye gelince, bu George çoktan öldükten sonra gelmedi ve ruhunun gerçekten unutulmaz bir ruh olduğunu kanıtladı.","en":"As for getting his picture on the dollar bill, that didn’t come after George had already died, and that proved that his spirit was truly an unforgettable one."}]},{"id":"CK-065","no":65,"title":"Uzun yaşamın sırları","level":1,"code":"SAG","s":[{"tr":"Japonya'daki Okinawa adası, dünyadaki en eski insanlardan bazılarına sahiptir.","en":"The island of Okinawa in Japan has some of the oldest people in the world."},{"tr":"100 yaşın üzerinde yaşayan kadın ve erkeklerden oluşan yüksek sayıdaki asırlık insanlarla ünlüdür.","en":"It’s famous for its high number of centenarians – men and women who live beyond 100 years of age."},{"tr":"Yaşam tarzları hakkında birçok bilimsel araştırma yapıldı ve beslenme düzenlerine göre aşçılık kitapları bile satın alabilirsiniz.","en":"There have been many scientific studies of their lifestyle and you can even buy cookery books based on their diets."},{"tr":"Sağlıklarının iyi olmasının nedenlerinden bazıları...","en":"Some of the reasons for their good health are that they …"},{"tr":"• balık tutmaya giderler ve yakaladıklarını yerler.","en":"• go fishing and eat what they catch."},{"tr":"• düzenli olarak bahçe işleri yaparlar ve kendi meyve ve sebzelerini yetiştirirler.","en":"• regularly do gardening and grow their own fruit and vegetables."},{"tr":"• Bisiklete binmeye giderler ve yürüyebilecekken asla araba kullanmazlar.","en":"• go cycling and never drive when they can walk."},{"tr":"• genellikle arkadaşlarla zaman geçirirler.","en":"• often spend time with friends."},{"tr":"İnsanların evlerinde buluşur ve oyun oynarlar.","en":"They meet at people’s houses and play games."},{"tr":"• nadiren süpermarketten yiyecek satın alırlar.","en":"• rarely buy food from a supermarket."},{"tr":"• düzenli egzersiz yapar, yüzmeye gider ve aktif yaşamlar sürdürüler.","en":"• do regular exercise, go swimming and lead active lives."}]},{"id":"CK-066","no":66,"title":"Sağlık ve mutluluğu ölçmek (1)","level":2,"code":"SAG","s":[{"tr":"Himalaya dağlarındaki küçük Butan ülkesi bin yaşın üzerindedir.","en":"The small country of Bhutan in the Himalayan mountains is over one thousand years old."},{"tr":"Geçmişte fakir bir ülkeydi ve pek fazla insan ziyaret etmedi.","en":"In the past it was a poor country and not many people visited it."},{"tr":"Ancak günümüzde turistler arasında giderek daha popüler hale geliyor.","en":"But nowadays, it is becoming more and more popular with tourists."},{"tr":"Tıp ve sağlık gelişiyor ve ekonomisi büyüyor.","en":"Medicine and health is improving and its economy is growing."},{"tr":"2006 yılına kadar Butan kralı olan Kral Jigme Singye Wangchuck, ülkesinin \"Gayri Safi Milli Mutluluğu\" ndan bahsetti.","en":"King Jigme Singye Wangchuck, the king of Bhutan until 2006, talked about his country’s ‘Gross National Happiness’."},{"tr":"Başka bir deyişle, ülkenin gelişimini ölçmenin yolunun mutluluk olduğunu düşünüyordu.","en":"In other words, he thought happiness is the way to measure the country’s development."},{"tr":"Ama mutluluğu nasıl ölçüyorsunuz?","en":"But how do you measure happiness?"},{"tr":"Belki de sağlık en iyi yoldur çünkü ünlü bir doktor bir zamanlar \"Mutlu insanlar genellikle hastalanmaz\" demişti.","en":"Perhaps health is the best way because a famous doctor once said, ‘Happy people generally don’t get sick."},{"tr":"Bir ülkede kaç kişinin kendini hasta veya sağlıksız hissettiğini ölçmek de kolaydır.","en":"It’s also easy to measure how many people feel ill or unhealthy in a country."},{"tr":"Örneğin, bir anket İzlanda'nın 'dünyanın en sağlıklı ülkesi' olduğunu söylüyor çünkü orada erkekler ve kadınlar uzun süre yaşıyor, hava çok temiz ve kişi başına dünyanın herhangi bir yerinden daha fazla doktor var.","en":"For example, one survey says Iceland is the ‘healthiest country in the world’ because men and women live a long time there, the air is very clean and there are more doctors available per person than anywhere else in the world."}]},{"id":"CK-067","no":67,"title":"Sağlık ve mutluluğu ölçmek (2)","level":2,"code":"SAG","s":[{"tr":"Bununla birlikte, dünyanın en mutlu ülkelerine dair başka bir anket daha vardı ve İzlanda zirveye yakın değildi.","en":"However, there was another survey of the happiest countries in the world and Iceland was not near the top."},{"tr":"Bu anketteki sorular şunları içeriyordu: Ne kadar kazanıyorsunuz?","en":"The questions on this survey included: How much do you earn?"},{"tr":"Ne kadar sağlıklısın?","en":"How healthy are you?"},{"tr":"Kendini ne kadar güvende hissediyorsun?","en":"How safe do you feel?"},{"tr":"155 farklı ülkeyi ziyaret ettikten sonra araştırmacılar, Danimarka'nın diğer ülkelerden daha mutlu olduğuna karar verdiler.","en":"After visiting 155 different countries, the researchers decided that Denmark feels happier than other countries."},{"tr":"Öyleyse mutluluk paraya ve sağlıklı olmaya eşit mi?","en":"So does happiness equal money and good health?"},{"tr":"Sanatçı Erik Krikortz'a göre değil.","en":"Not according to the artist Erik Krikortz."},{"tr":"Mutluluğu ölçmenin başka yolları olduğunu hissediyor.","en":"He feels that there are other ways of measuring happiness."},{"tr":"Krikortz'un bir web sitesi var ve ziyaretçiler ne kadar iyi uyudukları, aileleri ve arkadaşları, stres seviyeleri, ilhamları ve fiziksel aktiviteleri hakkında yorum yapmak için farklı mutlu veya üzgün yüzlere tıklıyor.","en":"Krikortz has a website and visitors click on different happy or sad faces to comment on how well they sleep, their family and friends, their level of stress, their inspiration and their physical activity."},{"tr":"Bitirdiğinizde, web sitesi her alan için sonuçları ekler ve size mutluluğunuz için nihai bir sonuç verir.","en":"When you finish, his website adds the results for each area and it gives you a final result for your happiness."}]},{"id":"CK-068","no":68,"title":"Sağlık ve mutluluğu ölçmek (3)","level":3,"code":"SAG","s":[{"tr":"Krikortz, memleketi Stockholm'de, anketinin sonuçlarını şehirdeki büyük bir binanın yan tarafındaki farklı renkli ışıklar olarak gösteriyor.","en":"In his home city of Stockholm, Krikortz also shows the results of his survey as different coloured lights on the side of a large building in the city."},{"tr":"Örneğin kırmızı, Stockholm halkının çok mutlu olduğu, yeşilin iyi olduğu ve mor birçok insanın üzgün olduğu anlamına gelir.","en":"For example, red means the people of Stockholm are very happy, green is OK and purple means many people are sad."},{"tr":"Krikortz, \"Her gün birçok insan binaya bakıyor ve nasıl\" biz \"olduğumuzu görüyor\" diyor.","en":"‘A lot of people look at the building every day and see how “we” are,’ Krikortz says."},{"tr":"Şehri ziyaret etmek isterseniz renkli ışıklar da kullanışlıdır.","en":"The coloured lights are also useful if you feel like visiting the city."},{"tr":"Örneğin, ışıklar kırmızıysa, yerel halkın mutlu hissettiğini bilirsiniz!","en":"For example, if the lights are red, you know the locals are feeling happy!"}]},{"id":"CK-069","no":69,"title":"Çılgın yarışmalar! (1)","level":2,"code":"TAR","s":[{"tr":"Ross McDermott ve Andrew Owen, farklı festivallere gitmek için Amerika Birleşik Devletleri'ni dolaşırlar ve The American Festivals Project blogunda deneyimlerini yazarlar.","en":"Ross McDermott and Andrew Owen travel round the United States going to different festivals and write about their experiences on the blog The American Festivals Project."},{"tr":"Bu festivallerin çoğu aynı zamanda yarışmalardır.","en":"Many of these festivals are also competitions."},{"tr":"Idiotarod, New York'ta her yıl düzenlenen bir yarış.","en":"The Idiotarod is an annual race in New York City."},{"tr":"Her takımda beş kişi ve bir alışveriş sepeti bulunmalıdır.","en":"Each team must have five people and a shopping cart."},{"tr":"Arabalarını dekore edebilirler ama tekerlekleri değiştiremezler.","en":"They can decorate their carts but they can’t change the wheels."},{"tr":"Tüm takımlar aynı yerden başlamalı ve bitirmelidir ancak aynı yollarda koşmaları gerekmez.","en":"All the teams have to start and finish at the same place but they don’t have to run on the same roads."},{"tr":"Takımlar rotalarını seçebilirler ancak her takımın üyeleri bitiş çizgisine birlikte varmalıdır, ve araba olmadan bitmemeleri gerekir!","en":"The teams can choose their route but the members of each team must arrive at the finish line together, and they mustn’t finish without the cart!"}]},{"id":"CK-070","no":70,"title":"Çılgın yarışmalar! (2)","level":2,"code":"TAR","s":[{"tr":"Mud Bowl futbolu normal Amerikan futboluna benzer.","en":"Mud Bowl football is similar to normal American football."},{"tr":"Maç daha kısa ama iki takım ve bir hakem var.","en":"The match is shorter but there are two teams and a referee."},{"tr":"Kazanan, altmış dakikanın sonunda en çok gol atan takımdır.","en":"The winner is the team with the most goals at the end of sixty minutes."},{"tr":"Tek gerçek fark, oyuncuların yarım metre çamur içinde oynamak zorunda olmaları!","en":"The only real difference is that the players have to play in half a metre of mud!"},{"tr":"Biçerdöverler normalde çiftliklerde bulunur, ancak her yaz bir gün için Michigan'daki küçük Hillsdale kasabasında çiftçiler 1.500 dolarlık bir ödül için birbirleriyle yarışırlar.","en":"Combine harvesters are normally on farms but, for one day every summer, in the small town of Hillsdale in Michigan, farmers compete against each other for a prize of $1,500."},{"tr":"Üç saat boyunca, dev makinelerin yalnızca bir biçerdöver hareket etmeye devam edene kadar çalışması gerekiyor.","en":"For three hours, the giant machines have to fight until only one combine harvester is still moving."}]},{"id":"CK-078","no":78,"title":"Maya Mağarasındaki El İzleri","level":2,"code":"TAR","s":[{"tr":"Arkeologlar Meksika'da bir mağarada el izleri buldular.","en":"Archaeologists found handprints in a cave in Mexico."},{"tr":"Mağara ünlü bir turistik yer olan Chichen Itza'nın yakınındaydı.","en":"The cave was near a famous tourist destination, Chichen Itza."},{"tr":"Birçok siyah ve kırmızı el izi mağaranın duvarlarını kapladı ve arkeologlar bunların bir Maya ritüelinin parçası olduğuna inanıyordu.","en":"Many black and red handprints covered the walls of the cave, and archaeologists believed that they were a part of a Maya ritual."},{"tr":"Çocuklar el izlerini 1200 yıldan daha uzun bir süre önce yaptı.","en":"Children made the handprints more than 1,200 years ago."},{"tr":"Siyah renk ölümü simgeliyordu ve ritüelde son anlamına geliyordu.","en":"The black color symbolized death and in the ritual, it meant the end."},{"tr":"Kırmızı renk, savaşı veya bir insanın toplumdaki yaşamını sembolize ediyordu.","en":"The red color symbolized war or a person’s life in society."},{"tr":"Arkeologlar, ayinin bir çocuk yetişkin olduğunda gerçekleştiğini söyledi.","en":"Archaeologists said that the ritual happened when a child became an adult."},{"tr":"El izleri, Maya kültürünün güçlü ve zengin olduğu zamanlardan geliyor.","en":"The handprints come from the time when the Maya culture was strong and rich."},{"tr":"Milyonlarca Maya hala Meksika, Guatemala ve Belize'de yaşıyor.","en":"Millions of Mayas still live in Mexico, Guatemala, and Belize."}]},{"id":"CK-080","no":80,"title":"Tırnaklara akrepler","level":3,"code":"TOP","s":[{"tr":"Tırnak sanatı daha önce uç noktalara gitti - yapay elmaslar ve tüylü tırnaklar gördük, ancak Meksika biraz tehlikeli olarak değerlendirilebilecek bir şey ekliyor.","en":"Nail art has gone to the extremes before – we have seen rhinestones and furry nails, but Mexico’s adding something which could be considered somewhat dangerous."},{"tr":"Müşteriler çiviye akrep yapıştırmak için yaklaşık 3 dolar ödüyor.","en":"Customers are paying around $3 to have a scorpion glued to a nail."},{"tr":"Akrepler son derece zehirlidir ve sizi sokarsa ölüme yol açabilir, ancak ekip, kullandıklarının öldükten sonra zehirli olmadığında ve takımın bunları tutarken cımbız kullandığında ısrar ediyor.","en":"Scorpions are highly venomous and if one stings you, it can lead to death, but the team insists that the ones that it is using are not venomous after they die and that the team uses tweezers when handling them."},{"tr":"Bir manikürcü, bu eğilimin herkes için olmadığını söyledi.","en":"One manicurist said that this trend is not for everyone."},{"tr":"Bazı insanlar olumlu tepki verirken, diğerleri bunun korkunç ve yapışkan bir eğilim olduğunu düşünüyor.","en":"Some people react positively while others think that it is a horrible and tacky trend."},{"tr":"İnsanlar ekibi hayvanlara zulmetmekle suçladı, ancak ekip, ölü akrepleri dağ sıralarında bulan insanlardan satın aldıklarını açıkladı.","en":"People have accused the team of animal cruelty, but the team explained that they buy the scorpions dead from people who find them in mountain ranges."}]},{"id":"CK-081","no":81,"title":"En uzun yaya köprüsü","level":3,"code":"BLT","s":[{"tr":"2016'da işçiler dünyanın en uzun yaya köprüsünü inşa etmeye başladı ve geçen hafta nihayet açıldı.","en":"In 2016, workers started to build the longest footbridge in the world, and last week, it finally opened."},{"tr":"Yaya köprüsü kuzey Portekiz'dedir ve Paiva Nehri'nin 175 metre yukarısında asılıdır.","en":"The footbridge is in northern Portugal, and it hangs 175 meters above the River Paiva."},{"tr":"516 metre uzunluğunda ve üzerinden yürümek 10 dakika sürüyor.","en":"It is 516 meters long and it takes 10 minutes to walk across it."},{"tr":"Aynı anda 100 kişi yaya köprüsünde olabilir, birçok şelale ve yeşil tepeler ile güzel manzaranın tadını çıkarabilirler.","en":"100 people can be on the footbridge at the same time, and they can enjoy the beautiful scenery with many waterfalls and green hills."},{"tr":"Tüm insanlar yaya köprüsünü sevmez çünkü alt kısım şeffaftır ve aşağıdaki nehri görebilirler.","en":"Not all people like the footbridge because the bottom is transparent and they can see the river below."},{"tr":"İlk ziyaretçiler yaya köprüsünden geçmekten biraz korktuklarını, ancak deneyim çok özel olduğunu ve sonunda keyif aldıklarını söylediler.","en":"The first visitors said that they were a little afraid to walk across the footbridge, but the experience was very special, and they enjoyed it in the end."},{"tr":"Köprü büyük sütunlardan ve çelik halatlardan oluşuyor ve 2.8 milyon dolara mal oluyor.","en":"The bridge consists of large pillars and steel cables, and it cost 2.8 million dollars."}]},{"id":"CK-083","no":83,"title":"Hindistan’daki virüs krizi","level":2,"code":"SAG","s":[{"tr":"Geçtiğimiz haftalarda, Hindistan'daki yeni COVID-19 vakalarının sayısı her gün 350.000'den fazlaydı.","en":"In the past weeks, the number of new COVID-19 cases in India was more than 350,000 people every day."},{"tr":"Hastaneler yeterli oksijene sahip olmadığı için birçok sorunu beraberinde getirdi.","en":"It brought many problems because hospitals did not have enough oxygen."},{"tr":"Başkent Delhi'deki hastaneler dolu olduğu için pek çok kişi tedavi görmeden öldü.","en":"Many people died without any treatment because hospitals in the capital city of Delhi were full."},{"tr":"Aileler dışarıda cesetleri yaktı ve alevleri gece boyunca görmek mümkün oldu.","en":"Families burned dead bodies outside, and it was possible to see the flames throughout the night."},{"tr":"ABD ve birçok Avrupa ülkesi aşılar, ventilatörler ve diğer yardımlar için materyal gönderdiler ve bunun krizi durdurmaya yardımcı olacağını umdular.","en":"The US and many European countries sent materials for vaccines, ventilators, and other help, and they hoped that it would help stop the crisis."},{"tr":"Zenginler ülkeyi terk etmeye başladı.","en":"Rich people started to leave the country."},{"tr":"Ülkedeki en zengin insanlardan biriydi.","en":"They were just some of the richest people in the country."},{"tr":"Ödeyebilecek parası olan aileler özel uçak rezervasyonu yaptırarak Avrupa ve Orta Doğu'ya kaçtı.","en":"Families, who could afford to pay, booked a private plane and they escaped to Europe and the Middle East."}]},{"id":"CK-085","no":85,"title":"Huş ağacı özü","level":1,"code":"DOG","s":[{"tr":"Huş ağacı özü, huş ağacının içindeki meyve suyudur.","en":"Birch sap is the juice inside a birch tree."},{"tr":"Birçok insan bunun çok sağlıklı olduğuna inanıyor ve özü elde etmek için huş ağaçlarına dokunuyorlar.","en":"Many people believe that it is very healthy and they tap birch trees to get the sap."},{"tr":"Sap berraktır ve rengi yoktur.","en":"The sap is clear and it has no color."},{"tr":"İnsanlar onu taze içtiklerinde tadı tatlıdır, ancak iki veya üç gün sonra ekşi olmaya başlar.","en":"When people drink it fresh, it tastes sweet, but after two or three days, it starts to get sour."},{"tr":"Sebebi ise özdeki şekerin alkole dönüşmesidir.","en":"The reason is that the sugar in the sap turns into alcohol."},{"tr":"Letonya'daki insanlar özel bir uygulama kullanmaya başladı.","en":"People in Latvia started to use a special app."},{"tr":"Bir huş ağacına dokunurlar ve uygulama özü toplama zamanı geldiğinde onlara bir mesaj gönderir.","en":"They tap a birch and the app sends them a message when it is time to collect the sap."},{"tr":"Bilim adamları, huş ağacı sapının insanların düşündüğü kadar sağlıklı olmadığını söylüyor.","en":"Scientists say that birch sap is not as healthy as people think."},{"tr":"Bugün birçok insan, büyükanne ve büyükbabaları yaptığı için özü içiyor.","en":"Many people today drink the sap because their grandparents and parents did it."},{"tr":"Çoğu zaman aynı ağacı kullanıyorlardı.","en":"Often, they used the same tree."}]},{"id":"CK-086","no":86,"title":"Gemideki silahlar","level":2,"code":"DUN","s":[{"tr":"ABD Donanması, Umman Denizi'nde bir gemiyle karşılaştı ve gemi silahlarla doluydu.","en":"The US Navy met a ship in the Arabian Sea and the ship was full of guns."},{"tr":"Yeşil plastik poşetlerin içinde binlerce silah vardı.","en":"There were thousands of weapons that were inside green plastic bags."},{"tr":"İlk başta, silahların kimin için olduğu ve geminin nereye gittiği belli değildi.","en":"At first, it was not clear who the guns were for and where the ship was going."},{"tr":"Geçmişte, ABD Donanması farklı gemilerde benzer silahlar buldu ve bu silahlar Yemen'deki Husi isyancıları içindi.","en":"In the past, the US Navy found similar guns on different ships, and these guns were for Houthi rebels in Yemen."},{"tr":"Yetkililer geminin İran'dan geldiğini öğrendi ve bunun büyük bir sorun olduğunu çünkü ABD'nin İran'a silah satmasını yasakladı.","en":"Officials found out that the ship was coming from Iran, and it was a big problem because the US banned Iran to sell guns."},{"tr":"2014 yılında Yemen'de savaş başladı ve insanlar yasadışı yollarla ülkeye birçok silah getirdi.","en":"In 2014, the war started in Yemen, and people brought many guns to the country illegally."},{"tr":"ABD ve diğer ülkeler savaşı durdurmaya çalıştı, ancak savaşın yakında bitmeyeceği açıktı.","en":"The US and other countries tried to stop the war, but it was clear that the war would not end soon."}]},{"id":"CK-087","no":87,"title":"İngiliz Kraliyet Ailesi YouTube’da","level":3,"code":"TOP","s":[{"tr":"İngiliz kraliyet ailesi William ve Kate, resmi kraliyet nişanlarından alınan 25 saniyelik bir kliple ilk resmi YouTube kanalını başlattı.","en":"British royals William and Kate have launched their first official YouTube channel with a 25-second clip taken from official royal engagements."},{"tr":"Klipte Kate'in ok atması, William'ın mutfakta çalışması, Kate'in bir çiftliği ziyareti sırasında koyunu kesmesi ve William'ın Sir David Attenborough ile birlikte oturup çevre ödülünü teşvik etmesi gibi anlar da vardı.","en":"The clip included Kate shooting an arrow, William working in a kitchen, Kate shearing a sheep during a visit to a farm, and William sitting with Sir David Attenborough promoting an environment prize, among other moments."},{"tr":"William ve Kate çalışmalarını tanıtmak için zaten Twitter ve Instagram kullanıyor.","en":"William and Kate already use Twitter and Instagram to promote their work."}]},{"id":"CK-088","no":88,"title":"Büyük Şehirlerde Ev Fiyatları","level":2,"code":"DUN","s":[{"tr":"Şu anda aynı eğilimleri büyük şehirlerde görüyor olmamız gerçekten ilginç.","en":"It’s really interesting that at the moment we see the same trends in big cities."},{"tr":"New York, Londra veya Sidney için de durum aynı.","en":"It’s the same for New York, London, or Sydney."},{"tr":"Her yerde düşük faiz oranları, ev fiyatlarının aynı seviyede kaldığı anlamına gelir.","en":"Low-interest rates everywhere mean that house prices stay at the same level."},{"tr":"Bu oldukça sıra dışı çünkü küresel bir durgunluk olduğunda insanlar ev fiyatlarının düşmesini bekliyor.","en":"It’s highly unusual because when there’s a global recession, people expect house prices to go down."},{"tr":"Banliyölerde, insanlar ağaçlı ve daha fazla alanlı alanlarda daha yüksek fiyatlar ödemeyi bile teklif ediyor.","en":"In the suburbs, people even offer to pay higher prices in areas with trees and more space."},{"tr":"İnsanlar orada yaşamak istiyor çünkü gelecekte şehir merkezine yakın yaşamak zorunda kalmayacaklarını çünkü her gün ofiste olmak zorunda olmayacaklarını düşünüyorlar.","en":"People want to live there because they think that maybe in the future they won’t have to live close to the city center because they won’t have to be in the office every day."},{"tr":"Daire kiralayanların fiyatlarının düştüğü de doğrudur.","en":"It’s also true that the prices for people who are renting apartments went down."}]},{"id":"CK-089","no":89,"title":"Oksijenle iş yapmak","level":2,"code":"SAG","s":[{"tr":"Hindistan, geçen hafta günde 414.000'den fazla yeni COVID vakası bildirdi.","en":"India reported more than 414,000 new COVID cases per day last week."},{"tr":"Her gün yaklaşık 4.000 kişi COVID-19'dan öldü.","en":"Nearly 4,000 people died from COVID-19 every day."},{"tr":"Dört adam bu ciddi durumdan yararlanmak istedi ve oksijenle iş yapmaya başladılar.","en":"Four men wanted to take advantage of the serious situation, and they started to make a business with oxygen."},{"tr":"Oksijen tüplerini Lodhi Colony'deki bir restoran ve barda gizlice depolamaya başladılar.","en":"They started to store oxygen cylinders secretly in a restaurant and bar in Lodhi Colony."},{"tr":"Tüpleri internet üzerinden çok yüksek fiyatlarla sattılar.","en":"They sold the cylinders online at very high prices."},{"tr":"Kırmızı olan yangın söndürme tüpleri kullandılar ve oksijenin rengi siyah olduğu için siyaha boyadılar.","en":"They used fire extinguishing cylinders which were red, and they painted them black because black was the color for oxygen."},{"tr":"Polis erkekleri tutukladı ve 419 oksijen yoğunlaştırıcı ele geçirdi.","en":"Police arrested the men, and they seized 419 oxygen concentrators."},{"tr":"Polisin üç kişiyi tutukladığı ülkenin başka bir yerinde de benzer bir olay yaşandı.","en":"A similar thing happened in another part of the country where police arrested three men."}]},{"id":"CK-090","no":90,"title":"Köpek, Domuz Yavrularını Evlat Ediniyor","level":2,"code":"DOG","s":[{"tr":"Altı yavrunun yakın zamanda annesi olan ve şimdi bir domuz yavrularına üvey anne olan Linda ile tanışın.","en":"Meet Linda, recent mother of six pups and now an adoptive mum to a litter of piglets."},{"tr":"Sahibi, bu eşsiz senaryonun nasıl ortaya çıktığını açıkladı.","en":"Her owner explained how this unique scenario came about."},{"tr":"Anne domuz öldü ama çoktan doğurdu, bu yüzden domuz yavrularını topladı ve köpeğinin de yavrularının olduğu evine getirdi.","en":"The mother pig died but had already given birth, so he collected the piglets and brought them to his home where his dog had also had puppies."},{"tr":"Köpeğin kabul edip etmeyeceğini görmek için bebekleri bir araya getirdi.","en":"He put the babies together to see if the dog would accept them."},{"tr":"İlk gün biraz tereddüt etti ama sonunda domuz yavrularına süt verdi.","en":"On the first day, she was a little hesitant, but she ended up giving the piglets milk."},{"tr":"Bir hafta sonra, domuz yavrularını beslemek için kendi iradesiyle gelecekti.","en":"A week on, she would arrive of her own volition to feed the piglets."},{"tr":"Linda şimdi Küba kasabası Playa Larga'da yerel bir cazibe merkezi haline geldi.","en":"Linda has now become something of a local attraction in the Cuban town of Playa Larga."}]},{"id":"CK-091","no":91,"title":"Mavi orman","level":2,"code":"DOG","s":[{"tr":"Belçika'da, Brüksel'in güneyinde her bahar binlerce insanın bluebell'i görmek için ziyaret ettiği özel bir orman var.","en":"In Belgium, there is a special forest south of Brussels which thousands of people visit every spring to see bluebells."},{"tr":"Bluebells nisan ortalarında çiçek açar ve mavi bir halıya benzerler.","en":"Bluebells bloom around mid-April and they look like a blue carpet."},{"tr":"Bu yıl farklı ve yetkililer insanlardan koronavirüsün yayılmasından endişe duydukları için evde kalmalarını istedi.","en":"This year is different, and officials asked people to stay at home because they worry about the spread of the coronavirus."},{"tr":"Yetkililer ziyaretçi sayısını sınırlandırdılar, otoparkları kapattılar ve otobüsleri iptal ettiler.","en":"Authorities limited the number of visitors, they closed parking lots, and canceled buses."},{"tr":"Bazı insanlar hala ormanı ziyaret etti ve güzelliğine hayran kaldılar.","en":"Some people still visited the forest and they admired its beauty."},{"tr":"Bir kadın ormana gidebildiği için mutlu olduğunu söyledi.","en":"A woman said that she was happy that she could go to the forest."},{"tr":"Yanında maskesi vardı ve bazı insanlarla tanışırsa maskesini taktı.","en":"She had her mask with her and if she met some people, she put the mask on."},{"tr":"Restoran veya barları ziyaret etmenin mümkün olmadığı zamanlarda doğaya gitmenin kendisini daha iyi hissettirdiğini söyledi.","en":"She said that going to nature made her feel better in the time when it was not possible to visit restaurants or bars."}]},{"id":"CK-092","no":92,"title":"Robotlar çocuklara yardım ediyor","level":2,"code":"BLT","s":[{"tr":"Otizmli çocuklara yardım eden özel robotlar var.","en":"There are special robots that help children with autism."},{"tr":"Otizm, bir kişinin diğer insanlarla iletişim kurmasını çok zorlaştıran bir hastalıktır.","en":"Autism is a disorder that makes it very difficult for a person to communicate with other people."},{"tr":"Ayrıca otizmi olan bir kişi pek çok sosyal durumu anlamaz.","en":"Also, a person with autism does not understand many social situations."},{"tr":"Otizmi olan insanlar yaşamda bir yapıya ihtiyaç duyar ve hızlı değişiklikleri anlamazlar.","en":"People with autism need structure in life and they do not understand quick changes."},{"tr":"Robotlar bu insanların hayatlarını kolaylaştırabilir.","en":"Robots can make the lives of these people easier."},{"tr":"3 ila 18 yaş arası çocuklar, çatışmaları rol oyunlarıyla çözmeyi öğrenirler.","en":"Children between 3 and 18 years learn to solve conflicts through role play."},{"tr":"Rol yapma, bazı durumlarda başka birinin rolünü oynadıkları anlamına gelir.","en":"Roleplay means that they play a role of somebody else in some situations."},{"tr":"Bu şekilde çocuklar gerçek hayatta nasıl davranacaklarını öğrenirler.","en":"This way children learn how to behave in real life."},{"tr":"2015'ten beri 1.200'den fazla çocuk robotları kullandı ve sonuç harika.","en":"More than 1,200 children used the robots since 2015 and the result is great."},{"tr":"Ebeveynler mutlu çünkü çoğu çocuk daha iyi iletişim kurabiliyor.","en":"The parents are happy because most children can communicate better."},{"tr":"Hatta başkalarına geçmişte yapamadıkları basit sorular sorarlar.","en":"They even ask other people simple questions which is something that they could not do in the past."}]},{"id":"CK-093","no":93,"title":"SpaceX Astronotları Geri Dönüyor","level":2,"code":"BLT","s":[{"tr":"Dört NASA ve SpaceX mürettebat astronotu, Dragon kapsülünde Dünya'ya dönmek için Uluslararası Uzay İstasyonu'ndan ayrıldı.","en":"Four NASA and SpaceX crew astronauts left the International Space Station to return to Earth in the Dragon capsule."},{"tr":"Geri dönüş, 1968'den beri NASA astronotları ve Apollo 8 görevi için karanlıktaki ilk su sıçramasıydı.","en":"The return was the first splashdown in the dark for NASA astronauts since 1968 and the Apollo 8 mission."},{"tr":"Karanlıkta geri dönmeye karar verdiler çünkü şiddetli rüzgarlar diğer geri dönüş girişimlerini yavaşlattı.","en":"They decided to return in the dark because high winds scuttled the other return attempts."},{"tr":"Paraşütlerin yardımıyla, altı buçuk saatlik bir yolculuktan sonra okyanusa güvenli bir şekilde indiler, tekneler ise astronotları kurtarmalarını bekliyordu.","en":"With the help of parachutes, they landed safely in the ocean after a six and a half hour trip, while boats waited for them to recover the astronauts."},{"tr":"Görev, SpaceX için yalnızca ikinci insanlı uçuştu.","en":"The mission was only the second manned flight for SpaceX."}]},{"id":"CK-094","no":94,"title":"Ormanda kaybolan turist","level":1,"code":"TOP","s":[{"tr":"Daniel Florian, Kolombiya'nın güneybatısındaki yerli bir bölgeyi ziyaret eden bir Alman turist.","en":"Daniel Florian is a German tourist who visited an indigenous area in southwest Colombia."},{"tr":"Sonra bir ormanda kayboldu ve yedi gün boyunca kayıptı.","en":"Then he got lost in a jungle and he was missing for seven days."},{"tr":"Yerel medya, Florian'ın bir şaman ritüeline katıldığını ve Yage çayı içtiğini söyledi.","en":"Local media said that Florian took part in a shaman ritual and that he drank Yage tea."},{"tr":"Yage, Güney Amerika'da yetişen bir asma türüdür.","en":"Yage is a type of vine that grows in South America."},{"tr":"İnsanlar kabuğunu kaynatıyor ve ondan çay yapıyorlar.","en":"People boil its bark and they make tea from it."},{"tr":"Geleneksel bir ilaç olarak kullanıyorlar ama insanlar çayı içtiklerinde halüsinasyonlar görüyorlar.","en":"They use it as a traditional medicine, but people have hallucinations when they drink the tea."},{"tr":"Kolombiyalı askerler Florian'ı buldu ve nerede olduğunu bilmiyordu.","en":"Colombian soldiers found Florian and he did not know where he was."},{"tr":"Birkaç gün su içmediği için çok yorgundu.","en":"He was very tired because he did not drink water for several days."},{"tr":"Askerler onu tedavi için yakındaki bir hastaneye götürdüler.","en":"The soldiers took him to a nearby hospital for treatment."}]},{"id":"CK-095","no":95,"title":"Rus askerleri Ukrayna sınırını terk ediyor","level":2,"code":"DUN","s":[{"tr":"Birkaç hafta önce Rusya 100.000'den fazla asker, tank, uçak ve gemiyi Kırım'a ve Ukrayna sınırına yakın diğer yerlere taşıdı.","en":"A few weeks ago, Russia moved more than 100,000 soldiers, tanks, planes, and ships to Crimea and other places near the border with Ukraine."},{"tr":"Ukrayna ve birçok Batılı ülke, Rusya'nın Ukrayna'ya saldırmayı planladığından endişeliydi.","en":"Ukraine and many Western countries worried that Russia planned to attack Ukraine."},{"tr":"Ukrayna ve müttefikleri Rusya'nın askerleri uzaklaştırmasını istedi, ancak Rusya hiçbir şey yapmadı.","en":"Ukraine and its allies wanted Russia to move the soldiers away, but Russia did nothing."},{"tr":"Rusya, askerlerin orada eğitim aldığını söyledi.","en":"Russia said that soldiers had a training there."},{"tr":"Ardından geçen hafta binlerce Rus askeri bölgeden ayrıldı.","en":"Then last week, thousands of Russian soldiers left the area."},{"tr":"Rus yetkililer, askerlerin ayrıldığını gösteren bir video yayınladı.","en":"Russian officials released a video that showed that the soldiers were leaving."},{"tr":"Rus savaş gemileri de Ukrayna sınırından uzaklaştı.","en":"Russian warships moved away from the Ukrainian border, too."},{"tr":"Rusya, tüm askerlerin 1 Mayıs'a kadar bölgeyi terk edeceğini, ancak bazı tankların ve diğer şeylerin sonbahar eğitimi için orada kalacağını söyledi.","en":"Russia said that all soldiers would leave the area by May 1, but some tanks and other things would stay there for autumn training."},{"tr":"Bazı ülkeler durumun tekrar ciddileşeceğinden endişeleniyor.","en":"Some countries worry that the situation could get more serious again."}]},{"id":"CK-096","no":96,"title":"Plajlarda Sigara İzmaritleri","level":2,"code":"TOP","s":[{"tr":"Julian Melcer, Tel Aviv'de yaşıyor ve her sabah İsrail plajlarından sigara izmaritleri topluyor.","en":"Julian Melcer lives in Tel Aviv and every morning, he picks up cigarette butts from Israeli beaches."},{"tr":"Julian, insanların geride bıraktığı çöpleri beğenmediği için plajları temizlemeye üç yıl önce başladı.","en":"Julian started cleaning the beaches three years ago because he did not like the trash which people left behind."},{"tr":"Julian, insanlarla sigara izmaritlerinin doğal dünya ve deniz hayvanları için ne kadar tehlikeli olduğunu anlatır.","en":"Julian talks to people about how dangerous cigarette buts are for the natural world and for sea animals."},{"tr":"Yaz aylarında kendisine ayda 4.000 dolara kadar kazandıran cep kül tablaları satıyor.","en":"He sells pocket ashtrays which earn him up to 4,000 dollars a month during the summer."},{"tr":"İnsanlar kül tablalarını sigara külü ve izmaritleri için kullanıyor.","en":"People use the ashtrays for cigarette ash and butts."},{"tr":"Gönüllüler her yıl dünyanın plajlarını temizliyor ve son otuz yılda 60 milyondan fazla sigara izmariti topladılar.","en":"Every year, volunteers clean the world’s beaches, and in the last thirty years, they picked up more than 60 million cigarette butts."},{"tr":"İnsanlar plastik kaplardan, şişelerden ve plastik ambalajlardan daha fazla sigara izmariti atıyorlar.","en":"People throw away more cigarette butts than plastic containers, bottles, and plastic wrappers altogether."},{"tr":"Sigara izmaritleri çok tehlikelidir ve Julian, insanların sorunun farkına varmasına yardımcı olur.","en":"Cigarette butts are very dangerous, and Julian helps make people aware of the problem."}]},{"id":"CK-097","no":97,"title":"Yılan Bir Adamı Isırdı","level":3,"code":"DOG","s":[{"tr":"Hindistan'ın Rajasthan eyaletindeki orman departmanı yetkilileri, bir okulun binasına giren bir pitonu kaldırdı.","en":"Forest department officials in India’s Rajasthan state removed a python that entered the premises of a school."},{"tr":"Yılanı başarıyla yakaladıktan sonra insanlar onunla fotoğraf çekmeye başladı.","en":"After successfully capturing the snake, people started to pose for pictures with it."},{"tr":"Bir adam yılanla selfie çekmeye çalıştı ve ısırıldı.","en":"One man tried to take a selfie with the snake, and he got bit."},{"tr":"Daha sonra, yetkililer yılanı tekrar alıp götürdüler, ama adam gerçekten bir fotoğraf çekmiş olsa da, o ana kesinlikle sonsuza dek tutunacaktır.","en":"Later, officials took the snake away again, but the man will surely hold onto the moment forever, regardless of having actually taken a picture."}]},{"id":"CK-098","no":98,"title":"Avrupa Süper Ligi","level":3,"code":"SPO","s":[{"tr":"En iyi Avrupa futbol kulüplerinin yöneticileri, 30 yıldan daha uzun bir süre önce bir Avrupa Süper Ligi hakkında düşünmeye başladı.","en":"Managers of top European football clubs started to think about a European Super League more than 30 years ago."},{"tr":"Fikir, Avrupa Süper Ligi'nin Avrupa'daki en güçlü ve en büyük futbol kulüplerini içermesiydi.","en":"The idea was that the European Super League would include the strongest and biggest football clubs in Europe."},{"tr":"Pek çok insan, bir Avrupa Süper Ligi'nin dünyanın en popüler futbol müsabakası olan Şampiyonlar Ligi'nin sonu anlamına gelmesinden endişe ediyordu.","en":"Many people worried that a European Super League would mean the end of the Champions League, which was the most popular football competition in the world."},{"tr":"Avrupa'nın en büyük 12 futbol kulübü yeni lige kaydoldu.","en":"The 12 biggest European football clubs signed up to the new league."},{"tr":"Bu kulüplerden bazıları Arsenal, Chelsea, Liverpool ve Manchester United'dı.","en":"Some of these clubs were Arsenal, Chelsea, Liverpool, and Manchester United."},{"tr":"Real Madrid, Barcelona ve Juventus, İspanya ve İtalya'dan da imza atan altı kulüp arasındaydı.","en":"Real Madrid, Barcelona, and Juventus were among the six clubs from Spain and Italy who also signed up."},{"tr":"Geçen hafta futbol taraftarları plana karşı protesto göstermeye başladı.","en":"Last week, football fans started to protest against the plan."},{"tr":"14 İngiliz kulübü yeni lig ile aynı fikirde olmadıklarını söyledi.","en":"14 English clubs said that they did not agree with the new league."},{"tr":"İngiltere başbakanı Boris Johnson, yeni bir lig planlarını durdurmak için yeni bir yasa çıkaracağını söyledi.","en":"The UK prime minister Boris Johnson said that he would introduce a new law to stop the plans for a new league."}]},{"id":"CK-099","no":99,"title":"Çad başkanı öldü","level":2,"code":"DUN","s":[{"tr":"Geçen hafta, Çad'ın başkanı Idriss Déby 68 yaşında öldü.","en":"Last week, Chad’s president, Idriss Déby, died at the age of 68."},{"tr":"Déby 1990'da başkan oldu ve 30 yıldan fazla bir süredir iktidardaydı.","en":"Déby became a president in 1990, and he was in power for more than 30 years."},{"tr":"En uzun süre hizmet veren Afrika başkanlarından biriydi.","en":"He was one of the longest-serving African presidents."},{"tr":"İslami militanlara karşı mücadelede Fransa ve diğer Batılı ülkelerle işbirliği yaptı.","en":"He cooperated with France and other Western countries in the fight against Islamic militants."},{"tr":"Geçen hafta, Déby bir cepheye gitti ve ülkenin kuzeyinde isyancılarla savaşan askerleri ziyaret etti.","en":"Last week, Déby went to a frontline, and he visited soldiers who were fighting with rebels in the north of the country."},{"tr":"Sonra bir kavgada ağır yaralandı ve öldü.","en":"Then he was badly hurt in a fight and he died."},{"tr":"Déby'nin oğlu yeni lider oldu ve o hükümeti devirdi.","en":"Déby’s son became the new leader, and he brought down the government."},{"tr":"Önümüzdeki 18 ay boyunca ülkeyi yönetecek 15 general seçti.","en":"He named 15 generals who would lead the country for the next 18 months."},{"tr":"Bu saatten sonra özgür seçimlerin olacağına söz verdi.","en":"He promised that after this time, there will be free elections."}]},{"id":"CK-100","no":100,"title":"Tesla araba kazası","level":1,"code":"BLT","s":[{"tr":"Bir hafta önce, yarı otomatik bir Tesla arabası ABD, Teksas'ta bir ağaca çarptı.","en":"One week ago, a semi-automated Tesla car crashed into a tree in Texas, US."},{"tr":"Yerel basın, arabanın çok hızlı gittiğini ve yoldan çıktığını söyledi.","en":"Local media said that the car was going very fast and it went off the road."},{"tr":"Bir ağaca çarptı ve yanmaya başladı.","en":"It crashed into a tree and it started to burn."},{"tr":"Yangını itfaiye ekipleri söndürürken araçta sürücü olmadığı belli oldu.","en":"Firefighters extinguished the fire, and it was clear that there was no driver in the car."},{"tr":"Ön yolcu koltuğunda bir adam oturuyordu ve arabanın arkasında bir adam oturuyordu.","en":"One man was sitting in the front passenger seat, and one man was sitting in the back of the car."},{"tr":"Kazada her iki adam da öldü.","en":"Both men died in the accident."},{"tr":"Son zamanlarda Tesla arabalarında daha fazla kaza oldu.","en":"There were more accidents of Tesla cars recently."},{"tr":"Tesla'nın CEO'su Elon Musk, Ocak ayında yeni bir yazılım yapmayı planladığını söyledi.","en":"Tesla’s CEO, Elon Musk, said in January that he planned to make a new software."},{"tr":"Bu yazılım, sürücünün yardımı olmadan arabayı kendisi sürecek.","en":"This software would drive the car itself, without any help of the driver."},{"tr":"Bu son kazalar Musk'ın planlarını değiştirebilir.","en":"These recent accidents could change Musk’s plans."}]},{"id":"CK-101","no":101,"title":"Astronotlar geri dönüyor","level":2,"code":"BLT","s":[{"tr":"Bir Amerikalı ve iki Rus astronot, Uluslararası Uzay İstasyonu'ndaki bir görevden Dünya'ya güvenli bir şekilde döndü.","en":"One American and two Russian astronauts returned safely to Earth from a mission on the International Space Station."},{"tr":"Görev 185 gün sürdü ve Dünya'nın 2.960 yörüngesini içeriyordu.","en":"The mission lasted 185 days and it included 2,960 orbits of Earth."},{"tr":"126 milyon kilometre uzunluğundaydı ve astronotlar birçok ilginç deney yaptı.","en":"It was 126 million kilometers long and the astronauts did many interesting experiments."},{"tr":"Kate Rubins bir bilim adamıydı ve uzaydaki ikinci seferiydi.","en":"Kate Rubins was a scientist and it was her second time in space."},{"tr":"Bakteriler ve virüsler üzerinde çalıştı ve yer çekiminin kalp üzerindeki etkilerini inceledi.","en":"She studied bacteria and viruses, and she studied the effects of gravity on the heart."},{"tr":"Üç astronotlu bir uzay aracı, eve 400 kilometre geri gitti ve Kazakistan'a güvenli bir şekilde indi.","en":"A spacecraft with the three astronauts traveled 400 kilometers back home and it landed safely in Kazakhstan."},{"tr":"İnişten sonra astronotların sağlık kontrolünden geçmesi gerekiyordu.","en":"After the landing, the astronauts needed to undergo a health check."},{"tr":"Kozmonotlar Rusya'daki eğitim üssüne dönecek ve Rubins evlerine Houston, Teksas, ABD'ye uçacak.","en":"The cosmonauts will return to their training base in Russia, and Rubins will fly home to Houston, Texas, US."}]},{"id":"CK-102","no":102,"title":"Örümcek ağı müziği","level":2,"code":"BLT","s":[{"tr":"Bilim adamları örümcek ağlarının 3 boyutlu modellerini incelediler ve alışılmadık sesler çıkarmak için bilgisayarları kullandılar.","en":"Scientists studied 3D models of spider webs and they used computers to make unusual sounds."},{"tr":"Bir bilgisayar programı bir ağın yoğunluğunu kontrol etti.","en":"A computer program checked the density of a web."},{"tr":"Yoğunluk daha yüksek olsaydı, müzik daha karmaşıktı.","en":"If the density was higher, the music was more complicated."},{"tr":"Sıradan bir müzik değil, bilim adamlarının örümceklerin hissedebileceğini düşündükleri bir melodiydi.","en":"It was not usual music but a melody that scientists thought that spiders could feel."},{"tr":"İnsanlar örümceklerin nasıl iletişim kurduğunu duyamaz çünkü kulaklarımız bu frekansın sinyallerini duyamaz.","en":"People cannot hear how spiders communicate because our ears cannot hear signals of this frequency."},{"tr":"Bilim adamları, bir gün örümceklerle iletişim kurabileceklerini umuyorlar.","en":"Scientists hope that one day, they can communicate with spiders."},{"tr":"Örümcek ağları çok güçlüdür ve ipek çelikten beş kat daha güçlüdür.","en":"Spider webs are very strong, and the silk is five times stronger than steel."},{"tr":"Bilim adamları, gelecekte bunu inşaatta kullanabileceklerine inanıyor.","en":"Scientists believe that in the future, they can use it in construction."}]},{"id":"CK-103","no":103,"title":"Marulda yılan","level":1,"code":"DOG","s":[{"tr":"Avustralya'dan bir adam yerel bir süpermarkette marul satın aldı.","en":"A man from Australia bought lettuce in a local supermarket."},{"tr":"Marul plastik bir torbadaydı.","en":"The lettuce was in a plastic bag."},{"tr":"Adam eve geldiğinde, içeride bir şeylerin hareket ettiğini gördü.","en":"When the man came home, he saw that something was moving inside."},{"tr":"Önce bunun bir solucan olduğunu düşündü, ama sonra hayvanın dili ağzından dışarı fırladı.","en":"First, he thought that it was a worm, but then, the animal’s tongue flicked out of its mouth."},{"tr":"Adam korktu çünkü hayvanın bir yılan olduğu belliydi.","en":"The man got scared because it was clear that the animal was a snake."},{"tr":"Adam ve kız arkadaşı çantada bir delik olduğunu ve hayvanın kaçabileceğini gördüler.","en":"The man and his girlfriend saw that there was a hole in the bag and that the animal could escape."},{"tr":"Torbayı hızla başka bir plastik torbaya koydular.","en":"They quickly put the bag into another plastic bag."},{"tr":"Yerel makamlar, yılanın zehirli olduğunu öğrendi.","en":"Local authorities found out that the snake was venomous."},{"tr":"Bir başka Avustralya kentindeki bir paketleme fabrikasından 870 kilometre uzakta çantayla gitti.","en":"It traveled in the bag 870 kilometers from a packing factory in another Australian city."}]},{"id":"CK-104","no":104,"title":"Karı koca tekrar bir arada","level":1,"code":"TOP","s":[{"tr":"Gordon ve Mary Davis 89 yaşında.","en":"Gordon and Mary Davis are both 89 years old."},{"tr":"68 yıl önce evlendiler.","en":"They got married 68 years ago."},{"tr":"Koronavirüs salgını başlamadan önce Mary evde yaşıyordu ve Gordon bir bakım evindeydi.","en":"Before the coronavirus pandemic started, Mary was living at home and Gordon was in a care home."},{"tr":"Gordon hastalandı ve hastaneye gitmesi gerekiyordu.","en":"Gordon fell ill and he needed to go to the hospital."},{"tr":"Pandemi sırasında Mary, İngiltere, Mansfield'deki bir bakım evine taşındı.","en":"During the pandemic, Mary moved into a care home in Mansfield, UK."},{"tr":"Gordon'un kaldığı bakım evi değildi.","en":"It was not the same care home which Gordon stayed at."},{"tr":"Bu, çiftin aylardır birbirini görmediği anlamına geliyordu.","en":"It meant that the couple did not see each other for months."},{"tr":"Mansfield bakım evinde bir oda vardı.","en":"It happened that there was a room available in the Mansfield care home."},{"tr":"Personel Mary'yi şaşırtmak istedi ve Gordon'un taşınacağını söylemediler.","en":"Staff wanted to surprise Mary, and they did not tell her that Gordon would move in."},{"tr":"Çift bu kadar uzun bir süre sonra birbirlerini görünce ikisi de ağlamaya başladı.","en":"When the couple saw each other after such a long time, they both started to cry."},{"tr":"Tekrar birlikte oldukları için mutlu oldular.","en":"They were happy to be together again."}]},{"id":"CK-105","no":105,"title":"Efsanevi Nazi Treni","level":1,"code":"TAR","s":[{"tr":"Efsaneye göre 1945'te Naziler bir treni 300 tona kadar altın, mücevher ve başyapıtla doldurdu.","en":"Legend has it that in 1945, the Nazis filled a train with up to 300 tons of gold, jewels, and masterpieces."},{"tr":"Onu Almanya'nın bir bölgesindeki gizli tünellere sürdüler.","en":"They drove it into secret tunnels in an area of Germany."},{"tr":"Bu bölge artık Polonya'nın bir parçasıdır.","en":"This area is now part of Poland."},{"tr":"Bir grup Polonyalı meraklı, bu ünlü trenin tam boyutlu bir kopyasını inşa ediyor.","en":"A group of Polish enthusiasts is building a full-size replica of this famous train."},{"tr":"Grup, eski bir ağaç işleme fabrikasında çalışıyor.","en":"The group is working in an old wood processing factory."},{"tr":"Bu insanların halihazırda 12 metreden uzun zırhlı bir vagonu var.","en":"These people already have an armored wagon, which is over 12 meters long."},{"tr":"Şimdi, üç zırhlı yük arabası ve bir zırhlı lokomotif yapacaklar.","en":"Now, they will build three armored freight cars and an armored locomotive."},{"tr":"Sonra her şeyi taşıyacaklar ve bir tünele bağlayacaklar.","en":"Then they will move everything and connect it to a tunnel."},{"tr":"Bu tren gelmiş gibi görünecek.","en":"This will look like the train has arrived."},{"tr":"Grup, bunun bölgenin turistik cazibe merkezi haline geleceğini umuyor.","en":"The group hopes that this will become the area’s tourist attraction."}]},{"id":"CK-106","no":106,"title":"Askerler Afganistan'dan ayrıldı","level":2,"code":"DUN","s":[{"tr":"Eylül 2001'de teröristler ABD'deki Dünya Ticaret Merkezi'ne ve Pentagon'a saldırdı.","en":"In September 2001, terrorists attacked the World Trade Center and the Pentagon in the US."},{"tr":"Yalnızca bir ay sonra, ilk ABD ve İngiliz askerleri El Kaide ve Taliban'ı yok etmek için Afganistan'a geldi.","en":"Only one month later, the first US and UK soldiers came to Afghanistan to destroy al-Qaeda and the Taliban."},{"tr":"Teröre karşı savaş 20 yıl sürdü ve 2.200'den fazla ABD askeri öldü.","en":"The war on terror lasted 20 years and more than 2,200 US soldiers died."},{"tr":"Savaş ABD'ye neredeyse 1 trilyon dolara mal oldu.","en":"The war cost the US almost 1 trillion dollars."},{"tr":"ABD başkanı Joe Biden, Mayıs 2021'e kadar tüm ABD askerlerini çekmek istedi, ancak yeni bir son tarih açıkladı.","en":"The US president, Joe Biden, wanted to pull out all US soldiers by May 2021, but he announced a new deadline."},{"tr":"Yeni son tarih, ABD'ye yönelik saldırıların 20. yıldönümü olan 11 Eylül'dü.","en":"The new deadline was September 11, which was the day of the 20th anniversary of the attacks on the US."},{"tr":"İngiltere de askerlerini çekmeyi planlıyor ama Afgan yetkililer bundan memnun değil.","en":"The UK plans to pull out its soldiers, too, but Afghan officials are not happy."},{"tr":"Afganistan'da bir iç savaşın başlayacağından endişe ediyorlar.","en":"They worry that a civil war will start in Afghanistan."}]},{"id":"CK-107","no":107,"title":"Yeni Sanatçı Bulundu","level":3,"code":"POR","s":[{"tr":"Mona Osman, 19 yaşında Londra'daki bir galeri kafede masa beklemeye başladığında, meslektaşlarının sanatsal yetenekleri hakkında hiçbir fikri yoktu.","en":"When Mona Osman began waiting tables at a London gallery café at the age of 19, her colleagues had no idea about her artistic talents."},{"tr":"Orada yıllarca çalıştı, diğer sanatçıların çalışmalarını sergiledi ve şimdi kişisel sergisi, resimlerinin dünyanın en ünlü sanat satıcılarından birinin dikkatini çektiği galeride asılı.","en":"She worked there for years, seeing other artists’ work on display, and now her solo show hangs in the gallery where her paintings came to the attention of one of the world’s most famous art dealers."},{"tr":"Charles Saatchi, Mona'nın işini o kadar çok seviyor ki şimdiye kadar altı parça satın almış.","en":"Charles Saatchi likes Mona’s work so much that he has already bought six pieces."},{"tr":"Mona haberi duyduğunda ayın üstündeydi.","en":"Mona was over the moon when she heard the news."},{"tr":"Damien Hirst ve Tracey Emin gibi sanatçıların kariyerlerinin başlamasına yardımcı olan Charles Saatchi, sanatsal yetenekleri nasıl tespit edeceğini kesinlikle biliyor ve Mona'nın onların izinden gitmesi gerektiği anlaşılıyor.","en":"Charles Saatchi certainly knows how to spot artistic talent, having helped launch the careers of artists like Damien Hirst and Tracey Emin, and it seems that Mona may be destined to follow in their footsteps."},{"tr":"Zaten ondan daha büyük parçalar üzerinde çalışmasını istedi.","en":"He has already asked her to work on some larger pieces."}]},{"id":"CK-108","no":108,"title":"Nehirdeki süt","level":2,"code":"TOP","s":[{"tr":"Geçen hafta, bir süt tankeri İngiltere, Galler'de bir nehre düştü ve nehre yaklaşık 28.000 litre süt döküldü.","en":"Last week, a milk tanker crashed into a river in Wales, United Kingdom, and around 28,000 liters of milk spilled into the river."},{"tr":"Nehir beyaza döndü, bazı insanlar bunu ilginç buldu, ancak tehlikeli olabileceğini düşünmediler.","en":"The river turned white, which some people found interesting, but they did not think that it could be dangerous."},{"tr":"Yetkililer, sütün çok kirletici olduğunu ve nehirdeki tüm yaşamı yok edebileceğini söylediler.","en":"Officials said that the milk was very polluting, and it could destroy all the life in the river."},{"tr":"Zooplankton öldürürse balık ölür.","en":"If it killed zooplankton, fish would die."},{"tr":"Balık ölürse, balığı yiyen diğer hayvanlar, örneğin kuşlar da ölür.","en":"If fish died, other animals which ate the fish, for example, birds, would die, too."},{"tr":"Kazadan iki gün sonra nehir açılmaya başladı.","en":"Two days after the accident, the river began to clear."},{"tr":"Yetkililer hala orada yaşayan nehri ve hayvanları izlemeye devam etti.","en":"Authorities still continued to watch the river and animals which lived there."},{"tr":"Yetkililer, insanlardan daha dikkatli olmalarını ve ölü balıkları bildirmelerini istedi.","en":"Officials asked people to be more watchful and to report any dead fish."}]},{"id":"CK-109","no":109,"title":"Japon golf şampiyonu","level":1,"code":"SPO","s":[{"tr":"Hideki Matsuyama Japonya'dan geliyor.","en":"Hideki Matsuyama comes from Japan."},{"tr":"29 yaşında.","en":"He is 29 years old."},{"tr":"O bir golf oyuncusu.","en":"He is a golf player."},{"tr":"Henüz dört yaşındayken golf oynamaya başlar.","en":"He starts to play golf when he is only four years old."},{"tr":"Matsuyama golfte çok iyidir.","en":"Matsuyama is very good at golf."},{"tr":"Birçok şampiyonluk kazandı.","en":"He wins many championships."},{"tr":"O bir amatör.","en":"He is an amateur."},{"tr":"Golf oynamanın onun işi olmadığı anlamına gelir.","en":"It means that playing golf is not his job."},{"tr":"Eğlenmek için golf oynuyor.","en":"He plays golf for fun."},{"tr":"2011'de bir deprem Japonya'yı vurdu.","en":"An earthquake hits Japan in 2011."},{"tr":"Matsuyama ilk Masters şampiyonasını oynayabilir.","en":"Matsuyama can play his first Masters championship."},{"tr":"Oynamak istemiyor.","en":"He does not want to play."},{"tr":"Japonları mutlu etmek istediği için oynamaya karar veriyor.","en":"He decides to play because he wants to make Japanese people happy."},{"tr":"Matsuyama, 2013 yılında profesyonel bir golf oyuncusu oldu.","en":"Matsuyama becomes a professional golf player in 2013."},{"tr":"Şimdi, Matsuyama Japon halkını yeniden mutlu ediyor.","en":"Now, Matsuyama makes Japanese people happy again."},{"tr":"Golf şampiyonu olur.","en":"He becomes a golf champion."},{"tr":"Tarihte Masters şampiyonasını kazanan ilk Japon ve Asyalı adamdır.","en":"He is the first Japanese and Asian man in history who wins the Masters championship."}]},{"id":"CK-110","no":110,"title":"Bir uygulama COVID-19'u algılayabilir","level":2,"code":"BLT","s":[{"tr":"Bilim adamları, COVID-19 olan kişilerin pembe göz sendromu olduğunu keşfettiler.","en":"Scientists found out that people who had COVID-19 had pink eye syndrome."},{"tr":"Gözlerinin beyaz kısmının renginin pembeye dönmesi anlamına gelir.","en":"It means that the color of the white part of their eyes turns pink."},{"tr":"Bilim adamları iki milyon farklı pembe rengi biliyorlar ve COVID-19 hastaları için hangi rengin normal olduğunu söyleyebilirler.","en":"Scientists know two million different colors of pink, and they can tell which color is usual for COVID-19 patients."},{"tr":"Bir Alman şirketi Semic RF'deki bilim adamları, COVID-19'u tespit edebilen özel bir uygulama yaptı.","en":"Scientists in a German company Semic RF made a special app which can detect COVID-19."},{"tr":"Uygulamayı kullanmak çok kolay.","en":"It is very easy to use the app."},{"tr":"Telefonunuza kuruyorsunuz ve ardından gözlerinizden birinin fotoğrafını çekiyorsunuz.","en":"You install it on your phone and then, you take a photo of one of your eyes."},{"tr":"Uygulama, hasta olup olmadığınızı beş dakikadan daha kısa sürede anlayabilen Yapay Zeka kullanır.","en":"The app uses Artificial Intelligence which can tell in less than five minutes if you are sick or not."},{"tr":"Uygulama ayrıca COVID-19'u başarılı bir şekilde tespit etmek için kan basıncınızı, nabzınızı, vücut sıcaklığınızı ve olası göz enfeksiyonunu kontrol eder.","en":"The app also checks your blood pressure, pulse, body temperature, and possible eye infection to detect COVID-19 successfully."}]},{"id":"CK-111","no":111,"title":"Top Gun Maverick","level":2,"code":"TAR","s":[{"tr":"Top Gun, birçok ülkede çok popüler hale gelen, donanma pilotlarını konu alan 1980'lerin filmiydi.","en":"Top Gun was the 1980s movie about navy pilots, which became very popular in many countries."},{"tr":"Filmin en büyük yıldızı Tom Cruise'du.","en":"The biggest star of the movie was Tom Cruise."},{"tr":"Maverick lakaplı bir pilot Pete Mitchell oynadı.","en":"He played a pilot, Pete Mitchell, who had the nickname Maverick."},{"tr":"Film yapımcıları Top Gun için Top Gun: Maverick adlı bir devam filmi yaptılar ve prömiyerini Eylül 2020'de planladılar.","en":"Filmmakers made a sequel to Top Gun called Top Gun: Maverick, and they planned its premiere in September 2020."},{"tr":"Koronavirüs nedeniyle tarihi değiştirmek zorunda kaldılar.","en":"They had to change the date because of the coronavirus."},{"tr":"Yeni tarih Temmuz 2021'di, ancak yine Kasım 2021 olarak değişti.","en":"The new date was July 2021, but it changed again to November 2021."},{"tr":"Tom Cruise, Mission: Impossible 7 adlı başka bir filmin yıldızı ve prömiyeri 2022'de olacak.","en":"Tom Cruise is a star of another movie called Mission: Impossible 7, and its premiere will be in 2022."},{"tr":"Paramount Pictures, her iki filmi de yapan bir Amerikan film stüdyosudur.","en":"Paramount Pictures is an American film studio that made both movies."},{"tr":"Görünüşe göre şirket tüm dünyada film yayınlamak için doğru zamanı bekliyor.","en":"It seems that the company is waiting for the right time to release movies all over the world."},{"tr":"Pek çok ülkedeki insanlar artık sinemalara gidemiyor ve şirket bilet satarak çok para kazanmak istiyor.","en":"People in many countries cannot go to cinemas now, and the company wants to make a lot of money from selling tickets."}]},{"id":"CK-112","no":112,"title":"Kuzey İrlanda'da şiddet","level":2,"code":"DUN","s":[{"tr":"1960'lar ile 1998 arasında, Kuzey İrlanda'da 3.000'den fazla insan öldü.","en":"Between the 1960s and 1998, more than 3,000 people died in Northern Ireland."},{"tr":"Sorunlar çoğunlukla politik ve milliyetçiydi ve İngiltere ile İrlanda bir barış anlaşması imzalayınca durdular.","en":"The problems were mainly political and nationalistic, and they stopped when the UK and Ireland signed a peace deal."},{"tr":"Adı Hayırlı Cuma Anlaşması idi.","en":"It was called The Good Friday Agreement."},{"tr":"2020'nin sonunda Birleşik Krallık AB'den ayrıldı ve bu da birçok sorunu beraberinde getirdi.","en":"At the end of 2020, the UK left the EU, which brought many problems."},{"tr":"AB'nin İrlanda ile Kuzey İrlanda arasında yeni bir sınırı var.","en":"The EU has a new border, a border between Ireland and Northern Ireland."},{"tr":"499 kilometre uzunluğunda ve kontrol noktası yok.","en":"It is 499 kilometers long and there are no checkpoints."},{"tr":"İrlanda ve Kuzey İrlanda özel bir anlaşma imzaladı, bu da her iki ülkenin hala birlikte iş yapabileceği anlamına geliyor.","en":"Ireland and Northern Ireland signed a special deal which means that both countries can still do business together."},{"tr":"Ancak bazı insanlar mutlu değil ve yeni kurallara katılmıyorlar.","en":"But some people are not happy and they do not agree with the new rules."},{"tr":"Şiddet bir hafta önce Kuzey İrlanda'nın Belfast kentinde başladı.","en":"The violence started in Belfast, Northern Ireland, one week ago."},{"tr":"Protestocular polise benzin bombası attılar ve birisi bir otobüsü kaçırdı.","en":"Protesters threw petrol bombs at police and somebody hijacked a bus."},{"tr":"Bazı insanlar durumun daha da kötüye gidebileceğinden ve daha fazla şiddetin başlayabileceğinden endişeleniyor.","en":"Some people worry that the situation could get worse and more violence could start."}]},{"id":"CK-113","no":113,"title":"Çin'de Cam Köprü","level":2,"code":"BLT","s":[{"tr":"Çin'de insanlar cam tabanlı bir köprü diktiler ve diğer insanları, gücünü test etmek için balyozlarla ona vurmaya davet ettiler.","en":"In China, people erected a bridge with a glass bottom and invited other people to hit it with sledgehammers to test its strength."},{"tr":"Bu gerçekten biraz cesaret aldı çünkü köprü yerden 300 metre yüksekte.","en":"This really took some courage because the bridge is 300 meters above the ground."},{"tr":"Ancak, bu insanlar köprünün yan tarafına koşturuldu.","en":"However, these people were harnessed to the side of the bridge."},{"tr":"Bu projenin arkasında İsrailli bir mimar var ve bu köprünün dünyanın en büyük cam köprüsü olduğunu söylüyor.","en":"An Israeli architect is behind this project and he says that this bridge is the largest glass bridge in the world."}]},{"id":"CK-115","no":115,"title":"İnsanlar yiyecekleri atıyor","level":3,"code":"DOG","s":[{"tr":"Birleşmiş Milletler'e göre insanlar 2019'da yaklaşık 930 milyon ton gıdayı çöpe attı.","en":"According to the United Nations, people threw away about 930 million tons of food in 2019."},{"tr":"Bunun yarısından fazlasından hanehalkları sorumluyken, geri kalanından mağazalar ve gıda hizmetlerinde çalışan şirketler sorumluydu.","en":"Households were responsible for more than a half of it, while stores and companies which worked in food service were responsible for the rest."},{"tr":"BM, sorunların tüm gıda üretim sürecinde olduğunu ve gıdanın %14'ünün mağazalara bile ulaşmadığını öğrendi.","en":"The UN found out that problems were in the whole process of food production and that 14% of food did not even get to stores."},{"tr":"İnsanların çöpe attığı tüm yiyecekler, dünyadaki emisyonların %10'unu oluşturdu.","en":"All the food, which people threw away, made 10% of the world’s emissions."},{"tr":"Sadece zengin ülkelerde değil, gelişmekte olan ülkelerde de olması ilginçti.","en":"It was interesting that it did not happen only in rich countries, but in developing countries, too."},{"tr":"2019'daki rakamlar çok büyük, ancak son raporlar insanların 2020'de iki kat daha fazla yiyecek attığını gösteriyor.","en":"The numbers from 2019 are huge, but the recent reports suggest that people threw away two times more food in 2020."}]},{"id":"CK-117","no":117,"title":"Kız ağzı ile çiziyor","level":1,"code":"POR","s":[{"tr":"Afganistan'da engellilik genellikle bir zayıflık olarak görülüyor.","en":"In Afghanistan, disability is often seen as a weakness."},{"tr":"Ancak bir Afgan kız böyle bir sakatlık görmüyor.","en":"One Afghan girl, however, does not see disability like that."},{"tr":"Uzuvlarının kısmi felci ile doğmuştu, ama bu onu resim yapmaktan alıkoymadı.","en":"She was born with partial paralysis of her limbs, but that did not stop her from drawing."},{"tr":"Parmaklarıyla çizmek yerine ağzını kullanıyor.","en":"Instead of drawing with her fingers, she uses her mouth."},{"tr":"Çizmeye başlamadan önce çok depresyonda olduğunu söyledi.","en":"She said that before she started to draw, she was very depressed."},{"tr":"Günde iki veya üç kez ağladı.","en":"She cried two or three times a day."},{"tr":"Şimdi kendini daha iyi hissediyor ve Kanada'da bir sanat sergisi açmak istiyor.","en":"She feels better now and would like to hold an art exhibition in Canada."}]},{"id":"CK-118","no":118,"title":"Prens Philip öldü","level":2,"code":"POR","s":[{"tr":"Prens Philip Cuma günü 99 yaşında öldü.","en":"Prince Philip died on Friday at the age of 99."},{"tr":"Philip, Kraliçe II. Elizabeth'in kocasıydı ve İngiliz Kraliyet Ailesi'nin en önemli kişilerinden biriydi.","en":"Philip was the husband of Queen Elizabeth II, and he was one of the most important people in the British Royal Family."},{"tr":"Philip ve Elizabeth 1947'de İngiltere, Londra, Westminster Abbey'de evlendiler.","en":"Philip and Elizabeth were married at Westminster Abbey, London, England, in 1947."},{"tr":"Philip eşini neredeyse 70 yıl boyunca destekledi ve onunla binlerce etkinliğe katıldı.","en":"Philip supported his wife for almost 70 years, and he attended thousands of events with her."},{"tr":"Her zaman onun bir adım gerisinde yürürdü.","en":"He always walked one step behind her."},{"tr":"Philip'in resmi bir rolü yoktu, ancak karısı bir keresinde onun en iyi arkadaşı olduğunu söyledi ve onu daha da güçlendirdi.","en":"Philip had no official role, but his wife once said that he was her best friend, and he made her stronger."},{"tr":"Philip ve Elizabeth'in dört çocuğu vardı ve ilk oğulları Charles, İngiltere'nin bir sonraki kralı olacak.","en":"Philip and Elizabeth had four children, and their first son Charles will be the next king of Britain."}]},{"id":"CK-119","no":119,"title":"Ölmekte Olan Kasaba: Civita","level":2,"code":"TAR","s":[{"tr":"Civita di Bagnoregio, İtalya'da 3.000 yıllık bir kasabadır.","en":"Civita di Bagnoregio is a 3,000-year-old town in Italy."},{"tr":"İnsanlar ona ölmekte olan bir kasaba diyor çünkü kasabanın yakında yok olması mümkün.","en":"People call it a dying town because it is possible that the town will soon disappear."},{"tr":"Civita kil ve volkanik bir kayalık üzerindedir ve yağmur ve rüzgarlar uçurumu hızla değiştirdi.","en":"Civita is on a clay and volcanic rock cliff, and rain and winds changed the cliff quickly."},{"tr":"Geçmişte kasaba bugün olduğundan üç kat daha büyüktü.","en":"In the past, the town was three times bigger than it is today."},{"tr":"Şimdi sadece 152 metre uzunluğunda ve 91 metre genişliğinde ve insanlar oraya sadece bir köprü ile ulaşabiliyor.","en":"Now it is only 152 meters long and 91 meters wide, and people can only get there via a bridge."},{"tr":"Yerel halk, duvarlara ve kayaya yüzlerce çelik çubuk bağladı ve çubukların duvarları düz tutacağını umdular.","en":"Local people attached hundreds of steel rods to the walls and rock, and they hoped that the rods would keep the walls straight."},{"tr":"Civita turistler için popüler bir yer haline geldi.","en":"Civita became a popular place for tourists."},{"tr":"2019'da kasabayı bir milyondan fazla turist ziyaret etti ve çok para getirdiler.","en":"In 2019, more than a million tourists visited the town and they brought a lot of money."},{"tr":"Sonra koronavirüs her şeyi değiştirdi ve oradaki insanların artık parası yok.","en":"Then the coronavirus changed everything, and people there do not have any money now."},{"tr":"Civita'nın UNESCO Dünya Mirası Listesi haline gelmesi durumunda durumun daha iyi olacağını umuyorlar.","en":"They hope that the situation will get better if Civita becomes a UNESCO World Heritage Site."}]},{"id":"CK-120","no":120,"title":"Gemi çok zor durumda","level":2,"code":"DUN","s":[{"tr":"Pazartesi günü, bir Hollanda kargo gemisinin Kuzey Denizi'ndeki bir fırtınada başı derde girdi.","en":"On Monday, a Dutch cargo ship got in trouble in a storm in the North Sea."},{"tr":"Büyük dalgalar ve kuvvetli rüzgarlar gemiyi bir yandan diğer yana hareket ettirdi ve ana motoru çalışmayı durdurdu.","en":"Large waves and strong winds made the ship move from side to side, and its main engine stopped working."},{"tr":"Gemide 12 kişi vardı ve bazıları gemide kalmak çok tehlikeli olduğu için suya atladı.","en":"There were 12 people on board and some of them jumped into the water because it was too dangerous to stay on board."},{"tr":"Kurtarma ekipleri 12 kişiyi güvenli bir yere götürdü, ancak gemi denizde kaldı ve Norveç kıyılarına doğru hareket etmeye başladı.","en":"Rescuers took all 12 people to safety, but the ship stayed at sea, and it started to move towards the Norwegian coast."},{"tr":"Gemi 111 metre uzunluğundaydı ve daha küçük tekneler taşıyordu.","en":"The ship was 111 meters long and it carried smaller boats."},{"tr":"Kargonun bir kısmı suya düştü ve geminin batması ve gemiden gelen petrolün denize girmesi riski çok yüksekti.","en":"Some of the cargo ended up in the water and there was a high risk that the ship would sink, and oil from the ship would get in the sea."}]},{"id":"CK-121","no":121,"title":"İlk Olimpiyat Oyunları","level":1,"code":"SPO","s":[{"tr":"6 Nisan 1896'da, 125 yıl önce, ilk modern Olimpiyat Oyunları Yunanistan'ın Atina kentinde başladı.","en":"On April 6, 1896, 125 years ago, the first modern Olympic Games started in Athens, Greece."},{"tr":"Oyunlar 10 gün sürdü ve 241 sporcu katıldı.","en":"The Games lasted 10 days and 241 athletes took part."},{"tr":"Sporcular 14 ülkeden geldi ve 43 farklı yarışmada yarıştılar.","en":"The athletes came from 14 countries, and they competed in 43 different events."},{"tr":"Tüm sporcular Avrupalıydı, ancak bir istisna vardı, ABD takımı.","en":"All athletes were European, but there was one exception, the US team."},{"tr":"Kazananlar gümüş madalya, ikinci olan sporcular bakır madalya aldı.","en":"Winners got a silver medal and athletes who were second got a copper medal."},{"tr":"Daha sonra Uluslararası Olimpiyat Komitesi bu ödülleri değiştirdi.","en":"Later, the International Olympic Committee changed these prizes."},{"tr":"Kazananlar altın madalya, ikinci olan sporcular gümüş madalya aldı.","en":"Winners got a gold medal, and athletes who were second got a silver medal."},{"tr":"Üçüncü sıradaki sporcular bakır madalya aldı.","en":"Athletes in third place got a copper medal."},{"tr":"1896 Olimpiyatları şimdiye kadarki en büyük spor olayıydı ve çok başarılıydılar.","en":"The 1896 Olympics were the largest sporting event so far, and they were very successful."},{"tr":"Yunanistan, 108 yıl sonra, 2004 Yazında Olimpiyatlara tekrar ev sahipliği yaptı.","en":"Greece hosted the Olympics again 108 years later, in Summer 2004."}]},{"id":"CK-122","no":122,"title":"Çocuklar ABD-Meksika sınırını geçiyor","level":2,"code":"DUN","s":[{"tr":"ABD yetkilileri geçen hafta, bir kişinin ABD-Meksika sınırındaki bir çitin üzerinden iki çocuğu düşürdüğünü gösteren bir video yayınladı.","en":"US authorities released a video last week which showed a person drop two children over a fence along the US-Mexico border."},{"tr":"Videoda iki kişi çite ulaştı ve biri 4 metre yüksekliğindeki çitin üzerinden bir çocuğu düşürdü.","en":"In the video, two persons got to the fence and one of them dropped one child over the 4-meter-high fence."},{"tr":"Ardından kişi ikinci çocuğu düşürdü ve her iki kişi de sınırdan kaçtı.","en":"Then, the person dropped the second child and both persons ran away from the border."},{"tr":"ABD sınır devriyesi çocukları buldu ve bir devriye karakoluna götürdü.","en":"US border patrol found the children and took them to a patrol station."},{"tr":"Çocuklar bir yürümeye başlayan çocuk ve 5 yaşındaki kız kardeşiydi.","en":"The children were a toddler and her 5-year-old sister."},{"tr":"Her gün yüzlerce çocuk ve genç ABD-Meksika sınırını geçiyor, bu ABD için büyük bir sorun çünkü bu çocuklar için yeterli konut yok.","en":"Hundreds of children and teenagers cross the US-Mexico border every day which is a big problem for the US because there is not enough housing for these children."},{"tr":"Genellikle ebeveynleri yasal olarak ABD'ye gidemezler, bu yüzden çocuklarını yalnız gönderirler.","en":"Often, their parents cannot get to the US legally, so they send their children alone."},{"tr":"Çocuklarının yakınlarına ulaşmasını umuyorlar.","en":"They hope that their children will get to their relatives."}]},{"id":"CK-123","no":123,"title":"1 Nisan Konseri","level":2,"code":"TAR","s":[{"tr":"Brüksel, Belçika'daki bir parkta bir konsere 2.000'den fazla kişi geldi, ancak bu sahte bir konserdi.","en":"More than 2,000 people came to a concert in a Brussels, Belgium, park, but it was a fake concert."},{"tr":"2021 Nisan Şaka Günü Facebook'ta birisi şaka yaptı.","en":"Somebody made a joke on Facebook on April Fool’s Day, 2021."},{"tr":"1 Nisan Şakası Günü ve Batı ülkelerinde birçok insan oyun oynayıp şakalar yapıyor.","en":"April Fool’s Day is on April 1 and many people in Western countries play tricks and make jokes."},{"tr":"Belçika'da koronavirüse yakalanan çok sayıda insan var ve dışarıda dörtten fazla kişi buluşamıyor.","en":"In Belgium, there are many people sick with the coronavirus, and no more than four people can meet outside."},{"tr":"Brüksel belediye başkanı, insanların ılık bahar havasının tadını çıkarmak istediğini ancak etkinliğin devam edemeyeceğini anladığını söyledi.","en":"The Brussels mayor said that he understood that people wanted to enjoy the warm spring weather, but the event could not continue."},{"tr":"Pandemi başladığından beri 882.000'den fazla kişi COVID-19 ile hastalandı ve 23.000 kişi öldü.","en":"More than 882,000 people were sick with COVID-19 since the pandemic started, and 23,000 people died."}]},{"id":"CK-124","no":124,"title":"Köpekler için Sanat Sergisi","level":1,"code":"TAR","s":[{"tr":"Bu haber, sanatı da seven tüm köpek severler için - Londra'da köpekler için bir sanat sergisi var.","en":"This news is for all dog lovers who also like art – there is an art exhibition for dogs in London."},{"tr":"Ve etkileşimli!","en":"And it’s interactive!"},{"tr":"Bir sanat eseri, yanında fan bulunan bir araba modelidir.","en":"One piece of art is a model of a car with a fan next to it."},{"tr":"Köpekler arabaya binebilir, kafalarını pencerenin dışına koyabilir ve yolculuğun tadını çıkarabilir!","en":"Dogs can get in the car, put their heads outside the windows, and enjoy the ride!"},{"tr":"Köpek mamasına benzeyen kahverengi toplarla dolu 3 metrelik bir köpek kasesi de var.","en":"There is also a 3-meter dog bowl filled with brown balls, which look like dog food."},{"tr":"Yaratıcı, oynadıkları köpeklerin sağlığı için önemli olduğunu söylüyor.","en":"The creator says that it is important for the health of dogs that they play."},{"tr":"Sanat eserinin birçok köpeği mutlu etmesini umuyor.","en":"He hopes that the artwork makes a lot of dogs happy."}]},{"id":"CK-126","no":126,"title":"Kötü Parolalar","level":3,"code":"BLT","s":[{"tr":"Mart ayında, bir grup bilgisayar korsanı hastaneler, okullar, hapishaneler ve diğer binaların içindeki 150.000 güvenlik kamerasını ihlal etti.","en":"In March, a group of hackers breached 150,000 security cameras inside hospitals, schools, prisons, and other buildings."},{"tr":"İnsanların neden bu kadar kötü şifreler kullandıklarına dair sorular ortaya çıktı.","en":"Questions arose about why people used such bad passwords."},{"tr":"Birçok kişi \"şifre\", \"şifre1\" veya \"ABC123\" gibi basit şifreler kullanır çünkü onları kolayca hatırlayabilirler.","en":"Many people use simple passwords like ’password’, ’password1,’ or ’ABC123’ because they can easily remember them."},{"tr":"Daha sonra bilgisayar korsanları bu tür parolaları sorunsuz bir şekilde tahmin edebilir ve web sitelerinde ve uygulamalarda insanların e-posta adreslerini ve kullanıcı adlarını kullanabilir.","en":"Then hackers can guess such passwords without problems, and they can use people’s email addresses and usernames on websites and apps."},{"tr":"Kötü parolalar, çalışanların parolalarını düzenli olarak değiştirmelerinin ana nedenidir çünkü şirketler bilgisayar korsanlarının önemli bilgileri çalabileceğinden korkarlar.","en":"Bad passwords are the main reason why employees must change their passwords regularly because companies are afraid that hackers could steal important information."},{"tr":"Birçok web sitesi ve uygulama telefonunuza bir metin gönderir ve sizden kim olduğunuzu onaylamanızı ister.","en":"Many websites and apps send a text to your phone and they ask you to confirm who you are."},{"tr":"Bu çok daha güvenli ve bilgisayar korsanları için o kadar kolay değil.","en":"This is much safer and not as easy for hackers."},{"tr":"Ayrıca, şifreniz tek bir kelime olmamalı, harflerin, sayıların ve özel sembollerin birleşiminden oluşmalıdır.","en":"Also, your password should not be a single word but a combination of letters, numbers, and special symbols."}]},{"id":"CK-127","no":127,"title":"Gökyüzündeki Işıklar","level":2,"code":"BLT","s":[{"tr":"Geçen hafta Portland, Oregon ve Seattle, Washington, ABD'deki insanlar gece gökyüzünde olağandışı ışıklar gördü.","en":"Last week, people in Portland, Oregon, and Seattle, Washington, US, saw unusual lights in the night sky."},{"tr":"Bunun başka bir dünyadan bir şey olduğunu düşündüler ama çok geçmeden gerçeği anladılar.","en":"They thought that it was something from another world, but they soon found out the truth."},{"tr":"Işıklar uçaklar veya göktaşları değil, bir SpaceX roketiydi.","en":"The lights were not planes or meteors but a SpaceX rocket."},{"tr":"Roket 4 Mart'ta ABD'nin Florida kentinden havalandı ve mühendisler dünyanın atmosferini terk etmeyi planladılar.","en":"The rocket took off from Florida, US, on March 4, and engineers planned that it would leave the earth’s atmosphere."},{"tr":"Sonra roket atmosfere geri döndü ve yanmaya başladı.","en":"Then the rocket came back to the atmosphere and it started to burn."},{"tr":"Portland ve Seattle'daki insanlar çok heyecanlıydı çünkü gökyüzündeki ışıkları görmeleri normal değildi.","en":"People in Portland and Seattle were very excited because it was not usual for them to see lights in the sky."},{"tr":"SpaceX roketleri genellikle insanların gökyüzündeki ışıkları çok sık görebildiği ABD'nin diğer bölgelerinde havalanmaktadır.","en":"SpaceX rockets usually take off in other parts of the US where people can see lights in the sky very often."}]},{"id":"CK-128","no":128,"title":"Derek Chauvin Mahkemesi","level":2,"code":"DUN","s":[{"tr":"Mayıs 2020'de, Derek Chauvin ve Minneapolis, Minnesota'daki diğer üç polis memuru George Floyd'u tutukladı.","en":"In May 2020, Derek Chauvin and three other Minneapolis, Minnesota police officers arrested George Floyd."},{"tr":"Derek Chauvin, Floyd'un boynunda dokuz dakikadan fazla diz çöktü ve sonra Floyd hastanede öldü.","en":"Derek Chauvin kneeled on Floyd’s neck for more than nine minutes, and later, Floyd died in hospital."},{"tr":"Derek Chauvin ile dava geçen hafta başladı ve Nisan ayı sonuna kadar devam edecek.","en":"The trial with Derek Chauvin started last week and it will continue until the end of April."},{"tr":"Milyonlarca insan davayı izleyecek çünkü birçok kişi bunu ABD hukuk sisteminin bir testi olarak görüyor.","en":"Millions of people will watch the trial because many people see it as a test of the US legal system."},{"tr":"Floyd'un ölümünden sonra, dünyanın her yerinden binlerce insan polis şiddetini ve ırkçılığını protesto etti çünkü Floyd siyahtı.","en":"After Floyd’s death, thousands of people around the world protested against police brutality and racism because Floyd was black."},{"tr":"Diğer üç polis memuruyla yapılan duruşma Ağustos ayında görülecek.","en":"The trial with the three other police officers will take place in August."},{"tr":"İkinci derece cinayete yardım etmekle suçlanıyorlar.","en":"They face charges with helping and assisting a second-degree murder."}]},{"id":"CK-129","no":129,"title":"Holi Festivali","level":1,"code":"TAR","s":[{"tr":"Hindistan'daki insanlar bu hafta eski Holi festivalini kutladı.","en":"People in India celebrated the ancient Holi festival this week."},{"tr":"Holi, insanların baharı, aşkı ve dostluğu kutladığı popüler bir festivaldir.","en":"Holi is a popular festival when people celebrate spring, love, and friendship."},{"tr":"Holi bir gece gündüz sürer ve Mart ayında gerçekleşir.","en":"Holi lasts one night and day and it takes place in March."},{"tr":"Dolunayda olduğu için tarih her yıl değişiyor.","en":"The date changes every year because it takes place on the full moon."},{"tr":"Milyonlarca insan birbirine renkli barut atıyor ve sokaklarda kutlama yapıyorlar.","en":"Millions of people throw colored powder at each other and they celebrate in the streets."},{"tr":"Akşamları giyinip akraba ve arkadaşlarını ziyaret ederler ve birbirlerine tatlılar verirler.","en":"In the evening, they dress up and visit relatives and friends, and they give each other sweets."},{"tr":"Bu yılki festival farklıydı.","en":"This year’s festival was different."},{"tr":"Hükümet, insanlardan evde kalmalarını istedi çünkü COVID-19 vakalarının sayısı yeniden artmaya başladı.","en":"The government asked people to stay at home because the number of COVID-19 cases started to grow again."},{"tr":"Geçen hafta, her gün 60.000'den fazla yeni vaka görüldü.","en":"In the past week, there were more than 60,000 new cases every day."},{"tr":"Geçen yıl ilkbahardan bu yana yaklaşık 162.000 kişi COVID-19'dan öldü.","en":"Almost 162,000 people died from COVID-19 since spring last year."}]},{"id":"CK-130","no":130,"title":"Kaplan ve İki Kadın","level":2,"code":"DOG","s":[{"tr":"Çin'in Pekin kentindeki bir vahşi yaşam parkında korkunç bir şey oldu.","en":"A terrible thing happened at a wildlife park in Beijing, China."},{"tr":"Bir aile parkı ziyaret edip Sibirya kaplanı barınağının yakınında dururken, karı koca tartıştı.","en":"While a family visited the park and stopped near the Siberian tiger enclosure, the husband and wife had an argument."},{"tr":"Karısı arabadan indi ve aniden bir kaplan belirdi ve onu sürükledi.","en":"The wife got out of the car and all of the sudden, a tiger appeared and dragged her away."},{"tr":"Kocası onun peşinden koştu, onu da arabada olan annesi takip etti.","en":"Her husband rushed after her, followed by her mother who was also in the car."},{"tr":"Kadın kurtuldu ama ciddi şekilde yaralandı.","en":"The woman survived but she had serious injuries."},{"tr":"Ne yazık ki annesi hayatta kalamadı.","en":"Sadly, her mother did not survive."},{"tr":"2014 yılında, bir kaplan parkta çalışan bir kişiyi öldürdüğünde benzer bir olay yaşandı.","en":"In 2014, a similar incident happened when a tiger killed a person who worked at the park."}]},{"id":"CK-131","no":131,"title":"Aşı Pasaportu","level":3,"code":"SAG","s":[{"tr":"Dünyadaki daha fazla ülke, insanları COVID-19'a karşı aşılamaya başlıyor ve bazı insanlar aşı pasaportu yapmak istiyor.","en":"More countries in the world are starting to vaccinate people against COVID-19, and some people would like to make vaccine passports."},{"tr":"Bu pasaportlar, bir kişinin COVID-19 aşısı olduğunu ve virüsü bu kadar kolay yayamayacağını gösterirdi.","en":"These passports would show that a person got the COVID-19 vaccine and that he could not spread the virus so easily."},{"tr":"Turistlere bağımlı olan birçok ülke heyecan duyuyor ve aşı pasaportlarını tanıtmak istiyorlar.","en":"Many countries which depend on tourists are excited, and they would like to introduce vaccine passports."},{"tr":"Salgın sırasında zarar gören işletmeler için aşı pasaportu çok yardımcı olabilir.","en":"For businesses which suffered during the pandemic, a vaccine passport could be a big help."},{"tr":"Sorun, testlerin COVID-19 aşılarının hiçbirinin %100 etkili olmadığını göstermesidir.","en":"The problem is that tests showed that none of the COVID-19 vaccines was 100% effective."},{"tr":"Bu, aşı olan bazı kişilerin hala virüsü yayabileceği anlamına gelir.","en":"This means that some people who get the vaccine could still spread the virus."},{"tr":"Diğer bir sorun da, bazı ülkelerin aylar önce aşılamaya başlaması, ancak bazı ülkelerin daha yeni başlamasıdır.","en":"Another problem is that some countries started to vaccinate people months ago, but some countries are just starting."}]},{"id":"CK-132","no":132,"title":"Dieselgate: Volkswagen Emisyon Skandalı","level":3,"code":"BLT","s":[{"tr":"Dieselgate, 2015 yılında yaşanan bir skandaldı.","en":"Dieselgate was a scandal that happened in 2015."},{"tr":"Alman otomobil üreticisi Volkswagen, ABD'deki emisyon testlerinde hile yapmak için yasadışı yazılım kullandı.","en":"The German carmaker Volkswagen used illegal software to cheat emissions tests in the US."},{"tr":"Şirket yasal maliyet olarak 38 milyar dolardan fazla ödeme yaptı ve arabalarının bazı parçalarını değiştirmek zorunda kaldı.","en":"The company paid more than 38 billion dollars in legal costs, and it had to replace some parts in its cars."},{"tr":"Volkswagen hala yeni ve daha iyi teknolojiler geliştiriyor ve geçen hafta şirket en son elektrikli otomobilini Dresden, Almanya'da tanıttı.","en":"Volkswagen still develops new and better technologies, and last week, the company introduced its latest electric car in Dresden, Germany."},{"tr":"Dieselgate hala bitmedi ve Volkswagen hala skandala bağlı sorunlar yaşıyor.","en":"Dieselgate still did not end, and Volkswagen is still having problems that are connected to the scandal."},{"tr":"Şirket, Dieselgate'de olanları araştırdı ve skandaldan eski patronu ve eski Audi patronunun sorumlu olduğu görüldü.","en":"The company investigated what happened in Dieselgate, and it seemed that its former boss and former Audi boss were responsible for the scandal."},{"tr":"Her iki adam da yanlış bir şey yapmadıklarını söyledi, ancak Volkswagen skandalı bitirmek için biraz para ödemeleri gerektiğini söyledi.","en":"Both men said that they did nothing wrong, but Volkswagen said that they had to pay some money to end the scandal."}]},{"id":"CK-134","no":134,"title":"Yavru Kuş ve Boksör Köpek","level":2,"code":"DOG","s":[{"tr":"Yavru bir kuş yuvasından bahçeye düştükten sonra bir köpekle şaşırtıcı bir dostluk kurdu.","en":"After a baby bird fell into a garden from her nest, she formed a surprising friendship with a dog."},{"tr":"Köpek kuşa zarar vermedi ama ona baktı.","en":"The dog did not harm the bird but took care of her."},{"tr":"Köpeğin sahibi kuş için kapalı bir ağaçta yeni bir yuva kurdu, ancak köpek ve kuşun birlikte kalmayı tercih ettiğini fark etti.","en":"The dog’s owner made a new home for the bird in an indoor tree, but the owner found that the dog and the bird preferred to stay together."},{"tr":"Sahibi onları ve etkinliklerini filme almaya başladı ve ardından videoları İnternete koydu.","en":"The owner began filming them and their activities and then put the videos on the Internet."},{"tr":"Köpek ve kuşun saklambaç oynadığını veya birlikte yattığını görebilirsiniz.","en":"You can see the dog and bird play hide-and-seek or lay together."},{"tr":"Videolar, insanlar onları binlerce kez izledikleri için çok popüler.","en":"The videos are very popular as people have already watched them thousands of times."}]},{"id":"CK-136","no":136,"title":"Tembel hayvan Bir Kasabaya Geliyor","level":3,"code":"DOG","s":[{"tr":"Peru'da bir iş adamı bir sabah erken saatlerde büyük bir sürprizle karşılaştı - işinin önünde bir tembel hayvan buldu.","en":"In Peru, a businessman came early to his business one morning to find a big surprise – he found a sloth in front of his business."},{"tr":"Diğer insanlar tembel hayvana bakıp fotoğraf çekerken, vahşi yaşam yetkililerinden yardım istedi.","en":"He called for help from wildlife authorities while other people looked at the sloth and took pictures."},{"tr":"Sonunda yetkililer tembelliği şehrin doğal parkına geri götürmek için geldiler.","en":"Eventually, the authorities came to take the sloth back to the city’s natural park."},{"tr":"Bu bir sürprizdi çünkü tembel hayvanlar normalde insanların yanına gitmezler - normalde ormanda kalırlar.","en":"This was a surprise because sloths normally do not go near people – they normally stay in the forest."},{"tr":"Çok yavaş hareket ederler ve günde 15 ila 20 saat uyuyabilirler.","en":"They are very slow-moving and can sleep from 15 to 20 hours a day."},{"tr":"İnsanlar ve onları yiyen diğer hayvanlar yüzünden tembel hayvanlar da tehlike altındadır.","en":"Sloths are also endangered because of humans and other animals that eat them."}]},{"id":"CK-137","no":137,"title":"Son Çocuklar","level":2,"code":"TOP","s":[{"tr":"Güney Kore'nin Nokdo Adası'nda sadece birkaç çocuk var ve adada yaşayan insan sayısı hızla azalıyor.","en":"South Korea’s Nokdo Island has only a few children, and the number of people who live on the island is going down quickly."},{"tr":"Bir ailede üç çocuk var ve birkaç yıl önce onlar için açılmış bir okul var.","en":"There are three children in one family and a school opened for them a few years ago."},{"tr":"Öğretmen yoktu ve Güney Kore anakarasından gelmesi gerekiyordu.","en":"There was no teacher and she had to come from South Korea’s mainland."},{"tr":"Güney Kore dünyanın en hızlı yaşlanan toplumu oldu ve 2020'de dünyadaki en düşük doğum oranına sahip oldu.","en":"South Korea became the world’s fastest aging society and in 2020, it had the lowest birth rate in the world."},{"tr":"1970'lerde Güney Kore'de birçok büyük fabrika açıldı ve kadınlar orada çalışmak zorunda kaldı.","en":"In the 1970s, many big factories opened in South Korea and women had to work there."},{"tr":"Ayrıca büyük şehirlerde yaşamak çok pahalı hale geldi ve ailelerin çok çocuğu olamazdı.","en":"Also, living in big cities became very expensive and families could not have many children."},{"tr":"Birçok erkek ve kadın çocuk sahibi olmama veya çocuk sahibi olmalarını engelleyen özel bir ameliyat olmaya karar verdi.","en":"Many men and women decided not to have children or to have a special surgery that stopped them from having children."}]},{"id":"CK-138","no":138,"title":"Tanzanya'nın Yeni Başkanı","level":3,"code":"DUN","s":[{"tr":"John Magufuli, Tanzanya'nın beşinci başkanıydı ve 17 Mart 2021'de öldü.","en":"John Magufuli was the fifth president of Tanzania and he died on March 17, 2021."},{"tr":"Samia Saluhu Hassan yeni başkan oldu.","en":"Samia Saluhu Hassan became the new president."},{"tr":"Ülkenin İngiltere'den bağımsızlığını kazandığı 1961'den beri Tanzanya'nın ilk kadın cumhurbaşkanı oldu.","en":"She became the first female president of Tanzania since 1961 when the country became independent from Britain."},{"tr":"Geçmişte Tanzanyalı liderler anakaradan geliyordu ve Hassan, Zanzibar'dan gelen ilk cumhurbaşkanı oldu.","en":"In the past, Tanzanian leaders came from the mainland, and Hassan became the first president who came from Zanzibar."},{"tr":"Zanzibar bir grup adadır ve Tanzanya'nın özerk bir parçasıdır.","en":"Zanzibar is a group of islands and it is an autonomous part of Tanzania."},{"tr":"Hassan'ın tarzı, insanlar arasında popüler olmak isteyen Magufuli'den çok farklı ve büyük kararlar vermek istemedi.","en":"Hassan’s style is very different from Magufuli who wanted to be popular with people, and he did not want to make big decisions."},{"tr":"Magufuli, koronavirüs ile ilgili sorunları çözmedi ve koronavirüsün çok tehlikeli olmadığını söyledi.","en":"Magufuli did not solve problems with the coronavirus, and he said that the coronavirus was not too dangerous."},{"tr":"Hassan birçok sorunu şimdi çözmeli ve ülkeye COVID-19 aşısı yaptırıp yaptırmayacağına karar vermelidir.","en":"Hassan must solve many problems now, and she must decide if the country will get the COVID-19 vaccine."}]},{"id":"CK-139","no":139,"title":"Buz banyosu","level":1,"code":"SAG","s":[{"tr":"Bir Hollandalı olan Wim Hof, buz banyosu, nefes alma ve zihinsel egzersizleri birleştiren The Wim Hof Method'u yarattı.","en":"A Dutchman, Wim Hof, created The Wim Hof Method which combines ice bathes, breathing, and mental exercises."},{"tr":"Wim Hof, soğuk suyla ilgili birçok dünya rekoruna sahiptir.","en":"Wim Hof holds many world records related to cold water."},{"tr":"67 metre buzun altında yüzdü ve Afrika'nın en yüksek dağına sadece şortla tırmandı.","en":"He swam 67 meters under ice, and he climbed the highest mountain in Africa only in shorts."},{"tr":"Buz banyosu yapmak istiyorsanız, en önemli şey doğru nefes almaktır.","en":"If you want to practice ice bathing, the most important thing is the right breathing."},{"tr":"Sonra soğuk suya girebilir ve farkındalık ve meditasyon yapabilirsiniz.","en":"Then you can get into cold water and practice mindfulness and meditation."},{"tr":"Dikkat sadece şimdiki ana odaklandığınız bir durumdur.","en":"Mindfulness is a state when you focus only on the present moment."},{"tr":"Meditasyon sakin ve rahat hissetmenize yardımcı olur.","en":"Meditation helps you feel calm and relaxed."},{"tr":"Yöntemin vücudunuz üzerinde birçok iyi etkisi vardır.","en":"The method has many good effects on your body."},{"tr":"Vücudunuz daha güçlü, daha sağlıklı hale gelir ve daha genç hissedersiniz.","en":"Your body becomes stronger, healthier, and you feel younger."},{"tr":"Daha iyi uyursunuz ve vücudunuz bir hastalıktan kolayca iyileşir.","en":"You sleep better and your body will easily recover from an illness."}]},{"id":"CK-140","no":140,"title":"Rusya'da suaygırları","level":2,"code":"DOG","s":[{"tr":"Suaygırları oldukça saldırgandır, kolayca korkar, öngörülemez ve dünyadaki en tehlikeli hayvanlardan biridir.","en":"Hippos are highly aggressive, easily frightened, unpredictable, and one of the most dangerous animals in the world."},{"tr":"İnsanlar bunları savaşmak için de kullanabilir, ancak Rusya'da bir sirk gösterisinde oyun oynuyorlar.","en":"People can also use them for fighting, but in Russia they do tricks at a circus show."},{"tr":"Bir sirkte üç su aygırı var ve görevlileri gösterinin insanlar için tamamen güvenli olduğunu söylüyor.","en":"One circus has three hippos, and their handler says that the show is completely safe for people."},{"tr":"Suaygırları insanlara çok yaklaştıklarında bile korkmuş görünmüyorlar.","en":"Even when the hippos get very close to people, they do not seem afraid."},{"tr":"Suaygırları tamamen eğitilmiştir ve kimse performans sergilemek için onlara fiziksel güç kullanmaz.","en":"The hippos are fully trained and no one uses physical force on them to perform."},{"tr":"Aç Suaygırlarının gerçek hayattan bir versiyonunu dönüyor, zıplıyor ve hatta oynuyorlar.","en":"They roll over, jump, and even play a real-life version of Hungry Hippos."}]},{"id":"CK-141","no":141,"title":"Robot Yüzler","level":2,"code":"BLT","s":[{"tr":"Bir Rus şirketi olan Promobot, gerçek insanlara benzeyen robotlar yapıyor.","en":"A Russian company, Promobot, makes robots which look like real people."},{"tr":"Robotları halihazırda dünyanın 40 ülkesinde çalışıyor.","en":"Its robots already work in 40 countries in the world."},{"tr":"Şirket, 3D modelleme kullanan yeni bir departman açtı.","en":"The company opened a new department which uses 3D modeling."},{"tr":"Şirketin suni deri, göz ve diş ürettiği bir laboratuvarı var.","en":"The company has a laboratory where it makes artificial skin, eyes, and teeth."},{"tr":"O kadar gerçek görünüyorlar ki birçok insan bunun sanat olduğuna inanıyor.","en":"They look so real that many people believe it is art."},{"tr":"Bu robotlarla iş hızla büyüyor ve Promobot bu yıl seri üretime başlamak istiyor.","en":"The business with these robots is growing fast, and Promobot wants to start mass production this year."},{"tr":"Teknoloji özeldir çünkü bilgisayar becerileri ile heykel yapmanın bir karışımıdır.","en":"The technology is special because it is a mix of sculpturing with computer skills."},{"tr":"Şu anda Promobot sadece bir kafa yapıyor, ancak şirket gelecekte tüm vücudu yapmak istiyor.","en":"At the moment, Promobot makes only a head, but the company wants to make the whole body in the future."}]},{"id":"CK-142","no":142,"title":"Antarktika’da Dev Buzdağı","level":2,"code":"DOG","s":[{"tr":"On yıl önce, bilim adamları Antarktika'daki Brunt Buz Sahanlığı'nda çatlaklar keşfettiler.","en":"Ten years ago, scientists discovered cracks on the Brunt Ice Shelf in Antarctica."},{"tr":"O zamandan beri, bölgeyi izlemek için uydular ve GPS kullandılar.","en":"Since that time, they used satellites and GPS to watch the area."},{"tr":"Birçok yeni çatlak ve yarık gördüler ve rafın kırılacağı açıktı.","en":"They saw many new cracks and chasms and it was clear that the shelf would break."},{"tr":"Rafın bazı kısımları hareket etmeye başladı ve günde yaklaşık 5 metre hareket ettiler.","en":"Some parts of the shelf started to move, and they moved about 5 meters per day."},{"tr":"İki hafta önce, büyük bir buzdağı nihayet buz tabakasından kurtuldu.","en":"Two weeks ago, a big iceberg finally broke free from the ice shelf."},{"tr":"Buzdağı 150 metre kalınlığındaydı ve yaklaşık 1.270 kilometre kareydi.","en":"The iceberg was 150 meters thick, and it measured about 1,270 square kilometers."},{"tr":"Antarktika'nın bazı bölgelerini keşfetmek mümkün değil çünkü kışlar çok uzun ve karanlık geçiyor.","en":"It is not possible to explore some parts of Antarctica because winters are very long and dark."},{"tr":"Bilim adamları modern teknolojileri kullanırlar ve kendilerinin ziyaret edemeyecekleri yerleri izlemelerine yardımcı olurlar.","en":"Scientists use modern technologies and they help them watch places which they could not visit themselves."}]},{"id":"CK-144","no":144,"title":"Mahkumlar Bir Gardiyanı Kurtarıyor","level":2,"code":"TOP","s":[{"tr":"ABD, Teksas'ta bazı mahkumlar çok şaşırtıcı bir şey yaptı.","en":"In Texas, USA, some prisoners did a very surprising thing."},{"tr":"Muhafızlarının hücrelerinin dışında çöktüğünü gördüklerinde, kaçmak için değil, ona yardım etmek için dışarı çıktılar.","en":"When they saw their guard collapse outside their cell, they broke out not to run away but to help him."},{"tr":"Yardım çağırdılar ve kimse gelmeyince, mahkemedeki diğer gardiyanları aramak için telsizini kullandılar.","en":"They called for help and when no one came, they used his radio to call for other guards at the court."},{"tr":"Diğer gardiyanlar ortaya çıktı ve mahkumları hücrelerine geri koydu.","en":"The other guards showed up and put the prisoners back into their cell."},{"tr":"Diğerleri CPR'yi denedi ve ardından sağlık görevlilerini çağırdı.","en":"The others tried CPR and then called for paramedics."},{"tr":"Gardiyan hayatta kaldı ve insanlar şimdi bu mahkumlara hızlı eylemleri için kredi veriyor.","en":"The guard ended up surviving, and people are now crediting these prisoners for their quick actions."}]},{"id":"CK-145","no":145,"title":"Yarasalar ve Virüsler","level":1,"code":"DOG","s":[{"tr":"Geçmişte koronavirüs ve diğer birçok tehlikeli virüs yarasalardan geldi ve bilim adamları nedenini merak ediyor.","en":"The coronavirus and many other dangerous viruses in the past came from bats and scientists wonder why."},{"tr":"1.300'den fazla yarasa türü vardır ve bunlar çok farklıdır.","en":"There are more than 1,300 kinds of bats and they are very different."},{"tr":"Bazı yarasalar meyve yiyor, bazıları küçük hayvanları yiyor ve hatta bazıları diğer hayvanların kanını içiyor.","en":"Some bats eat fruit, some eat small animals, and some even drink the blood of other animals."},{"tr":"Bazı yarasalar ormanlarda, bazıları mağaralarda yaşar.","en":"Some bats live in forests and some live in caves."},{"tr":"Bu çeşitlilik, muhtemelen yarasaların bu kadar çok virüsü barındırmasının bir nedenidir.","en":"This diversity is probably a reason why bats host so many viruses."},{"tr":"Bilim adamları, yarasaların farelere göre insanları enfekte edebilecek daha fazla virüse ev sahipliği yaptığını keşfettiler.","en":"Scientists found out that bats host more viruses that can infect people than rats."},{"tr":"Yarasalar oldukça uzun yaşar, bu da virüslerin gelişmesi için daha fazla zamana sahip olduğu anlamına gelir.","en":"Bats live quite long which means that viruses have more time to develop."},{"tr":"Yarasalar uçtuğu için vücut sıcaklıkları daha yüksektir.","en":"Since bats fly, their body temperature is higher."},{"tr":"Bu, bazı virüslerin bu kadar tehlikeli olmasının başka bir nedeni olabilir.","en":"This can be another reason why some viruses are so dangerous."},{"tr":"Daha sıcak yerlerde yaşayabilirler.","en":"They can live in warmer places."}]},{"id":"CK-146","no":146,"title":"Meghan Kazandı","level":2,"code":"POR","s":[{"tr":"Meghan Markle, Sussex Düşesi ve Prens Harry'nin karısıdır.","en":"Meghan Markle is the Duchess of Sussex and the wife of Prince Harry."},{"tr":"Mayıs 2018'de evlendiler ama Meghan'ın babası düğüne gelmedi.","en":"They got married in May 2018, but Meghan’s father did not come to the wedding."},{"tr":"Meghan, babasına ne kadar üzüldüğünü yazdığı uzun bir mektup yazdı ve babasıyla arasındaki ilişkiyi anlattı.","en":"Meghan wrote a long letter to her father in which she wrote how sad she felt, and she described the relationship between her father and her."},{"tr":"The Mail on Sunday gazetesi mektubu yayınladı ve Meghan gazeteye karşı bir iddia getirdi.","en":"The Mail on Sunday paper published the letter, and Meghan brought a claim against the paper."},{"tr":"Gazetenin yaptıklarının özel hayatı üzerinde büyük bir etkisi olduğunu söyledi.","en":"She said that what the paper did had a big impact on her private life."},{"tr":"Geçen hafta bir mahkeme, gazetenin Meghan'ın yasal masrafları için 630.000 dolar ödemesi gerektiğine karar verdi.","en":"Last week, a court decided that the paper had to pay 630,000 dollars for Meghan’s legal costs."},{"tr":"Düşes 2 milyon dolar istediğini söyledi, ancak gazete çok fazla olduğunu söyledi.","en":"The duchess said that she wanted 2 million dollars, but the paper said that it was too much."}]},{"id":"CK-147","no":147,"title":"Karton Tekne","level":1,"code":"TOP","s":[{"tr":"Tamamen kartondan bir tekne yapabileceğinizi düşünüyor musunuz?","en":"Do you think you could build a boat completely from cardboard?"},{"tr":"Belki \"hayır\" diyorsunuz, ama İngiltere'den iki adam \"elbette yapabilirsin! Diyor.","en":"Maybe you say, “no”, but two men from England say, “of course you can!”"},{"tr":"On gün içinde 300 eski kutuyu bir tekneye dönüştürdüler.","en":"Over ten days, they turned 300 old boxes into a boat."},{"tr":"Hatta can yelekleri bile yaptılar ve arkasına küçük bir dıştan takma motor taktılar.","en":"They even made some life jackets and put a small outboard on the back."},{"tr":"Kabarcıklı ambalajdan yaptıkları bayrak da dahil olmak üzere atık paketlemeden her şeyi yaptılar.","en":"They made everything else from waste packaging, including the flag, which they made from bubble wrap."},{"tr":"Tekneyi Thames Nehri'ne koydular ve hepsi plana göre gitti.","en":"They put the boat into the River Thames and all went to plan."}]},{"id":"CK-148","no":148,"title":"Gemideki Hayvanlar","level":2,"code":"DOG","s":[{"tr":"Aralık ayında, bir İspanyol gemisi, İspanya'nın Cartagena limanında 855 inek aldı.","en":"In December, a Spanish ship took 855 cows on board at the Spanish port of Cartagena."},{"tr":"Gemi Türkiye'ye gitti ama oraya varamadı.","en":"The ship traveled to Turkey but it did not get there."},{"tr":"Nedeni belgelerdeki bir hataydı ve Türkiye hayvanları reddetti.","en":"The reason was a mistake in documents and Turkey rejected the animals."},{"tr":"Türkiye sığırlarda mavi dil virüsü olduğunu düşünüyordu.","en":"Turkey thought that the cattle had the bluetongue virus."},{"tr":"Diğer ülkeler de hayvanları reddettiği için gemi iki ay denizde kaldı.","en":"Other countries rejected the animals, too, so the ship stayed at sea for two months."},{"tr":"Yolculuk hayvanlar için çok uzun sürdü, birçok sağlık sorunu yaşamaya başladılar ve sonra bazıları öldü.","en":"The journey was too long for the animals, they started to have many health problems, and then some of them died."},{"tr":"İspanyol veterinerler hayvanları kontrol etti ve gemideki kötü durumu gördüler.","en":"Spanish veterinarians checked the animals and they saw the bad situation on the ship."},{"tr":"Hayvanları öldürüp acılarına son vermenin daha iyi olacağına karar verdiler.","en":"They decided that it would be better to kill the animals and end their pain."}]},{"id":"CK-150","no":150,"title":"Niagara Şelalesi dondu","level":1,"code":"DOG","s":[{"tr":"Şubat ayında soğuk rüzgarlar Kuzey Amerika'ya çok düşük sıcaklıklar getirdi.","en":"In February, cold winds brought very low temperatures to North America."},{"tr":"ABD'nin en iyi turistik yerlerinden biri olan Niagara Şelalesi dondu.","en":"Niagara Falls, which is one of the best tourist attractions in the US, froze."},{"tr":"Düşmeler tamamen donmadı ama öyle görünüyordu.","en":"The falls did not freeze completely, but they looked so."},{"tr":"Yoğun buz, şelalelerin üzerinde bir kabuk oluşturdu, ancak su hala buzun altından akıyordu.","en":"Thick ice made a crust on the falls, but the water was still flowing under the ice."},{"tr":"Şelaleler donmuyor çünkü içlerinde çok fazla su var ve su çok kuvvetli.","en":"The falls cannot freeze because there is too much water in them, and the water is very strong."},{"tr":"Akışı asla durduramaz.","en":"It can never stop flowing."},{"tr":"Su, tarihte yalnızca bir kez durdu.","en":"The water stopped flowing only once in history."},{"tr":"Eerie Gölü'nden gelen buz akışı engellediğinde meydana geldi, bu nedenle şelalelerde çok az su akıyordu.","en":"It happened when ice from Lake Eerie blocked the flow, so only little water was flowing in the falls."},{"tr":"Bir daha olamaz çünkü nehir üzerinde buzu durduran özel bir yapı var.","en":"It cannot happen again because there is a special construction on the river which stops the ice."}]},{"id":"CK-151","no":151,"title":"Sahte Büyükanneler Aşı İstiyor","level":2,"code":"SAG","s":[{"tr":"Koronavirüs aşısı olmak istedikleri için büyükanne gibi giyinmiş iki kadın.","en":"Two women dressed up to look like grannies because they wanted to get the coronavirus vaccine."},{"tr":"Kadınlar, Florida, ABD'deki aşı bölgesine geldiklerinde şapka, eldiven ve gözlük takıyorlardı.","en":"The women were wearing hats, gloves, and glasses when they arrived at the vaccination site in Florida, US."},{"tr":"Aşı belgelerinde doğum yıllarını değiştirdiler ve aşı olmayı umdular.","en":"They changed their birth years in vaccination documents and they hoped that they would get a vaccine."},{"tr":"ABD'de 65 yaş ve üstü kişiler önce aşıyı yaptırırken, kadınlar sadece 34 ve 44 yaşındaydı.","en":"In the US, people who are 65 and older, get the vaccine first, but the women were only 34 and 44 years old."},{"tr":"Personel, belgelerdeki doğum tarihlerinin ve sürücü belgelerinde yer alan doğum tarihlerinin farklı olduğunu gördü.","en":"The staff saw that the birth dates in the documents and the birth dates in their driver’s licenses were different."},{"tr":"Bir polis memuru kadınlardan ayrılmalarını istedi ve geri dönemeyeceklerini söyledi.","en":"A police officer asked the women to leave and he said that they could not come back."}]},{"id":"CK-152","no":152,"title":"Mars'a İniş","level":2,"code":"BLT","s":[{"tr":"Geçen hafta, NASA'nın Perseverance gezgini Mars'a başarılı bir şekilde indi.","en":"Last week, NASA’s Perseverance rover landed successfully on Mars."},{"tr":"Kızıl Gezegene yolculuk altı ay sürdü, ancak görevin en tehlikeli kısmı inişti.","en":"The journey to the Red Planet lasted six months, but the most dangerous part of the mission was the landing."},{"tr":"Geçmişte birkaç uzay aracı Mars'a inemedi, ancak Perseverance ince atmosferi aştı ve güvenli bir şekilde indi.","en":"Several spacecraft failed to land on Mars in the past, but Perseverance got through the thin atmosphere and landed safely."},{"tr":"Gezgin, Jezero Krateri adlı bir bölgeye indi ve bilim adamları geçmişte orada su olduğuna inanıyor.","en":"The rover landed in an area called the Jezero Crater, and scientists believe that there was water there in the past."},{"tr":"Gezici, bilim adamlarının inceleyeceği kayaları toplayacak ve yaşam belirtileri bulmaya çalışacak.","en":"The rover will collect rocks that scientists will study, and they will try to find signs of life."},{"tr":"Gezici, altı tekerleğe ve birçok kameraya sahiptir ve bir ton ağırlığındadır.","en":"The rover has six wheels and many cameras and it weighs a ton."},{"tr":"Jezero Krateri'ni keşfetmek için en az iki yıl geçirecek.","en":"It will spend at least two years exploring in the Jezero Crater."}]},{"id":"CK-153","no":153,"title":"Temiz Sidney Suları","level":2,"code":"DOG","s":[{"tr":"Her yıl yaklaşık 8 milyon ton plastik okyanusa düşüyor ve birçok yerde insanlar denizlerde ve nehirlerde yüzerken kumsallarda plastik buluyor.","en":"Every year, around 8 million tons of plastic end up in the ocean, and in many places, people find plastic on beaches when they swim in seas and rivers."},{"tr":"Laura Stone bir Avustralyalı ve Sidney Limanı'nın nasıl temizleneceği konusunda bir fikri var.","en":"Laura Stone is an Australian and she got an idea on how to clean the Sydney Harbor."},{"tr":"Rehber olarak çalıştığı kano turları düzenliyor.","en":"She organizes kayak tours where she works as a guide."},{"tr":"İnsanları limanda turlara çıkarıyor ve yol boyunca insanlar plastik alıyor.","en":"She takes people on tours in the harbor, and people pick up plastic along the way."},{"tr":"İnsanlar her ay 180 kilogramın üzerinde çöp topluyor ve sonuç inanılmaz.","en":"Every month, people collect over 180 kilograms of trash and the result is amazing."},{"tr":"Stone, insanların turlardan keyif aldığını çünkü bunun koronavirüs salgını sırasında yapabilecekleri bir şey olduğunu söyledi.","en":"Stone said that people enjoyed the tours because it was something that they could do during the coronavirus pandemic."},{"tr":"İnsanlar seyahat edemiyorlardı ama dışarıda vakit geçirmek istiyorlardı.","en":"People could not travel, but they wanted to spend time outside."},{"tr":"İnsanlar daha fazla geri dönüştürmeye ve ne kadar plastik kullandıklarını düşünmeye başladı.","en":"People started to recycle more and to think about how much plastic they used."}]},{"id":"CK-154","no":154,"title":"Trump Suçlama Davası","level":3,"code":"DUN","s":[{"tr":"Donald Trump, Ocak 2021'de görevine son veren 45. ABD başkanıydı.","en":"Donald Trump was the 45th president of the US who ended his office in January 2021."},{"tr":"Şimdi, ABD hükümetinin bazı üyelerinin ABD hükümet binasına yapılan saldırıdan Trump'ın sorumlu olduğunu söylediği için bir suçlama davası başladı.","en":"Now, an impeachment trial started because some members of the US government said that Trump was responsible for the attack on a US government building."},{"tr":"Trump, ABD başkanlık seçimlerinin sonucunu birkaç kez değiştirmeye çalıştı.","en":"Trump tried several times to change the result of the US presidential election."},{"tr":"6 Ocak'ta hükümet oyları saydı ve Joe Biden'in zaferini onayladı.","en":"On January 6, the government counted the votes and confirmed the victory of Joe Biden."},{"tr":"Aynı anda Trump, destekçileriyle konuşuyor ve onlara hükümet binasına gitmelerini ve gerçek için savaşmalarını söyledi.","en":"At the same moment, Trump was talking to his supporters, and he told them to go to the government building and fight for the truth."},{"tr":"Bazıları saldırının Trump'ın şiddet içeren dilinden kaynaklandığını söyledi.","en":"Some people said that the attack was the result of Trump’s violent language."},{"tr":"Ayrıca gelecekte başkan olursa Trump'ın tehlikeli olacağını söylediler.","en":"They also said that Trump would be dangerous if he became a president in the future."}]},{"id":"CK-155","no":155,"title":"Uyuyacak bir yer","level":1,"code":"TOP","s":[{"tr":"Bir ekip evsizler için özel bir uyku kabini yaptı.","en":"A team of people made a special sleeping pod for homeless people."},{"tr":"Almanya'nın Ulm şehrinde test ediyorlar.","en":"They are testing it in the city of Ulm, Germany."},{"tr":"Evsizleri soğuktan ve rüzgardan korumak için bölmenin yeterince sıcak olup olmadığını kontrol etmek gerekir.","en":"It is necessary to check if the pod is warm enough to keep homeless people safe from cold and wind."},{"tr":"Test başarılı olursa, ekip bölmeleri diğer Alman şehirlerine de koymak istiyor.","en":"If the test is successful, the team wants to put the pods in other German cities, too."},{"tr":"Bölmenin çatısında ışık veren bir güneş paneli vardır ve aynı zamanda kapıyı açar.","en":"The pod has a solar panel on the roof which makes light and it also opens the door."},{"tr":"Bölme metal ve ahşaptır ve bir kişi için uygundur.","en":"The pod is from metal and wood and it is suitable for one person."},{"tr":"Kapı akşamları açılıyor ve yatacak yeri olmayan biri içeride kalabilir.","en":"The door unlocks in the evening and someone, who has no place to sleep, can stay inside."},{"tr":"Bölme sıcak ve içinde temiz hava var.","en":"The pod is warm and there is fresh air inside."},{"tr":"Kapı açıldığında sosyal hizmet uzmanları bir mesaj alır.","en":"When the door opens, social workers get a message."},{"tr":"Ertesi gün başka bir kişi için hazır olduğundan emin olmak için yeri kontrol edip temizlerler.","en":"They check and clean the place the next day to make sure that it is ready for another person."}]},{"id":"CK-156","no":156,"title":"Donmuş Pantolon Mücadelesi","level":1,"code":"TOP","s":[{"tr":"Arktik rüzgarlar ABD'ye çok soğuk hava getirdi ve çoktan birkaç kişi öldü.","en":"Arctic winds brought very cold weather to the US, and several people already died."},{"tr":"Bazı insanlar için de çok eğlenceliydi.","en":"For some people, though, it was a lot of fun, too."},{"tr":"Birçok kişi donmuş pantolon yarışmasına katıldı ve sosyal medya, dışarıda kendi başına duran donmuş pantolon fotoğraflarıyla doldu.","en":"Many people took part in the frozen pants challenge, and social media became full of photos of frozen pants that were standing outside on their own."},{"tr":"Bazı insanlar çok yaratıcıydı ve komik fotoğraflar çekmek için pijama pantolonları veya hokey ve karate üniformaları kullandılar.","en":"Some people were very creative, and they used pajama pants or hockey and karate uniforms to make funny photos."},{"tr":"Minneapolis'te bir kadın, gününü aydınlatmak için ön bahçesini farklı renklerde pantolonlarla dekore etti.","en":"A woman in Minneapolis decorated her front garden with pants of different colors to make her day bright."},{"tr":"Denemek istiyorsanız, püf noktası basit.","en":"If you want to try it, the trick is simple."},{"tr":"Pantolonunu suya batırıyorsun ve dışarıya asıyorsun.","en":"You soak your pants in water and hang them outside."},{"tr":"Sadece birkaç dakika sürer ve pantolon donmaya başlar.","en":"It takes only a few minutes and the pants start to freeze."},{"tr":"Sonra pantolonu şekillendirip dışarıda karda bırakıyorsun.","en":"Then you shape the pants and put them outside in the snow."}]},{"id":"CK-157","no":157,"title":"El bombası","level":2,"code":"DUN","s":[{"tr":"Kolombiya'da bir olay meydana geldi.","en":"An incident occurred in Colombia."},{"tr":"Bir asker yanlışlıkla bir el bombası fırlatıcısını çalıştırdı ve başka bir askerin yüzüne 40 milimetrelik bir el bombası fırlattı.","en":"A soldier accidentally activated a grenade launcher and threw a 40-millimeter grenade into another soldier’s face."},{"tr":"El bombası askerin yüzüne sıkışmıştı.","en":"The grenade was stuck inside the soldier’s face."},{"tr":"Bir helikopter, el bombası patlayabileceği için askeri hareket ettiremedi, bu yüzden bir ambulans onu sekiz saatlik bir yolculukla Bogota'ya nakletti.","en":"A helicopter could not move the soldier because the grenade could explode, so an ambulance transferred him in an eight-hour ride to Bogota."},{"tr":"Doktorlar da güvenlik için hastane dışında onu ameliyat etti.","en":"Doctors operated on him outside of the hospital for safety, too."},{"tr":"Olağandışı operasyon başarılı oldu ve asker iyileşecek.","en":"The unusual operation was a success and the soldier is going to be fine."}]},{"id":"CK-158","no":158,"title":"Avrupa'nın En Yaşlı Kişisi","level":1,"code":"POR","s":[{"tr":"Lucile Randon, 1904'te Protestan bir ailede doğdu.","en":"Lucile Randon was born in 1904 in a Protestant family."},{"tr":"Üç erkek kardeşi vardı ve biri I.Dünya Savaşı'nda öldü.","en":"She had three brothers and one of them died in World War I."},{"tr":"26 yaşındayken dinini değiştirdi ve Katolik oldu.","en":"When she was 26, she changed her religion and she became Catholic."},{"tr":"1944'te adını Rahibe Andre olarak değiştirdi.","en":"In 1944, she changed her name to Sister Andre."},{"tr":"31 yıl çalıştığı Vichy'de bir hastanede çalışmaya başladı.","en":"She started to work in a hospital in Vichy, where she worked for 31 years."},{"tr":"Daha sonra, 30 yılını Fransız Alpleri'nde bir huzurevinde geçirdi.","en":"Then, she spent 30 years in a retirement home in the French Alps."},{"tr":"Rahibe Andre şu anda Fransa'nın Toulon kentinde, koronavirüsün 10 kişiyi öldürdüğü bir bakım evinde yaşıyor.","en":"Sister Andre is now living in a care home in Toulon, France, where the coronavirus killed 10 people."},{"tr":"Rahibe Andre'de de COVID-19 vardı, ama bunu bilmiyordu bile.","en":"Sister Andre had COVID-19, too, but she did not even know it."},{"tr":"Kendini iyi hissetti ve 117. doğum gününü kutlayabilirdi.","en":"She felt well and she could celebrate her 117th birthday."},{"tr":"Avrupa'nın en yaşlı ve dünyadaki en yaşlı ikinci kişidir.","en":"She is Europe’s oldest person and the second-oldest person in the world."},{"tr":"En sevdiği yemek ıstakoz ve şaraptan hoşlanıyor.","en":"Her favorite food is lobster and she likes wine."}]},{"id":"CK-159","no":159,"title":"Apple Elektrikli Araba","level":2,"code":"BLT","s":[{"tr":"Apple şirketi, ilk iPhone'u ürettiğinde işi elektronikle değiştirdi.","en":"The Apple company changed the business with electronics when it made the first iPhone."},{"tr":"Apple, 2015 yılında şoförsüz elektrikli otomobil yapmayı düşünmeye başladı ve birçok kişi bunun da özel olacağını düşünüyor.","en":"In 2015, Apple started to think about making an electric car without a driver, and many people think that it will be special, too."},{"tr":"Apple'ın elektrikli otomobil planları hakkında kimse pek bir şey bilmiyor çünkü şirket bunu gizli tutuyor.","en":"Nobody really knows much about Apple’s plans for an electric car because the company keeps it secret."},{"tr":"Elektrikli arabalar için bir fabrika inşa etmek çok zaman alıyor ve çok paraya mal oluyor.","en":"To build a factory for electric cars takes a lot of time, and it costs a lot of money."},{"tr":"Görünüşe göre Apple, araba üreten bir şirketle birlikte çalışacak.","en":"It seems that Apple will work together with a company that makes cars."},{"tr":"Geçtiğimiz hafta, iki Koreli otomobil üreticisi Hyundai ve Kia, Apple ile elektrikli bir otomobil üzerinde çalışmadıklarını ve hangi şirketin Apple ile çalışmak isteyeceğinin net olmadığını söyledi.","en":"Last week, two Korean automakers Hyundai and Kia said that they were not working with Apple on an electric car, and it is not clear which company would like to work with Apple."},{"tr":"Avrupa'da elektrikli otomobil satışları hızla artıyor.","en":"Sales of electric cars are growing fast in Europe."},{"tr":"Uzmanlar, 2050'de yaklaşık 800 milyon elektrikli otomobil olabileceğini söylüyor.","en":"Experts say that there could be around 800 million electric cars in 2050."}]},{"id":"CK-160","no":160,"title":"Akıllı Spor Salonu","level":2,"code":"BLT","s":[{"tr":"Koronavirüs salgını sırasında birçok spor salonu kapanmak zorunda kaldı.","en":"During the coronavirus pandemic, many gyms had to close."},{"tr":"Aynı zamanda birçok insan evde çok zaman geçirdi.","en":"At the same time, many people spent a lot of time at home."},{"tr":"Evden çalıştılar ve hastalar karantinada kalmak zorunda kaldı.","en":"They worked from home and sick people had to stay in quarantine."},{"tr":"Akıllı spor salonları olan işletmeler hızla büyümeye başladı.","en":"Businesses with smart gyms started to grow quickly."},{"tr":"Akıllı bir spor salonu, insanların evde kullandığı bir fitness aracıdır.","en":"A smart gym is a fitness tool that people use at home."},{"tr":"Kendi eğitim planınız var ve ayrıca evde egzersiz yapan diğer insanlardan oluşan bir topluluğun parçası olabilirsiniz.","en":"You have your own training plan, and you can also be a part of a community of other people who exercise at home."},{"tr":"Akıllı bir spor salonu gerçekten zekidir çünkü nasıl hareket ettiğinizi kontrol edebilir ve egzersizi kolaylaştırır veya zorlaştırır.","en":"A smart gym is really clever because it can check how you move, and it makes the exercise easier or harder."},{"tr":"Akıllı spor salonu ucuz değil ve 1.000 dolardan fazlaya mal olabilir.","en":"The smart gym is not cheap and it can cost more than 1,000 dollars."},{"tr":"Bazı şirketler, gelecekte daha fazla kişinin akıllı spor salonlarını kullanacağına ve koronavirüs salgınının bu değişikliği ancak hızlı bir şekilde yaptığına inanıyor.","en":"Some companies believe that more people will use smart gyms in the future and that the coronavirus pandemic only made this change quickly."}]},{"id":"CK-161","no":161,"title":"Turuncu Kar","level":1,"code":"DOG","s":[{"tr":"Afrika'dan gelen rüzgarlar her yıl Sahra Çölü'nden Avrupa'ya toz ve kum getiriyor.","en":"Every year, winds from Africa bring dust and sand from the Sahara Desert to Europe."},{"tr":"Alışılmadık bir şey değil ama bu yıl farklı çünkü rüzgar çok kuvvetli.","en":"It is nothing unusual, but this year is different because the wind is very strong."},{"tr":"Geçtiğimiz hafta sonu, Avrupa'nın birçok yerinden insanlar muhteşem bir manzaranın tadını çıkarabildiler.","en":"Last weekend, people across many parts of Europe could enjoy an amazing view."},{"tr":"İsviçre ve diğer ülkelerdeki gökyüzü turuncuya döndü.","en":"Skies in Switzerland and other countries turned orange."},{"tr":"Havada o kadar çok toz vardı ki karla kaplıydı ve sanki kar turuncuydu.","en":"There was so much dust in the air that it covered the snow and it seemed that the snow was orange."},{"tr":"İsviçre Alpleri'ndeki kayakçılar heyecanlıydı ve turuncu karda kayak yapmaktan zevk alıyorlardı.","en":"Skiers in the Swiss Alps were excited and they enjoyed skiing in orange snow."},{"tr":"Toz, Avrupa'daki havayı çok kirletti, ancak bilim adamları bunun insanlar için tehlikeli olmadığını söyledi.","en":"The dust made the air in Europe very dirty, but scientists said that it was not dangerous for people."},{"tr":"Toz zerreleri gerçekten büyüktü ve insanlar onları soluyamıyordu.","en":"The specks of dust were really big and people could not breathe them in."}]},{"id":"CK-162","no":162,"title":"Ölü Şarkıcı Tekrar Söylüyor","level":1,"code":"POR","s":[{"tr":"Kim Kwang-Seok, 1996'da ölen Güney Koreli bir rock yıldızıydı.","en":"Kim Kwang-Seok was a South Korean rock star who died in 1996."},{"tr":"25 yıl sonra hayranları onun şarkı söylediğini tekrar duyabildi.","en":"25 years later, his fans could hear him sing again."},{"tr":"Kim yaşarken var olmayan bir şarkı söyledi.","en":"He sang a song which did not exist when Kim was alive."},{"tr":"Nasıl oldu?","en":"How did it happen?"},{"tr":"Bir TV şovu vardı ve yapımcılar Kim'i hayata döndürmeyi planladılar.","en":"There was a TV show, and the producers planned to bring Kim back to life."},{"tr":"Bir AI şirketi, Kim'in şarkılarını kaydeden özel bir program kullandı.","en":"An AI company used a special program that recorded Kim’s songs."},{"tr":"AI daha sonra şarkılarda duyguları ve duyguları göstermeyi öğrendi.","en":"The AI then learned to show feelings and emotions in songs."},{"tr":"Program Kim´in 20 şarkısını öğrendi ve AI Kim´in sesiyle 700 Kore şarkısı söyledi.","en":"The program learned 20 of Kim’s songs, and the AI sang 700 Korean songs with Kim’s voice."},{"tr":"Kim'i tekrar duyduklarında bazı insanlar mutlu oldu.","en":"Some people were happy when they heard Kim again."},{"tr":"Yapımcılar doğru olanı yaptıklarından emin değillerdi.","en":"The producers were not sure if they did the right thing."},{"tr":"Kim´in ailesiyle de konuşmak zorunda kaldılar.","en":"They had to speak to Kim’s family, too."},{"tr":"Kim´in ailesi yeni şarkıdan çok memnun kaldı.","en":"Kim’s family was very happy with the new song."}]},{"id":"CK-163","no":163,"title":"Bulaşık Makinesindeki Tilki","level":1,"code":"DOG","s":[{"tr":"Bulaşık makinesini değiştirmeye gittiğinde Londra'da bir adam ev işleriyle ilgileniyordu.","en":"A man in London was getting on with his household jobs when he went to change the dishwasher."},{"tr":"Tabak ve kaşık dışında bir de tilki vardı.","en":"Apart from plates and spoons, there was a fox in there."},{"tr":"Londralı bir veterinerdir, bu yüzden tilkinin sadece birkaç aylık olduğunu söyleyebilirdi.","en":"The Londoner is a vet so he could tell that the fox was just a few months old."},{"tr":"Çok korkmuştu.","en":"It was very scared."},{"tr":"Bulaşık makinesinin alt arabasını çıkardı ve tilkinin gitmesi için süpürme fırçası kullandı.","en":"He removed the dishwasher’s bottom trolley and used a sweeping brush to make the fox leave."},{"tr":"Tilki bahçeye koştu ve veteriner daha sonra annesiyle birlikte gördü.","en":"The fox ran to the garden, and the vet later saw it with its mother."}]},{"id":"CK-164","no":164,"title":"Kolezyum Yeniden Açılıyor","level":3,"code":"TAR","s":[{"tr":"İtalya'nın Roma kentindeki Kolezyum, dünyanın en büyük amfitiyatrosudur.","en":"The Colosseum in Rome, Italy, is the largest amphitheater in the world."},{"tr":"1.900 yıldan daha eski, ancak hala ziyaretçilere açık.","en":"It is more than 1,900 years old, but it is still open to visitors."},{"tr":"İtalyan yetkililer koronavirüs nedeniyle Kolezyum'u ve diğer birçok halka açık yeri kapattı.","en":"Italian authorities closed the Colosseum, as well as many other public places, because of the coronavirus."},{"tr":"İtalya'da durum çok ciddiydi ve insanlar aylarca hiçbir yere gidemediler.","en":"The situation was very serious in Italy, and people could not go anywhere for months."},{"tr":"Şimdi, durum düzeliyor gibi görünüyor ve Kolezyum ve diğer müzeler yeniden açılabilir.","en":"Now, it seems that the situation is getting better, and the Colosseum and other museums can open again."},{"tr":"Kolezyum'da açılışı kutlamak için bir konser verildi ve konservatuvar öğrencileri klasik şarkılar söylediler.","en":"There was a concert at the Colosseum to celebrate the opening, and conservatory students sang classical songs."},{"tr":"Birkaç kişi, neredeyse boş bir amfitiyatronun özel atmosferinin ve anın tadını çıkarabilirdi.","en":"A few people could enjoy the moment and the special atmosphere of an almost empty amphitheater."},{"tr":"Şarkıcılar, yeni ve daha iyi zamanların başlangıcında olabilecekleri için kendileri için de alışılmadık bir an olduğunu söylediler.","en":"The singers said that it was an unusual moment for them, too, because they could be at the start of new and better times."}]},{"id":"CK-165","no":165,"title":"Sahte Aşı","level":2,"code":"SAG","s":[{"tr":"Çin polisi, sahte COVID-19 aşıları yapan ve satan 80 kişiyi tutukladı.","en":"Chinese police arrested 80 people who were making and selling fake COVID-19 vaccines."},{"tr":"Halk bir çeteye mensuptu ve Eylül 2020'de aşı yapmaya başladılar.","en":"The people belonged to a gang, and they started to make the vaccine in September 2020."},{"tr":"Polis, 3.000'den fazla aşı iğnesi buldu ve çetenin aşıyı Çin'de ve diğer ülkelerde de sattığını öğrendi.","en":"Police found more than 3,000 shots of the vaccine, and they found out that the gang sold the vaccine in China and in other countries, too."},{"tr":"Polis hangi ülkelerde olduklarını bilmiyordu.","en":"The police did not know which countries they were in."},{"tr":"Aşı tuz ve su karışımı olduğu için işe yaramadı.","en":"The vaccine could not work because it was a mixture of salt and water."},{"tr":"Geçmişte Çin'in sahte aşılarla sorunları vardı ve birçok insan Çin aşılarının iyi olduğuna inanmıyordu.","en":"China had problems with fake vaccines in the past, and many people did not believe that Chinese vaccines were good."},{"tr":"Şimdi durum farklı ve insanların %70'inden fazlası COVID-19 aşısını almayı kabul edeceklerini söyledi.","en":"Now the situation is different, and more than 70% of people said that they would agree to get the COVID-19 vaccine."}]},{"id":"CK-166","no":166,"title":"Çok Küçük Bir Bukalemun","level":3,"code":"DOG","s":[{"tr":"Kuzey Madagaskar'daki bilim adamları yeni bir tür bukalemun buldular ve bunun dünyadaki en küçük bukalemun olabileceğini düşünüyorlar.","en":"Scientists in northern Madagascar found a new type of chameleon, and they think that it could be the smallest chameleon in the world."},{"tr":"Bilim adamları sadece iki bukalemun, bir erkek ve bir dişi gördüler.","en":"Scientists only saw two chameleons, one male, and one female."},{"tr":"Gerçekten de dünyadaki en küçük bukalemunlar olup olmadıklarını söylemek mümkün değildi çünkü onları daha büyük ve hatta daha küçük olabilecek aynı tipteki diğer bukalemunlar ile karşılaştıramazlardı.","en":"It was not possible to say if they really were the smallest chameleons in the world because they could not compare them to any other chameleons of the same type which could be bigger or even smaller."},{"tr":"Madagaskar'daki insanlar fakirdir ve tarla yapmak ve hayvan beslemek için ağaçları keserler.","en":"People in Madagascar are poor, and they cut down trees to make fields and to keep animals."},{"tr":"Yağmur ormanlarının geniş alanlarının ve birçok hayvanın da yok olmasının nedeni budur.","en":"It is the reason why large areas of rainforest disappeared and many animals, too."},{"tr":"Bilim adamları, bu tür bukalemunları yakında nesli tükenmekte olan hayvanlar listesine koyacaklarını düşünüyor.","en":"Scientists think that they will put this type of chameleon on the list of endangered animals soon."}]},{"id":"CK-167","no":167,"title":"Polis, Köpek Gibi","level":2,"code":"TOP","s":[{"tr":"İngiltere'de bir polis memuru köpek gibi davranan bir adamı yakaladı.","en":"A police officer in England caught a man pretending to be a dog."},{"tr":"Polis bir adamı kovalıyordu ve ona o kadar gerçekçi havladı ki, etrafındaki herkes yanında eğitimli bir köpeği olduğunu düşündü.","en":"The policeman was chasing a man and barked at him so realistically that everyone around thought that he had a trained dog with him."},{"tr":"Her şey Perşembe günü güneybatı İngiltere sokaklarında başladı.","en":"It all started on the streets of southwest England on Thursday."},{"tr":"Polis ve ekibi hızlı bir kovalamacaya karıştı.","en":"The policeman and his team were involved in a high-speed chase."},{"tr":"Arabayı dört gençle durdurdular ama kaçmaya çalıştılar.","en":"They stopped the car with four young people inside but they tried to run away."},{"tr":"İnsanlar kaçarken polis köpek gibi havlamaya başladı ve genç bir adam durdu.","en":"When the people were running away, the policeman started to bark like a dog, and one young man stopped."},{"tr":"Olaydan bu yana, diğer kişiler polisle ilgili bazı şakalar yaptı ama umursamıyor.","en":"Since the incident, other people made some jokes about the policeman, but he does not care."},{"tr":"Taktiği işe yaradı ve önemli olan bu.","en":"His tactic worked and it is all that matters."}]},{"id":"CK-168","no":168,"title":"Adamın Yeni Yüzü Var","level":1,"code":"SAG","s":[{"tr":"2018 yılında, ABD, New Jersey'den Joe DiMeo adlı 22 yaşındaki bir çocuk ciddi bir araba kazası geçirdi.","en":"In 2018, a 22-year-old named Joe DiMeo from New Jersey, US had a serious car crash."},{"tr":"Joe vücudunun %80'inden fazlasında yanık geçirdi.","en":"Joe suffered burns on more than 80% of his body."},{"tr":"Dudakları ve göz kapakları yandı ve doktorlar parmaklarını kesmek zorunda kaldı.","en":"His lips and eyelids were burned, and doctors had to amputate his fingers."},{"tr":"Joe komada üç aydan fazla kaldı.","en":"Joe spent more than three months in a coma."},{"tr":"Uyandığında biraz egzersiz yapmaya başladı.","en":"When he woke up, he started to exercise a little."},{"tr":"Joe, doktorların yüzünü ve ellerini naklettiği ameliyat oldu.","en":"Joe underwent surgery during which doctors transplanted his face and hands."},{"tr":"Her iki vücut parçası da aynı kişiden geldi ve dünyada başarılı olan bu tür ilk ameliyat oldu.","en":"Both body parts came from the same person, and it was the first such surgery in the world which was successful."},{"tr":"New York'ta gerçekleşti ve 140 kişilik bir ekip 23 saat çalıştı.","en":"It took place in New York and a team of 140 people worked for 23 hours."},{"tr":"Joe, ameliyattan sonra mutlu olmak için her zaman bir neden olduğunu söyledi.","en":"After the surgery, Joe said that there was always a reason to be happy."}]},{"id":"CK-169","no":169,"title":"Hasta İnsanların Oksijene İhtiyacı Var","level":3,"code":"SAG","s":[{"tr":"Koronavirüsün ikinci dalgası Nijerya'yı vurdu ve COVID-19 hastaları için oksijenle ilgili sorunları beraberinde getirdi.","en":"A second wave of the coronavirus hit Nigeria and it brought problems with oxygen for COVID-19 patients."},{"tr":"Hastaneler, geçen yıl Sonbahar veya Sonbahar'dan bu yana 65.000'den fazla hasta rapor etti ve eskisine göre yedi kat daha fazla oksijene ihtiyaçları vardı.","en":"Hospitals reported more than 65,000 sick people since Autumn or Fall last year and they needed seven times more oxygen than before."},{"tr":"Kasım ayında oksijen üreten fabrikalar hasta sayısının çok hızlı artması nedeniyle sorun yaşamaya başladı.","en":"In November, factories that produced oxygen started to have problems because the number of patients grew very quickly."},{"tr":"Yetkililer iki yeni fabrika kurmaya karar verdi ve daha da fazlasını yapmayı planlıyorlar.","en":"Officials decided to build two new factories and they plan to build even more."},{"tr":"Bazı COVID-19 hastalarının çok fazla oksijene ihtiyacı vardır çünkü solunumlarında büyük problemleri vardır.","en":"Some COVID-19 patients need a lot of oxygen because they have big problems with their breathing."},{"tr":"Bazı hastaların çok fazla oksijene ihtiyacı yoktur ve hastanelerin ne kadar oksijene ihtiyaç duyacağını bilmek kolay olmamasının nedeni budur.","en":"Some patients do not need so much oxygen, and it is the reason why it is not easy to know how much oxygen hospitals will need."}]},{"id":"CK-170","no":170,"title":"California Otoyolu Çöküyor","level":2,"code":"DOG","s":[{"tr":"ABD, Kaliforniya'daki bir kış fırtınası şiddetli yağmur ve kar getirdi.","en":"A winter storm in California, US, brought heavy rain and snow."},{"tr":"Sonuç olarak, bir otoyolun bir kısmı Cuma günü okyanusa düştü.","en":"As a result, a part of a highway collapsed into the ocean on Friday."},{"tr":"California yetkilileri bunun nasıl olduğunu açıkladı.","en":"California officials explained how it happened."},{"tr":"Çok fazla yağmur suyu vardı ve drenaj boruları tüm suyu alamıyordu.","en":"There was a lot of rainwater and the drainage pipes could not take all the water away."},{"tr":"Su otoyola aktı ve yola zarar verdi.","en":"The water flowed onto the highway and it damaged the road."},{"tr":"Neyse ki, bu olduğunda yolda araba yoktu ve kimse yaralanmadı.","en":"Luckily, there were no cars on the road when it happened and nobody got hurt."},{"tr":"Kış fırtınaları iki Kaliforniya ilçesinde acil bir duruma neden oldu ve binlerce insan evlerini terk etmek zorunda kaldı.","en":"Winter storms caused an emergency in two California counties, and thousands of people had to leave their homes."},{"tr":"Kaza olduğunda yetkililer şaşırmadı.","en":"Officials were not surprised when the accident happened."},{"tr":"Yol bir tepenin kenarında ve bazı riskler getiriyor.","en":"The road is on the edge of a hill and it brings some risks."},{"tr":"Tepeler kayabilir ve kayalar düşebilir.","en":"Hills can slide and rocks can fall."},{"tr":"Doğa güçlü olduğu için insanlar bu konuda hiçbir şey yapamazlar.","en":"People cannot do anything about it because nature is strong."}]},{"id":"CK-171","no":171,"title":"Somali Otel Saldırısı","level":2,"code":"DUN","s":[{"tr":"Pazar akşamı, bir grup İslamcı Somali'nin başkenti Mogadişu'da bir otele saldırdı.","en":"On Sunday evening, a group of Islamists attacked a hotel in the Somali capital, Mogadishu."},{"tr":"Önce otelin önünde bir araba patladı ve ardından bir grup adam içeri koştu.","en":"First, a car exploded in front of the hotel, and then, a group of men ran inside."},{"tr":"Polisle ateş etmeye ve kavga etmeye başladılar.","en":"They started to shoot and fight with the police."},{"tr":"Çatışma sabah erken saatlere kadar sürdü ve polis dokuz kişinin öldüğünü söyledi.","en":"The shooting lasted until the early morning hours, and police said that nine people died."},{"tr":"Ölenlerin dördü saldırganlardı.","en":"Four of the dead people were the attackers."},{"tr":"Terörist bir grup El Şebab, saldırıyı kendilerinin yaptığını söyledi.","en":"A terrorist group, al-Shabaab, said that they made the attack."},{"tr":"Somali'deki siyasi durum şu anda istikrarsız ve ülkede siyaseti değiştirmek isteyen silahlı gruplar var.","en":"The political situation in Somalia is unstable now and there are armed groups that want to change the politics in the country."},{"tr":"Durum, ülkede seçimlerin yapıldığı geçen yılın Aralık ayından bu yana daha da kötüye gitti.","en":"The situation got worse since December last year that was the date of elections in the country."},{"tr":"Bazı politikacılar cumhurbaşkanının sonuçları etkilemek istediğini söylediği için seçimler gerçekleşmedi.","en":"The elections did not happen because some politicians said that the president wanted to influence the results."}]},{"id":"CK-172","no":172,"title":"Myanmar Darbesi","level":1,"code":"DUN","s":[{"tr":"Ordu 2011 yılına kadar Myanmar'da hüküm sürdü.","en":"The army ruled in Myanmar until 2011."},{"tr":"Bazı siyasi değişikliklerden sonra Aung San Suu Kyi ülkenin lideri oldu.","en":"After some political changes, Aung San Suu Kyi became the leader of the country."},{"tr":"Suu Kyi, 1989 ve 2010 yılları arasında 15 yıl hapis yattı.","en":"Between 1989 and 2010, Suu Kyi spent 15 years in prison."},{"tr":"1991'de Nobel Barış Ödülü'nü aldı.","en":"In 1991, she got the Nobel Peace Prize."},{"tr":"Rohingya halkına karşı güçlü bir eylemde bulunduğunu kabul ettiği için bazı insanlar ondan memnun değildi.","en":"Some people were not happy with her because she agreed with strong action against the Rohingya people."},{"tr":"Rohingya çatışması 2015'te başladı ve 700.000'den fazla insan Myanmar'ı terk etti.","en":"The Rohingya conflict started in 2015 and more than 700,000 people left Myanmar."},{"tr":"Pazartesi günü ordu ülkenin kontrolünü ele geçirdi ve birçok hükümet lideri hapse atıldı.","en":"On Monday, the army took control of the country, and many government leaders ended up in prison."},{"tr":"Ordu, Suu Kyi'nin kazandığı son seçimin adil olmadığını söyledi.","en":"The army said that the recent election, in which Suu Kyi won, was not fair."},{"tr":"Darbenin nedeni buydu.","en":"It was the reason for the coup."},{"tr":"Sokaklar artık askerlerle dolu, olağanüstü hal var ve insanlar gece dışarı çıkmasın.","en":"The streets are full of soldiers now, there is a state of emergency, and people must not go out at night."}]},{"id":"CK-173","no":173,"title":"Terminatör ve bir Fil","level":1,"code":"DOG","s":[{"tr":"Terminatör bir fil ile karşılaştı.","en":"The Terminator met an elephant."},{"tr":"Arnold Schwarzenegger, Güney Afrika'da safarideyken bir fil ile çok yakın bir karşılaşma yaşadı.","en":"While on safari in South Africa, Arnold Schwarzenegger had a very close encounter with an elephant."},{"tr":"Videoyu yaşandıktan hemen sonra Instagram'da 5,4 milyon takipçisi ile paylaştı.","en":"He shared the video with his 5.4 million followers on Instagram just after it happened."},{"tr":"Arabasının etrafında bir fil hareket ediyordu.","en":"An elephant was moving around his car."},{"tr":"Araba hareket etmeye başladığında arkasından koşmaya başladı.","en":"When the car started to move, it started running behind it."},{"tr":"Deneyim Schwarzenegger'i engellemedi.","en":"The experience did not put Schwarzenegger off."},{"tr":"İnsanların filleri öldürmeyi bırakmaları gerektiğini ve fotoğraf çekmeleri gerektiğini tweetledi.","en":"He tweeted that people should stop killing elephants and that they should take a photo, not a shot."}]},{"id":"CK-174","no":174,"title":"Vegan bir yaşam tarzı","level":2,"code":"SAG","s":[{"tr":"Veganuary, 2014 yılında başlayan bir kampanyadır ve amacı insanları veganlık hakkında bilgilendirmek ve Ocak ayı boyunca onlara vegan yemek yemelerini sağlamaktır.","en":"Veganuary is a campaign that started in 2014, and its idea is to inform people about veganism and make them eat vegan food for the whole of January."},{"tr":"Ocak 2021'de 500.000 kişi Veganuary'ye katıldı ve bunu birçok nedenden dolayı yaptılar.","en":"In January 2021, 500,000 people joined Veganuary, and they did it for many reasons."},{"tr":"Bazı insanlar daha sağlıklı olmak istediler veya çevreye yardım etmek istediler.","en":"Some people wanted to become healthier or they wanted to help the environment."},{"tr":"Birçok insan hayvanları ve çiftliklerde nasıl yaşadıklarını önemsiyordu.","en":"Many people cared about the animals and how they lived on farms."},{"tr":"Birçok profesyonel sporcu Veganuary'yi destekledi ve vegan olduklarında hayatlarının değiştiğini söylediler.","en":"Many professional sportspeople supported Veganuary, and they said that their lives changed when they became vegan."},{"tr":"Daha fazla enerjileri vardı, kendilerini daha güçlü hissediyorlardı ve daha sıkı çalışabilirlerdi.","en":"They had more energy, they felt stronger, and they could train harder."},{"tr":"Bazı insanlar vegan olmak için çok uğraşıyorlar ama bundan zevk almıyorlar.","en":"Some people try very hard to become vegan, but they do not enjoy it."},{"tr":"Bazen daha iyi yemek yemek ve yemeğin nereden geldiğini düşünmek daha iyidir.","en":"Sometimes it is better to simply eat better and think about where food comes from."}]},{"id":"CK-175","no":175,"title":"Yalan Haberler ve 1918 Gribi","level":2,"code":"TAR","s":[{"tr":"1918'de dünyaya bir grip vurdu ve salgın ABD tarihinin en kötüsü oldu.","en":"In 1918, a flu hit the world, and the pandemic became the worst in US history."},{"tr":"1918 ile 1919 arasında yaklaşık 675.000 Amerikalı öldü ve sayının bu kadar yüksek olmasının nedeni 1. Dünya Savaşı ve savaş propagandasıydı.","en":"Between 1918 and 1919, about 675,000 Americans died and the reason why the number was so high was World War I and war propaganda."},{"tr":"ABD başkanı Woodrow Wilson'ın savaşmak için erkeklere ve oğlanlara ihtiyacı vardı.","en":"The US president Woodrow Wilson needed men and boys to fight."},{"tr":"İnsanlar gripten haberdar olsaydı, savaşı etkileyebilirdi.","en":"If people knew about the flu, it could have an impact on the war."},{"tr":"ABD hükümeti, gazetecilerin insanları bilgilendirme şeklini değiştiren bir yasa çıkardı.","en":"The US government passed a law that changed the way how journalists informed people."},{"tr":"Gazeteciler hükümet hakkında kötü bir şey yazarlarsa hapse girebilirler.","en":"If journalists wrote something bad about the government, they could go to prison."},{"tr":"Gazeteler sadece savaş hakkında yazdı ve grip hakkında çok az bilgi vardı.","en":"Newspapers wrote only about the war and little information was about the flu."},{"tr":"1918 gribi çok ölümcül oldu ve insanlar hastalığın ilk belirtilerinden 12 saat sonra ölebilirdi.","en":"The 1918 flu was very deadly, and people could die 12 hours after the first signs of the disease."},{"tr":"İnsanlar burun, ağız, göz ve kulaklarından kanadı.","en":"People bled from the nose, mouth, eyes, and ears."}]},{"id":"CK-176","no":176,"title":"Robot Kelimesinin 100 Yılı","level":2,"code":"TAR","s":[{"tr":"\"Robot\" kelimesinin nereden geldiğini biliyor musunuz?","en":"Do you know where the word ’robot’ comes from?"},{"tr":"Çek yazar Karel Čapek bu kelimeyi ilk olarak \"R.U.R.\" adlı bir bilim kurgu oyununda kullandı.","en":"The Czech writer Karel Čapek first used the word in a science-fiction play called ‘R.U.R.’."},{"tr":"Karel Čapek 1890'da doğdu ve zamanının siyasi durumunu eleştiren birçok eser yazdı.","en":"Karel Čapek was born in 1890 and he wrote many works which criticized the political situation of his time."},{"tr":"1921'de \"R.U.R.\" yazdı ve oyun robotlar yapan bir fabrika hakkındaydı.","en":"He wrote ‘R.U.R.’ in 1921, and the play was about a factory which made robots."},{"tr":"\"Robot\" kelimesi, sıkı çalışma anlamına gelen Çekçe \"robota\" kelimesinden gelir. Čapek birçok yazar ve film yapımcısına ilham verdi ve robotların gücü konusu çok popüler oldu.","en":"The word ’robot’ comes from the Czech word ’robota’ which means hard work. Čapek inspired many authors and filmmakers and the topic of the power of robots became very popular."},{"tr":"Günümüzde birçok farklı robot türü var.","en":"Today, there are many different types of robots."},{"tr":"Bazıları küçük, bazıları büyük ve bazıları farklı görevler yapabilir.","en":"Some are small, some are big and some can do different tasks."},{"tr":"Hastane zeminlerini temizlerler, otellerde ve restoranlarda yardım ederler ve hatta insanların evcil hayvanları bile olabilirler.","en":"They clean hospital floors, help in hotels and restaurants, and they can even be people’s pets."}]},{"id":"CK-177","no":177,"title":"Endonezya'da Tütün Çocukları","level":2,"code":"DUN","s":[{"tr":"Endonezya, en büyük 5. tütün üreticisidir.","en":"Indonesia is the 5th biggest producer of tobacco."},{"tr":"Endonezya'da 15 yaşın altındaki çocukları işe almak yasa dışıdır, ancak Endonezya’nın tarımında yaklaşık 1,5 milyon çocuk çalışmaktadır.","en":"Hiring children under 15 years of age in Indonesia is illegal but around 1.5 million children work in Indonesia’s agriculture."},{"tr":"Binlercesi kauçuk, hurma yağı ve tütün tarlalarında çalışıyor.","en":"Thousands of them work on rubber, palm oil, and tobacco plantations."},{"tr":"Birçoğu \"yeşil tütün hastalığından\" muzdariptir - baş ağrısı çeker, başları döner ve hastalanırlar.","en":"Many of them suffer from “green tobacco sickness” – they get headaches, get dizzy, and sick."},{"tr":"Ailelerinin para kazanmasına yardımcı olmak için okulu atlıyorlar ama günde sadece bir dolar kazanıyorlar.","en":"They skip school to help their families make money, but they make only one dollar a day."},{"tr":"İnsan hakları grupları bir şeyleri değiştirmeye çalışıyor.","en":"Human rights groups are trying to change things."},{"tr":"Endonezya'nın en büyük şirketlerinden aileleri tehlikeler hakkında eğitmelerini istiyorlar.","en":"They ask the biggest companies in Indonesia to educate the families about the dangers."}]},{"id":"CK-178","no":178,"title":"Korsanlar Gemilere Saldırıyor","level":2,"code":"DUN","s":[{"tr":"Gine Körfezi, Batı Afrika ülkelerine ürün ulaştıran büyük gemiler için önemli bir yoldur.","en":"The Gulf of Guinea is an important way for big ships which deliver products to West African countries."},{"tr":"Korsanlar bunu biliyor ve şirketlerin gemileri ve denizcileri için çok para ödeyeceklerini biliyorlar.","en":"Pirates know it, and they know that companies will pay a lot of money for their ships and sailors."},{"tr":"Pek çok korsan, büyük ekonomik sorunları olan bir ülke olan Nijerya'dan geliyor.","en":"Many pirates come from Nigeria which is a country with big economic problems."},{"tr":"Ülke son beş yılda iki durgunluk yaşadı ve birçok insan işini kaybetti.","en":"The country went through two recessions in the past five years, and many people lost their jobs."},{"tr":"Bazı insanlar ne yapacaklarını bilemediler ve gemilere saldırmaya karar verdiler.","en":"Some people did not know what to do, and they decided to attack ships."},{"tr":"Korsanlar kıyıya yakın nehirlerde beklerler, bir gemiye saldırırlar ve mürettebatı kaçırırlar.","en":"Pirates wait in rivers near the coast, they attack a ship, and they kidnap the crew."},{"tr":"Şirketlerden para istiyorlar ve şirketler ödeme yaptığında korsanlar gemiyi ve mürettebatı serbest bırakıyor.","en":"They ask companies for money and when companies pay, pirates release the ship and the crew."},{"tr":"25 ülke korsanları durdurmaya çalışıyor ama birlikte çalışmak önemli çünkü korsanların silahları var ve çok tehlikeli.","en":"25 countries try to stop the pirates, but it is important to work together because the pirates have guns and they are very dangerous."}]},{"id":"CK-179","no":179,"title":"İngiliz barları ve Koronavirüs","level":3,"code":"SAG","s":[{"tr":"“Lamb and Flag”, Oxford, İngiltere'de bir bar ve 1566'da açıldı.","en":"Lamb and Flag is a pub in Oxford, UK, and it opened in 1566."},{"tr":"Daha sonra şehir merkezine taşındı ve Tolkien ve Lewis gibi ünlü yazarların gözde mekanı oldu.","en":"Later, it moved to the city center, and it became a favorite place for famous writers like Tolkien and Lewis."},{"tr":"Oxford, öğrencilerin ve akademisyenlerin yaşadığı bir yerdi ve barlar hayatlarının bir parçası haline geldi.","en":"Oxford was a place where students and scholars lived, and pubs became a part of their lives."},{"tr":"Öğrenciler bu güne kadar bazı barları canlı tuttu, ancak koronavirüs salgını her şeyi değiştirdi.","en":"Students kept some pubs alive to this day, but the coronavirus pandemic changed everything."},{"tr":"Şimdi 455 yıl sonra Kuzu ve Bayrak para yüzünden kapanmak zorunda.","en":"Now, after 455 years, Lamb and Flag must close because of money."},{"tr":"Koronavirüs birçok bar, restoran ve oteli etkiledi ve insanlar bu yerlerin kendileri için ne kadar önemli olduğunu görmeye başladı.","en":"The coronavirus had an impact on many pubs, restaurants, and hotels, and people started to see how important these places are for them."},{"tr":"Bazı politikacılar hükümetten, İngiliz yaşamının ve geleneğinin önemli bir parçası oldukları için barlara daha fazla para vermesini istedi.","en":"Some politicians asked the government to give more money to pubs because they are an important part of British life and tradition."}]},{"id":"CK-180","no":180,"title":"Bira Yogası","level":1,"code":"SAG","s":[{"tr":"Kamboçya'daki insanlar, ülke kapandığından dolayı altı hafta boyunca egzersiz derslerine gidemedi.","en":"People in Cambodia couldn’t go to exercise classes for six weeks because the country was on lockdown."},{"tr":"Resmi olarak, ülkede COVID-19 nedeniyle kimse ölmedi ve kapanma 1 Ocak'ta sona erdi.","en":"Officially, no one died in the country owing to Covid-19, and the lockdown ended on January 1."},{"tr":"Bir bira fabrikası egzersiz yapmanın yeni bir yolunu buldu ve bira yoga dersleri verdi.","en":"A brewery came up with a new way to exercise and it offered beer yoga classes."},{"tr":"Bir ders 60 dakika sürdü ve aynı sınıfa 12'den fazla kişi katılamazdı.","en":"One class lasted 60 minutes and no more than 12 people could attend the same class."},{"tr":"Bir ders sekiz dolara mal oluyor ve fiyata, ders sırasında insanların içebileceği bir bira da dahil.","en":"One class cost eight dollars and the price included one beer that people could drink during the class."},{"tr":"Bazı insanlar kendilerine sıkıcı geldiği için yoga derslerini sevmiyordu.","en":"Some people didn’t like yoga classes since they were boring for them."},{"tr":"Ama egzersiz yapmaktan çok arkadaşlarla buluşmakla ilgili olan bira yogasından hoşlanıyorlardı.","en":"But, they enjoyed beer yoga, which was more about meeting friends than exercising."},{"tr":"İşten sonra eğlenme zamanları gelmişti.","en":"It was their time for fun after work."},{"tr":"Bira yogası ABD'de 2013'te başladı ve dünyanın birçok yerinde ortaya çıktı.","en":"Beer yoga started in the US in 2013 and it appeared in many parts of the world."},{"tr":"Kısa bir süre için popüler oldu.","en":"It became popular only for a short time."}]},{"id":"CK-181","no":181,"title":"Kahveli Coca-Cola","level":2,"code":"TOP","s":[{"tr":"Geçtiğimiz hafta, Coca-Cola şirketi ABD pazarına iki yeni ürün tanıttı.","en":"Last week, Coca-Cola company introduced two new products to the US market."},{"tr":"Ürünler Kahveli Coca-Cola ve Kahveli Sıfır Şekerli Coca-Cola idi.","en":"The products were Coca-Cola with Coffee and Coca-Cola with Coffee Zero Sugar."},{"tr":"Coca-Cola'nın marka direktörüne göre, Coca-Cola with Coffee öğleden sonra için mükemmel bir içecektir.","en":"According to the brand director of Coca-Cola, Coca-Cola with Coffee is a perfect drink for the afternoon."},{"tr":"Pek çok insan kahveyi sever ve birçok kişi Coca-Cola'yı sever ve bazen ne içeceğine karar veremezler.","en":"Many people love coffee, and many people love Coca-Cola, and sometimes they cannot decide what they drink."},{"tr":"Artık tek üründe her iki içeceğin de tadını çıkarabilecekler.","en":"Now, they will be able to enjoy both drinks in one product."},{"tr":"Coca-Cola için mükemmel bir iş çünkü kahveyi tercih edenler Coca-Cola alacak.","en":"It is a perfect business for Coca-Cola because people who prefer coffee will buy Coca-Cola."},{"tr":"Yeni içecekler Brezilya kahvesi içeriyor ve üç farklı tadı var.","en":"The new drinks contain Brazilian coffee, and they have three different flavors."},{"tr":"Coca-Cola birçok ülkede Coca-Cola Coffee satmaktadır ve tadı her ülkede biraz farklı olabilir.","en":"Coca-Cola sells Coca-Cola Coffee in many countries and the taste can be a little different in each country."},{"tr":"Bunun nedeni, farklı ülkelerdeki insanların farklı zevklere sahip olmasıdır.","en":"The reason is that people in different countries have different tastes."}]},{"id":"CK-182","no":182,"title":"Başkanlık Sarayı","level":2,"code":"DUN","s":[{"tr":"Alexei Navalny, Rusya Devlet Başkanı Vladimir Putin'in siyasi rakibi ve Karadeniz kıyısındaki bir saray hakkında bir belgesel yaptı.","en":"Alexei Navalny is a political rival of the Russian president Vladimir Putin and he made a documentary about a palace on the Black Sea coast."},{"tr":"Saray çok büyük ve Monako'dan kırk kat daha büyük bir arazi üzerinde.","en":"The palace is very big, and it is on a large of land which is forty times larger than Monaco."},{"tr":"Bahçeler, bir bağ, helikopterler için bir iniş yeri ve özel bir tiyatro var.","en":"There are gardens, a vineyard, a landing place for helicopters, and a private theatre."},{"tr":"Güvenlik sarayı her zaman izler.","en":"Security watches the palace all the time."},{"tr":"Belgeselde Navalny, mülkün Putin'e ait olduğunu ve 1.3 milyar dolara mal olduğunu söyledi.","en":"In the documentary, Navalnysaid that the estate belonged to Putin and that it cost 1.3 billion dollars."},{"tr":"Navalny, Putin'in parayı yolsuzluktan aldığını söyledi.","en":"Navalny said that Putin got the money from corruption."},{"tr":"Sonra Putin, sarayın kendisine veya ailesine ait olmadığını söyledi.","en":"Then Putin said that the palace didn’t belong to him or his family."},{"tr":"Belgeselin yalanlarla dolu olduğunu söyledi.","en":"He said that the documentary was full of lies."},{"tr":"Sonra uzmanlar, Putin'in Navalny'den korktuğunu çünkü Navalny'nin Rusya'da daha popüler hale geldiğini söyledi.","en":"Then The experts said that Putin was afraid of Navalny because Navalny was getting more popular in Russia."}]},{"id":"CK-183","no":183,"title":"Larry King Öldü","level":2,"code":"POR","s":[{"tr":"Larry King ünlü bir talk-show sunucusuydu ve geçen hafta ABD, Los Angeles'ta 87 yaşında öldü.","en":"Larry King was a famous talk show host and he died last week in Los Angeles, US, at the age of 87."},{"tr":"King'in kariyeri neredeyse 60 yıl sürdü ve dünya çapında üne kavuştu.","en":"King’s career lasted almost 60 years and he became famous worldwide."},{"tr":"25 yıldır CNN'de yayınlanan \"Larry King Live\" adlı kendi talk şovu vardı.","en":"He had his own talk show called “Larry King Live” which ran on CNN for 25 years."},{"tr":"King, yaklaşık 50.000 politikacı ve ünlü ile röportaj yaptı.","en":"King did interviews with around 50000 politicians and celebrities."},{"tr":"Bu insanlar örneğin ABD başkanları, Dalai Lama ve Amerikalı şarkıcı Lady Gaga idi.","en":"These people were for examples US presidents, Dalai Lama, and the American singer Lady Gaga."},{"tr":"King, hayatında pek çok ödül aldı, ancak bazıları onu da eleştirdi.","en":"King got many rewards in his life, but some people criticized him, too."},{"tr":"King'in tarzı agresif değildi ve misafirlerini cevap vermeye zorlamadı.","en":"King’s style wasn’t aggressive, and he didn’t force his guests to answer."},{"tr":"Medya, King'in geçen ay COVID-19 ile hastanede olduğunu söyledi, ancak bundan ölüp ölmediğini söylemediler.","en":"The media said that King was in the hospital with Covid-19 last month, but they didn’t say if he died from it."}]},{"id":"CK-184","no":184,"title":"Yeni Başkan İnsanlardan Maske Takmalarını İstiyor","level":2,"code":"SAG","s":[{"tr":"Yeni ABD başkanı Joe Biden, koronavirüs ile nasıl savaşmak istediğini açıkladı.","en":"The new US president, Joe Biden, announced how he wanted to fight with the coronavirus."},{"tr":"Şubat ayında 100.000'den fazla insanın ölebileceğini söyleyen Biden, önümüzdeki 100 gün boyunca insanlardan yüz maskesi takmalarını istedi.","en":"In February, Biden, who said that more than 100000 people could die, asked people to wear face masks for the next 100 days."},{"tr":"İnsanlar maske taksa, yaklaşık 50.000 hayat kurtarabilirdi.","en":"If people wore masks, it could save about 50000 lives."},{"tr":"Biden, maske takmanın COVID-19 aşılarından daha önemli olduğunu söyledi.","en":"Biden said that wearing a mask was more important than Covid-19 vaccines."},{"tr":"Yeni başkan, son başkan Donald Trump'ı da eleştirdi ve Trump'ın virüsü durdurmak için yeterince çalışmadığını söyledi.","en":"The new president criticized the last president, Donald Trump, and he said that Trump didn’t work hard enough to stop the virus."},{"tr":"Biden'in fikri, aşıları insanlara daha hızlı ulaştırmak ve COVID-19 hastalarına daha fazla ilaç ulaştırmaktır.","en":"Biden’s idea is to get vaccines to people faster and to get more drugs to Covid-19 patients."},{"tr":"Yakında, ABD'ye gelen kişilerin negatif bir COVID-19 testi göstermesi gerekecek.","en":"Soon, people who come to the US will have to show a negative Covid-19 test."}]},{"id":"CK-185","no":185,"title":"Sıradışı Kartlar","level":2,"code":"TAR","s":[{"tr":"Indy Mellink, sıradışı kartlar yaratan 23 yaşında bir psikoloji öğrencisi ve tasarımcı.","en":"Indy Mellink is a 23-year-old psychology student and designer who created unusual cards."},{"tr":"Geçen yaz kuzenine bir oyunu açıklıyordu ve kendine bir kralın neden bir vezirden daha çok kağıt oynadığını sordu.","en":"Last summer, she was explaining a game and she asked herself why a king played cards more than a queen."},{"tr":"Tarihte erkeklerin her zaman kadınlardan daha önemli olduğunu insanlara göstermenin önemli olduğunu düşünüyordu.","en":"In history, she thought that it was important to make people see that men were always more important than women."},{"tr":"Mellink, üzerinde erkek ve kadın resimleri olmayan kartlar yapma fikrine sahipti.","en":"Mellink got an idea to make cards that would have no images of men and women on them."},{"tr":"Kral, kız ve vale yerine altın, gümüş ve bronz çubukların olduğu kartlar yaptı.","en":"She made cars where there were gold, silver, and bronze bars instead of king, queen, and jack."},{"tr":"Mellink kartları test etti ve yaklaşık 1.500 paket sattı.","en":"Mellink tested the cards and she sold around 1500 packs."},{"tr":"Bazı oyuncular kağıt oynarken erkeklerin ve kadınların farklı durumlarını hiç düşünmediklerini söylediler.","en":"When some players played cards, they said that they never thought about the different situations of men and women."},{"tr":"Bir kralın bir kraliçeden daha önemli olduğunu düşünmediler.","en":"They didn’t think that a king was more important than a queen."}]},{"id":"CK-186","no":186,"title":"Louvre Piramidi","level":3,"code":"TAR","s":[{"tr":"Fransız sanatçı JR, Louvre Müzesi'nin girişi olan 1980'lerin cam piramidini sakladı.","en":"French artist JR hid the 1980s glass pyramid which is the entrance to the Louvre Museum."},{"tr":"Onu çevreleyen binaların siyah beyaz resimleriyle kapladı, böylece müzenin avlusundaki belirli bir noktadan devasa cam piramit yok olmuş gibi görünüyordu.","en":"He covered it in black and white pictures of the buildings that surround it, so from a specific spot in the courtyard of the museum, it appeared as if the huge glass pyramid disappeared."},{"tr":"Fransız sanatçı, çalışmalarıyla dünyanın dört bir yanındaki binaları ve mahalleleri dönüştürerek sokakları dev kolajlara dönüştürdü.","en":"The French artist transformed streets into giant collages turning buildings and neighborhoods around the world with his work."},{"tr":"Örneğin 2009'da Nairobi'deki Kibera gecekondu mahallesini kadın sakinlerinin portreleriyle kapladı.","en":"In 2009, for example, he covered the Kibera slum in Nairobi with portraits of its women residents."}]},{"id":"CK-187","no":187,"title":"Köpek Hastanenin Dışında Bekliyor","level":1,"code":"DOG","s":[{"tr":"Cemal Şentürk adlı Türk bir adamın Boncuk adında bir köpeği var.","en":"A Turkish man named Cemal Şentürk has a dog called Boncuk."},{"tr":"Şentürk ve Boncuk'un çok güçlü bir ilişkisi var ve her zaman birlikte olmaya alışkınlar.","en":"Şentürk and Boncuk have a very strong relationship, and they are used to being together all the time."},{"tr":"Geçenlerde Şentürk hastaneye gitmek zorunda kaldı ve onu oraya bir ambulans götürdü.","en":"Recently, Sentürk had to go to the hospital and an ambulance took him there."},{"tr":"Boncuk ambulansı takip etti ve hastanenin dışında kaldı.","en":"Boncuk followed the ambulance and stayed outside the hospital."},{"tr":"Köpek orada birkaç gün bekledi ve Şentürk'ün kızı onu evine götürdü.","en":"The dog waited there for a few days, and Sentürk’s daughter took her home."},{"tr":"Sonra köpek hastaneye koştu ve bunu birkaç kez yaptı.","en":"Then, the dog ran back to the hospital and she did it several times."},{"tr":"Altı gün sonra doktorlar Şentürk'ü hastaneden çıkardı ve sonunda köpeğiyle tekrar karşılaştı.","en":"After six days, doctors released Sentürk from the hospital and he and his dog finally met again."},{"tr":"İkisi için de çok mutlu bir andı.","en":"It was a very happy moment for both of them."},{"tr":"Şentürk, köpeğini çok özlediğini söyledi.","en":"Şentürk said that he missed his dog very much."},{"tr":"Köpeklerin insanları mutlu ettiğini ve onların en iyi arkadaşları olabileceklerini söyledi.","en":"He said that the dogs make people happy and they could be their best friends."}]},{"id":"CK-188","no":188,"title":"Tenisçiler Otel Odalarında Kalmalı","level":3,"code":"SPO","s":[{"tr":"İki haftalık tenis turnuvası, Avustralya Açık, 8 Şubat'ta başlıyor ve turnuvaya katılan 1.200'den fazla kişinin katı kurallara uyması gerekiyor.","en":"The two-week tennis tournament, the Australian Open, is starting on Ferbuary 8, and more than 1200 people who take part in the tournament must keep strict rules."},{"tr":"Bu kişiler memurlar, oyuncular ve üç uçakla gelen ekipleridir ve daha sonra aynı uçuştaki diğer bazı yolcular COVID-19 için pozitif testler yaptı.","en":"These people are officials, players, and their teams who came on three planes, and later some other passengers on the same flight had positive tests for Covid-19."},{"tr":"Turnuva organizatörleri 72 oyuncuyu otel odalarında izole etmeye karar verdi ve tüm oyuncuların her gün bir COVID-19 testine gitmesi gerekiyor.","en":"Tournament organizers decided to isolate 72 players in hotel rooms, and all players need to go for a Covid-19 test every day."},{"tr":"Bazı oyuncular yeterince eğitim alamadıkları için sinirlendi.","en":"Some players got angry because they couldn’t get enough training."},{"tr":"Novak Djokovic dünyanın 1 numaralı yıldızı ve organizatörlerden antrenman yapmak için daha fazla zaman ayırmalarını istedi.","en":"Novak Djokovic is the world’s No.1 star, and he asked organizers to get more time so as to train."},{"tr":"Oyuncuların tenis kortu olan evlere taşınabileceğini söyledi.","en":"He said that players could move into houses with tennis courts."}]},{"id":"CK-189","no":189,"title":"İşaret Uygulaması","level":2,"code":"BLT","s":[{"tr":"2009 yılında Brian Acton ve Jan Koum bir mobil uygulama olan WhatsApp'ı yarattı.","en":"In 2009, Brian Acton and Jan Koum created a mobile app, WhatsApp."},{"tr":"WhatsApp kullanıcıları ücretsiz görüşme yapabilir, görüntülü görüşme yapabilir veya mesaj gönderebilir.","en":"WhatsApp users can make free calls, video calls, or send messages."},{"tr":"Facebook, 2014 yılında WhatsApp'ı 22 milyar dolara satın aldı ve ondan para kazanmak istedi.","en":"In 2014, Facebook bought WhatsApp for 22 billion dollars, and it wanted to make money from it."},{"tr":"Facebook, şirketlerden ve reklamcılardan para kazanmak istiyordu ancak WhatsApp kullanıcıları hakkında biraz bilgi almak gerekiyordu.","en":"Facebook wanted to make money from companies and advertisers, but it was necessary to get some information about WhatsApp users."},{"tr":"Acton bundan hoşlanmadı ve 2017'de WhatsApp'taki işinden istifa etti.","en":"Acton didn’t like this, and in 2017, he resigned from his job on WhatsApp."},{"tr":"Acton, 2018'de Signal Messenger adında yeni bir şirket kurdu.","en":"In 2018, Acton started a new company called Signal Messenger."},{"tr":"WhatsApp ile pek çok benzer şeyi yapabilir, ancak gizlilikle ilgili sorunları yoktur.","en":"I can do many similar things as WhatsApp, but it doesn’t have problems with privacy."},{"tr":"Güvenlidir ve mesajı kimin için olduğu dışında kimse mesajı okuyamaz.","en":"It is safe and nobody can read a message except the person who the message is for."}]},{"id":"CK-190","no":190,"title":"Kolları ve Bacakları Olmayan Bir Adam","level":1,"code":"POR","s":[{"tr":"Youssef Abu Amira, Gazze, Filistin'den geliyor ve yakın zamanda hukuk diploması aldı.","en":"Youssef Abu Amira comes from Gaza, Palestine, and he recently got a law degree."},{"tr":"Onunla ilgili özel bir şey de var.","en":"There is also something special about him."},{"tr":"Yusuf bacaksız doğdu ve kolları tam olarak gelişmedi.","en":"Yusuf was born without legs, and his arms didn’t develop fully."},{"tr":"Yusuf güçlü bir adamdır ve engeli onu hayallerine ulaşmaktan asla alıkoymamıştır.","en":"Yusuf is a strong man, and his disability never stopped him from achieving his dreams."},{"tr":"Youssef hayatı seviyor ve mutlu olmak istiyor.","en":"Youssef loves life and he wants to be happy."},{"tr":"Yeni bir hobi edinmiş ve karate yapmaya başlamıştır.","en":"He took up a new hobby and he started to do karate."},{"tr":"Karate, iki kişinin birbirini yumruklayıp tekmelediği Japon dövüş sanatıdır.","en":"Karate is Japanese martial art where two people punch and kick each other."},{"tr":"Youssef çok sert yumruk atabiliyor ve hayali diğer sporcularla uluslararası düzeyde rekabet etmek.","en":"Youssef can punch very hard, and his dream is to compete with other sportsmen on an international level."}]},{"id":"CK-191","no":191,"title":"COVID-19 Nedeniyle İki Milyon Kişi Öldü","level":2,"code":"SAG","s":[{"tr":"COVID-19'dan ölenlerin sayısı 2 milyona ulaştı.","en":"The number of people who died from Covid-19 reached two million."},{"tr":"Ne yazık ki bilim insanları rakamların yakında düşmesini beklemiyorlar.","en":"Unfortunately, scientists don’t expect the numbers to go down soon."},{"tr":"Bazı ülkeler insanları aşılamaya başladı, ancak süreç yavaş ilerliyor ve bazı ülkelerde aşı mevcut değil.","en":"Some countries started to vaccinate people, but the process is slow, and there isn’t any vaccine available in some countries."},{"tr":"Bu nedenle yazdan önce virüsü kontrol altına almak zor olabilir.","en":"Therefore, it could be difficult to get the virus under control before summer."},{"tr":"Washington Üniversitesi'nden bilim insanları, ölenlerin sayısının 2021'in sonunda 2,89 milyona ulaşabileceğini söyledi.","en":"Scientists from the University of Washington said that the number of dead people could reach 2.89 million by the end of 2021."},{"tr":"En çok ölülerin yaşandığı ülkeler ABD, Brezilya, Hindistan ve Meksika'dır.","en":"Countries with the highest number of dead people are the US, Brazil, India, and Mexico."},{"tr":"ABD'de, COVID-19 nedeniyle yaklaşık 390.000 kişi öldü.","en":"In the US, almost 390000 people died from Covid-19."},{"tr":"COVID-19, 2020'de sıtma ve tüberkülozdan daha fazla insanı öldürdü.","en":"Covid-19 killed more people than malaria and tuberculosis in 2020."}]},{"id":"CK-192","no":192,"title":"Avustralya'da Sıcak Hava Balonu","level":1,"code":"TOP","s":[{"tr":"Avustralya'da 9 kişinin bulunduğu bir sıcak hava balonu okyanusun üzerinde uçuyordu.","en":"A hot air balloon was flying over the ocean in Australia with 9 people on board."},{"tr":"Yakıtı azalıyordu ve düzgün inemiyordu.","en":"It was running low on fuel and it wasn’t able to land properly."},{"tr":"İnsanlar, balonun okyanusa düşmesinden korkuyorlardı, ancak yoldan geçen bir tekne onu gördü ve yardım etti.","en":"The people were afraid that the balloon would ditch into the ocean, but a passing boat saw it, and helped."},{"tr":"Pilot, yolcuları teker teker indirmeyi başardı.","en":"The pilot was able to offload the passengers one at a time."},{"tr":"Yolcular güvende olduktan sonra, balon pilotun bir sahile güvenli bir şekilde inmesi için yeterince hafifti.","en":"Once the passengers were safe, the balloon was light enough for the pilot to land safely on a beach."},{"tr":"Eylemleri için çok övgü aldı.","en":"He received a lot of praise for his actions."}]},{"id":"CK-193","no":193,"title":"İşletmeler için Daha İyi Bir Gelecek","level":3,"code":"SAG","s":[{"tr":"Dünyadaki birçok ülke insanları koronavirüse karşı aşılamaya başlıyor.","en":"Many countries in the world are starting to vaccinate people against the coronavirus."},{"tr":"Muhtemelen insanların davranışları ve işletmeler üzerinde de bir etkisi olacaktır.","en":"It will probably have an impact on people’s behavior and on businesses, too."},{"tr":"En büyük etki enerji işi üzerinde olacaktır.","en":"The biggest impact will be on the energy business."},{"tr":"İnsanlar daha fazla seyahat etmeye, uçmaya ve arabalarını kullanmaya başlayacak, bu da benzin veya yakıt ve yağ talebini artıracaktır.","en":"People will start to travel more, fly, and use their cars, which will increase the demand for petrol, or fuel, and oil."},{"tr":"İnsanlar muhtemelen daha az bilgi teknolojisi kullanacaklar çünkü evden çok fazla çalışmayacaklar ve daha az çevrimiçi toplantı yapacaklar.","en":"People will probably use less information technology because they will not work from home so much, and they will have fewer online meetings."},{"tr":"Ayrıca restoranlar yeniden açılacak ve bazı tarımsal ürünlere olan talep artacaktır.","en":"Restaurants will also reopen and the demand for some agricultural products will grow."},{"tr":"Bu ürünler örneğin kahve veya şeker olacaktır.","en":"These products will be, for example, coffee and sugar."}]},{"id":"CK-194","no":194,"title":"Dalai Lama, Greta ile Konuşuyor","level":2,"code":"DUN","s":[{"tr":"Dalai Lama, Tibet'in ruhani lideridir ve küresel sorunlarla ilgilenmektedir.","en":"Dalai Lama is the spiritual leader of Tibet, and he is interested in global problems."},{"tr":"Geçen hafta Greta Thunberg ile konuştu.","en":"Last week, he spoke to Greta Thunberg."},{"tr":"Greta Thunberg, iklim değişikliğini durdurmak isteyen gençlerin lideri olan İsveçli bir kız.","en":"Greta Thunberg is a Swedish girl who became the leader of young people who wanted to stop climate change."},{"tr":"Dalai Lama, Thunberg ve iki bilim adamı iklim krizi hakkında konuştu.","en":"Dalai Lama, Thunburg, and two scientists spoke about the climate crisis."},{"tr":"Dalai Lama, Thunberg'in çok cesur bir genç kadın olduğunu ve ona daha iyi bir gelecek için umut verdiğini söyledi.","en":"Dalai Lama said that Thunberg was a very brave young woman and that she gave him hope for a better future."},{"tr":"Dalai Lama, dünyadaki tüm insanların birlikte düşünmesi ve çalışması gerektiğini söyledi.","en":"Dalai Lama said that all people in the world had to think and work together."},{"tr":"Thunberg, insanların iklim sorunları hakkında daha fazla şey öğrenmesi ve onları durdurmak için bir şeyler yapması gerektiğini söyledi.","en":"Thunberg said that people had to learn more about climate problems and do something in order to stop them."}]},{"id":"CK-195","no":195,"title":"En Eski Resim","level":2,"code":"TAR","s":[{"tr":"Bilim adamları dünyanın en eski hayvan resmi olduğuna inandıkları bir resim buldular.","en":"Scientists found a painting that they believed that it was the oldest animal painting in the world."},{"tr":"Resim, Endonezya'nın Sulawesi adasının dağlarındaki bir vadide, bir mağaradaydı.","en":"The painting was in a cave, in a valley up in the mountains of Indonesian islands of Sulawesi."},{"tr":"Büyük bir şehre çok yakındı ama oraya gitmek kolay olmadı.","en":"It was very close to a big city, but it wasn’t easy to get to the place."},{"tr":"Bilim adamları çok şanslıydı çünkü resmin üzerinde bir mineral vardı.","en":"Scientists were very lucky because there was a mineral on the painting."},{"tr":"Bu sayede bilim adamları, resmin kaç yaşında olduğunu bulmak için özel bir yöntem kullanabildiler.","en":"Thanks to it, scientists could use a special method to find out how old the painting was."},{"tr":"45.500 yaşında olduğunu öğrendiler.","en":"They found out that it was 45500 years old."},{"tr":"Resimde başı, kuyruğu ve bacakları olan bir yaban domuzu görülüyordu.","en":"The painting showed a wild pig with a head, tail, and legs."},{"tr":"Yanında iki insan eli vardı.","en":"There were two human hands next to it."}]},{"id":"CK-196","no":196,"title":"Hayatımızda Robotlar","level":1,"code":"BLT","s":[{"tr":"Robotlar hayatımızın bir parçası ve daha da fazla var olmak üzereler.","en":"Robots are part of our lives, and they are about to be even more present."},{"tr":"İlk örnek, sürücüsüz arabalar olacak.","en":"The first example is going to be self-driving cars."},{"tr":"Önümüzdeki 20-30 yıl içinde evlerimizde ciddi insansı robotlar görmeye başlayacağız.","en":"In the next 20 or 30 years, we will start to see serious humanoid robots in our homes."},{"tr":"Bilim kurguda gördüğümüz her şeyi yapacaklar.","en":"They will do all the things that we see in science fiction."},{"tr":"Robotlar insanların ilgisini çeker ama aynı zamanda onları korkutur.","en":"Robots intrigue people, but also scare them."},{"tr":"Londra'daki Bilim Müzesi'nin küratörü, bu tepkinin doğal ve insani olduğunu söylüyor.","en":"The curator of the Science Museum in London says that this reaction is natural and human."}]},{"id":"CK-197","no":197,"title":"İnsanlar Daha Az Çikolata Yiyor","level":3,"code":"DOG","s":[{"tr":"ABD ve Avrupa'daki insanlar daha az çikolata yiyor ve bu da Afrika'daki kakao çekirdeği çiftçilerini etkiliyor.","en":"People in the US and Europe eat less chocolate, which has an impact on cocoa bean farmers in Africa."},{"tr":"Fildişi Sahili, Batı Afrika'da bir ülkedir ve en büyük kakao çekirdeği üreticilerinden biridir.","en":"The Ivory Coast is a country in West Africa, and it is one of the biggest producers of cocoa beans."},{"tr":"İnsanlar çikolata yapmak için kakao çekirdeklerini kullanırlar ve çikolata talebi düştüğünde çiftçiler çekirdeklerini satmazlar.","en":"People use cocoa beans to make chocolate, and when the demand for chocolate falls, farmers don’t sell their beans."},{"tr":"Afrikalı çiftçilerin satamadıkları 100.000 tondan fazla kakao çekirdeği var.","en":"African farmers have more than 100000 tons of cocoa beans which they cannot sell."},{"tr":"Ekinleri için para almıyorlar, bu da çocukları için okul masraflarını karşılayacak yeterli paraları olmadığı anlamına geliyor.","en":"They don’t get money for their crops, which means that they don’t have enough money to pay for school for their children."},{"tr":"Avrupalı ve ABD'li alıcılar çiftçilerle işlerini yavaşlatmak istiyor, ancak bunun onlar üzerinde ne gibi bir etkisinin olduğunun farkında değiller.","en":"European and US buyers want to slow business with the farmers, but they don’t realize what an impact it has on them."}]},{"id":"CK-198","no":198,"title":"Goriller Koronavirüse Yakalandı","level":3,"code":"DOG","s":[{"tr":"ABD'nin Kaliforniya eyaletinin San Diego kentindeki bir hayvanat bahçesindeki gorillerin koronavirüs testleri pozitif çıktı. Bu ABD'de ve belki de dünyada ilk kez oldu.","en":"Gorillas at a zoo in San Diego, California, US, had positive tests for the coronavirus. It was the first time that this happened in the US and maybe in the world, too."},{"tr":"Hayvanat bahçesinde çalışan bir kişinin koronavirüs testi pozitif çıktı, ancak herhangi bir semptomu yoktu.","en":"A person who worked at the zoo had a positive test for the coronavirus, but he didn’t have any symptoms."},{"tr":"Hayvanat bahçesinde çalışmaya devam etti ve gorillerin yanındayken maske taktı.","en":"He continued working at the zoo, he wore a mask when he was near the gorillas."},{"tr":"Görünüşe göre goriller virüsü ondan almış.","en":"It seems that the gorillas got the virus from him."},{"tr":"Hayvanat bahçesi müdürü, hayvanların kendilerini iyi hissettiğini ve ciddi sağlık sorunları olmadığını söyledi.","en":"The director of the zoo said that the animals were feeling well, and they didn’t have serious health problems."},{"tr":"Vitaminleri, yiyecekleri ve bol suları var.","en":"They have vitamins, food, and plenty of water."},{"tr":"Onlara ilaç vermeye gerek yoktu.","en":"It wasn’t necessary to give them any medicine."},{"tr":"Goriller gruplar halinde yaşar ve dünyada pek fazla yoktur.","en":"The gorillas live in groups, and there aren’t very many of them in the world."},{"tr":"Bilim adamları, koronavirüsün dünyadaki goril sayısını daha da azaltabileceğinden endişe ediyor.","en":"Scientists worry that the coronavirus could reduce the number of gorillas in the world even more."}]},{"id":"CK-199","no":199,"title":"İnsanlar Bir Kamyonu Kurtarıyor","level":2,"code":"DUN","s":[{"tr":"Hindistan'ın Nagaland eyaletinde bir kamyon dar bir yolda ilerliyordu ve bir geçide düştü.","en":"A truck in Nagaland state, India, was driving along a narrow road and it fell down a gorge."},{"tr":"Yerel köy yetkilileri köylülerden yardım istedi.","en":"The local village officials asked the villagers for help."},{"tr":"Birçok adam geldi ve kamyonu geçitten çıkarmaya çalıştılar.","en":"Many men came and they tried to pull the truck out of the gorge."},{"tr":"Geçit 21 metre derinliğindeydi ve adamların kullanabilecekleri makineleri yoktu.","en":"The gorge was 21 meters deep and the men did not have any machines which they could use."},{"tr":"Kamyonu tekrar yola çıkarmak için sadece ipler ve sarmaşıklar kullandılar ve kurtarma operasyonu sırasında şarkı söylüyorlardı.","en":"They used only ropes and vines to get the truck back on the road and they were singing during the rescue operation."},{"tr":"Yetkililer, sürücünün herhangi bir yaralanma yaşamadığı için çok şanslı olduğunu söyledi.","en":"Officials said that the driver was very lucky because he did not suffer any injuries."},{"tr":"İnsanlar operasyonun bir videosunu sosyal medyadan izleyebilirdi.","en":"People could watch a video of the operation on social media."}]},{"id":"CK-200","no":200,"title":"Endonezya Uçak Kazası","level":2,"code":"DUN","s":[{"tr":"Geçen hafta, Endonezya'nın başkenti Cakarta'dan kalktıktan sadece dört dakika sonra denize bir uçak düştü.","en":"Last week, a plane crashed into the sea only four minutes after it took off from Jakarta, the capital of Indonesia."},{"tr":"Uçak kalktığında yağmur yağıyordu ve hava tahmini pek iyi değildi.","en":"When the plane took off, it was raining, and the weather forecast was not very good."},{"tr":"Yetkililere göre uçağın irtifası çok hızlı değişti ve uçak radardan kayboldu.","en":"According to authorities, the plane’s altitude changed very quickly, and the plane disappeared off the radar."},{"tr":"Yetkililer uçağı denizde takip edebildi ve kaza yerine arama kurtarma gemileri gönderdiler.","en":"Officials were able to track the plane in the sea, and they sent search and rescue ships to the place of the crash."},{"tr":"Birinin hayatta kalma şansı azdı, ancak yetkililer cesetleri aramaya söz verdi.","en":"The chances that someone survived were little, but officials promised ro search for the bodies."},{"tr":"İki yıl önce Endonezya'da başka bir uçak kazası oldu.","en":"Two years ago, there was another place crash in Indonesia."},{"tr":"Birçok sorunu olan Boeing 737 MAX idi.","en":"It was the Boeing 737 MAX which had many problems."},{"tr":"Geçen hafta düşen uçak da bir Boeing'di, ancak farklı bir tipti.","en":"The plane which crashed last week was a Boeing, but it was a different type."}]},{"id":"CK-201","no":201,"title":"Başkan Yasaklandı","level":3,"code":"DUN","s":[{"tr":"ABD başkanı Donald Trump, sosyal medyada çok aktifti.","en":"The US president, Donald Trump, was very active on social media."},{"tr":"Ardından geçen hafta Twitter, Facebook ve Instagram onu yasakladı.","en":"Then last week Twitter, Facebook and Instagram banned him."},{"tr":"Sosyal medya platformları, sebebin Trump'ın insanları önemli bir hükümet binası olan ABD Kongre Binası'na saldırtması olduğunu söyledi.","en":"The social media platforms said that the reason was that Trump made people attack the US Capitol, an important government building."},{"tr":"İnsanları savaşmaya teşvik etti ve cumhurbaşkanlığı seçimlerinin adil olmadığını söyledi.","en":"He encouraged people to fight and he said that the presidential election was not fair."},{"tr":"Facebook'un patronu Mark Zuckerberg, insanların yeni başkan Joe Biden'a demokratik bir şekilde oy verdiğini ve Trump'ın paylaşımlarının tehlikeli olduğunu söyledi.","en":"Mark Zuckerberg, the boss of Facebook, said that people voted for the new president, Joe Biden, democratically and that Trump’s posts were dangerous."},{"tr":"Joe Biden'ın açılışı 20 Ocak'ta gerçekleşecek ve Trump orada olmayacağını söyledi.","en":"The inauguration of Joe Biden will take place on January 20, and Trump said that he would not be there."},{"tr":"Trump açılıştan önce Twitter, Facebook ve Instagram'ı kullanamaz.","en":"Trump cannot use Twitter, Facebook and Instagram before the inauguration."}]},{"id":"CK-202","no":202,"title":"Küçük Vombat Kurtarıldı","level":1,"code":"DOG","s":[{"tr":"Tazmanya'da bir kadın karayolunda ölü bir vombat gördü.","en":"A woman saw a dead wombat by the road in Tasmania."},{"tr":"Leşe doğru yürüdükten sonra kesenin hareket ettiğini fark etti.","en":"After walking up to the carcass, she noticed that the pouch was moving."},{"tr":"Kesede canlı bir bebek vombat vardı!","en":"There was a live baby wombat in the pouch!"},{"tr":"Kadın, bebeği annesinin vücudundan çıkarttı.","en":"The woman took the baby out of its mother’s body."},{"tr":"Hava soğuktu, bu yüzden küçük wombat'ı bir havluya sardı.","en":"It was cold, so she wrapped the little wombat in a towel."},{"tr":"Artık bebeğe başka bir kadın bakıyor.","en":"Another woman now takes care of the baby."},{"tr":"Vücut ısısını yüksek tutmak için sütyeninde saklıyor.","en":"She keeps it in her bra in order to keep its body temperature up."},{"tr":"Ayrıca yer, bebeğin kesesine çok benziyor.","en":"Also, the place feels a lot like the pouch for the baby."},{"tr":"Orada üç ay kalacak.","en":"It will stay there for three months."}]},{"id":"CK-203","no":203,"title":"Özel teslimat","level":1,"code":"BLT","s":[{"tr":"Çinli şirket Neolix, sürücüsüz özel minibüsler icat etti.","en":"The Chinese company, Neolix, invented special vans that don’t have a driver."},{"tr":"Neolix, koronavirüs salgını sırasında bu minibüsleri kullanmaya başladı.","en":"Neolix started to use these vans during the coronavirus epidemic."},{"tr":"Bir şeyleri hastanelere götürüyorlar ve sokakların dezenfekte edilmesine yardımcı oluyorlar.","en":"They deliver things to hospitals and they help disinfect streets."},{"tr":"ABD fast-food şirketi KFC, Neolix ile iş yaptı.","en":"The US fast-food company, KFC, has done business with Neolix."},{"tr":"Neolix'in minibüsleri sokaklarda ilerliyor ve yiyecek sunuyorlar.","en":"Neolix’s vans drive along the streets and offer food."},{"tr":"Yiyecekleri satın almak çok kolay.","en":"It is very easy to buy the food."},{"tr":"Müşteriler telefonlarıyla bir kod tarar ve bir uygulamada istedikleri yemeği seçerler.","en":"Customers scan a code with their phones and they choose the food which they want on an app."},{"tr":"Ödeme yaptıklarında minibüsün kapısı açılıyor ve yiyecekleri dışarı çıkarıyorlar.","en":"When they pay, the van’s door opens and they take the food out."},{"tr":"Koronavirüs salgını öncesinde insanlar şoförsüz arabaları sevmiyordu.","en":"Before the coronavirus pandemic, people didn’t like cars without a driver."},{"tr":"Şimdi durum değişti ve insanlar bunun faydalarını görüyor.","en":"Now, the situation has changed and people see the benefits of them."},{"tr":"Uzmanlar, bu özel minibüslerin, örneğin halk otobüsleri gibi sürücüye ihtiyaç duymayan diğer araçların geliştirilmesine yardımcı olabileceğini söylüyor.","en":"Experts say that these special vans could help develop other vehicles which don’t need a driver, for example, public buses."}]},{"id":"CK-204","no":204,"title":"Müslümanlar ve COVID-19 Aşısı","level":2,"code":"SAG","s":[{"tr":"Endonezya nüfusunun neredeyse %90'ı Müslüman ve İslam'ı uyguluyorlar.","en":"Almost 90 % of the Indonesian population are Muslims and they practice Islam."},{"tr":"Müslümanların yiyebileceği veya kullanabileceği helal ürünler var.","en":"There are halal products that Muslims can eat or use."},{"tr":"Haram ürünleri Müslümanların yiyemeyeceği şeylerdir.","en":"Haram products are things that Muslims cannot eat."},{"tr":"Endonezya, COVID-19'a karşı toplu aşı başlatmak istiyor, ancak bazıları aşının helal olmadığını söylüyor.","en":"Indonesia wants to start mass vaccination against Covid-19, but some people say that the vaccine isn’t halal."},{"tr":"Bazı aşıların içinde genellikle jelatin bulunur ve genellikle domuzlardan gelir.","en":"Some vaccines usually have gelatin in them and it often comes from pigs."},{"tr":"İslam, Müslümanların domuz yemesine izin vermez ve domuzlar helal değildir.","en":"Islam doesn’t allow Muslims to eat pigs, and pigs aren’t halal."},{"tr":"Endonezyalı Müslüman yetkililer aşının kullanılmasının uygun olup olmadığına karar vermelidir.","en":"Indonesian Muslim officials must decide if it is okay to use the vaccine or not."},{"tr":"Endonezya için aşı yapan bir Rus şirketi, aşıda jelatin olduğunu söylemedi.","en":"A Russian company that makes the vaccine for Indonesia didn’t say that there was gelatin in the vaccine."},{"tr":"Diğer ülkeler için aşı yapan diğer şirketler, aşılarının jelatin içermediğini söylediler.","en":"Other companies which make vaccines for other countries said that their vaccines didn’t contain gelatin."}]},{"id":"CK-205","no":205,"title":"Hastanede cadı","level":2,"code":"TAR","s":[{"tr":"Befana, İtalya'daki çocuklara tatlılar ve hediyeler getiren geleneksel bir cadıdır.","en":"Befana is a traditional witch who brings sweets and gifts to children in Italy."},{"tr":"Bu, Epiphany Eve denen 5 Ocak gecesi olur.","en":"This happens on the night of January 5, which is called Epiphany Eve."},{"tr":"Gelenek, Noel Baba'ya veya Noel'deki Aziz Nicholas'a çok benzer.","en":"The tradition is very similar to Santa Claus, or Saint Nicholas on Christmas."},{"tr":"Bir kadın özel bir şey yapmaya karar verdi.","en":"A woman decided to do something special."},{"tr":"Taranto hastanesindeki hasta çocukları mutlu etmek istedi.","en":"She wanted to make sick children at the Taranto Hospital happy."},{"tr":"Befana kılığına girdi ve hastane binaları arasında uçtu.","en":"She dressed up as Befana and she flew among the hospital buildings."},{"tr":"Hastane personeli ve çocuklar alkışladı ve el salladı.","en":"Hospital staff and children cheered and waved."},{"tr":"Kadının adı Donatella ve dağ kurtarıcısı olarak çalışıyor.","en":"The woman’s name is Donatella and she works as a mountain rescuer."},{"tr":"Kurtarıcıların genellikle işlerinde kullandıkları bir kablo kullandı ve ona astı.","en":"She used a cable which rescuers usually use in their work and she hung onto it."}]},{"id":"CK-206","no":206,"title":"LA'de Köpek Kafe","level":2,"code":"DOG","s":[{"tr":"Los Angeles, California'daki insanlar bir fincan kahve içebilir ve aynı zamanda bir köpek kafesinde köpeklerle oynayabilir.","en":"People in Los Angeles, California, can have a cup of coffee and play with dogs at the same time at a dog café."},{"tr":"Kafedeki her köpek bir barınaktan geliyor ve evlat edinilmeye hazır.","en":"Every dog in the café come from a shelter and available for adoption."},{"tr":"Sahibi, Los Angeles barınaklarında ötenazi yapılan köpeklerin sayısını azaltmak istiyor.","en":"The owner wants to decrease the number of dogs that are euthanized in Los Angeles shelters."},{"tr":"Ayrıca bunun gibi daha fazla kafe olacağını ve böylece daha fazla köpek ölmeyeceğini umuyor.","en":"She also hopes that there are going to be more cafés like this one, and so more dogs will not die."},{"tr":"Pek çok insan bu fikri beğendiğinden, kafe oldukça pahalı olabilir.","en":"Since many people like the idea, the café can be very expensive."},{"tr":"Bir fincan kahve ve köpeklerle 55 dakika olmak 10 dolara mal oluyor.","en":"To get one cup of coffee and 55 minutes with the dogs costs 10 dollars."}]},{"id":"CK-207","no":207,"title":"İnsanlar ABD Kongre Binası'na Saldırıyor","level":2,"code":"DUN","s":[{"tr":"Geçen Perşembe, ABD hükümeti Joe Biden´ın başkanlık seçimlerindeki zaferini resmen onayladı.","en":"Last Thursday, the US government formally confirmed Joe Biden’s victory in the presidential election."},{"tr":"Aynı zamanda ABD Başkanı Donald Trump, Beyaz Saray yakınında bir konuşma yaptı.","en":"At the same time, the US president, Donald Trump, gave a speech near the White House."},{"tr":"Etkinliğe Trump'a destek göstermek için binlerce kişi geldi.","en":"Thousands of people came to the event to show support for Trump."},{"tr":"Trump, seçimin adil olmadığını tekrarladı ve insanlardan hakikat için savaşmalarını istedi.","en":"Trump repeated that the election wasn’t fair, and he asked people to fight for the truth."},{"tr":"Kızgın insanlar binaya girdi ve şiddet başladı.","en":"Angry people broke into the building and violence began."},{"tr":"İnsanlar camları kırdı ve Meclis Odasına gitmeye çalıştılar.","en":"People broke windows and they tried to get to the House Chamber."},{"tr":"Polis, hükümet üyelerini güvenli bir yere götürmek zorunda kaldı.","en":"Police had to take members of the government to a safe place."},{"tr":"Polis bir kadını vurdu ve birkaç kişi yaralandı ve bazıları öldü.","en":"Police shot one woman, and several people were hurt and some died."}]},{"id":"CK-208","no":208,"title":"Plastik Dolu Bali Plajları","level":2,"code":"DOG","s":[{"tr":"Bali, Endonezya'nın popüler bir adasıdır ve her yıl binlerce turist ziyaret etmektedir.","en":"Bali is a popular Indonesian island and thousands of tourists visit it every year."},{"tr":"Ne yazık ki adanın plajlarındaki plastik atıklarla ilgili büyük bir sorunu var.","en":"Sadly, the island has a big problem with plastic waste on its beaches."},{"tr":"Muson mevsimi başladığında, güçlü dalgalar Bali sahillerine tonlarca plastik getiriyor.","en":"When the monsoon season starts, strong waves bring tons of plastic to Bali’s beaches."},{"tr":"Bu her yıl oluyor, ancak yetkililer bu yılın önceki yıllara göre çok daha kötü olduğunu söylüyor.","en":"This happens every year, but authorities say that this year is much worse than in previous year."},{"tr":"Endonezyalı işçiler her gün 30 ila 60 ton plastiği temizliyor.","en":"Indonesian workers clean between 30 and 60 tons of plastic every day."},{"tr":"Yılın bu zamanında Bali genellikle turistlerle doludur.","en":"At this time of year, Bali is usually full of tourists."},{"tr":"Koronavirüs salgını birçok noktaya seyahat etmeyi neredeyse imkansız hale getirdi, bu nedenle Bali'de sadece birkaç turist var.","en":"The coronavirus pandemic made it almost impossible to travel to many destinations, so there are only a few tourists in Bali."}]},{"id":"CK-209","no":209,"title":"DSÖ Ekibi Çin'e Gidemiyor","level":2,"code":"SAG","s":[{"tr":"Dünya Sağlık Örgütü, Çin'e gidecek 10 uluslararası uzmandan oluşan bir ekip oluşturdu.","en":"The World Health Organization made a team of 10 international experts who will go to China."},{"tr":"COVID-19'un kökenini ve virüsün hayvanlardan insanlara nasıl bulaştığını araştıracaklar.","en":"They will investigate the origin of Covid-19 and how the virus got from animals to people."},{"tr":"Virüs Aralık 2019'da başladı ve uzmanlar, Wuhan şehrindeki ıslak bir pazardan geldiğine inanıyor.","en":"The virus started in December 2019 and experts believe that it came from a wet market in the city of Wuhan."},{"tr":"DSÖ ve Çin, DSÖ'nün ekibini Çin'e gönderme planını aylarca tartıştı ve Aralık 2020'de Çin nihayet kabul etti.","en":"The WHO and China discussed for many months the WHO’s plan to send its team to China, and in December 2020, China finally agreed."},{"tr":"Daha sonra ülke takımın gelmesine izin vermedi.","en":"Then, the country didn’t allow the team to come."},{"tr":"Çinli yetkililer vizeleriyle ilgili bir sorun olduğunu söyledi.","en":"Chinese officials said that there was a problem with their visas."},{"tr":"Bazı insanlar Çin'in COVID-19 hakkındaki gerçeği öğrenmek için yeterince çabalamadığını söylüyor.","en":"Some people say that China isn’t trying hard enough so as to find out the truth about Covid-19."}]},{"id":"CK-210","no":210,"title":"İran'ın Nükleer Programı","level":1,"code":"DUN","s":[{"tr":"2015'te İran ve diğer birçok ülke bir nükleer anlaşma imzaladı.","en":"In 2015, Iran and many other countries signed a nuclear deal."},{"tr":"Anlaşma, İran'ın nükleer tesislerini azaltacağı anlamına geliyordu.","en":"The deal meant that Iran would reduce its nuclear facilities."},{"tr":"Artık her şey değişiyor.","en":"Everything is changing now."},{"tr":"İran ile ABD arasındaki ilişkiler son aylarda daha da kötüleşti.","en":"The relationship between Iran and th US got worse in the last months."},{"tr":"Sonuç olarak İran anlaşmayı bozmaya ve biraz uranyum almaya karar verdi.","en":"As a result, Iran decided to break the deal and get some uranium."},{"tr":"Uranyum nükleer silahların yakıtıdır ve bazı ülkeler İran'ın nükleer silah yapmayı planladığından endişe duymaktadır.","en":"Uranium is fuel for nuclear weapons, and some countries worry that Iran is planning to make a nuclear weapon."},{"tr":"İran silah yapmak istemediğini söyledi ancak bazı ülkeler buna inanmıyor.","en":"Iran said that it didn’t want to make a nuclear weapon, but some countries don’t believe this."},{"tr":"İnsanlar uranyumu birçok endüstride ve ayrıca enerji üretmek için kullanıyor.","en":"People use uranium in many industries and also to make energy."},{"tr":"Bir silah yapmak uzun zaman alıyor ve yapımı kolay olmayan birçok parçaya sahiptir.","en":"It takes a long time to make a weapon and it has many components which aren’t easy to make."}]},{"id":"CK-211","no":211,"title":"Kar altındaki adam","level":1,"code":"TOP","s":[{"tr":"Fulvio Giovannini İtalya, Dolomitler'de kayak yapıyordu.","en":"Fulvio Giovannini was skiing in the Dolomites, Italy."},{"tr":"Güzel bir Aralık günüydü ve adam kötü bir şey olmasını beklemiyordu.","en":"It was a nice December day, and the man didn’t expect anything bad to happen."},{"tr":"Sonra bir çığ oldu ve Giovannini neredeyse bir saat boyunca onun altında kaldı.","en":"Then, an avalanche happened, and Giovannini got stuck under it for almost one hour."},{"tr":"Daha sonra nasıl hissettiğini anlattı.","en":"Later, he described how he felt."},{"tr":"Hareket edemiyordu ve sadece başını sallayabiliyordu.","en":"He couldn’t move, and he could only nod with his head."},{"tr":"Bu yüzündeki karı almasına yardımcı oldu ve biraz ışık görebiliyordu.","en":"It helped him get the snow off his face and he could see some light."},{"tr":"Sakin kaldı ve hayatta kalacağını umuyordu.","en":"He stayed calm and he hoped that he would survive."},{"tr":"Giovannini özel ekipman giyiyordu, bu yüzden kurtarıcılar onun nerede olduğunu bildi.","en":"Giovannini was wearing special equipment, so rescuers knew where he was."},{"tr":"Onu karda buldular ve kurtardılar.","en":"They found him in the snow and saved him."},{"tr":"Giovannini dağları seviyor.","en":"Giovannini loves mountains."},{"tr":"Kaza onu daha da güçlendirdi ve oraya geri dönmek istiyor.","en":"The accident made him stronger, and he wants to go back there."}]},{"id":"CK-212","no":212,"title":"İngiliz Pompeii","level":1,"code":"TAR","s":[{"tr":"İngiltere'de arkeologlar 3000 yıllık bir ahşap tekerlek buldular.","en":"In England, archaeologists found a 3000-year-old wooden wheel."},{"tr":"Çok iyi korunmuş.","en":"It is very well-preserved."},{"tr":"İngiltere'de bulunan en eski ve en eksiksiz tekerlektir.","en":"It is the oldest and most complete wheel found in Britain."},{"tr":"Cambridgeshire yakınlarındaki bölgedeki birçok buluntudan sadece biri.","en":"It is only one of many finds at the site near Cambridgeshire."},{"tr":"Geçen ay, uzmanlar kaselerde yiyecek parçaları keşfettiler.","en":"Last month, experts discovered pieces of food in bowls."},{"tr":"Bir yangın köyü yok ettiğinde biri yemek yiyordu.","en":"When a fire destroyed the village, somebody was eating the food."},{"tr":"Bir arkeolog, bunun birinin hayatına ya da evine adım atmak gibi olduğunu söyledi.","en":"One archaeologist said that it was like stepping into somebody’s life or somebody’s home."},{"tr":"Bu keşifler, arkeologlara insanların MÖ 1100-800 yılları arasında nasıl yaşadıkları hakkında yeni bir resim veriyor.","en":"These discoveries give archaeologists a new picture about the way people lived between 1100-800 BC."},{"tr":"Orada çalışan ekip, siteyi Roma kenti Pompeii'nin İngiliz versiyonu olarak adlandırıyor.","en":"The team who is working there calls the site a British version of the Rome town of Pompeii."}]},{"id":"CK-213","no":213,"title":"İllüzyon Müzesi","level":1,"code":"TAR","s":[{"tr":"Mısır, Kahire'de yeni bir İllüzyon Müzesi açıldı.","en":"A new Museum of Illusions opened in Cairo, Egypt."},{"tr":"Bir yanılsama, duyularımızın beynimizi kandırdığı ve gerçekte olmayan bir şeyi gördüğümüz veya hissettiğimiz zamandır.","en":"An illusion is when our senses trick our brain, and we see or feel something that isn’t really happening."},{"tr":"Müzede insanlar örneğin hologramlar veya özel resimler görürler ve Sonsuzluk Odası denen bir odayı ziyaret ederler.","en":"In the museum, people see, for example, holograms, or special pictures, and they visit a room called the Infinity Room."},{"tr":"Müze müdürü, insanların burayı eğlenceden daha fazlası için ziyaret ettiğini söyledi.","en":"The manager of the museum said that people visit the place for more than fun."},{"tr":"Zihinleri, vizyonları ve bilimleri hakkında da birçok ilginç şey öğrenebilirler.","en":"They can learn a lot of interesting things about their minds, vision, and science, too."},{"tr":"Dünyada benzer 15 müze var.","en":"There are 15 similar museums around the world."},{"tr":"İlk müze 2015 yılında Hırvatistan'da açıldı ve kısa sürede çok popüler oldu.","en":"The first museum opened in Croatia in 2015 and it quickly became very popular."},{"tr":"Çok başarılı bir fikir ve her yaştan insan onu seviyor.","en":"It is a very successful idea and people of all ages love it."}]},{"id":"CK-214","no":214,"title":"Adam COVID-19 Aşısını İmha Etti","level":2,"code":"SAG","s":[{"tr":"Polis, ABD'nin Wisconsin eyaletinde bir hastanede çalışan bir adamı tutukladı.","en":"Police arrested a man who worked at a hospital in Wisconsin, US."},{"tr":"Polis, adamın 500 dozdan fazla koronavirüs aşısını imha ettiğini söyledi.","en":"Police said that the man destroyed more than 500 doses of a coronavirus vaccine."},{"tr":"Adam aşıyı buzdolabından alırken hata yaptığını ve tekrar koymayı unuttuğunu söyledi.","en":"The man said that he made a mistake and he forgot to put it back when he took the vaccine from the refrigerator."},{"tr":"Daha sonra aşıyı yok etmek istediğini söyledi.","en":"Later, he said that he wanted to destroy the vaccine."},{"tr":"Sorun, aşının çok uzun süre kalması ve etkisiz hale gelmesiydi.","en":"The problem was that the vaccine stayed out too long and it became ineffective."},{"tr":"Bazı insanlar aşıyı yaptırdı, ancak aşıyı yapan şirket bunun insanlar için tehlikeli olmadığını söyledi.","en":"Some people got the vaccine, but the company which made the vaccine said that it wasn’t dangerous to people."},{"tr":"Adam aşıyı neden imha etmek istediğini açıklamadı.","en":"The man didn’t explain why he wanted to destroy the vaccine."}]},{"id":"CK-215","no":215,"title":"Havaalanı Saldırısı","level":1,"code":"DUN","s":[{"tr":"Yemen'de bir havaalanında bomba patladı.","en":"A bomb exploded at an airport in Yemen."},{"tr":"Olayda en az 26 kişi öldü, 60'tan fazla kişi yaralandı.","en":"A least 26 people died in the incident, and more than 60 people suffered injuries."},{"tr":"Patlamadan kısa bir süre önce havaalanına bir uçak indi.","en":"Just a moment before the explosion, a plane landed at the airport."},{"tr":"Uçak, Yemen’in yeni hükümetinin üyelerini taşıyordu.","en":"The plane was carrying members of Yemen’s new government."},{"tr":"Şans eseri, incinmediler.","en":"Luckily, they didn’t get hurt."},{"tr":"Politikacılar, daha sonra ikinci bir patlamanın yaşandığı Mashiq Sarayı'na gitti.","en":"The politicians went to Mashiq Palace, where a second explosion happened later."},{"tr":"Yetkililer saldırılardan kimin sorumlu olduğunu bilmiyor.","en":"Officials don’t know who is responsible for the attacks."},{"tr":"Yemen'de savaş oldu ve ülkenin büyük bir bölümünü yok etti.","en":"There was a war in Yemen and it destroyed a large part of the country."},{"tr":"Savaşta 100.000'den fazla insan öldü ve milyonlarca insan şu anda çok kötü koşullarda yaşıyor.","en":"More than 100 000 people died in the war, and millions of people live in very bad conditions now."}]},{"id":"CK-216","no":216,"title":"İki burunlu Köpek","level":1,"code":"DOG","s":[{"tr":"İnsanlar ABD'nin Kaliforniya eyaletindeki Fresno sokaklarında iki burunlu bir köpek buldular.","en":"People found a two-nosed dog in the streets of Fresno, California, US."},{"tr":"İnsanlar, Toby adlı köpeği kendisine bir ev bulmaya çalışan bir barınağa götürdü.","en":"People took the dog, whose name is Toby, to a shelter that tried to find him a home."},{"tr":"Ancak bunu yapmak kolay olmadı çünkü insanlar iki burunlu köpeği istemiyorlardı.","en":"However, it wasn’t easy to do because people didn’t want the two-nosed dog."},{"tr":"Toby, sığınağın onu öldürmek zorunda kalma riskiyle karşı karşıyaydı.","en":"Toby was at risk of the shelter having to kill him."},{"tr":"Şans eseri, başarılı bir müzik yapımcısı onu kurtardı.","en":"Luckily, a successful music producer rescued him."},{"tr":"Yapımcının özel evcil hayvanlar edinme alışkanlığı vardır.","en":"The producer has a habit of adopting special pets."},{"tr":"En fazla sayıda iki başlı canlı hayvana sahiptir ve ayrıca beş ayaklı bir köpeği ve iki ayaklı bir köpeği vardır.","en":"He has the largest number of two-headed living animals, and he also has a five-legged dog and a two-legged dog."}]},{"id":"CK-217","no":217,"title":"Dini Bir Mekanda Parti","level":2,"code":"TAR","s":[{"tr":"Filistinli DJ Sama Abdul-Hadi, Nabi Musa adlı dini bir yerde sahne aldı.","en":"Palestinian DJ Sama Abdul-Hadi performed at a religious place called Nabi Musa."},{"tr":"Nabi Musa, insanların normalde eğlenmek için değil namaz kılmak için gittikleri bir türbe ve camidir.","en":"Nabi Musa is a shrine and mosque where people normally go to pray, not to party."},{"tr":"İnsanlar 12. yüzyılda Nabi Musa'yı inşa ettiler ve birçok insan orada Hz.Musa'dan kalma kalıntılar olduğuna inanıyor.","en":"People built Nabi Musa in the 12th century and many people believe that there are relics there from the Phophet Moses."},{"tr":"DJ türbede çekim yaptı ve bu da bazı insanları çok kızdırdı.","en":"The DJ filmed at the shrine, which made some people very angry."},{"tr":"DJ'in kardeşi turizm bakanlığına sorduklarını söyledi ve yetkililer konserin Nabi Musa'da yapılabileceğini söyledi.","en":"The DJ’s brother said that they asked the ministry of tourism, and officials said that the concert could take place in Nabi Musa."},{"tr":"Polis, performansın ardından geçen hafta DJ'i tutukladı ve 15 günden fazla polisle birlikte kalacak.","en":"Police arrested the DJ last week after the performance, and he will stay with the police for more than 15 days."},{"tr":"İnternet üzerinden bir dilekçe verildi ve insanlar polisten DJ'i serbest bırakmasını istedi.","en":"There was an online petition and people asked the police to release the DJ."}]},{"id":"CK-218","no":218,"title":"Pierre Cardin Öldü","level":1,"code":"POR","s":[{"tr":"Pierre Cardin 1922'de İtalya'da doğdu.","en":"Pierre Cardin was born in Italy in 1922."},{"tr":"Dört yıl sonra ailesi Fransa'ya kaçtı.","en":"Four years later, his family escaped to France."},{"tr":"Pierre, Pietro olarak doğdu, ancak ailesi, Fransa'ya taşındıklarında adını değiştirdi.","en":"Pierre was born Pietro, but his family changed his name when they moved to France."},{"tr":"Cardin´in işi tiyatrolar ve filmler için maske ve kostüm yapmaktı.","en":"Cardin’s job was to make masks and costumes for theatres and films."},{"tr":"1946'da terzi oldu ve o zamanlar ünlü olmayan Christian Dior için çalıştı.","en":"In 1946, he became a tailor, and he worked for Christian Dior, who wasn’t famous at that time."},{"tr":"1950'de Cardin kendi moda markasını kurdu ve pek çok kişi onu alışılmadık iş uygulamalarıyla tanıyordu.","en":"In 1950, Cardin started his own fashion brand, and many people knew him for his unusual business practices."},{"tr":"Büyük mağazalarda kıyafet satmaya başladı ve parfüm, saat, araba gibi diğer şeyleri satmaya başladığında markası daha da popüler oldu.","en":"He started to sell the clothes in big stores, and when he started to sell other things such as perfumes, watches, and cars, his brand became even more popular."},{"tr":"Birçok kişi onun iş tarzını beğenmedi, ancak bu Cardin'i tüm dünyada ünlü yaptı.","en":"Many people didn’t like his business style, but it made Cardin famous all over the world."},{"tr":"Cardin geçen hafta 98 yaşında öldü.","en":"Cardin died last week at the age of 98."}]},{"id":"CK-219","no":219,"title":"Nashville Bombalaması","level":1,"code":"DUN","s":[{"tr":"Noel Günü, ABD'nin Tennessee eyaletindeki Nashville kasabasında bir bomba patladı.","en":"On Christmas, a bomb exploded in the town of Nasville, Tennessee, US."},{"tr":"Patlamada en az sekiz kişi yaralandı ve çok sayıda bina hasar gördü.","en":"The explosion injured at least 8 people and damaged many buildings."},{"tr":"Bir CCTV kamerası bombanın patladığı anı kaydetti.","en":"A CCTV camera recorded the moment when the bomb exploded."},{"tr":"500 metre ötedeki binalardaki camı kırdı.","en":"It broke the glass in buildings that were 500 meters away."},{"tr":"Polis, bombanın bir kamp aracının içinde olduğunu öğrendi.","en":"Police found out that the bomb was inside a campervan."},{"tr":"Bombacı 63 yaşında bir adamdı ve kamp aracına aitti.","en":"The bomber was a 63-year-old man, and the campervan belonged to him."},{"tr":"Komşular, adamın yalnız yaşadığını ve diğer insanlarla tanışmaktan hoşlanmadığını söyledi.","en":"Neighbors said that the man lived alone, and he didn’t like to meet other people."},{"tr":"Görünüşe göre bombalamayı dikkatlice planladı ve kimse ona yardım etmedi.","en":"It seems that he planned the bombing carefully and nobody helped him."},{"tr":"Hala neden yaptığı belli değil.","en":"It is still not clear why he did it."},{"tr":"Bombalamadan önce komşularından birine Nashville'in tamamının onu yakında tanıyacağını söyledi.","en":"Before the bombing, he told one of his neighbors that all of Nashville would know him soon."}]},{"id":"CK-220","no":220,"title":"Hırvatistan Depremi","level":3,"code":"DOG","s":[{"tr":"Salı günü güçlü bir deprem Hırvatistan'ı vurdu ve 1880'den bu yana en güçlü deprem oldu.","en":"A strong earthquake hit Croatia on Tuesday, and it was the strongest earthquake since 1880."},{"tr":"Deprem merkezi Petrinja kasabası yakınındaydı ve deprem buradaki binaların çoğuna zarar verdi.","en":"The epicenter was near the town of Petrinja, and the earthquake damaged most buildings there."},{"tr":"Binaları kullanmak artık mümkün değil.","en":"It wasn’t possible to use the buildings now."},{"tr":"Depremin büyüklüğü 6,3'tü ve o kadar güçlüydü ki, Macaristan ve Avusturya kadar uzaktaki insanlar da hissedebiliyordu.","en":"The magnitude of the earthquake was 6,3, and it was so strong that people as far away as Hungry and Austria could feel it, too."},{"tr":"En az beş kişi öldü ve yetkililer birçok binayı boşaltmak zorunda kaldı.","en":"At least five people died and authorities had to evacuate many buildings."},{"tr":"1963'te Üsküp kasabası yakınlarında meydana gelen depremde 1000'den fazla kişi öldü ve neredeyse tüm kasabayı yok etti.","en":"In 1963, more than 1000 people died in an earthquake near the town of Skopje, and it destroyed almost all of the town."},{"tr":"Bu haftaki deprem 1963 depreminden daha da güçlüydü.","en":"The week’s earthquake was even stronger than the 1963 earthquake."}]},{"id":"CK-221","no":221,"title":"Yılan Masajı","level":2,"code":"SAG","s":[{"tr":"Mısır Kahire'deki bir kaplıca, insanların kas ve eklem ağrılarını azaltmalarına yardımcı olmak için yılanlar kullanıyor.","en":"A spa in Cairo, Egypt, uses snakes to help people reduce muscle and joint pain."},{"tr":"Masaj 30 dakika sürüyor ve önce bir masör müşterinin sırtına ve yüzüne yağ sürüyor.","en":"The massage takes 30 minutes and first, a masseur put oil on a client’s back and face."},{"tr":"Sonra arkasına yaklaşık 28 zehirsiz yılan koyar.","en":"Then he puts 28 non-venomous snakes on the back."},{"tr":"Yılanlar sırtta ve yüzünde sorunsuz hareket eder.","en":"The snakes move smoothly on the back and face."},{"tr":"Kaplıca sahibi, yılanların bir insanın vücudundaki acıyı hissedebildiklerini ve acı veren yerlerin üzerinden geçtiklerini söyledi.","en":"The owner of the spa said that the snakes could feel the pain in a person’s body, and they moved over the painful places."},{"tr":"Ayrıca masajın daha iyi kan dolaşımına yardımcı olduğunu ve insanları daha mutlu hissettirdiğini söyledi.","en":"He also said that the massage helped better blood circulation, and it made people feel happier."},{"tr":"Bazı insanlar başta korkarlar ama bir süre sonra masajın keyfini çıkarmaya başlarlar ve rahatlayabilirler.","en":"Some people are scared at first, but after a while, they start to enjoy the massage, and they can relax."},{"tr":"Bazı insanlar, yılan korkusunun üstesinden geldikleri için de kendilerini iyi hissederler.","en":"Some people also feel good about themselves since they overcome their fear of snakes."}]},{"id":"CK-222","no":222,"title":"Drakula hakkında fıkra","level":1,"code":"GNL","s":[{"tr":"Drakula hangi yarasanın en iyi olduğunu bilmek istiyor.","en":"Dracula wants to know which bat is the best."},{"tr":"Ona ne kadar kan içebileceklerini göstermeleri gerekir.","en":"They must show him how much blood they can drink."},{"tr":"Çok kan içen yarasa en iyisidir.","en":"The bat which drinks a lot of blood is the best."},{"tr":"İlk yarasa gider ve 10 dakika sonra geri gelir.","en":"The first bat goes and comes back after 10 minutes."},{"tr":"Ağzı kanla dolu.","en":"It’s mouth is full of blood."},{"tr":"Drakula, \"Güzel, bunu nasıl yaptın? Diyor. Yarasa, “Şu kuleyi görüyor musun? Kulenin altında bir ev var.","en":"Dracula says “nice, how did you do? The bat says “do you see that tower? There is a house under the tower."},{"tr":"İçeri girdim ve tüm ailenin kanını içtim. \" Drakula, \"Çok iyi\" diyor.","en":"I went inside and I drank the blood of all the family”. Dracula says “very good”."},{"tr":"İkinci yarasa gider ve 5 dakika sonra gelir.","en":"The second bat goes and comes after 5 minutes."},{"tr":"Yüzünde kan var.","en":"There is blood on its face."},{"tr":"Drakula, \"Bunu nasıl yaptın? Yarasa, “Şu kuleyi görüyor musun? Kulenin altında bir otel var.","en":"Dracula says “how did you do this? The bat says “do you see that tower? There is a hotel under the tower."},{"tr":"İçeri girdim ve oradaki tüm insanların kanını içtim. \" Drakula \"Fantastik\" diyor.","en":"I went inside and I drank the blood of all the people there” Dracula says, “fantastic”."},{"tr":"Şimdi üçüncü yarasa gidiyor ve 1 dakika sonra geri geliyor.","en":"Now the third bat goes and comes back after 1 minute."},{"tr":"Tüm vücudunda kan var.","en":"There is blood on all his body."},{"tr":"Drakula gözlerine inanmıyor, \"Bunu nasıl yaptın? Yarasa, \"Şu kuleyi görüyor musun? Drakula, \"Evet\" diyor.","en":"Dracula doesn’t believe his eyes, “how did you do this? The bat says, “do you see that tower? Dracula says, “Yes”."},{"tr":"Ve yarasa, \"Ben görmedim\" diyor.","en":"And the bat says, “I didn’t see it”."}]},{"id":"CK-223","no":223,"title":"Arjantin'de buzullar","level":2,"code":"DOG","s":[{"tr":"Beyaz Dev, Arjantin'in en büyük turistik yerlerinden biridir.","en":"The White Giant is one of Argentina’s biggest tourist attractions."},{"tr":"29 kilometre uzunluğunda bir buz ırmağıdır.","en":"It is a 29-kilometer long river of ice."},{"tr":"200'den fazla buzul barındırıyor ve Antarktika'dan sonra dünyanın en büyük kıtasal buz uzantısıdır.","en":"It is home to more than 200 glaciers, and it is the largest continental ice extension in the world after Antarctica."},{"tr":"Her dört yılda bir buz tutan bir buzul vardır ve çok sayıda insan gösteriyi izlemeye gelir.","en":"There is a glacier that sheds ice about every four years, and large number of people come to watch the show."},{"tr":"Geçenlerde yaklaşık 4 bin kişi bir buz tünelinin çatısının düşmesini izledi.","en":"Around 4 thousand people recently watched the roof of an ice tunnel fall."},{"tr":"Oldukça önemliydi.","en":"It was quite important."}]},{"id":"CK-224","no":224,"title":"Bisiklet Şakası","level":1,"code":"GNL","s":[{"tr":"Şehirde bir adam araba kullanıyor.","en":"A man is driving in the city."},{"tr":"Şehirdeki maksimum hız saatte 60 km'dir.","en":"The maximum speed in the city is 60 km per hour."},{"tr":"Saatte 80 km gider.","en":"He goes 80 km per hour."},{"tr":"Bir polis tarafından durduruldu.","en":"He is stopped by a policeman."},{"tr":"Polis adama gelir.","en":"The policeman comes to the man."},{"tr":"Adam pencereyi indirir.","en":"The man pulls down the window."},{"tr":"Polis \"İyi günler\" dedi.","en":"“Good afternoon”, says the policeman."},{"tr":"Çok hızlı gidiyordun. 50 Euro ödeyeceksin. \"","en":"“You were going too fast. You will pay 50 euros.”"},{"tr":"Adam, \"Biliyorum\" dedi.","en":"“I know” says the man."},{"tr":"Mutsuz ama parayı polise verir.","en":"He is unhappy, but he gives the money to the policeman."},{"tr":"Polis, \"Bu sizin makbuzunuz\" dedi.","en":"“This is your receipt,” says the policeman."},{"tr":"Adam \"Makbuza ihtiyacım yok. Onunla ne yapacağım? \" der.","en":"“I don’t need a receipt. What will I do with it” says the man."},{"tr":"\"Sakla. Dört makbuz aldığında bir bisiklet alacaksın.\"","en":"“Keep it. When you get four receipts, you will get a bicycle.”"}]},{"id":"CK-225","no":225,"title":"Paris Anlaşması","level":1,"code":"DOG","s":[{"tr":"2015 yılında 195 ülke Paris İklim Anlaşması'nı imzaladı.","en":"In 2015, 195 countries signed the Paris Climate Agreement."},{"tr":"Anlaşma, ülkelerin küresel sıcaklık artışını 2 santigrat derecenin altında tutması yönünde.","en":"The deal is for countries keep the increase of global temperature below 2 degrees Celsius."},{"tr":"İklim değişikliğinin etkisini azaltmak için yapılması gereken önemli bir şey.","en":"It is an important thing to do to reduce the impact of climate change."},{"tr":"Kimse ülkeleri anlaşmayı imzalamaya zorlamadı.","en":"Nobody forced the countries to sign the deal."},{"tr":"Bir ülke anlaşmadan ayrılmaya karar verirse, yapabilir.","en":"If a country decides to leave the deal, it can."},{"tr":"Ayrıca, bir ülke anlaşmanın hedefine ulaşmazsa hiçbir şey olmaz.","en":"Also, if a country doesn’t reach the goal of the deal, nothing happens."},{"tr":"Gezegenimizi koruyacak değişiklikler yapmanın önemli olduğunu hala herkes biliyor.","en":"Everybody still knows that it is important to make changes that will protect our planet."},{"tr":"Birçok büyük şirket 2050 yılına kadar emisyonları sıfıra düşürmeye karar verdi ve şimdi daha fazla şirket temiz enerji ve yeşil teknolojilere para harcıyor.","en":"Many large companies decided to lower emissions to zero by 2050 and now, more companies are putting money into clean energy and green technologies."},{"tr":"Yapılması gereken doğru şey olduğuna inanıyorlar.","en":"They believe that it is the right thing to do."}]},{"id":"CK-226","no":226,"title":"Maymun Para Çalıyor","level":1,"code":"DOG","s":[{"tr":"Geçen ay alışılmadık bir hırsız bir kuyumcu dükkanını ziyaret etti.","en":"Last month, an unusual thief visited a jewelry shop."},{"tr":"Hırsız bir maymundu.","en":"The thief was a monkey."},{"tr":"Önce dükkanın bir çalışanı dükkan kapısının önünde oturan maymunu fark etti ve maymuna bir parça meyve ikram etti.","en":"First, an employee of the shop noticed the monkey that sat in front of the shop door and he offered a piece of fruit to the money."},{"tr":"Bundan kısa bir süre sonra, tatminsiz maymun kapıyı itti ve dükkana girdi.","en":"Shortly after that, the unsatisfied monkey pushed the door and went inside the shop."},{"tr":"Bir ofis koltuğuna oturdu, rahatladı, sonra biraz para aldı ve onunla kaçtı.","en":"He took a seat in an office chair, relaxed, then took some money, and ran off with it."},{"tr":"Çalışan, para karşılığında maymuna bir muz ikram etmeye çalıştı, ancak hırsız istemedi ve yaklaşık 10.000 rupi yani yaklaşık 150 ABD doları ile sokağa kaçtı.","en":"The employee tried to offer the monkey a banana in exchange for the money, but the thief didn’t want it, and escaped into the street with about 10000 rupees, which is about 150 US dollars."},{"tr":"Dükkan personeli bu maymunu daha önce gördüklerini söyledi.","en":"Shop staff said that they saw this monkey before."},{"tr":"Tekrar gelirse şimdi daha dikkatli olacaklar.","en":"If he comes back again, they will be more careful now."}]},{"id":"CK-227","no":227,"title":"Zengin Kardeşler Hakkında Fıkra","level":2,"code":"GNL","s":[{"tr":"Üç zengin kardeş, doğum gününde yaşlı anneleri için özel bir şey yapmak istedi.","en":"Three rich brothers wanted to do something special for their old mother on her birthday."},{"tr":"İlk erkek kardeş ona büyük bir ev aldı.","en":"The first brother bought her a big house."},{"tr":"İkinci erkek kardeş ona şoförlü büyük bir araba verdi.","en":"The second brother gave her a car, with a driver."},{"tr":"Üçüncü erkek kardeş, annesinin İncil'i okumayı sevdiğini ama annesinin iyi göremediğini hatırladı, bu yüzden ona İncil'den okuyabilecek özel bir papağan verdi.","en":"The third brother remembered that his mother loved to read the Bible, but she couldn’t see well, so he gave her a special parrot that could read from the Bible."},{"tr":"Kısa süre sonra kardeşler annelerinden mektuplar aldı.","en":"Soon, the brothers received letters from their mother."},{"tr":"İlk mektupta “Bana aldığın ev çok büyük. Sadece küçük bir bölümünde yaşıyorum ama tüm evi temizlemem gerekiyor. \"","en":"The first letter said “the house which you bought me is very big. I only live in a small part of it, but I have to clean the whole house.”"},{"tr":"İkinci oğul, \"Evden çok sık ayrılmıyorum, bu yüzden arabayı çok sık kullanmıyorum. Ve onu kullandığımda, şoför bana hoş gelmiyor. \"","en":"The second son got the letter; “I don’ leave the house very often, so I don’t use the car very often. And when I use it, the driver isn’t nice to me.”"},{"tr":"Üçüncü oğul, “Tatlı oğlum, annenin neyi sevdiğini biliyorsun. Tavuk çok lezzetliydi. \"","en":"The third son got the letter; “My sweet son, you know what your mother loves. The chicken was very tasty.”"}]},{"id":"CK-228","no":228,"title":"Tokyo'daki Kirpi Kafe","level":1,"code":"DOG","s":[{"tr":"Tokyo'da hayvan kafeleri duyulmamış değil.","en":"In Tokyo, animal cafés aren’t unheard of."},{"tr":"Şehirde kedi, tavşan, baykuş, şahin, yılan hatta kirpi kafeleri var.","en":"There are cat, rabbit, owl, hawk, snake, and even hedgehog cafés in the city."},{"tr":"Bir kirpi kafeye Harry denir - bu, Japonca'da \"iğne\" anlamına gelen \"hari\" kelimesi üzerine oynanan bir oyundur.","en":"One hedgehog café is called Harry – this is a play on Japanese word “hari” meaning “needle”."},{"tr":"9 dolar eşdeğeri, kafede 30 kirpi ile bir saatlik oyun süresi satın alıyor.","en":"The equivalent of 9 dollars buys an hour of playtime with 30 hedgehogs in the café."},{"tr":"Her kirpi farklı türdendir.","en":"Every hedgehog is of a different kind."},{"tr":"Kafede bir kadın, kirpi görmenin çok nadir olduğunu söyledi.","en":"One woman in the café said that it is very rare to see a hedgehog."},{"tr":"Çocuklarının bir kirpi görebilmesinin tek yolu böyle bir yere gelmektir.","en":"The only way her children can see is to come a place like this."}]},{"id":"CK-229","no":229,"title":"Su Geçirmez Giysiler ve Pencereler","level":1,"code":"BLT","s":[{"tr":"İngiliz kamuoyu, hava şartlarına hazırlıksız yakalanmanın üzücü olduğunu çok iyi biliyor.","en":"The British public knows well that it is upsetting to to be caught out unprepared by the weather."},{"tr":"Şimdi, su geçirmez giysiler için bir gelecek var, ama bu tam olarak nedir?","en":"Now, there is a future for waterproof clothes, but what is this, exactly?"},{"tr":"Su geçirmez ceketinize benzer.","en":"It is similar to your water proof jacket."},{"tr":"Su zıplıyor ve çok kolay yuvarlanıyor.","en":"The water bounces off and rolls off really easily."},{"tr":"Su itici, sıçrama etkisine neden olur ve bu, ev boyasında kullanılanla aynıdır.","en":"Water-repellent causes the bouncing effect, and this is the same one that is used in house paint."},{"tr":"İlk defa, insanlar kovucuyu botlara ve bir cekete püskürttüler.","en":"For the first time, people sprayed the repellent onto boots, and a jacket."},{"tr":"Daha sonra test için çamurlu su kullandılar.","en":"Then they used muddy water for testing."},{"tr":"Uzaklaştırıcı gerçekten işe yaradı, ama gelecek için şansınız nedir?","en":"The repellent really worked, but what are the chances for the future?"},{"tr":"Buradaki zorluk, Uzaklaştırıcıyı daha güçlü hale getirmektir.","en":"The challenge is to make the repellent stronger."},{"tr":"Yani kendi kendini temizleyen pencereler ve artık pencere temizliği yok!","en":"So, Self-cleaning windows, and no more window cleaning!"},{"tr":"Elbette kimse bu fikre hayır demeyecektir.","en":"Surely, no one will say no to this idea."}]},{"id":"CK-230","no":230,"title":"Şempanze Hayvanat Bahçesinden Kaçar","level":1,"code":"DOG","s":[{"tr":"Kuzey Japonya'da bir şempanze bir hayvanat bahçesinden kaçtı.","en":"In Northern Japan, a chimp escaped a zoo."},{"tr":"24 yaşındaki erkek kaçmaya çalışmak için elektrik hatlarına tırmandı.","en":"The 24-year-old male climbed up power lines to try to get away."},{"tr":"İşçiler ve hayvan uzmanları, hayvanı aşağı indirmek için kiraz toplayıcı kullanmaya çalıştılar, ancak bu işe yaramadı, bu yüzden bir veteriner, şempanzeyi sakinleştirici bir tabancayla vurdu.","en":"Workers and animal experts tried to use a cherry picker so as to get the animal down, but that didn’t work, so a veterinarian shot the chimp with a tranquilizer gun."},{"tr":"Bir süre sonra şempanze yere düştü.","en":"After a moment, the chimp fell down."},{"tr":"Yerde onu yakalamaya çalışan insanlar vardı ama başarısız oldular.","en":"There were people on the ground who tried to catch him, but they failed."},{"tr":"Ancak yerel medya şempanzenin iyi olduğunu söyledi.","en":"However, local media said that the chimp was fine."}]},{"id":"CK-231","no":231,"title":"Bir Kız Tıpkı Onun Gibi Bir Oyuncak Bebek Alır","level":2,"code":"TOP","s":[{"tr":"ABD'nin Teksas eyaletinde Emma adında bir kızın protez bacağı var.","en":"In Texas, The USA, a girl named Emma has a prosthetic leg."},{"tr":"Ailesi onun için özel bir şey yapmak istedi, bu yüzden protez yapan bir şirketle temasa geçtiler.","en":"Her family wanted to do something special for her, so they contacted a company that makes prosthetics."},{"tr":"Şirkete protez bacak yapabilmek için bir oyuncak bebek gönderdiler.","en":"They sent the company a doll so that the company could create a prosthetic leg for it."},{"tr":"Pembe, Emma'nın en sevdiği renk olduğundan, şirket bebek için pembe bir bacak oluşturdu ve sonra onu Emma'ya gönderdi.","en":"The company created a pink leg for the doll as pink is Emma’s favorite color, and then sent it to Emma."},{"tr":"Emma bebeği aldığında, ailesi nasıl tepki verdiğini filme aldı.","en":"When Emma received the doll, her parents filmed how she responded."},{"tr":"Ağladığı için çok mutluydu.","en":"She was so happy that she cried."},{"tr":"Ayrıca şirketten bebeğinin hikayesi ve bacağı hakkında bir mektup okudu.","en":"She also read a letter from the company about her doll’s story, and about its leg."}]},{"id":"CK-232","no":232,"title":"Fin Saunası","level":2,"code":"TAR","s":[{"tr":"UNESCO, tüm dünyadaki kültürel mirasların bir listesini yapan bir kuruluştur.","en":"UNESCO is an organization that makes a list of cultural heritages all over the world."},{"tr":"Bu yerlerin ve geleneklerin korunmasına yardımcı olur.","en":"It helps protect these places and traditions."},{"tr":"2020 yılında UNESCO listeye Finlandiya'nın saunası dahil 35 şey ekledi.","en":"In 2020, UNESCO added 35 things to the list, including Finland’s sauna."},{"tr":"Sauna, Fin kültürünün en önemli parçasıdır ve insanlar onu binlerce yıl önce kullanmaya başlamıştır.","en":"The sauna is the most important part of Finnish culture, and people started to use it thousands of years ago."},{"tr":"Ülkede yaklaşık üç milyon sauna var ve bir Finlandiyalı en az haftada bir sauna kullanıyor.","en":"There are about three million saunas in the country, and a Finnish person uses a sauna at least once a week."},{"tr":"Sauna sadece banyo yapmaktan ibaret değildir.","en":"The sauna isn’t only about bathing."},{"tr":"İnsanları daha sağlıklı kılar ve rahatlamalarına yardımcı olur.","en":"It makes people healthier and it helps them relax."},{"tr":"UNESCO'nun 2020'de listesine dahil ettiği diğer şeyler arasında, örneğin Çek el yapımı cam ürünleri, Japon ahşap sanatı ve Güney Kore'nin ışık festivali sayılabilir.","en":"Among other things that UNESCO included on its list in 2020, for example, Czech handmade glass products, Japanese wooden art, and South Korea’s light festival can be shown."}]},{"id":"CK-233","no":233,"title":"Rusya ve Olimpiyatlar","level":1,"code":"SPO","s":[{"tr":"Rusya'nın Soçi kentinde düzenlenen 2014 Olimpiyat Oyunları'ndan sonra, Dünya Dopingle Mücadele Ajansı birçok Rus sporcunun yasaklı ilaç aldığını ortaya çıkardı.","en":"After the 2014 Olympics in Sochi, Russia, the World Anti-Doping Agency found out that many Russian athletes took banned drugs."},{"tr":"Rus yetkililer dopingi biliyordu ve Moskova laboratuvarı sonuçları değiştirdi.","en":"Russian officials knew about doping and Moscow laboratory changed the results."},{"tr":"Bir mahkeme, Rusya'yı dört yıl boyunca tüm spor etkinliklerinden men etti.","en":"A court banned Russia from all sports events for four years."},{"tr":"Ardından geçen hafta başka bir mahkeme yasağı değiştirdi.","en":"Then last week, another court changed the ban."},{"tr":"Rusya, adını, bayrağını ve marşını önümüzdeki iki Olimpiyatta ve önümüzdeki iki yıl içinde herhangi bir dünya şampiyonasında kullanamaz.","en":"Russia cannot use its name, flag, and anthem at the next two Olympics and at any world championship in the next two years."},{"tr":"Rus sporcular yarışabilir, ancak resmi olarak Rusya'yı temsil edemezler.","en":"Russian athletes can compete, but they cannot officially represent Russia."},{"tr":"Üniformaları \"nötr atlet\" yazacak.","en":"Their uniforms will say “neutral athlete”."},{"tr":"Pek çok sporcu kızgın çünkü bunun Rusya için gerçek bir yasak olmadığını söylüyorlar.","en":"Many athletes are angry because they say that this isn’t a real ban of Russia."}]},{"id":"CK-234","no":234,"title":"Meksika'da Albino Balina","level":2,"code":"DOG","s":[{"tr":"Albinizm, bir hayvan veya insan çok az doğduğunda veya ciltte renk oluşturan melanin pigmenti olmadan doğduğunda ortaya çıkar.","en":"Albinism happens when an animal or a human is born with very little or without the pigment melanin that makes color in the skin."},{"tr":"İnsanlar bunu memelilerde, kuşlarda ve sürüngenlerde görüyor, ancak Meksika yakınlarındaki gri balina göçünün 2008-2009 sezonuna kadar deniz memelilerinde nadiren görüyor.","en":"People see it in mammals, birds, and reptiles, but barely in marine mammals, until the 2008 to 2009 season of grey whale migration near Mexico."},{"tr":"O sezonda uzmanlar genç bir albino balina gördüler.","en":"In that season, experts saw a young albino whale."},{"tr":"Şimdi, uzmanlar Pasifik Kıyısı açıklarındaki gri balinaları inceliyor ve albino balinayı tekrar görüyor.","en":"Now, the experts study grey whales off the Pacific Coast and see the albino whale again."},{"tr":"Normal renkli bebeği ile yüzüyor.","en":"She swims with her baby that is normal-colored."}]},{"id":"CK-235","no":235,"title":"Avrupa'da Noel","level":2,"code":"TAR","s":[{"tr":"Noel geliyor ve birçok insan yılın bu özel zamanını dört gözle bekliyor.","en":"Christmas is coming and many people are looking forward to this special time of year."},{"tr":"Bu yıl Noel farklı.","en":"This year, Christmas is different."},{"tr":"Tüm dünyada yeni bir koronavirüs dalgası başladı.","en":"All over the world, a new wave of coronavirus started."},{"tr":"Hükümetler virüsü nasıl durduracaklarını ve aynı zamanda insanların Noel'in tadını çıkarmalarına nasıl izin vereceklerini düşünüyor.","en":"Governments are thinking about how to stop the virus and how to let people enjoy Christmas at the same time."},{"tr":"İtalya'da insanlar Noel arifesinde kiliselere gelemiyor.","en":"In Italy, people cannot come to churches on Chirstmas Eve."},{"tr":"Bunun nedeni, saat 22: 00'den önce evde olmaları gerektiğidir.","en":"This is because they must be at home before 10 pm."},{"tr":"Papa Francis'in Noel arifesi ayininin iki saat önce başlamasının ve insanların eve dönmek için yeterli zamanlarının olmasının nedeni budur.","en":"It is the reason why Pope Francis’s Christmas Eve mass will start two hours earlier, and people will have enough time to return home."},{"tr":"Almanya ve Avusturya'da bu yıl geleneksel Noel pazarı yok.","en":"In Germany and Austria, there are no traditional Christmas markets this year."},{"tr":"Almanya'da insanlar arabalarıyla bazı Noel pazarlarına gidebilirler.","en":"In Germany, people can get to some Christmas markets in their car."},{"tr":"Çoğu restoran ve otel kapanmalıdır ve insanlar sinemalara veya tiyatrolara gidemez.","en":"Most restaurants and hotels must close, and people cannot go to cinemas and theaters."}]},{"id":"CK-236","no":236,"title":"Uçaklar Güvenli mi","level":2,"code":"SAG","s":[{"tr":"COVID-19 salgını sırasında, hava yolculuğunda büyük bir düşüş oldu.","en":"During Covid-19 pandemic, there was a big fall in air travel."},{"tr":"En kötü noktada, tüm uçakların üçte ikisi uçmadı.","en":"At the worst point, two thirds of all planes didn’t fly."},{"tr":"Operatörler uçakları aylarca kaldıkları pistlere park etti.","en":"Operators parked the planes on runways where they stayed for months."},{"tr":"Şimdi, uçaklar tekrar uçmaya başlıyor, ancak birçok insan yeterince güvenli olmadıklarından endişeleniyor.","en":"Now, planes are starting to fly again, but many people worry that they aren’t safe enough."},{"tr":"Uzmanlar, acil durum sistemlerinde boş piller gibi teknik sorunlar olabileceğini söyledi.","en":"Experts said that there could be technical problems such as empty batteries in emergency systems."},{"tr":"Havayollarının uzun süredir uçmayan uçaklara nasıl baktıkları da net değil.","en":"It isn’t also clear how airlines maintained the planes which didn’t fly for a long time."},{"tr":"Bu yıl pilotlar indiğinde çok sayıda kaza ve doğru hız veya yükseklikte sorunlar yaşandı.","en":"This year, there were many accidents and problems with the right speed or altitude when pilots landed."},{"tr":"Uzmanlar, pilotların tekrar gerçek uçaklarla uçabilmeleri için eğitime gitmeleri gerektiğini söyledi.","en":"Experts said that pilots needed to go to train in order that they could fly with real planes again."}]},{"id":"CK-237","no":237,"title":"Etna Dağı Patlamaları","level":2,"code":"DOG","s":[{"tr":"Etna Dağı, Avrupa'nın en yüksek yanardağıdır.","en":"Mount Etna is the highest volcano in Europe."},{"tr":"İtalya'nın Sicilya adasının en büyük ikinci şehri olan Catania'nın yakınındadır.","en":"It is near Catania, which is the second-largest city on the island Sicily, Italy."},{"tr":"İtalya'da yalnızca üç aktif yanardağ vardır, ancak Etna Dağı diğer iki yanardağdan çok daha yüksektir.","en":"There are only three active volcanoes in Italy, but Mount Etna is a lot higher than the other volcanoes."},{"tr":"3.326 metre yüksekliğindedir ve neredeyse her zaman aktiftir.","en":"It is 3.326 meters high and it is almost always active."},{"tr":"Son patlama Aralık 2018'de meydana geldi ve iki gün sonra, bir deprem Catania'daki birkaç binayı yıktı.","en":"The last eruption happened in December 2018, and tho days later, an earthquake destroyed several buildings in Catania."},{"tr":"Bu hafta Etna Dağı tekrar patladı ve havaya bir kül bulutu gönderdi.","en":"This week, Mount Etna erupted again, and it sent a cloud of ash into the air."},{"tr":"İnsanlar yanardağdan çıkan lavları izledi.","en":"People watched lava coming out from the volcano."},{"tr":"Neyse ki patlama insanlar için tehlikeli değildi ve yetkililer herhangi bir hasar bildirmedi.","en":"Luckily, the eruption wasn’t dangerous for people and officials didn’t report any damage."}]},{"id":"CK-238","no":238,"title":"Katilin Mesajı","level":2,"code":"DUN","s":[{"tr":"Zodyak Katili, polisin 1960'larda ve 1970'lerde Kuzey Kaliforniya, ABD'de insanları öldüren bir seri katil için kullandığı isimdir.","en":"The Zodiac Killer is the name that police used for a serial killer who killed people in Northern California, US, the the 1960s and 1970s."},{"tr":"Polis bugün hâlâ katilin kimliğini bilmiyor.","en":"The police don’t still know the killer’s identity today."},{"tr":"Katil, San Francisco'daki gazetelere mektup ve kart gönderdi.","en":"The killer sent letters and card to newspapers in San Francisco."},{"tr":"Öldürdüğü insanlar ve bunu nasıl yaptığı hakkında yazdı.","en":"He wrote about the people he killed and how he did it."},{"tr":"Ayrıca dört şifre gönderdi.","en":"He also sent four ciphers."},{"tr":"Sıradan insanlar kadar uzmanlar da mesajları okumaya çalıştı ama çok zordu.","en":"Experts, as well as ordinary people, tried to read the messages, but it was very hard."},{"tr":"Geçen hafta, Avustralyalı bir matematikçi ve diğer iki adam, katilin mesajlarından birini çözdü.","en":"Last week, An Australian mathematician and two other men solved one of the killer’s messages."},{"tr":"Polisin adamın kim olduğunu öğrenmesine yardımcı olmadı, ancak katil mesajı özel bir şekilde yazdı.","en":"It didn’t help the police find out who the man was, but the killer wrote the message in a special way."},{"tr":"Polis, katilin adını bir gün öğreneceklerini umuyor.","en":"Police hope that they will know the killer’s nam one day."}]},{"id":"CK-239","no":239,"title":"Güneş tutulması","level":2,"code":"DOG","s":[{"tr":"Pazartesi günü, Güney Amerika'daki insanlar güneşin tam tutulmasını izliyor.","en":"On Monday, people in South America watch the total eclipse of the sun."},{"tr":"2020'deki tek tam tutulmaydı, bu yüzden birçok insan için çok özel bir olaydı.","en":"It was the only total eclipse in 2020, so it was a special event for many people."},{"tr":"Güney Amerika'da yaz olduğu için güneş gökyüzünde yüksekti ve tutulmayı izlemek kolaydı.","en":"Since it was summer in South America, the sun was high in the sky, and it was easy to watch the eclipse."},{"tr":"Hava tahmini pek iyi değildi, ama sonunda gökyüzü açıldı ve insanlar iki dakika süren tam tutulmanın tadını çıkardılar.","en":"The weather forecast was not very good, but in the end, the sky cleared, and people enjoyed the total eclipse that lasted two minutes."},{"tr":"Ay, dünya ile güneş arasına girdiğinde tam bir güneş tutulması meydana gelir.","en":"A total eclipse of the sun happens when the moon gets between the earth and the sun."},{"tr":"Ay güneşi gölgeliyor ve hava kararıyor.","en":"The moon shades the sun and it gets dark."},{"tr":"Güneşi tamamen bloke etmek için ayın dünyadan doğru uzaklıkta olması gerekir.","en":"The moon needs to be at the right distance from the earth so as to block the sun completely."}]},{"id":"CK-240","no":240,"title":"Victoria Şelaleleri'nde Uçurum Dalgıçları","level":2,"code":"DOG","s":[{"tr":"Victoria Şelaleleri yakınlarındaki Zambezi Nehri'ne 30 metreden iki uçurum dalgıcı atladı.","en":"Two cliff divers jumped from 30 meters into Zambezi River near Victoria Falls."},{"tr":"Nehrin bu kısmı Zambiya ve Zimbabve arasındaki sınırını oluşturur.","en":"This part of the river forms the boundary between Zambia and Zimbabwe."},{"tr":"Uçurum dalgıçları profesyoneldir.","en":"The cliff divers are professionals."},{"tr":"Normalde 26,5 ile 28 metre arasında atlarlar, bu yüzden bu onlar için yeni bir oyundu.","en":"They normally jump from between 26.5 and 28 meters, so this was a new game for them."},{"tr":"Şelaleler, derinlik ve genişlik karması bakımından dünyanın en büyüğüdür ve aynı zamanda Mosi-oa-Tunya veya Gök Gürültülü Duman olarak da bilinir.","en":"The falls are the world’s largest in combined depth and width, and are also known as Mosi-oa-Tunya or Smoke that Thunders."}]},{"id":"CK-241","no":241,"title":"Noel ışıkları","level":2,"code":"TAR","s":[{"tr":"Ohio, ABD'den Sarah Bailey, ailesinin evini birçok Noel ışığı ile dekore etti.","en":"Sarah Bailey from Ohio, US, decorated her family home with many Christmas lights."},{"tr":"Bir ışık gösterisi hazırladı ve gösteri sırasında bir Taylor Swift şarkısı çaldı.","en":"She prepared a light show, and she played a Taylor Swift song during the show."},{"tr":"Bailey videoyu sosyal medyasında yayınladı ve Swift tepki gösterdiğinde gözlerine inanamadı.","en":"Bailey posted the video on her social media, and she couldn’t believe her eyes when Swift reacted to it."},{"tr":"Swift, Bailey'nin şarkısını seçtiği için mutlu olduğunu yazdı.","en":"Swift wrote that she was happy that Bailey chose her song."},{"tr":"Bailey ayrıca videoda, kasabasında bir yiyecek bağışı olduğunu ve Swift'in de biraz para bağışladığını hatırlattı.","en":"Bailey also reminded in the video that there was a food donation in her town and Swift donated some money, too."},{"tr":"Bailey, müzik yıldızından bir yanıt aldığı için çok mutluydu.","en":"Bailey was very happy to get a response from the music star."},{"tr":"Bu yılın birçok insan için çok zor olduğunu söyledi, ve ışık gösterisiyle onları mutlu etmek istedi.","en":"She said that this year was very difficult for many people, and she wanted to make them happy with her light show."}]},{"id":"CK-242","no":242,"title":"Fırtınada Gemi","level":2,"code":"DUN","s":[{"tr":"Pasifik Okyanusunda bir fırtına başladığında bir Japon kargo gemisi Japonya'ya gidiyordu.","en":"A Japanese cargo ship was on its way to Japan when a storm started in the Pacific Ocean."},{"tr":"Bazı insanlar dalgaların yaklaşık 16 metre yüksekliğinde olduğunu söyledi.","en":"Some people said that the waves were about 16 meters high."},{"tr":"Gemi, eşya dolu konteynerler taşıyordu.","en":"The ship was carrying containers that were full of things."},{"tr":"1.800'den fazla konteyner denize düştü ve bunların 60'ı havai fişek ve pil gibi tehlikeli maddelerle doluydu.","en":"More than 1800 containers fell in the sea, and 60 of them were full of dangerous goods such as fireworks and batteries."},{"tr":"Felaket, tarihteki en büyük ikinci felaketti.","en":"The disaster was the second biggest disaster in history."},{"tr":"Tarihteki en kötü nakliye felaketi, 2013 yılında Hint Okyanusu'nda 1.700 konteyneri olan bir kargo gemisinin batmasıyla meydana geldi.","en":"The worst shipping disaster in history happened in 2013 when a cargo ship with 1700 containers sank in the Indian Ocean."},{"tr":"Bir yangın 2.400 konteyneri yok etti.","en":"A fire destroyed 2400 containers."},{"tr":"8 Aralık'ta gemi, güvenlik kontrolü için Japonya'ya geldi.","en":"On December 8, the ship arrived in Japan for a safety check."},{"tr":"Yetkililer, gemiyi tekrar kullanmanın güvenli olup olmadığına karar verecek.","en":"Authorities will decide if it is safe to use the ship again."}]},{"id":"CK-243","no":243,"title":"Viyana'da İki Panda","level":2,"code":"DOG","s":[{"tr":"Yılda yalnızca bir kez, pandalar için çiftleşme mevsimi olur.","en":"Only once a year, mating season for pandas happens."},{"tr":"Dişiler yılda sadece iki veya üç gün hamile kalabiliyor, bu da hamile kalmayı zorlaştırıyor.","en":"The females can only get pregnant for two or three days a year, which makes getting pregnant difficult."},{"tr":"Avusturya'nın Viyana kentindeki bir hayvanat bahçesinde, iki panda birkaç kez çiftleşti, ki bu bir hayvanat bahçesinde nadir görülen bir olaydır.","en":"In a zoo in Vienna, Austria, two pandas mated a few times, which is a rare event in a zoo."},{"tr":"Hayvanat bahçesi gösteriyi filme aldı ve videoyu yayınladı.","en":"The zoo filmed the act and released the video."},{"tr":"Bir pandanın hamilelik süresi 163 güne kadardır, bu nedenle hayvanat bahçesinin çiftleşmenin başarılı olup olmadığını görmek için beklemesi gerekir.","en":"The length of a panda’s pregnancy is up to 163 days, so the zoo must wait in order to see if the mating was a success."}]},{"id":"CK-244","no":244,"title":"Makine, Kitapları Güvenli Hale Getiriyor","level":2,"code":"BLT","s":[{"tr":"Japonya'daki kütüphaneler, kitapları sterilize eden özel makineler kullanır.","en":"Libraries in Japan use special machines that sterilize books."},{"tr":"Ziyaretçiler makineyi kitap ödünç aldıklarında ve iade ettiklerinde kullanabilirler.","en":"Visitors can use the machine when they borrow books and return them."},{"tr":"Bir kitabı sterilize etmek 30 saniye sürer.","en":"It takes 30 seconds to sterilize a book."},{"tr":"Makine sayfaları hareket ettirir ve tozu temizler.","en":"The machine moves the pages and clear out dust."},{"tr":"Özel ışık bakterileri öldürür ve kitapları güvenli ve temiz hale getirir.","en":"Special light kills bacteria and makes the books safe and clean."},{"tr":"Bazı insanlar makinenin gerçekten çalışıp çalışmadığını bilmiyorlar, ancak bir şeyi yapmanın hiç yoktan daha iyi olduğunu söylüyorlar.","en":"Some people don’t know if the machine really works, but they say that it is better to do something than nothing."},{"tr":"Kütüphaneler 2018'de makineleri kullanmaya başladı ve şu anda Japon kütüphanelerinde üç milyondan fazla makine var.","en":"Libraries started to use the machines, and there are more than three million machines in Japanese libraries."},{"tr":"Şu anda koronavirüs var ve insanlar makineleri giderek daha fazla kullanıyor.","en":"Now, there is the coronavirus, and people are using the machines more and more."},{"tr":"Birçok yaşlı kütüphanelerden kitap ödünç alır ve yaşlıları güvende tutmak önemlidir.","en":"Many elderly borrow books from libraries, and it is important to keep the elderly safe."}]},{"id":"CK-245","no":245,"title":"Breakdance Olimpik Bir Spor Haline Geliyor","level":2,"code":"SPO","s":[{"tr":"Breakdans bir tür sokak dansıdır ve ABD'den gelir.","en":"Breakdancing is a form of street dance and it comes from the US."},{"tr":"Afro-Amerikan topluluğu 1970'lerin başında New York'ta breakdance yarattı.","en":"The African American community created breakdance in New York in the early 1970s."},{"tr":"Kısa sürede çok popüler oldu ve 1980'lerde tüm dünyaya yayılmaya başladı.","en":"It quickly became very popular and it started to go all over the world in the 1980s."},{"tr":"Şimdi yetkililer breakdance'in olimpik bir spor haline geleceğini ve ilk olarak 2024'te Paris'teki Olimpiyat oyunlarında ortaya çıkacağını duyurdu.","en":"Now, officials announced that breakdance would become an Olympic sport and it would first appear at the Olympic games in Paris in 2024."},{"tr":"Haberler birçok break dansçıyı çok heyecanlandırdı.","en":"The news made many breakdancers very excited."},{"tr":"Resmi bir rapor, dünyada yaklaşık bir milyon break dansçı olduğunu söyledi.","en":"An official report said that there were about a million breakdancers in the world."},{"tr":"Breakdance sadece ne kadar güçlü olduğunuzla ilgili değildir.","en":"Breakdance is not only about how strong you are."},{"tr":"Olimpiyatlardaki jüri hareketleri ve dönüşleri değerlendirecek, ancak aynı zamanda stil, ritim ve yaratıcılığı da izleyecekler.","en":"The judges at the Olympics will judge moves and spins, but they will also watch style, rhythm, creativity."}]},{"id":"CK-246","no":246,"title":"İlk Kişi Aşı Oldu","level":2,"code":"SAG","s":[{"tr":"90 yaşındaki Margaret Keenan, dünyada resmi olarak koronavirüs aşısı yaptıran ilk kişi oldu.","en":"90-year-old Margaret Keenan became the first person in the world to get the coronavirus vaccine officially."},{"tr":"Aşı olan ikinci kişi 81 yaşındaki William Shakespeare idi.","en":"The second person to get the vaccine was 81-year-old William Shakespeare."},{"tr":"Her iki kişi de aşıyı İngiltere, Coventry'deki Üniversite Hastanesinde oldu.","en":"Both people got the vaccine at the University Hospital in Coventry, UK."},{"tr":"Bazı insanlar kendilerinden önce aşı yaptırdı, ancak bu, testlerin bir parçasıydı.","en":"Some people got the vaccine before them, but it was a part of the tests."},{"tr":"Şimdi, Birleşik Krallık dünyadaki insanları resmi olarak aşılayan ilk ülke oldu.","en":"Now, the UK became the first country in the world to vaccinate people officially."},{"tr":"Aşıyı ilk olanlar arasında 80 yaş ve üstü kişiler olacak, ancak şehirlerde veya küçük kasabalarda yaşamayan kişilere aşı yaptırmak zor olabilir.","en":"People who are 80 and over will be among the first to get the vaccine, but it can be difficult to vaccinate people who don’t live in the cities or small towns."},{"tr":"Bazı insanlar da aşının güvenli olmadığından endişeleniyor çünkü testler yeterince kapsamlı değil.","en":"Some people also worry that the vaccine isn’t safe because the tests aren’t thorough enough."}]},{"id":"CK-247","no":247,"title":"Venezuela Oy kullanıyor","level":3,"code":"DUN","s":[{"tr":"Venezuela Devlet Başkanı Nicolas Maduro, hükümet üzerinde tam kontrole sahip olmak istedi.","en":"Venezuelan president, Nicolas Maduro wanted to get full control over the government."},{"tr":"İnsanlar hükümet için 277 politikacıya oy verdi, ancak birçok siyasi parti oylamayı protesto etti.","en":"People voted for 277 politicians for the government, but many political parties protested against the vote."},{"tr":"Oylamanın adil ve özgür olacağından emin olmadığını söylediler.","en":"They said that it wasn’t sure that the vote would be fair and free."},{"tr":"Ayrıca oylamayı izleyecek ve adil olduğundan emin olacak hiçbir uluslararası gözlemci olmamasından da mutsuzlardı.","en":"They were also unhappy that there were no international observers who would watch the vote and make sure that it was fair."},{"tr":"Yetkililer, halkın %25 ila %36'sının oylamaya on yılın en düşük rakamı olan katılmasını bekliyorlardı.","en":"Officials expected that between 25% and 36% of people would take part in the vote, which was the lowest number in ten years."},{"tr":"Hükümet sayıyı yükseltmek istedi ve cumhurbaşkanı insanları oylamaya katılmaya teşvik etmek için özel bir ikramiye teklif etti.","en":"The government wanted to make the number higher and the president offered a special bonus to encourage people to take part in the vote."}]},{"id":"CK-248","no":248,"title":"Maskeli Domuzlar","level":2,"code":"TAR","s":[{"tr":"Çekler, Noel arifesi yemeğinden önce içmezler veya yemek yemezlerse altın bir domuz göreceklerine inanıyor.","en":"Czech people believe that they will see a golden pig if they don’t drink or eat before Christmas Eve dinner."},{"tr":"Bir Çek şirketi Noel süsleri yapıyor.","en":"A Czech company makes Christmas ornaments."},{"tr":"Altın domuza benzeyen süslemeler yapmak bir gelenektir.","en":"It is a tradition to make ornaments that look like golden pigs."},{"tr":"Her yıl, süslemeciler beyaz, altın ve pembe altın renkli domuz yavrusu süsleri yaparlar.","en":"Every year, ornament makers make golden piglet decorations in white, gold, and pink."},{"tr":"Genellikle çiçek ve fiyonk eklerler, ancak bu yıl domuzlar farklı görünüyor.","en":"They usually add flowers and bows, but this year, the pigs look different."},{"tr":"Firmanın sahibine göre, süslemeciler mevcut duruma tepki vermek istedi.","en":"According to the owner of the company, ornament makers wanted to react the current situation."},{"tr":"Bu nedenle yüz maskeleri eklediler.","en":"Therefore, they added face masks."},{"tr":"Maskelerdeki altın domuz yavruları hemen büyük bir hit oldu ve süslemeciler artık domuz yavrularından başka bir şey yapmıyorlar.","en":"Golden piglets in masks immediately became a big hit, and ornament makers are now making nothing else apart from the piglets."}]},{"id":"CK-249","no":249,"title":"Dünya Orkestrası","level":2,"code":"TAR","s":[{"tr":"197 müzisyen bir araya geldi ve bir orkestra oluşturdular.","en":"197 musicians got together and they created an orchestra."},{"tr":"Her müzisyen farklı bir ülkedendi.","en":"Each musician was from a different country."},{"tr":"Orkestra, \"Together is Beautiful\" adlı bir şarkı kaydetti.","en":"The orchestra recorded a song called \"Together is Beautiful\"."},{"tr":"Sanatçılar, fiziksel ve kültürel sınırları aşmanın ve özel bir şey yapmanın mümkün olduğunu göstermek istediler.","en":"The artists wanted to show that it was possible to cross physical and cultural borders and to make something special."},{"tr":"Sonunda, ne kadar iyi çalıştığına şaşırdılar.","en":"In the end, they were surprised at how well it worked."},{"tr":"Tek bir sanatçı gibi hissettiler.","en":"They felt like one artist."},{"tr":"Proje üç yıl önce başladı ve ünlü bir besteci George Fenton denetledi.","en":"The project started three years ago and a famous composer George Fenton supervised it."},{"tr":"Fenton melodiler üretti ve bazı müzisyenler net bir plan yapmadan parçalarını eklediler.","en":"Fenton came up with melodies and some musicians added their parts without a clear plan."},{"tr":"Farklı stilleri birleştirdiler ve kendi ülkelerinden gelen enstrümanları kullandılar.","en":"They combined different styles and they used instruments that came from their home countries."}]},{"id":"CK-250","no":250,"title":"Teleskop Çöküyor","level":1,"code":"BLT","s":[{"tr":"Arecibo Teleskopu, Porto Riko'da bir teleskoptu.","en":"The Arecibo Telescope was a telescope in Puerto Rico."},{"tr":"İnsanlar onu 1963'te doğal bir deliğe inşa ettiler.","en":"People built it into a natural hole in 1963."},{"tr":"Teleskobun çanağı 305 metre genişliğinde ve alıcısı 900 ton ağırlığındaydı.","en":"The telescope’s dish was 305 meters wide and its receiver weighed 900 tons."},{"tr":"Teleskop çok eski ve hasarlıydı, bu yüzden yetkililer onu çıkarmaya karar verdi.","en":"The telescope was very old and damaged, so officials decided to remove it."},{"tr":"Geçen hafta teleskop kendi kendine çöktü.","en":"Last week, the telescope collapsed it self."},{"tr":"Bir kablo koptu ve alıcı 100 metre aşağıdaki çanağa düştü.","en":"A cable snapped and the receiver fell 100 meters onto the dish."},{"tr":"Geçmişte teleskop çok önemliydi ve dünyanın her yerinden birçok bilim adamı onu kullandı.","en":"In the past, the telescope was very important, and many scientists from all over the world used it."},{"tr":"Diğer şeylerin yanı sıra, onu dünyanın dışında akıllı bir yaşam aramak için kullandılar.","en":"Besides other things, they used it to search for intelligent life outside the earth."},{"tr":"Pek çok filmde ve oyunda, örneğin 1995 James Bond filmi \"Golden Eye\" da sahnelerin bir parçasıydı.","en":"It was a part of scenes in many films and games, for example, in the 1995 James Bond film “Golden Eye”."}]},{"id":"CK-251","no":251,"title":"Mülteciler için Ada","level":2,"code":"DUN","s":[{"tr":"2017'de Myanmar'daki tehlikeli bir durum milyonlarca insanın ülkeyi terk etmesine neden oldu.","en":"In 2017, a dangerous situation in Myanmar caused millions od people to leave the country."},{"tr":"Bangladeş'e kaçtılar ve şimdi mülteci kamplarında kalıyorlar.","en":"They escaped to Bangladesh and now, they are staying in refugee camps."},{"tr":"Bangladeş hükümeti, sorunu tam mülteci kamplarıyla çözmenin bir yolunu buldu.","en":"The Bangladeshi government found a way to solve the problem with full refugee camps."},{"tr":"Birkaç yıl önce, hükümet bir adada mülteciler için evler inşa etmeye başladı, ancak birçok insan bundan memnun değil.","en":"A few years ago, the government started to build homes for refugees on an island, but many people aren’t happy with it."},{"tr":"Ada, Bangladeş kıyılarının yaklaşık 40 kilometre uzağında yer alıyor ve yağmur mevsiminde adanın büyük bir kısmı su altında kalıyor.","en":"The island lies about 40 kilometers off the coast of Bangladesh and during the rain season, a big part of the island ends up underwater."},{"tr":"Geçen hafta Bangladeş mültecileri adaya taşımaya başladı.","en":"Last week, Bangladesh started to move the refugees to the island."},{"tr":"Zaten sorunları da beraberinde getirdi çünkü bazıları oraya taşınmayı kabul etmediklerini söyledi.","en":"It already brought problems because some people said that they didn’t agree to move there."}]},{"id":"CK-252","no":252,"title":"Kar Altındaki Şehir","level":1,"code":"DOG","s":[{"tr":"Norilsk şehri Rusya, Sibirya’da bulunur ve ülkenin en kuzey şehridir.","en":"The city of Norilsk is located in Siberia, Russia, and it is the most northerly city in the country."},{"tr":"Dünyanın kuzeyini belirleyen hayali bir çizgi olan Kuzey Kutup Dairesi'nin sadece 300 kilometre kuzeyinde yer almaktadır.","en":"It lies only 300 kilometers north of Arctic Circle which is an imaginary line that marks the north of the world."},{"tr":"Birkaç hafta önce, saatte 100 km'ye kadar yüksek rüzgarlar yoğun kar yağışı getirdi.","en":"A few weeks ago, high winds of up to 100 kmph brought heavy snowfall."},{"tr":"Bazı yerlerde kar iki metreden daha yüksekti.","en":"In some places, the snow was more than two meters high."},{"tr":"Arabaları ve yolları gömdü.","en":"It buried cars and roads."},{"tr":"Rüzgar o kadar kuvvetliydi ki yerel yetkililer yerel havalimanını kapatmaya karar verdi.","en":"The winds were so strong that local officials decided to close the local airport."},{"tr":"Yetkililer, son iki ayda şehirden yaklaşık 400 bin ton kar temizlediklerini söylediler.","en":"Officials said that they cleared around 400000 tons of snow from the city in the last two months."},{"tr":"Aşırı havanın seyahat üzerinde büyük bir etkisi oldu, ancak yerel halkı hiç üzmedi.","en":"The extreme weather had a big impact on travel, but it didn’t make local people unhappy."}]},{"id":"CK-253","no":253,"title":"Aya iniş","level":2,"code":"BLT","s":[{"tr":"Geçen hafta, Çin'in uzay aracı aya başarıyla indi.","en":"Last week, China’s spacecraft successfully landed on the moon."},{"tr":"Aya yolculuk 122 saat sürdü ve bilim adamları inecek yeri dikkatlice seçtiler.","en":"The journey to the moon lasted 122 hours, and scientists chose the place to land."},{"tr":"Alan, Fırtınalar Okyanusu olarak adlandırıldı ve düz bir lav alanıydı.","en":"The area was called the Oceans of Storms and it was a flat lava area."},{"tr":"Burayı daha önce kimse keşfetmemişti.","en":"Nobody explored this place ever before."},{"tr":"Kameralar inişi kaydetti ve görüntüleri Dünya'ya geri gönderdiler.","en":"Cameras recorded the landing and they sent images back to Earth."},{"tr":"Uzay aracı yaklaşık iki kilogram kaya toplayacak ve onu Dünya'ya geri getirecek.","en":"The spacecraft will collect about two kilograms of rock and bring it back to Earth."},{"tr":"Uzay aracı Dünya'ya dönerse, Çin için büyük bir başarı olacak.","en":"If the spacecraft returns to Earth, it will be a big success for China."},{"tr":"Geçmişte sadece ABD ve Sovyetler Birliği aydan kaya getirdi.","en":"In the past, only the US and Soviet Union brought rock from the moon."},{"tr":"Uzay Yarışı sırasında 60'lı ve 70'li yıllarda, iki ülke aya ilk iniş yapmak ve insanları uzaya göndermek için yarıştığında gerçekleşti.","en":"It happened in the 60s and 70s during the Space Race, when the two countries competed to be first to land on the moon and send people into space."}]},{"id":"CK-254","no":254,"title":"Gizemli Keşif","level":2,"code":"BLT","s":[{"tr":"Bret Hutchins, ABD, Utah'ın ücra bir köşesinde uçuyor ve koyun sayıyordu.","en":"Bret Hutchins was flying over a remote part of Utah, US, and he was counting sheep."},{"tr":"Aniden alışılmadık bir nesne gördü.","en":"He saw an unusual object."},{"tr":"Hutchins helikopter pilotundan iniş yapmasını istedi ve gördüklerine inanamadılar.","en":"Hutchins asked the helicopter pilot to land and they couldn’t believe what they saw."},{"tr":"Parlak metal bir monolit oradaydı.","en":"A shiny metal monolith was there."},{"tr":"Yaklaşık 300 ila 360 santimetre yüksekliğindeydi ve sanki biri onu yere koymuştu.","en":"It was about 300 to 360 centimeters high, and it seemed that somebody put it in the ground."},{"tr":"Ama her yerde büyük kırmızı kayalar vardı ve sanki monolit oraya ait değilmiş gibi görünüyordu.","en":"However, there were big red rocks all around and it seemed as if the monolith didn’t belong there."},{"tr":"Bazıları, nesnenin 2011'de ölene kadar New Mexico ve New York'ta yaşayan sanatçı John McCracken'in heykellerine benzediğini söyledi.","en":"Some people said that the object looked like artist John McCracken who lived in New Mexico and New York until he died in 2011."},{"tr":"Diğerleri, monolitin ve buranın Stanley Kubrick filminin '2001' filminden bir sahne gibi göründüğünü söyledi.","en":"Some people said that the monolith and the place where it looked like a scene from Stanley Kubrick movie “2001”."}]},{"id":"CK-255","no":255,"title":"Sokaklarda Para","level":1,"code":"DUN","s":[{"tr":"Yaklaşık 30 kişilik bir çete Brezilya, Criciúma sokaklarını ele geçirdi.","en":"A gang of about 30 men took control over the streets Criciúma, Brazil."},{"tr":"Suçlular, polisin herhangi bir işlem yapmasını engellemek için şehre erişimi engelledi.","en":"The criminals blocked access to the city to stop the police from taking any action."},{"tr":"Erkekler gece yarısından hemen sonra ucuz arabalarla şehre geldi.","en":"Men came to the city inexpensive cars just after midnight."},{"tr":"Bazı insanlar onları filme aldı ve iyi eğitilmiş ve organize oldukları açıktı.","en":"Some people filmed them, and it was clear that they were well trained and organized."},{"tr":"Bir banka soydular ve havaya uçurdular.","en":"They robbed a bank and blew it up."},{"tr":"Arabalara zarar verip sokaklarda ateş etmeye başladılar.","en":"They damaged cars and started to shoot in the streets."},{"tr":"Belediye başkanı, insanlardan evlerinde kalmalarını istedi.","en":"The mayor of the city asked people to stay in their homes."},{"tr":"Suçlular şehri terk ederken, sokakları parayla doldurdular ve bazı insanlar bir kısmını kapmak için dışarı çıktılar.","en":"While the criminals were leaving the city, they littered the streets with money, and some people went outside to grab some of it."}]},{"id":"CK-256","no":256,"title":"Sri Lanka Hapishanesi Sorunları","level":3,"code":"DUN","s":[{"tr":"Sri Lanka'da mahkumlar, yetkililerin koronavirüsü ele alma şeklinden memnun değildi ve protesto etmeye başladılar.","en":"In Sri Lanka, prisoners weren’t happy with the way that authorities handled the coronavirus, and they started to protest."},{"tr":"Colombo'nun başkenti yakınlarındaki Mahara hapishanesinde durum kontrolden çıktı.","en":"In the Mahara prison near the capital of Colombo, the situation got out of control."},{"tr":"Sri Lanka hapishaneleri çok kalabalıktı ve yeni koronavirüs vakalarının sayısı artmaya başladı.","en":"Sri Lankan prisons were very crowded and the number of new cases of coronavirus started to go up."},{"tr":"Mahkumlar daha fazla test istiyorlardı ve ayrıca enfekte mahkumlar için daha fazla oda istiyorlardı.","en":"Prisoners wanted more tests, and they also wanted more rooms for infected prisoners."},{"tr":"Gardiyanlar mahkumları sakinleştirmeye çalıştı, ancak yetkililerin gardiyanlara yardım etmek için yüzlerce polis memuru göndermesi gerekiyordu.","en":"The guards tried to calm the prisoners, but officials needed to send hundreds of police officers to help th guards."},{"tr":"Yetkililer, sekiz mahkumun öldüğünü ve 50'den fazla mahkumun hastanede ağır yaralandığını söyledi.","en":"Officials said that eight prisoners died and more than 50 prisoners were seriously hurt in hospital."}]},{"id":"CK-257","no":257,"title":"Beyaz Saray Noel Süslemeleri","level":1,"code":"TAR","s":[{"tr":"Amerika'nın First Lady'si Melania Trump, Beyaz Saray Noel süslerini ilk kez halka gösterdi.","en":"American first Lady, Melania Trump, showed her White House Christmas decorations to the public for the first time."},{"tr":"Sosyal medyada Trump, bu yılki dekorasyon temasının \"Güzel Amerika\" olduğunu söyledi.","en":"On social media, Trump said that this year’s theme of the decorations was “America The Beautiful”."},{"tr":"Trump, Amerikan ulusunu onurlandırmak istediğini söyledi.","en":"Trump said that she wanted to honor the American nation."},{"tr":"Trump'ın yeşil ağaçlar, beyaz ışıklar ve kırmızı süslemelerle geleneksel dekorasyonları seçmesinin nedeni buydu.","en":"This was the reason why Trump chose traditional decorations with green trees, white lights, and red ornaments."},{"tr":"Geçmişte, Trump daha sıra dışı süslemeler seçti.","en":"In the past, Trump chose more unusual decorations."},{"tr":"Örneğin 2018'de kırmızı Noel ağaçlarını seçti ve bazı insanlar onlardan memnun değildi.","en":"For example, she chose red Christmas trees, and some people weren’t happy about them."},{"tr":"Bir şey değişmedi.","en":"One thing didn’t changed."},{"tr":"Noel ağacı her zaman 5.5 metre boyundadır ve tavana kadar uzanır.","en":"The Christmas tree is always tall and it reaches the ceiling."},{"tr":"Yer açmak için tavan ışığını çıkarmak gerekir.","en":"It is necessary to remove the ceiling light to make room for it."}]},{"id":"CK-258","no":258,"title":"Goril Sezaryen ile Doğdu","level":2,"code":"DOG","s":[{"tr":"İngiltere'deki bir hayvanat bahçesindeki hamile bir gorilin sorunları vardı ve bebek sezaryen ile çıkarılmak zorunda kaldı.","en":"A pregnant gorilla at a zoo in England had problems, and the baby had to be taken out by cesarean section."},{"tr":"Bebek goril, sezaryen ile başarıyla doğan ilk gorildir.","en":"The baby gorilla is the first gorilla to be born successfully by cesarean section."},{"tr":"Bebeğin henüz bir adı yok ama ağırlığı bir kilodan fazla ve durumu iyi.","en":"The baby doesn’t have a name yet, but she is over a kilo heavy and her situation is fine."},{"tr":"Bir hayvanat bahçesi görevlisi, zaten annesi gibi oldukça güçlü bir karaktere sahip olduğunu söyledi.","en":"A zookeeper said that she already has a very strong character like her mother."},{"tr":"İnsanların ne zaman uyandığını ve ne zaman acıktığını bilmelerini sağlıyor.","en":"She lets people know when she is awake and when she is hungry."},{"tr":"Alışılmadık bir şekilde, bir insan jinekolog sezaryeni gerçekleştirdi.","en":"Unusually, a human gynecologist carried out the cesarean section."},{"tr":"Operasyonun bir insanı ameliyat etmeye çok benzediğini söyledi.","en":"He said that the operation was very similar to operating on a human."}]},{"id":"CK-259","no":259,"title":"Yeşil Uçuş","level":3,"code":"DOG","s":[{"tr":"Lufthansa bir Alman şirketidir ve dünyanın en büyük havayollarından biridir.","en":"Lufthansa is a German company and it is one of the world’s largest airlines."},{"tr":"Geçen hafta Lufthansa ilk CO2-nötr uçuşu yapacağını duyurdu.","en":"Last week, Lufthansa announced that it would make the first CO2-neutral flight."},{"tr":"Lufthansa, bitkilerden veya hayvan atıklarından yapılan bir yakıt olan biyoyakıt kullanacak.","en":"Lufthansa will use biofuel, which is a fuel that is made from plants or animal waste."},{"tr":"Sorun şu ki, biyoyakıt geleneksel yakıttan üç ila altı kat daha pahalı, bu nedenle havayollarının yakın gelecekte onu çok fazla kullanması pek olası değil.","en":"The problem is that biofuel is three to six times more expensive than conventional fuel, so it is not very likely that airlines will use it very much in the near future."},{"tr":"Koronavirüs, şirketlerin daha az petrole ihtiyaç duymasına neden oldu ve bazı rafinerilerin kapanması da mümkün.","en":"The coronavirus has caused companies to need less oil and it is possible that some refineries will close."},{"tr":"Bu, bazı şirketleri biyoyakıt kullanmaya ve daha çevreci olmaya zorlayabilir, bu da çevreye daha az zararlı teknolojileri kullanacakları anlamına gelir.","en":"This could force some companies to use biofuel and become greener, which means that they will use technologies that are less harmful to the environment."}]},{"id":"CK-260","no":260,"title":"Amazon Grevi","level":2,"code":"DUN","s":[{"tr":"Amazon bir ABD şirketidir ve dünyanın en büyük çevrimiçi perakendecisidir.","en":"Amazon is a US company and the world’s largest online retailer."},{"tr":"Amazon'un ABD dışındaki en büyük pazarı Almanya'da ve Alman Amazon işçileri üç gün sürecek bir greve gitmeyi planlıyor.","en":"Amazon’s biggest market outside the US is in Germany and German Amazon workers are planning to go a strike that will last three days."},{"tr":"Grev, yedi Alman Amazon deposunda gerçekleşecek ve 25 Kasım'da başlayacak.","en":"The strike will take place in seven German Amazon warehouses and it will start on November 25."},{"tr":"Ancak 27 Kasım'da \"Muhteşem Cuma\" var.","en":"However, On November 27, there is “Black Friday”."},{"tr":"Birçok mağaza için Kara Cuma, Noel alışveriş sezonunun başlangıcıdır ve çok büyük satışlar sunarlar.","en":"For many stores, Black Friday is the start of Christmas shopping season, and they offer very big sales."},{"tr":"Amazon çalışanları daha yüksek maaş ve daha iyi çalışma koşulları istiyor.","en":"Amazon workers want higher salaries and better working conditions."},{"tr":"Koronavirüs salgını sırasında, daha fazla insan çevrimiçi alışveriş yaptı ve bu Amazon için daha fazla iş anlamına geliyor.","en":"During the coronavirus pandemic, more people have shopped online and it means more business for Amazon."}]},{"id":"CK-261","no":261,"title":"Köpek Motosiklet Sürüyor","level":1,"code":"DOG","s":[{"tr":"İnternetteki bir video viral hale geldi.","en":"A video on the Internet became viral."},{"tr":"Bir motosiklet üzerindeki bir adam ve bir köpeği gösteriyor.","en":"It shows a man and a dog on a motorbike."},{"tr":"Garip bir şekilde, sürüş yapan köpektir.","en":"Strangely, it is the dog that is driving."},{"tr":"Bir kişi videoyu Manado, Endonezya'da filme aldı.","en":"A person filmed the video in Manado, Indonesia."},{"tr":"Adam ve köpek çok yakın olmalı.","en":"The man and the dog must be very close."},{"tr":"Ancak, insanların köpekleri yediği meşhur bir yere gidiyorlardı.","en":"However, they were driving to a famous place where people eat dogs."},{"tr":"Adam, motorsiklet kullanan bir köpeğin insanlara alışılmadık görünebileceğini, ancak Endonezya'da bunun tamamen normal olduğunu söyledi.","en":"The man said that a driving dog can seem unusual to people, but that it is completely normal in Indonesia."}]},{"id":"CK-262","no":262,"title":"Diego Maradona Öldü","level":1,"code":"SPO","s":[{"tr":"Diego Maradona, Arjantinli bir futbol efsanesiydi.","en":"Diego Maradona was an Argentinian football legend."},{"tr":"60 yaşında kalp krizinden öldü.","en":"He died from a heart attack at the age of 60."},{"tr":"Milyonlarca futbol taraftarı, muhteşem futbol becerileri için Maradona'yı sevdi.","en":"Millions of football fans loved Maradona for his amazing football skills."},{"tr":"1986 Dünya Kupası'ndan sonra Arjantin'in kupayı kazanmasına yardım ettiğinde bir yıldız oldu.","en":"After the 1986 World Cup, when he helped Argentina win the cup."},{"tr":"Maradona'nın İngiltere karşısındaki performansından tüm dünya etkilendi.","en":"All the world was impressed by Maradona’s performance against England."},{"tr":"Bugün birçok insanın hala hatırladığı harika bir gol attı.","en":"Today, He scored an amazing goal that many people still remember."},{"tr":"Maradona, \"Tanrı'nın Eli\" olarak golden bahsetti.","en":"Maradona spoke out the goal as the “Hand of God”."},{"tr":"Ancak Maradona'nın özel hayatı o kadar da iyi değildi.","en":"However, Maradona’s private life wasn’t so great."},{"tr":"Maradona'nın uyuşturucu ve alkol sorunları vardı ve birkaç kez sorunları nedeniyle oynamasına izin verilmedi.","en":"Maradona had problems with drugs and alcohol and several times, he wasn’t allowed to play owing to the problems."},{"tr":"Futbol kariyerini 1997'de durdurdu.","en":"He stopped his football career in 1997."}]},{"id":"CK-263","no":263,"title":"Dünyanın En Zengin Adamları","level":1,"code":"POR","s":[{"tr":"Elon Musk, Tesla şirketinin kurucu ortağıdır ve Ocak 2020'de net değeri 7,2 milyar dolardı.","en":"Elon Musk is the co-founder of the company Tesla and in January 2020, its net worth was $7,2 billion."},{"tr":"Ancak Kasım ayında net değeri neredeyse 128 milyar dolardı.","en":"However, in November, its net worth was almost $128 billion."},{"tr":"Ocak ayında dünyanın en zengin 35. adamıydı ve şimdi en zengin ikinci adam oldu.","en":"In January, he was the 35th richest man in the world, and now he has become the second richest man."},{"tr":"Bill Gates, yıllarca dünyanın en zengin adamıydı.","en":"Bill Gates was the richest man in the world for many years."},{"tr":"Bill Gates, Microsoft şirketinin kurucu ortağıdır ve yıllar boyunca hayır kurumlarına 27 milyar dolardan fazla bağışta bulunmuştur.","en":"Bill Gates is the co-founder of the company Microsoft, and he gave more than 27 billion dollars to charity over the years."},{"tr":"Net serveti 127,7 milyar dolar ve geçen yıl ilk kez iki kişinin ondan daha fazla parası var.","en":"His net worth is $127.7 billion, and last year, for the first time, two people have more money than him."},{"tr":"Jeff Bezos, 2017'de dünyanın en zengin adamı oldu.","en":"In 2017, Jeff Bezos became the richest man in the world."},{"tr":"Amazon'un kurucusu ve 182 milyar dolarlık net değeri.","en":"He is the founder of Amazon and its net worth is $182 billion."}]},{"id":"CK-264","no":264,"title":"Kolombiya Katliamı","level":3,"code":"DUN","s":[{"tr":"Cumartesi günü, on silahlı adam Kolombiya'da bir kahve çiftliğinde toplu katliamda en az sekiz kişiyi öldürdü.","en":"On Saturday, ten armed men killed at least eight people in a mass killing on a coffee farm in Colombia."},{"tr":"Yerel yetkililer, olayın uyuşturucu işiyle bağlantılı olduğunu ve suçluların en büyük uyuşturucu kartellerinden birinin parçası olduğunu söyledi.","en":"Local authorities said that the incident was connected to the drug business and that the criminals were a part of one of the biggest drug cartels."},{"tr":"Uyuşturucu karteli muhtemelen yerel yönetime ve insanların yaşama biçimine zarar vermek istedi.","en":"The drug cartel probably wanted to harm the local government and the way that people lived."},{"tr":"Kolombiya'da uyuşturucu işiyle ilgili sorunlar uzun yıllar sürüyordu ve geçen yıl daha da kötüleşti.","en":"Problems with the drug business have lasted for many years in Colombia, and they got even worse."},{"tr":"Kolombiya, dünyadaki en büyük kokain üreticilerinden biridir ve uyuşturucu ticareti birçok insanı etkilemektedir.","en":"Colombia is one of the biggest creators of cocaine in the world, and the drug business affects many people."},{"tr":"Uyuşturucu ticareti nedeniyle 260 binden fazla insan öldü ve milyonlarca insan şiddet nedeniyle evlerini terk etmek zorunda kaldı.","en":"More than 260 thousand people died owing to the drug business and millions of people had to leave their homes because of the violence."}]},{"id":"CK-265","no":265,"title":"Kör Koşucu","level":1,"code":"POR","s":[{"tr":"Thomas Panek 49 yaşında ve kör.","en":"Thomas Panek is 49 years old and he is blind."},{"tr":"Rehber köpek yetiştiren bir organizasyonun başkanıdır.","en":"He is the president of an organization that trains guide dogs."},{"tr":"Bir rehber köpek, kör bir kişinin güvenli bir şekilde dolaşmasına yardımcı olur.","en":"A guide dog helps a blind person travel around safely."},{"tr":"Panek, köpeğinin yardımıyla 20'den fazla maraton koştu.","en":"Panek has run more than 20 marathons with the help of his dog."},{"tr":"Ama kör koşucuların hayatlarını nasıl daha da kolaylaştıracağına dair bir fikri var.","en":"However, he has an idea of how to make the lives of blind runners even easier."},{"tr":"Panek, Google ile çalışmaya başladı ve birlikte kör koşucuların köpekleri olmadan koşabilecekleri bir yol bulmak istediler.","en":"Panek started to work with Google and together they wanted to find a way that blind runners could run without their dogs."},{"tr":"Yazılım mühendisleri Guideline adlı bir uygulama yaptı.","en":"Software engineers made an app called Guideline."},{"tr":"Uygulama AI kullanır, koşucunun konumunu kontrol eder ve ona nereye gideceğini söyler.","en":"The app uses AI, it checks the runners’ location and it tells him where to go."},{"tr":"Panek, uygulamayı ABD, New York City'deki Central Park'ta test etti ve tamamen kendi başına beş kilometre koştu.","en":"Panek tested the app in Central Park in New York City, US, and he ran five kilometers completely on his own."},{"tr":"Yalnızca akıllı telefonuna, kulaklığına ve uygulamasına ihtiyacı vardı.","en":"He needed only his smartphone, headphones, and the app."}]},{"id":"CK-266","no":266,"title":"Çocuğun Hayalleri Gerçekleşiyor","level":3,"code":"POR","s":[{"tr":"Afganistan'daki fakir bir aileden bir çocuk, plastik bir torbayı Lionel Messi formasına dönüştürdükten sonra internetin kalbini zaptetti.","en":"A boy from a poor family in Afghanistan captured the Internet’s heart after he customized a plastic bag into a Lionel Messi shirt."},{"tr":"Beş yaşındaki çocuk, futbolcunun kendisine bir futbol topu ve iki futbol forması içeren bir paket göndermesiyle hayallerini gerçekleştirdi.","en":"The five-year-old boy had his dreams come true as the footballer sent him a package with a football and two football jerseys."},{"tr":"Bir forma Barcelona takımından, ikincisi ise Arjantin takımından.","en":"One jersey is from the Barcelona team, and the second one is from the Argentina team."},{"tr":"Afgan çocuk mutlu ve gururla 10 numaralı futbol formalarını giyiyor.","en":"The Afghan boy is happy and he proudly wears his number 10 football jerseys."}]},{"id":"CK-267","no":267,"title":"Çok Genç Bir Fenomen","level":2,"code":"POR","s":[{"tr":"Sirio, İtalya'dan yedi yaşında bir çocuk.","en":"Sirio is a seven-year-old boy from Italy."},{"tr":"Konuşamıyor ve kendini besleyemiyor ama bu onun sosyal medya yıldızı olmasını engellemedi.","en":"He cannot speak and he cannot feed himself, but it didn’t stop him from becoming a social media star."},{"tr":"İtalya'nın en genç etkileyicilerinden biri oldu.","en":"He has become one of Italy’s youngest influencers."},{"tr":"Annesi Valentina, Sirio'nun Instagram sayfasını işletiyor.","en":"His mother Valentina runs Sirio’s Instagram page."},{"tr":"Engelli bir kişinin hikayesini farklı anlatmak istediğini söyledi.","en":"She said that she wanted to tell the story of a disabled person differently."},{"tr":"Valentina, oğlunun engelini kabul etmenin zor olduğunu, ancak diğer insanlardan yardım aldığı için şanslı olduğunu söyledi.","en":"Valentina said that it was difficult to accept her son’s disability, but he was lucky to get help from other people."},{"tr":"Doğru yardımla oğlu iyi bir hayat yaşamaya başladı.","en":"With the right help, her son started to live a good life."},{"tr":"Benzer durumda olan birçok aileyle tanıştı ve birbirlerine destek oldular.","en":"She met many families who were in a similar situation and they supported each other."},{"tr":"Sirio'nun ailesi, oğullarının hayatından zevk aldığını göstermenin çok önemli olduğunu anladı.","en":"Sirio’s parents understood that it was very important to show that their son enjoyed his life."},{"tr":"İnsanlar genellikle engellilere üzülürler ve engellilerin iyi bir hayat yaşayamayacaklarını düşünürler.","en":"People are usually sorry for disabled people, and they think that disabled people cannot live a good life."}]},{"id":"CK-268","no":268,"title":"Vahşi Ayılar Kasabalara Geliyor","level":2,"code":"DOG","s":[{"tr":"Japonya'daki vahşi ayılar kasaba ve köylere yaklaşmaya başladı.","en":"Wild bears in Japan started to come closer to towns and villages."},{"tr":"Nisan ve Eylül ayları arasında, son beş yılın en yüksek sayısı olan 13.500'den fazla vahşi ayı görüldü.","en":"Between April and September, there were more than 13 500 wild bear sightings, which was the highest number in the last five years."},{"tr":"Bilim adamları, ayıların insanlara yaklaşmasının daha fazla nedeni olduğunu söyledi.","en":"Scientists said that there were more reasons why bears came closer to people."},{"tr":"Bu yıl ayılar için zordu çünkü onlar için yeterli yiyecek yoktu.","en":"This year was hard for bears because there wasn’t enough food for them."},{"tr":"Ayrıca yaşlı insanların bahçelerinde meyve toplamak için yeterli enerjisi yoktu ve bu meyve ayılar için çok çekiciydi.","en":"Also, older people didn’t have enough energy to pick fruit in their gardens, and this fruit was very attractive for bears."},{"tr":"Koronavirüs bir neden daha olabilirdi çünkü insanlar dışarıda çok fazla zaman geçirmediler ve ayıların boş sokaklarda ve bahçelerde dolaşıp yiyecek aramaları iyi bir şanstı.","en":"The coronavirus could be one more reason because people didn’t spend so much time outside and it was a good chance for the bears to walk in empty streets and gardens and look for some food."},{"tr":"Bazı şirketler ayıları uzak tutmanın bir yolunu bulmaya çalışıyor.","en":"Some companies are trying to find a way to keep the bears away."},{"tr":"Bir şirket kurda benzeyen özel bir makine yaptı.","en":"A company made a special machine that looked like a wolf."},{"tr":"Yüksek sesle kükredi ve başını gerçek bir kurt gibi hareket ettirdi.","en":"It roared loudly and moved its head like a real wolf."}]},{"id":"CK-269","no":269,"title":"Tayland Protestoları","level":1,"code":"DUN","s":[{"tr":"Tayland'da halk hükümeti protesto etti.","en":"People in Thailand protested against the government."},{"tr":"Hareket beş ay önce başladı ve anayasayı değiştirmek istediler.","en":"The movement started five months ago and they wanted to change the constitution."},{"tr":"Ayrıca başbakanın işini bırakmasını da istediler.","en":"They also wanted the prime minister to leave his job."},{"tr":"Tayland başbakanı ordunun yardımıyla 2014 yılında iktidara geldi.","en":"The Thai prime minister got to power in 2014 with the help of the military."},{"tr":"Protestolar sırasında polis insanlara ateş açtı ve en az 50 kişiyi yaraladı.","en":"During the protests, police fired at people, and they injured at least 50 of them."},{"tr":"Polis ayrıca biber gazı ve tazyikli su kullandı ve protestocular tazyikli sulardan korunmak için büyük havuz ördekleri kullandı.","en":"Police also used tear gas and water cannons, and protesters used big pool ducks to protect against the water cannons."},{"tr":"Sarı ördekler protestoların sembolü oldu.","en":"The yellow ducks became a symbol of protests."},{"tr":"Geçen hafta Bangkok'ta binlerce insan toplandı.","en":"Last week, thousands of people gathered in Bangkok."},{"tr":"Polis şiddetini protesto ettiler.","en":"They protested against police violence."},{"tr":"Polis merkezinin önünde buluştular ve binaya zarar vermeye çalıştılar.","en":"They met outside the police headquarters and they tried to damage the building."}]},{"id":"CK-270","no":270,"title":"Fil Kurtarıldı","level":1,"code":"DOG","s":[{"tr":"Bir fil, birkaç gün boyunca bir Hintli köyünün çevresindeki ormanda dolaşıyordu.","en":"An elephant was roaming in a forest around an Indian village for several days."},{"tr":"Bir gece hayvan bir çiftliğin kuyusuna düşmüş.","en":"One night, the animal fell into a farm well"},{"tr":"Çiftçi, gece hayvanın ağladığını duyunca kurtarma servislerini aradı.","en":"When the farmer heard the animal cry in the night, he called rescue services."},{"tr":"Kuyu yaklaşık 17 metre derinliğindeydi ve fili çıkarmak kolay olmadı.","en":"The well was about 17 meters deep, and it wasn’t easy to get the elephant out."},{"tr":"Kurtarma ekipleri, onu beslemek için filin üzerine hindistan cevizi ağacı yaprakları attı.","en":"Rescuers threw coconut tree leaves to elephant to feed her."},{"tr":"Şans eseri, kuyuda fazla su yoktu ama yine de suyu çıkarmak gerekiyordu.","en":"Luckily, there wasn’t much water in the well, but it was still necessary to pull the water out."},{"tr":"Su çıkınca bir veteriner hayvanı uyuttu.","en":"When the water was out, a veterinarian made the animal fall asleep."},{"tr":"Kurtarma ekipleri uyuyan fili çıkarmak için kamyonlar ve vinçler kullandı.","en":"Rescuers used trucks and cranes to pull the sleeping elephant out."},{"tr":"Hayvanı kurtarmak neredeyse 14 saat sürdü.","en":"It took almost 14 hours to rescue the animal."},{"tr":"Fil uyandığında iyi görünüyordu, bu yüzden kurtarıcılar onu ormana bıraktı.","en":"When the elephant woke up, she seemed well, so rescuers released her into the forest."}]},{"id":"CK-271","no":271,"title":"Iota fırtınası","level":3,"code":"DOG","s":[{"tr":"Storm Iota Orta Amerika'yı vurdu ve ciddi hasara neden oldu.","en":"Storm Iota hit Central America and it caused serious damage."},{"tr":"Iota, 2020'nin en güçlü fırtınasıydı ve bilim adamları, Eta Kasırgası'nın sadece birkaç hafta önce vurduğu aynı bölgeyi vuracağını tahmin ettiler.","en":"Iota was the most powerful storm of 2020 and scientists predicted that it would hit the same area that Hurricane Eta hit only a few weeks before."},{"tr":"Iota, saatte 250 km'lik kuvvetli rüzgarlar getirdi ve büyük dalgalar kıyı şeridine zarar verdi.","en":"Iota brought strong winds of 250 kmph and big waves damaged the coastline."},{"tr":"Nikaragua'da büyük bir karaya çıktı ve Karayipler'deki San Andrés adasındaki yolları tahrip etti.","en":"It made big landfall in Nicaragua and it destroyed roads on the Caribbean island of San Andres."},{"tr":"Adada birçok kişi evlerini terk etmek zorunda kaldı ve yetkililer bir hastaneden hastaları tahliye etti.","en":"Many people had to leave their homes on the island, and officials evacuated patients from a hospital."},{"tr":"İki kişi öldü, altı kişi yaralandı ve birçok kişi kayboldu.","en":"Two people died, six people had injuries, and many people went missing."},{"tr":"Bilim adamları, Iota'nın Orta Amerika'nın büyük bölgelerinde sellere ve toprak kaymalarına neden olacağından endişe ediyorlar.","en":"Scientists worry that Iota will cause floods and landslides in the large parts of Central America."}]},{"id":"CK-272","no":272,"title":"İnsanlar Evde COVID-19 Testi Olabilir","level":1,"code":"SAG","s":[{"tr":"Yeni ilaçları onaylayan ABD kuruluşu ilk COVID-19 test kitini onayladı.","en":"The US organization that approves new drugs has approved the first Covid-19 testing kit."},{"tr":"İnsanlar kiti evde kullanacak ve kendilerini COVID-19 için test edecekler.","en":"People will use the kit at home, and they will test themselves for Covid-19."},{"tr":"İnsanlar swab adı verilen özel bir çubuk kullanacaklar.","en":"People will use a special stick that is called a swab."},{"tr":"Çubuğun ucunda bir parça pamuk var ve insanlar sopayı burunlarına sokacaklar.","en":"There is a piece of cotton at the end of the stick and people will put the stick in their noses."},{"tr":"Sonucu 30 dakika içinde öğrenecekler.","en":"They will know the result within 30 minutes."},{"tr":"Test yaklaşık 50 dolara mal olacak ve insanlar 2021 Baharında eczanelerden satın alabilecekler.","en":"The test will cost around $50, and people will be able to buy it in drugstores in Spring 2021."},{"tr":"ABD'de birçok yeni COVID-19 vakası görüldü.","en":"There have been many new cases of Covid-19 in the US."},{"tr":"Bazı şirketler yakında bir COVID-19 aşısı yapacaklarını söyledi.","en":"Some companies said that they would make a Covid-19 vaccine soon."},{"tr":"Ancak yine de mümkün olduğunca çok insanı test etmek çok önemlidir.","en":"However, it is still very important to test as many people as possible."},{"tr":"İnsanlar testi satın alırsa, test edilmek için uzun kuyruklarda beklemek ve sonuç için birkaç gün beklemek zorunda kalmayacaklar.","en":"If people buy the test, they won’t have to stand in long lines to get tested and wait several days for a result."}]},{"id":"CK-273","no":273,"title":"Bir Okul Yeni Bir Yere Taşınıyor","level":2,"code":"BLT","s":[{"tr":"Çin'in Şanghay kentindeki mühendisler, bir okulu yeni bir yere taşımak zorunda kaldı.","en":"Engineers in Shanghai, China, had to move a school to a new place."},{"tr":"Bunun nedeni, aynı yerde bir iş binasının olmasıydı.","en":"The reason was that there would be a business building in the same place."},{"tr":"Okul 85 yaşındaydı ve mühendisler onu yok etmek istemediler.","en":"The school was 85 years old and engineers didn’t want to destroy it."},{"tr":"Bu nedenle, 62 metre uzağa taşımaya karar verdiler.","en":"Therefore, they decided to move it 62 meters away."},{"tr":"Onlar için zor bir görevdi ama başardılar.","en":"It was a difficult task for them, but they succeeded."},{"tr":"Binanın altına 200 özel robotik bacak yerleştirdiler ve bacaklar onu yerden kaldırdı.","en":"They installed 200 special robotic legs under the building, and the legs lifted it off the ground."},{"tr":"Yukarı ve aşağı hareket eden bacakları kontrol ettiler ve bacaklar binayı döndürdü.","en":"They controlled the legs that moved up and down, and the legs rotated the building."},{"tr":"Binanın yeni yerine taşınması 18 gün sürdü.","en":"It lasted 18 days to move the building to its new location."},{"tr":"Şangay'daki mühendisler, robotik ayaklar yardımıyla bir binayı ilk kez taşıdılar.","en":"Engineers in Shanghai moved a building with the help of robotic legs for the first time."}]},{"id":"CK-274","no":274,"title":"Stonehenge Tüneli","level":2,"code":"TAR","s":[{"tr":"İngiliz hükümeti, Stonehenge altında 2 milyar dolarlık bir tüneli onayladı.","en":"The British government approved a $2 billion tunnel under Stonehenge."},{"tr":"Stonehenge, İngiltere'nin güneybatısında, insanların 5.000 yıldan daha uzun bir süre önce inşa ettiği tarih öncesi bir taş anıt.","en":"Stonehenge is a prehistoric stone monument in southwest England that people built more than 5000 years ago."},{"tr":"1986'dan beri Stonehenge, dünya mirası siteleri listesinde yer almaktadır.","en":"Since 1986, Stonehenge has been on the list of world heritage sites."},{"tr":"Yetkililerin Stonehenge'in altına bir tünel inşa etmeye karar vermelerinin nedeni, bölgedeki trafikle uğraşmaktı.","en":"The reason why officials decided to build a tunnel under Stonehenge was to deal with traffic in the area."},{"tr":"Stonehenge yakınlarında daralan çok yoğun bir yol var ve genellikle trafiği durduruyor.","en":"There is a very busy road near Stonehenge which becomes narrow, and it usually stops traffic."},{"tr":"Tünel yaklaşık üç kilometre uzunluğunda olacak ve yoldan yaklaşık 50 metre uzakta olacak.","en":"The tunnel will be about three kilometers long, and it will be about 50 meters farther away than the road."},{"tr":"Birçok kişi tüneli protesto ediyor.","en":"Many people protest against the tunnel."},{"tr":"Çevrelerindeki taşları ve manzarayı yok edeceğinden korkuyorlar.","en":"They are afraid that it will destroy the stones and landscape around them."}]},{"id":"CK-275","no":275,"title":"Alaska Petrolü İçin Mücadele","level":3,"code":"DUN","s":[{"tr":"ABD başkanı Donald Trump, Alaska'da sondaj haklarını satmak istiyor ve bunu yeni başkan Joe Biden devralmadan önce hızla yapmak istiyor.","en":"The US president, Donald Trump, wants to sell drilling rights in Alaska, and he wants to do it fast before the new president, Joe Biden, takes over."},{"tr":"Uzmanlar, Alaska'da 4,3 ila 11,8 milyar varil petrol olabileceğini söyledi, ancak çevreciler, Alaska'nın ülkenin son gerçek vahşi yerlerinden biri olduğunu iddia ediyor.","en":"Experts said that there could be between 4,3 and 11,8 billion barrels of oil in Alaska, but environmentalists argue that Alaska is one of the country’s last truly wild places."},{"tr":"Büyük bir kutup ayısı, ren geyiği ve kuş popülasyonu var.","en":"There is a large population of polar bears, reindeers, and birds."},{"tr":"Yeni seçilen başkan Joe Biden, Alaska'daki tüm petrol aramalarını durduracağına söz verdi ve bölgeyi koruyacağını söyledi.","en":"Joe Biden who was just elected promised that he would stop all oil exploration in Alaska, and he said that he would protect the area."},{"tr":"Ancak Donald Trump, Joe Biden başkan olmadan önce sondaj haklarını satarsa, Biden'ın durumu değiştirmesi çok zor olabilir.","en":"However, if Donald Trump sells the drilling rights before Joe Biden becomes the president, it can be very difficult for Biden to change the situation."}]},{"id":"CK-276","no":276,"title":"Etiyopya Çatışması","level":2,"code":"DUN","s":[{"tr":"Etiyopya'nın Tigray Eyaletinde askeri bir çatışma çıktı.","en":"There was a military conflict in Ethiopia’s Tigray state."},{"tr":"Etiyopya'nın askerleri yerel güçlerle savaştı ve kazandılar.","en":"Ethiopia’s soldiers fought with local forces and the won."},{"tr":"Etiyopya başbakanı, kuvvetlerin yüzlerce insanı öldürdüğünü söyledi.","en":"Ethiopia’s prime minister said that the forces killed hundreds of people."},{"tr":"Çok şiddetliydi ve birçok insanın Sudan'a kaçmasına neden oldu.","en":"It was very violent and it made many people run away to Sudan."},{"tr":"Tanıklar, ölümlerden yerel güçlerin sorumlu olduğunu söyledi, ancak askerler bunun doğru olmadığını söyledi.","en":"Witnesses said that local forces were responsible for the deaths, but the soldiers said that it wasn’t true."},{"tr":"Gerçekte ne olduğunu bulmak mümkün değildi.","en":"It wasn’t possible to find out what really happened."},{"tr":"Etiyopya hükümeti Tigray Eyaletine yeni bir başkan atadı.","en":"Ethiopia’s government appointed a new president of Tigray State."},{"tr":"Hükümet, geçmişteki cumhurbaşkanını terörizm ve ülke için kötü olan diğer eylemlerle suçladı.","en":"The government accused the past president of terrorism and other acts that were bad for the country."}]},{"id":"CK-277","no":277,"title":"PlayStation 5","level":3,"code":"BLT","s":[{"tr":"Japon şirketi Sony, geçtiğimiz hafta yeni PlayStation 5'i satmaya başladığında tüm PlayStation hayranlarını mutlu etti.","en":"The Japanese company Sony made all PlayStation fans happy when it started to sell its new PlayStation 5."},{"tr":"Yeni konsol, Sony'nin video oyunları dünyasını tamamen değiştiren PlayStation 4'ü satmaya başlamasından yedi yıl sonra geldi.","en":"The new console came seven years since Sony started to sell the PlayStation 4, which completely changed the the world of video games."},{"tr":"Koronavirüs salgını sırasında video oyunlarında bir patlama yaşandı ve Sony, yeni PlayStation 5'in şirkete yıllarca para kazandıracağını umuyor.","en":"During the coronavirus pandemic, there has been a boom in video gaming and Sony hopes that the new PlayStation 5 will bring the company money for many years."},{"tr":"PlayStation 5'in fiyatı, Microsoft'un bu ay da satmaya başladığı Microsoft'un Xbox'ı ile aynı fiyat olan 500 dolar.","en":"The price of PlayStation 5 is $500 which is the same price as Microsoft Xbox that Microsoft started to sell this month, too."},{"tr":"Uzmanlar PlayStation 5 ve Xbox'ı karşılaştırdı.","en":"Experts compared the PlayStation 5 and the Xbox."},{"tr":"PlayStation 5'in daha etkileyici ve farklı titreşimler yaratan bir denetleyiciye sahip olduğunu söylüyorlar.","en":"They say that the PlayStation 5 has a more impressive and controller which makes different vibrations."},{"tr":"Öte yandan, yeni Xbox'ın tasarımı daha çekici.","en":"On the other hand, the design of the new Xbox is more attractive."}]},{"id":"CK-278","no":278,"title":"Kardeşler 30 Yıl Sonra Buluşuyor","level":1,"code":"TOP","s":[{"tr":"Bolivya'da bir yanardağ patladığında iki kız kardeş üç ve dokuz yaşındaydı.","en":"Two sisters were ages three and nine when a volcano in Bolivia erupted."},{"tr":"1985'teki trajedi 20.000'den fazla insanı öldürdü.","en":"The tragedy in 1985 killed more than 20000 people."},{"tr":"Volkan, kız kardeşlerin memleketini yok etti ve evlatlık verildiler.","en":"The volcano destroyed the sisters’ hometown and they were put up for adoption."},{"tr":"Bu şekilde ayrıldılar.","en":"This is how they became separated."},{"tr":"Otuz yıl sonra, kız kardeşlerden biri bir Facebook videosunda ailesini sordu.","en":"Thirty years later, one of the sisters asked about her family on a Facebook video."},{"tr":"Diğer kız kardeş videoyu gördü ve kız kardeşini buldu.","en":"The other sister saw the video and found her sister."},{"tr":"Şimdi, birbirlerinin otuz yılını yakalamak zorundalar.","en":"Now, they have to catch up with thirty years of each other’s lives."},{"tr":"Ayrıca ebeveynlerine ne olduğunu öğrenmeye çalışıyorlar.","en":"They are also trying to find out what happened to their parents."},{"tr":"Şimdiye kadar başarılı olamadılar.","en":"So far, they haven’t been successful."}]},{"id":"CK-279","no":279,"title":"Mısırlı Adam Kadın Oluyor","level":1,"code":"POR","s":[{"tr":"Farida Aly Mısır'da doğdu.","en":"Farida Aly was born in Egypt."},{"tr":"Erkek olarak doğdu, ama her zaman bir kadın gibi hissetti.","en":"She was born as a man, but she always felt like a woman."},{"tr":"Onun için zordu çünkü duyguları hakkında kimseyle konuşamıyordu.","en":"It was difficult for her because she couldn’t talk to anybody about her feelings."},{"tr":"Farida yıllarca kan ve kişilik testleri geçirdi.","en":"Farida spent many years undergoing blood and personality tests."},{"tr":"Doktorlar beynini taradılar ve Farida'nın zihinsel sorunları olduğunu söylediler.","en":"Doctors scanned her brain, and they said that Faridahad mental problems."},{"tr":"Farida kadın olmak istedi ve cinsiyetini değiştirecek bir operasyon geçirmeye karar verdi.","en":"Farida wanted to become a woman, and she decided to undergo an operation that would change her gender."},{"tr":"Mısır'da cinsiyet değiştirmek yasaldır, ancak Mısır muhafazakar bir Müslüman ülkedir.","en":"In Egypt, it is legal to change gender, but Egypt is a conservative Muslim country."},{"tr":"İnsanların yeni şeyleri sevmediği ve kötü bulduğu anlamına gelir.","en":"It means that people don’t like new things and they find them bad."},{"tr":"Farida işini kaybetti ve ailesini terk etmek zorunda kaldı.","en":"Farida lost her job and she had to leave her family."},{"tr":"İnsanların geçmişini bilmediği başka bir şehre taşındı.","en":"She moved to another city where people didn’t know her past."},{"tr":"Şimdi, Farida mahalleden çocuklara ders veriyor ve bir gün kendi çocuğuna sahip olmayı umuyor.","en":"Now, Farida teaches children from the neighborhood and she hopes to have her own child one day."}]},{"id":"CK-280","no":280,"title":"Amerika’nın Sıradaki First Lady'si","level":2,"code":"POR","s":[{"tr":"Dr. Jill Biden, yeni ABD başkanı Joe Biden'ın karısıdır.","en":"Dr. Jill Biden is the the wife of the new US president, Joe Biden."},{"tr":"Jill Biden 69 yaşında ve dört diplomalı üniversite profesörü.","en":"Jill Biden is 69 years old and she is a college professor with four degrees."},{"tr":"Joe ve Jill Biden tanışmadan önce Joe Biden başka bir kadınla evliydi.","en":"Before Joe and Jill Biden met, Joe Biden was married to another woman."},{"tr":"Üç çocukları, iki erkekleri ve bir kızları vardı.","en":"They had three children, two boys, and a girl."},{"tr":"Ancak Biden'in karısı ve bir yaşındaki kızı bir araba kazasında öldü.","en":"However, Biden’s wife and a one-year-old daughter died in a car crash."},{"tr":"Böyle trajik bir olaydan sonra Jill'in Joe'nun ailesinin bir parçası olması çok zordu.","en":"It was very difficult for Jill to become a part of Joe’s family after such a tragic event."},{"tr":"Joe ve Jill 1977'de evlendiler ve 1981'de kızları Ashley doğdu.","en":"Joe and Jill got married in 1977, and in 1981, their daughter Ashley was born."},{"tr":"Joe Biden, ABD başkanı Barack Obama'nın başkan yardımcısıydı ve 2011'de Jill Biden ve Michelle Obama askeri ailelere yardım etmeye başladı.","en":"Joe Biden was the vice president to the US president Barack Obama, and in 2011, Jill Biden and Michelle Obama started to help military families."},{"tr":"Jill Biden bu işe devam etmeyi planlıyor ve öğretmenlik mesleğini sürdürmek istiyor.","en":"Jill Biden plans to continue this work, and she wants to keep her job as a teacher."}]},{"id":"CK-281","no":281,"title":"İnsanlar Dünyanın En Derin Noktasına Ulaşır","level":1,"code":"BLT","s":[{"tr":"Çin'in derin deniz denizaltısı dünya rekoru olan 10.000 metre derinliğe ulaştı.","en":"China’s deep-sea submarine reached the world’s record depth of 10000 meters."},{"tr":"İnsanlı denizaltı, Mariana Çukuru'nun dibine, dünyanın en derin noktasına doğru gidiyordu.","en":"The manned submarine was on its way to the deepest point on Earth, the bottom of the Mariana Trench."},{"tr":"10.971 metre derinliğindedir ve batı Pasifik Okyanusunda yer alır.","en":"It is 10971 meters deep and it is located in the western Paciic Ocean."},{"tr":"Denizaltında üç adam var ve okyanus tabanını keşfedecekler.","en":"There are three men on the submarine, and they will explore the ocean floor."},{"tr":"Ekip, numune almak için robotik eller kullanıyor.","en":"The crew uses the robotic hands to get samples."},{"tr":"Okyanusun tepesine canlı yayın yapan yüksek kaliteli kameralar kullanıyorlar.","en":"They use high-quality cameras that create a live stream to the top of the ocean."},{"tr":"Denizaltının tamamen karanlık olan yerlerde görmeyi mümkün kılan çok parlak ışıkları var.","en":"The submarine has very bright lights that make it possible to see in places that are completely dark."},{"tr":"Bu derinlikte ışık yoktur, bu nedenle denizaltı onu görünür kılan yeşil bir renktir.","en":"There isn’t any light at this depth, so the submarine is a green color which makes it visible."}]},{"id":"CK-282","no":282,"title":"Bir Tema Parkı Değişiyor","level":3,"code":"DUN","s":[{"tr":"2020'de Hong Kong'daki bir tema parkı, koronavirüs nedeniyle kapanmak zorunda kaldı.","en":"In 2020, a theme park in Hong Kong had to close due to the coronavirus."},{"tr":"Yıl boyunca park 200 günden fazla kapalıydı.","en":"For the year, the park was closed for more than 200 days."},{"tr":"Şimdi tekrar açık ama park sahiplerinin ziyaretçi sayısını %25 sınırlaması gerekiyor.","en":"Now, it is open again, but the park owners must limit the number of visitors by 25%."},{"tr":"Parkın başkanı, mevcut durumun parkın ziyaretçileri çekmenin yeni yollarını bulması için bir şans olduğunu söyledi.","en":"The chairman of the park said that the current situation was a chance for the park to find new ways to attract visitors."},{"tr":"Parkın sahilde olması ve bol yeşillik olması, kamp yapma şekli olan glamping gibi aktivitelerin yapılmasını mümkün kılıyor, ancak daha rahat.","en":"The park is located on the coast and there is a lot of greenery, which makes it possible to do activities such as glamping, which is a form of camping, but it is more comfortable."},{"tr":"Ziyaretçiler ayrıca bir akvaryumda yoga yapabilirler.","en":"Visitors can also do yoga in an aquarium."},{"tr":"Turistler artık Hong Kong'a seyahat edemiyor, bu yüzden parkı yerel halk için daha çekici hale getirmek gerekiyor.","en":"Tourists cannot travel to Hong Kong now, so it is necessary to make the park more attractive for local people."},{"tr":"Başkan, koronavirüs başlamadan önceki duruma dönmenin yıllar alabileceğini söyledi.","en":"The chairman said that it could take years to return to the situation before the coronavirus started."}]},{"id":"CK-283","no":283,"title":"Yeni ABD Başkanı","level":2,"code":"DUN","s":[{"tr":"Demokrat Joe Biden, Donald Trump ile bir savaşın galibi oldu ve yeni ABD başkanı oldu.","en":"Democrat Joe Biden became the winner of a battle with Donald Trump, he became the new US president."},{"tr":"Tüm oyları saymak birkaç gün sürdü ve başlangıçta Donald Trump yeniden kazanacak gibi görünüyordu.","en":"It took several days to count all the votes, and in the beginning, it seemed that Donald Trump would win again."},{"tr":"Ancak durum değişti ve Biden öne geçti.","en":"However, the situation changed and Biden took the lead."},{"tr":"Biden için iyi haber kazandığı Pennsylvania'dan geldi ve Trump'ın onu yenemeyeceği açıktı.","en":"Good news for Biden came from Pennsylvania, where he won, it was clear that Trump couldn’t beat him."},{"tr":"Biden'in destekçileri ABD'nin dört bir yanında sokaklarda kutlama yapmaya başladı, ancak Trump'ın destekçileri hiç de mutlu değildi.","en":"Biden’s supporters started to celebrate in streets across the Us, but Trump’s supporters weren’t happy at all."},{"tr":"TV ağları Biden'ın kazanan olduğunu söylediği sırada, Trump golf oynuyordu.","en":"At the time when TV networks said that Biden was the winner, Trump was playing golf."}]},{"id":"CK-284","no":284,"title":"Rusya Devlet Başkanı Sağlıklı mı","level":2,"code":"DUN","s":[{"tr":"Rusya Devlet Başkanı Vladimir Putin'in gelecek yıl görevine son vereceği iddiaları var.","en":"There are claims that the Russian president Vladimir Putin will go to end his job next year."},{"tr":"Bazıları Rus liderin Parkinson hastalığından muzdarip olduğuna inanıyor, ancak o bunun doğru olmadığını söyledi.","en":"Some people believe that the Russian leader is suffering from Parkinson’s disease, but he said that it isn’t true."},{"tr":"Putin 68 yaşında ve insanların onun sağlıklı olmadığını düşünmeleri ilk değil.","en":"Putin is 68 years old and it isn’t the first time when people think that he isn’t healthy."},{"tr":"Bir video, Putin'in masasında oturduğunu gösteriyordu, ancak bacakları titriyordu ve bir sandalyeye sıkıca tutuyordu.","en":"A video showed Putin sitting at his desk, but his legs were shaking and he was holding tight to a chair."},{"tr":"Bu, birçok insanı Putin'in hasta olduğuna inandırdı.","en":"This made many people believe that Putin was ill."},{"tr":"Son zamanlarda Putin bir buzkıran üzerinde bir törene katıldı ve sağlıklı görünüyordu.","en":"Recently, Putin took part in a ceremony on an icebreaker and he seemed healthy."},{"tr":"Putin, işini bitirdikten sonra kendisine yasal dokunulmazlık verecek yeni bir yasa çıkardı.","en":"Putin introduced a new law that will give him legal immunity after he ends his job."},{"tr":"Bazıları için bu, Putin'in emekli olmayı planladığının bir işaretidir.","en":"For some people, this is a sign that Putin is planning to retire."}]},{"id":"CK-285","no":285,"title":"Böceklerden Evcil Hayvan Maması","level":2,"code":"DOG","s":[{"tr":"İsviçreli şirket Nestle bu ay yeni evcil hayvan maması ürünlerini tanıtıyor.","en":"The Swiss company Nestle is introducing new pet food products this month."},{"tr":"Nestle, kullanmaları gereken et miktarını düşürdüğü için sinek larvalarından özel bir köpek maması türü yapmaya başlıyor.","en":"Nestle is starting to make a special type of dog food from fly larvae as it lowers how much meat they need to use."},{"tr":"Nestle, böcek bazlı yiyeceklerin daha çevre dostu olduğuna inanıyor.","en":"Nestle believes that bug-based food is more environmentally friendly."},{"tr":"Daha küçük markalar ürünlerinde böcek kullanmaya başladı, ancak artık talep, insanların süpermarketlerde satın alabilecekleri daha fazla ürünü yapacak kadar güçlü görünüyor.","en":"Smaller brands started to use insects in their products, but now it seems that demand is strong enough to make more products that people will be able to buy in supermarkets."},{"tr":"Bu yıl insanlar evde evcil hayvanlarıyla daha fazla zaman geçirdiler.","en":"This year, people spent more time at home with their pets."},{"tr":"Daha yakın arkadaş oldular ve insanlar evcil hayvan mamasına daha fazla para harcamaktan çekinmiyorlar.","en":"They became closer friends and people don’t mind spending more money on pet food."}]},{"id":"CK-286","no":286,"title":"Bir Balina Kadınları Yemek İstiyor","level":1,"code":"DOG","s":[{"tr":"Bir grup kanocu sabahlarını ABD'nin Kaliforniya sularında geçirdi.","en":"A group of kayakers spent their morning in the waters of California, US."},{"tr":"Sabah, beklenmedik bir şey olana kadar sakin görünüyordu.","en":"The morning seemed calm until something unexpected happened."},{"tr":"İki kayakçı, yaklaşık 9 metre uzaklıktaki balinaları izliyordu.","en":"Two kayakers were watching whales that were about 9 meters away."},{"tr":"Aniden sudan bir balina çıktı, ağzını açtı ve kadınları yuttu.","en":"Suddenly, a whale came out of the water, and opened its mouth, and swallowed the women."},{"tr":"Neyse ki balina kısa sürede ağzını açtı ve iki kadın kaçmayı başardı.","en":"Luckily, the whale soon opened its mouth and the two women were able to escape."},{"tr":"Kadınlar yüzeye çıktığında, arkadaşları yardıma geldi ve onları sahile götürdüler.","en":"When the women got up to the surface, their friends came to help, and they got them to the beach."},{"tr":"Balinalar çok güçlü, ancak kadınlarda herhangi bir yaralanma olmadı.","en":"The whales are very strong, but the women didn’t have any injuries."},{"tr":"Araştırmacılar hayvanı bulmaya çalışıyor.","en":"Researchers are trying to find the animal."},{"tr":"Bunun da zarar görmediğinden emin olmak istiyorlar.","en":"They want to make sure that it didn’t also get hurt."}]},{"id":"CK-287","no":287,"title":"Yeni Alzheimer İlacı","level":2,"code":"SAG","s":[{"tr":"Bir ABD şirketi, Alzheimer hastalığını yavaşlatabilecek yeni bir ilacı test etti.","en":"A US company tested a new drug that could slow Alzheimer’s disease."},{"tr":"İlaç hastalığı durdurmayacak, ancak semptomlarını yavaşlatacaktı.","en":"The drug would not stop the disease, but it would slow its symptoms."},{"tr":"Çarşamba günü şirket, ilacın etkili olduğuna dair güçlü bilgiler olduğunu söyledi.","en":"On Wednesday, the company said that there was strong information that the drug was effective."},{"tr":"Ancak bazı insanlar buna inanmadı, çünkü geçmişte ilacın iki testinden biri başarısız oldu.","en":"However, some people didn’t believe it because one of two tests of the drug failed in the past."},{"tr":"Yetkililer ilacı ABD'de kullanım için onaylarsa, on yıl içinde yeni bir Alzheimer ilacı olacak.","en":"If authorities approve the drug for use in the US, it will be a new Alzheimer’s drug in ten years."},{"tr":"Alzheimer hastalığı bir beyin hastalığıdır, yani beyni ve sinirleri etkiler.","en":"Alzheimer’s disease is a brain disease, which affects the brain and nerves."},{"tr":"Genellikle 65 yaş ve üzeri kişileri etkiler.","en":"It affects people who are 65 years old and more."},{"tr":"Hastalık, hafıza, planlama veya problem çözme sorunlarına ve olağan görevleri yerine getirmede zorluklara yol açar.","en":"The disease leads to problems with memory, planning, or solving problems and difficulty doing usual tasks."}]},{"id":"CK-288","no":288,"title":"Türkiye Depremi","level":1,"code":"DUN","s":[{"tr":"Geçen sene Türkiye'nin İzmir kentinde bir deprem meydana geldi.","en":"Last year, an earthquake hit the Turkish city of İzmir."},{"tr":"Yetkililer, depremin büyüklüğünün 6,6 ile 7 arasında olduğunu söyledi.","en":"Officials said that the earthquake was a magnitude between 6,6 and 7."},{"tr":"Şehirde birkaç bina çöktü ve en az 80 kişi öldü.","en":"Several building collapsed in th city, and at least 80 people died."},{"tr":"Binlerce insan bütün hafta sonu çalıştı ve kayıp insanları enkazdan kurtarmaya çalıştı.","en":"Thousands of people worked all weekend and they tried to rescue missing people from the rubble."},{"tr":"Molozları uzaklaştırmak için kazıcılar kullandılar.","en":"They used diggers to put the rubble away."},{"tr":"Enkaz altında 33 saat kalan 70 yaşındaki adamı kurtardılar.","en":"They saved a 70-year-old man who stayed in the rubble for 33 hours."},{"tr":"Ayrıca 14 yaşındaki bir kızı da kurtardılar ve bir ambulans kızı götürürken tüm kurtarma görevlileri tezahürat yapıp alkışladı.","en":"They also rescued a 14-year-old girl, and all rescue workers cheered and clapped while an ambulance was taking the girl away."},{"tr":"Yunanistan'ın Samos adasında meydana gelen depremde iki genç hayatını kaybetti.","en":"Two teenagers died in the earthquake that happened on the Greek island of Samos."}]},{"id":"CK-289","no":289,"title":"Çin-Avustralya Ticaret Savaşı","level":2,"code":"DUN","s":[{"tr":"2018'de Avustralya, Çinli Huawei şirketinin 5G ağı için ekipman sağlamamasına karar verdi.","en":"In 2018, Australia decided that the Chinese company Huawei wouldn’t provide equipment for the 5G network."},{"tr":"Avustralya, gerekçenin ulusal güvenlik olduğunu söyledi.","en":"Australia said that the reason was national security."},{"tr":"Bu yıl Avustralya, koronavirüsün nereden geldiğinin araştırılması gerektiğini söyledi.","en":"This year, Australia said that it was necessary to investigate where the coronavirus came from."},{"tr":"Bu Çin'i çok kızdırdı.","en":"This made China very angry."},{"tr":"Geçen ay Huawei, bir Avustralya rugby takımına para vermeyeceğini duyurmuştu.","en":"Last month, Huawei announced that it wouldn’t give money to an Australian rugby team."},{"tr":"Ayrıca Çin, et ve şarap gibi bazı Avustralya ürünlerinin ithalatını durdurdu.","en":"China also stopped imports of some Australian products, for example, meat and wine."},{"tr":"Çin, Avustralya'yı 5G anlaşmasını yapmaya zorlamaya çalışıyor.","en":"China is trying to push Australia to make the 5G deal."},{"tr":"Ancak Çin'in dikkat ettiği bir şey var.","en":"However, there is one thing that China cares about."},{"tr":"Çin endüstrisi buna bağlı olduğu için ülke demir tedarikini durdurmamalı.","en":"The country must not stop supplies of iron because the China industry depends on it."}]},{"id":"CK-290","no":290,"title":"Balina Bir Treni Kurtarır","level":2,"code":"DOG","s":[{"tr":"Pazartesi günü, bir metro treni Hollanda'nın Rotterdam kentindeki son durağın bariyerlerinden geçti.","en":"On Monday, a metro train drove through the barriers of the final stop in Rotterdam, the Netherhands."},{"tr":"Daha önce tüm yolcular treni istasyonda bıraktı ve tren bir park alanına devam etti.","en":"All passengers left the train at the station before, and the train continued to a parking area."},{"tr":"Ama durmadı ve bir balina kuyruğu heykeline çarptı.","en":"However, it didn’t stop, and it hit a sculpture of a whale’s tail."},{"tr":"Hollandalı bir mimar, 20 yıl önce balina kuyruklarından iki heykel yaptı.","en":"A Dutch architect made two sculptures of whale tails 20 years ago."},{"tr":"On metre yüksekliğindeydiler ve plastikten yapılmışlardı.","en":"They were ten meters high, and they were made from plastic."},{"tr":"Kuyruklardan birinin üzerinde oturan treni gören mimar, trenin heykele zarar vermemesine şaşırmış.","en":"When the architect saw the train sitting on one of the tails, he was surprised that the train didn’t damage the sculpture."},{"tr":"Heykeller, trenin kaldırılmasını zorlaştıran bir göletin yanındaki bir parkın içindeydi.","en":"The sculptures were in a park by a pond which made it difficult to be removed the train."}]},{"id":"CK-291","no":291,"title":"Sean Connery Öldü","level":2,"code":"POR","s":[{"tr":"İskoç film yıldızı Sean Connery, 90 yaşında öldü.","en":"Scottish movie star Sean Connery died at the age of 90."},{"tr":"Connery'nin ailesi çok fakirdi ve İskoç başkenti Edinburgh'un kenar mahallelerinde yaşıyorlardı.","en":"Connery’s family was very poor, and they lived in the slums in the Scottish capital, Edinburgh."},{"tr":"Connery’nin, vücut geliştirme hobisi oyunculuk kariyerini başlatana kadar iyi bir işi yoktu.","en":"Connery didn’t have a good job until his bodybuilding hobby started his acting career."},{"tr":"Connery, onu uluslararası bir yıldız yapan büyüleyici İngiliz ajan James Bond'u canlandırdı.","en":"Connery played the charming British agent James Bond, who made him an international star."},{"tr":"Sean Connery'den sonra Bond'u oynayan tüm oyuncular onun belirlediği yüksek standardı yakalamaya çalıştı.","en":"All the actors who played Bond after Sean Connery tried to meet the high standard that he set."},{"tr":"Connery, James Bond dışında birçok ilginç rol oynadı.","en":"Connery played many other interesting roles apart from James Bond."},{"tr":"1987'de 'Dokunulmazlar'daki rolüyle ödül kazandı.","en":"In 1987, he won an award for his role in “The Untouchables”."},{"tr":"2000 yılında Kraliçe II. Elizabeth ona şövalye unvanı verdi.","en":"In 2000, Queen Elizabeth II awarded him with the title of knight."},{"tr":"Connery, İskoçya'nın Britanya'nın bağımsızlığını destekledi.","en":"Connery supported the Scottish independence of Britain."}]},{"id":"CK-292","no":292,"title":"Kutup Ayısı Nora","level":1,"code":"DOG","s":[{"tr":"ABD'nin Ohio eyaletindeki bir hayvanat bahçesi bir kutup ayısının videosunu çekti. Videonun başında kutup ayısı sadece 7 günlük.","en":"A zoo in Ohio, US made a video of a polar bear. At the beginning of the video, the polar bear is only 7 days old."},{"tr":"Videonun sonunda 83 günlük.","en":"At the end of the video, she is 83 days old."},{"tr":"Yeni doğmuş bir bebekten kabarık küçük bir ayının nasıl büyüdüğünü görebilirsiniz.","en":"You can see how she grows from a newborn to a fluffy little bear."},{"tr":"İnsanlar ayının adını seçmek için oy kullandı.","en":"People voted to choose the bear’s name."},{"tr":"Hayvanat bahçesi 115 ülkedeki hayranlarından 88.000 oy aldı.","en":"The zoo received 88000 votes from fans in 115 countries."},{"tr":"İnsanlar “Nora” adını seçti.","en":"People chose the name “Nora”."},{"tr":"Nora'nın elle büyütülmesi gerekiyordu çünkü annesi ona bakmamıştı.","en":"Nora had to be raised by hand because her mother didn’t take care of her."},{"tr":"Şimdi, o üç aylık ve bir İnternet ünlüsü.","en":"Now, she is three months old and an Internet celebrity."}]},{"id":"CK-293","no":293,"title":"Uçan araba","level":1,"code":"BLT","s":[{"tr":"Münster Üniversitesi'nden Profesör Stefan Klein uçan bir araba tasarladı.","en":"Professor Stefan Klein from the University of Münster designed a flying car."},{"tr":"Slovak şirketi KleinVision arabayı yaptı ve test etme zamanı geldi.","en":"The Slovak company made the car and it was time to test it."},{"tr":"22 Ekim'de, araba ilk uçuşunu Slovakya'daki bir havaalanında yaptı ve havada neredeyse 460 metre uçtu.","en":"On October 22, the car took its first flight at an airport in Slovakia, and it flew almost 460 meters in the air."},{"tr":"Araba, üç dakikadan daha kısa bir sürede bir yol arabasından uçan bir arabaya dönüşüyor.","en":"The car changes from a road car to a flying car in less than three minutes."},{"tr":"1.100 kilogram ağırlığında ve 200 kilogram yük taşıyabilir.","en":"It weighs 1100 kilograms, and it can carry a load of 200 kilograms."},{"tr":"1.6 litrelik bir motoru var ve durmadan yaklaşık 1.000 kilometre uçabiliyor.","en":"It has a 1,6-liter engine, and it can fly about 1000 kilometers without stopping."},{"tr":"Şirkete göre uçan araba çok uygun.","en":"According to the company, the flying car is very convenient."},{"tr":"İnsanların havaalanına seyahat etmesine gerek yok.","en":"People don’t need to travel to the airport."},{"tr":"İhtiyaç duydukları yere uçabilirler ve sonra arabayı bir otoparka park ederler.","en":"They can fly where they need and then they park the car in a car park."}]},{"id":"CK-294","no":294,"title":"Fransa Saldırısı","level":2,"code":"DUN","s":[{"tr":"Fransa'nın Nice kentinde geçen hafta bir kişi bıçakla üç kişiyi öldürdü.","en":"Last week, a man killed three people with a knife in the French city of Nice."},{"tr":"Saldırı, şehrin tarihi merkezindeki bir bazilikanın içinde meydana geldi.","en":"The attack happened inside a basilica in the historic center of the city."},{"tr":"Polis saldırganı vurdu ama öldürmedi.","en":"Police shot the attacker, but they didn’t kill him."},{"tr":"Adam kritik durumda hastaneyi boyladı.","en":"The man ended up in hospital in critical condition."},{"tr":"Polis, saldırganın Eylül ayında İtalya üzerinden Fransa'ya gelen Tunuslu 21 yaşındaki bir adam olduğunu söyledi.","en":"Police said that the attacker was a 21-year-old man from Tunisia, who came to France through Italy in September."},{"tr":"Fransa bir terör acil durum seviyesi ilan etti ve 4.000 asker okulları, kiliseleri ve diğer yerleri korumaya yardımcı olacak.","en":"France declared a terror emergency level, and 4000 soldiers will help protect schools, churches, and other places."},{"tr":"Sadece haftalar önce bir adam, bir Fransızca öğretmenini, sınıfında Hz. Muhammed'in karikatürlerini gösterdiği için öldürdü.","en":"Only weeks ago, a man killed a French teacher since he showed cartoons of the Prophet Mohammed in his class."},{"tr":"Bu, Fransa'da İslam ve ifade özgürlüğü konusundaki duyguları artırdı.","en":"This increased emotions in France over Islam and freedom of speech."}]},{"id":"CK-295","no":295,"title":"Vinç Rüzgarda Hareket Ediyor","level":2,"code":"DUN","s":[{"tr":"Zeta kasırgası ABD'nin doğu kıyılarını vurdu ve birçok ABD eyaletinde birçok soruna neden oldu.","en":"Hurricane Zeta hit the east coast of the US, and it caused many problems in many US states."},{"tr":"Kasırgadan sonra kalan kuvvetli rüzgar, New York'ta bir vincin dönmesine neden oldu.","en":"Strong winds that remained after the hurricane caused a crane to spin in New York city."},{"tr":"Salı günü vinç kontrolden çıkmaya başladı ve bu da birçok yerel insanı korkuttu.","en":"On Tuesday, the crane started to spin out of control, which scared many local people."},{"tr":"Enkaz, vincin üzerinde çalıştığı 84 katlı kuleden düştü.","en":"Debris fell off an 84-story tower that the crane was working on."},{"tr":"Yetkililer, birinin yaralanma riskinin yüksek olması nedeniyle kulenin etrafındaki birkaç caddeyi kapattı.","en":"Authorities closed several streets around the tower because there was a high risk that somebody could get hurt."},{"tr":"İtfaiye görevlileri geldiğinde rüzgar ve sisten dolayı kulenin tepesini göremediler.","en":"When fire officers arrived, they couldn’t see the top of the tower due to wind and fog."},{"tr":"Vinçler 160 km/s hıza kadar rüzgarlara dayanabilir ve rüzgarda dönerler.","en":"Cranes can resist winds of up to 160 kmph and they spin in the wind."},{"tr":"Yetkililer, enkazın neden düştüğünü öğrenmek istiyor.","en":"Officials want to find out why the debris fell down."}]},{"id":"CK-296","no":296,"title":"Dünyanın En Soğuk Köyü","level":1,"code":"DOG","s":[{"tr":"Soğuk kıştan bıktıysanız, dünyanın en soğuk kasabasında yaşadıklarını söyleyen bir Rus kasabasının sakinlerini düşünün.","en":"If you are tired of the cold winter, think about the residents of a Russian town who say that they live in the coldest town on Earth."},{"tr":"Kasabalarına Oymyakon denir ve Sibirya'nın derinliklerinde bulunur.","en":"This town is called Oymyakon and it lies deep in Siberia."},{"tr":"Oradaki sıcaklıklar genellikle eksi 60'a düşer.","en":"The temperatures there often drop to minus 60."},{"tr":"Bu yerel halk, bu düşük sıcaklıkların bazen arka arkaya on gün sürdüğünü söylüyor.","en":"These local people say that these low temperatures sometimes last for ten days in a row."},{"tr":"Kasabalarında inanılmaz bir şey daha var.","en":"There is another amazing thing in their town."},{"tr":"Bu düşük sıcaklıklarda hayatta kalan bir attır.","en":"It is a horse that survives in these low temperatures."},{"tr":"At küçük ama soğuk kışlar için mükemmel şekilde şekillendirilmiş.","en":"The horse is small, but is perfectly formed for cold winters."}]},{"id":"CK-297","no":297,"title":"Dünyanın En İyi Pasta Şefi","level":2,"code":"POR","s":[{"tr":"Pierre Marcolini, 1964 doğumlu Belçikalı bir çikolatacıdır.","en":"Pierre Marcolini is a Belgian chocolatier who was born in 1964."},{"tr":"1995 yılında ilk mağazasını açmadan önce Belçika ve Fransa'da ünlü şirketlerde çalıştı.","en":"In 1995, he worked for famous companies in Belgium and France before he opened his first shop."},{"tr":"Hayali çikolata dünyasını değiştirmek ve onu daha modern hale getirmekti.","en":"His dream was to change the world of chocolate and to make it more modern."},{"tr":"Marcolini hayatında birçok ödül aldı ve son zamanlarda World Pastry Stars, dünyanın en iyi pasta şefi unvanını kazanmak için bir yarışma düzenledi.","en":"Marcolini received many prizes in his life, recently, World Pastry Stars organized a competition to win the title of the world’s best pastry chef."},{"tr":"Marcolini unvanı kazandı ve Belçika'nın en iyi çikolatayı yaptığını kanıtladı.","en":"Marcolini won the title and he proved that Belgium made the best chocolate."},{"tr":"Marcolini, en iyi kakao çekirdeklerini bulmak için dünyayı dolaşıyor.","en":"Marcolini travels the world to find the finest cocoa beans."},{"tr":"Yetiştiricilerle konuşuyor ve çikolatasını yapmanın tüm adımlarını kontrol ediyor.","en":"He speaks to growers and he controls all the steps of making his chocolate."},{"tr":"Kakao çekirdeklerini kendisi kavuran birkaç çikolatacıdan biridir.","en":"He is one of the few chocolatiers who roast cocoa beans himself."},{"tr":"100 €'dan fazla veya 129 $'dan fazlaya mal olan özel çikolata hediye kutuları satıyor.","en":"He sells special chocolate gift boxes that cost more than €100 or more than $129."}]},{"id":"CK-298","no":298,"title":"Hapisteki Guru","level":1,"code":"POR","s":[{"tr":"1998 ve 2020 yılları arasında Keith Raniere bir Amerikan gurusuydu.","en":"Between 1998 and 2020, Keith Raniere was an American guru."},{"tr":"Toplantılarına birçok Hollywood yıldızı ve ünlü kişi katıldı.","en":"Many HollyWood stars and famous people attended his meetings."},{"tr":"Raniere ayrıca New York Eyaletinde bulunan çok seviyeli bir pazarlama şirketi kurdu.","en":"Raniere also started a multi-level marketing company that was located in New York state."},{"tr":"Raniere'nin birçok takipçisi, kendisinin onları taciz ettiğini ve onlara seks kölesi dediğini söyledi.","en":"Many of Raniere’s followers said that he abused them and that he called them his sex slaves."},{"tr":"Geçen yıl mahkeme, Raniere'yi seks kaçakçılığı ve çocuk pornografisi tutmaktan suçlu buldu.","en":"Last year, the court found Raniere guilty of sex trafficking and keeping child pornography."},{"tr":"Ayrıca insanları onlardan para almakla tehdit etti.","en":"He also threatened people to get money from them."},{"tr":"Salı günü bir mahkeme Raniere'yi 120 yıl hapis cezasına çarptırdı.","en":"On Tuesday, a court sent Raniere to prison for 120 years."},{"tr":"Raniere, yanlış bir şey yapmadığı için üzülmediğini söyledi.","en":"Raniere said that he didn’t feel sorry because he didn’t do anything wrong."}]},{"id":"CK-299","no":299,"title":"Ferrari Roma","level":1,"code":"BLT","s":[{"tr":"Ferrari, 2021 Ferrari Roma adında yeni bir araba tanıttı.","en":"Ferrari has introduced a new car, the 2021 Ferrari Roma."},{"tr":"Araba 2021 baharında satışa çıkacak ve fiyatı 216.670 dolardan başlıyor.","en":"The car is going to be on sale in spring 2021, and its price starts at $216,670."},{"tr":"Araba 611 beygir gücünde ve 320 km/s hıza ulaşabiliyor.","en":"The car is 611-horsepower, and it can reach the speed of 320 kmph."},{"tr":"Çok fazla bacak ve baş mesafesi vardır, bu nedenle uzun insanlar için bile rahattır.","en":"There is a lot of leg and headroom, so it is comfortable even for tall people."},{"tr":"Frenler hızlı tepki verir ve direksiyon hafiftir.","en":"The brakes react quickly and the steering is light."},{"tr":"Arka koltuk var, ancak bir el çantası veya bazı alışveriş çantaları için uygundur.","en":"There is a back seat, but it is suitable for a handbag or some shopping bags."},{"tr":"Araba, klasik Ferrari çizgilerini modern stille birleştiriyor.","en":"The car combines the classic Ferrari lines with modern style."},{"tr":"Bunun, hibrit elektrikli parçası olmayan son Ferrari arabası olması muhtemel.","en":"It is possible that this is the last Ferrari car that doesn’t have any hybrid electric parts."}]},{"id":"CK-300","no":300,"title":"Nijerya Protestoları","level":2,"code":"DUN","s":[{"tr":"Nijerya'da halk polis şiddetini protesto etti.","en":"People in Nigeria protested against police brutality."},{"tr":"Ordunun protestoculara ateş açmasıyla yakın zamanda yaşanan bir olaydan sonra halkın öfkesi arttı.","en":"The people’s anger increased after a recent incident when the military shot at protesters."},{"tr":"Protesto 20 Ekim'de gerçekleşti ve oldukça barışçıl geçti.","en":"The protest took place on October 20th, and it was quite peaceful."},{"tr":"Protestocular, yerde oturan insanların videolarını çekti.","en":"Protesters shot videos of people siting on the ground."},{"tr":"Şarkı söyleyip Nijerya bayraklarını sallıyorlardı.","en":"They were singing and waving Nigerian flags."},{"tr":"Sonra arka planda bazı çekimler duymak mümkün oldu.","en":"Then it was possible to hear some shooting in the background."},{"tr":"Bazı videolar askerleri gösteriyordu, ancak Nijerya ordusu olay yerinde asker olmadığını söyledi.","en":"Some videos showed soldiers, but the Nigerian army said that there were no soldiers at the place."},{"tr":"Son üç yılda 80'den fazla polis vahşeti hikayesi yaşandı.","en":"In the part three years, there have been more than 80 stories of police brutality."},{"tr":"SARS adında özel bir polis birimi vardı ve insanlardan bilgi almak için genellikle vahşet kullanıyordu.","en":"There was a special police unit called SARS, and they usually used brutality to get information from people."}]},{"id":"CK-301","no":301,"title":"Mısır Keşfi","level":2,"code":"TAR","s":[{"tr":"Mısır'daki arkeologlar 80'den fazla antik tabut keşfettiler.","en":"Archaeologists in Egypt discovered more than 80 ancient coffins."},{"tr":"Arkeologlar, başkentin 30 kilometre güneyindeki büyük bir mezarlık olan Saqqara'da inanılmaz keşif yaptılar.","en":"Archaeologists made the amazing discovery in Saqqara, which is a large burial site 30 kilometers south of the capital city."},{"tr":"Saqqara'da, dünyanın en eski piramitlerinden biri olan Djoser Piramidi de var.","en":"In Saqqara, there is also one of the oldest pyramids in the world, Pyramid of Djoser."},{"tr":"Keşif, yaklaşık 2.500 yıllık lahitleri ve ahşap heykelleri içeriyordu.","en":"The discovery included sarcophagi and wooden statues that were around 2500 years old."},{"tr":"Heykellerin bazıları boyanmış, bazıları altınla kaplanmıştır.","en":"Some of the statues were painted, some were covered with gold."},{"tr":"Arkeologlar, bu hafta içinde keşifle ilgili ayrıntıları vermeyi planlıyorlar.","en":"Archaeologists plan to give details about the discovery later this week."},{"tr":"2011'de Mısır'daki siyasi durum çarpıcı bir şekilde değişti ve birçok insan ülkeye seyahat etmekten korktu.","en":"In 2011, the political situation in Egypt changed dramatically, and many people were afraid to travel to the country."},{"tr":"Şimdi Mısır turistleri geri getirmeye çalışıyor ve yeni keşifler bu çabaya yardımcı olabilir.","en":"Now, Egypt is trying to bring tourists back, and new discoveries could help this effort."}]},{"id":"CK-302","no":302,"title":"Tayland Kaplan Tapınağı","level":2,"code":"DOG","s":[{"tr":"Tayland'daki Kaplan Tapınağı 137 kaplana ev sahipliği yapıyor, ancak bunların hepsi değişebilir.","en":"The Tiger Temple in Thailand is home to 137 tigers, but all of this could change."},{"tr":"Yetkililer, turistler arasında popüler olan Budist tapınağını araştırıyor.","en":"Officials are investigating Buddhist temple that is popular with tourists."},{"tr":"Yetkililer, tapınağı büyük kedilere kötü davranmakla suçladı.","en":"The officials accused the temple of maltreating the big cats."},{"tr":"Ocak ayında yetkililer beş kaplanı alıp koruma merkezlerine taşıdı.","en":"In January, the officials moved them to conservations centers."},{"tr":"Ancak bazı insanlar hayvanları tapınaktan uzaklaştırmanın onlar için stresli olabileceğini söylüyor.","en":"However, some people say that it can be stressful to take the animals away from the temple for them."},{"tr":"İnsanlar ayrıca tapınağın yasadışı vahşi yaşam ticaretiyle bağlantılı olduğunu söylüyor.","en":"People also say that the temple is connected to the illegal trade of wildlife."},{"tr":"Yetkililer her şeyi araştırmalı ve ardından kedilerin kalıp kalamayacağını veya gitmesi gerektiğini söylemelidir.","en":"Officials must investigate everything and then they must say if the cats stay or must go."}]},{"id":"CK-303","no":303,"title":"Moda endüstrisi","level":2,"code":"DOG","s":[{"tr":"Moda endüstrisi çevre için büyük bir sorundur.","en":"The fashion industry is a big problem for the environment."},{"tr":"Dünyadaki atık suyun %20'si moda endüstrisinden gelir ve endüstri aynı zamanda dünya karbon emisyonlarının %10'undan sorumludur.","en":"20% of the world’s wastewater comes from the fashion industry, and the industry is also responsible for 10% of world carbon emissions."},{"tr":"Tüm uçakların ve gemilerin birlikte yaptıklarından daha fazlasıdır.","en":"It is more than all planes and ships make together."},{"tr":"İlginç bir gerçek şu ki, bir kot pantolon yapmak için yaklaşık 7.500 litre su gerekiyor.","en":"An interesting fact is that it takes about 7500 liters of water to make a pair of jeans."},{"tr":"Aynı zamanda, insanlar çok fazla kıyafet atıyorlar.","en":"At the same time, people throw a lot of clothes away."},{"tr":"Her saniye o kadar çok kıyafet atıyorlar ki bir çöp kamyonunu dolduruyorlar.","en":"Every second, they throw away so many clothes that they would fill one garbage truck."},{"tr":"İnsanlar en son modayı takip ediyor ve yeni kıyafetler almaya devam ediyorlar.","en":"People follow latest fashions and they keep buying new clothes."},{"tr":"Bazı moda şirketleri çevreye daha duyarlı olmaya çalışıyor ve geri dönüştürülmüş malzemelerden kıyafet yapıyorlar.","en":"Some fashion companies try to be more friendly to the environment, and they make clothes from recycled materials."},{"tr":"Çevreye zarar vermeyen modern teknolojileri kullanırlar.","en":"They use modern technologies that don’t harm the environment."}]},{"id":"CK-304","no":304,"title":"Katil Eşek Arısı Kovanı","level":2,"code":"DOG","s":[{"tr":"Geçen yıl, insanlar ABD'de katil eşekarısı tespit etmeye başladı.","en":"Last year, people started to spot murder hornets in the US."},{"tr":"Bu büyük bir sürprizdi çünkü katil eşekarıları Asya'nın tropik bölgelerinde yaşıyor ve kimse ABD'ye nasıl geldiklerini bilmiyordu.","en":"It was a bg surprise because murder hornets live in tropical parts of Asia, and nobody knew how they got to the US."},{"tr":"Şimdi, uzmanlar nihayet Washington eyaletinde bir yuva buldular ve bu bir basketbol topu büyüklüğündeydi.","en":"Now, experts finally found a nest in Washington state and it was about the size of a basketball."},{"tr":"Uzmanlar bazı böcekler yakaladı ve onlar için özel bir cihaz ayarladılar.","en":"Experts caught some bugs, and they fixed a special device for them."},{"tr":"Cihaz onlara yuvanın yolunu gösterdi.","en":"The device showed them the way to the nest."},{"tr":"Katil eşekarısı genellikle insanları öldüremez, ancak bir kişinin zehirine alerjisi varsa, şoka girebilir.","en":"Murder hornets cannot usually kill people, but if a person is allergic to their venom, he can go into shock."},{"tr":"Katil eşekarısı bal arıları için çok tehlikelidir ve birkaç saat içinde bir bal arısı yuvasını yok edebilirler.","en":"Murder hornets are very dangerous to honeybees and they can destroy a honeybee nest in a few hours."},{"tr":"Ürünlerini yetiştirmek için bal arılarına ihtiyaç duyan çiftçiler için büyük bir sorundur.","en":"It is a big problem for farmers who need honeybees to grow their crops."}]},{"id":"CK-305","no":305,"title":"Brexit Anlaşması","level":2,"code":"DUN","s":[{"tr":"İngiltere ile AB arasındaki Brexit görüşmeleri sona eriyor gibi görünüyor.","en":"Brexit talks between the UK and the EU seem to be coming to an end."},{"tr":"Ama yine de duyguları harekete geçiren bir konu var ve o da balık tutmak.","en":"But there is still one topic that stirs emotions, and that is fishing."},{"tr":"İngiltere başbakanı, ülkenin İngiliz sularının kontrolünü geri almak istediğini söyledi.","en":"The UK prime minister said that the country wants to take back control of British waters."},{"tr":"2019'da balıkçılık İngiltere'nin üretiminin yalnızca %0.03'ünü oluşturuyordu, peki İngilizler için neden bu kadar önemli?","en":"In 2019, fishing made up only 0.03% of the UK’s output, so why is it so important to the British?"},{"tr":"Birçok insan balıkçılığı Britanya'nın gücünün bir sembolü olarak görüyor, bu yüzden Britanya'nın sularını elinde tutmasını istiyorlar.","en":"Many people see fishing as a symbol of Britain’s power, so they want Britain to keep its waters."},{"tr":"AB buna katılmıyor ve İngiliz sularına girmek istiyor.","en":"The EU does not agree, and it wants access to British waters."},{"tr":"Fransa için İngiliz sularına erişim çok önemlidir ve onsuz ülkenin büyük sorunları olacaktır.","en":"For France, access to British waters is very important, and without it the country will have big problems."}]}];
